RG.HK["17"] = [{"id":"17_kanazawajo","n":"金沢城（加賀百万石の本拠）","yomi":"かなざわじょう","cat":"城","rank":"S","y":1583,"era":["azuchi","edo"],"sh":"国指定史跡","ad":"金沢市丸の内","st":"JR金沢駅からバスで約15分「兼六園下・金沢城」下車すぐ","la":36.5652,"lo":136.6593,"hook":"一向一揆の寺があった丘に、前田利家が築いた «百万石の城»。天守はなくても、石垣だけで一日楽しめる。","lead":"金沢城は、加賀藩をおさめた前田家の城です。もとは一向宗（浄土真宗）の門徒たちの拠点 «尾山御坊» があった場所で、1583年に前田利家が入ってから約290年、前田家14代の本拠になりました。石川門や三十間長屋が今も残り、菱櫓などが木造で復元されています。","story":["戦国時代のはじめ、この丘には城ではなく寺がありました。本願寺が建てた «尾山御坊（金沢御堂）» です。加賀の国は、一向宗の門徒たちが守護を倒して自分たちで治める、全国でもめずらしい土地でした。御坊はその «心臓» のような場所だったのです。","1580年、織田信長の命を受けた柴田勝家の軍、佐久間盛政らが御坊を攻め落とします。そして1583年、賤ヶ岳の戦いのあと、羽柴秀吉に従った前田利家が金沢に入りました。«ここを加賀・能登・越中を治める要にする»。利家はそう考え、本格的な城づくりを始めます。","城は何度も火事に苦しみました。1602年には落雷で天守が焼け、その後は二度と天守は建てられませんでした。1631年の大火のあと、藩は犀川の上流から水を引く «辰巳用水» をつくり、城に水を送るしくみを整えます。なぜそこまで水にこだわったのか? 答えは «火事に強い城にするため» でした。","金沢城の見どころは、何といっても石垣です。自然の石をそのまま積んだもの、形をそろえてすき間なく組んだもの、表面をきれいに整えたものなど、いろいろな時代の積み方が一度に見られ、«石垣の博物館» とよばれます。職人たちの工夫を比べて歩くと、時代の流れが見えてきます。","明治になると城には陸軍の師団が置かれ、戦後は金沢大学のキャンパスになりました。大学が移ったあと、2001年に菱櫓・五十間長屋・橋爪門続櫓が昔の工法で木造復元され、その後も河北門、玉泉院丸庭園、鼠多門などがよみがえっています。«百万石の城» は今も少しずつ姿を取り戻しているのです。"],"tl":[["1546年","本願寺が «尾山御坊（金沢御堂）» を建てる"],["1580年","柴田勝家の軍が尾山御坊を攻め落とす"],["1583年","前田利家が金沢に入城"],["1602年","落雷で天守が焼失。以後、天守は再建されず"],["1632年","辰巳用水が完成したと伝わる"],["1788年","石川門が再建される（現存）"],["1858年","三十間長屋が再建される（現存）"],["1871年","廃藩置県。のち陸軍の拠点に"],["2001年","菱櫓・五十間長屋・橋爪門続櫓を木造で復元"],["2008年","«金沢城跡» が国の史跡に指定"]],"who":[["前田利家","加賀藩の祖。1583年に入城し、城と城下町づくりを始めた"],["前田利長","利家の長男で2代藩主。高山右近の助けも借りて城を整えたといわれる"],["高山右近","キリシタン大名。前田家に身を寄せ、城や城下の整備にかかわったと伝わる"],["佐久間盛政","柴田勝家のおい。尾山御坊を攻め落とし、利家より前にこの地にいた"]],"deep":["加賀藩は «百万石» とよばれますが、正しくは加賀・能登・越中を合わせて約102万石から120万石前後（時期により変わる）。江戸時代の大名で最大の石高でした。","石川門の屋根が白く見えるのは «鉛瓦» のため。木の板に鉛の板を張った瓦で、雪に強いためとも、いざというときに鉄砲玉にするためともいわれますが、後者ははっきりしません。","天守は1602年に焼けたあと再建されず、かわりに «三階櫓» が城のシンボルになりました。三階櫓も1759年の宝暦の大火で焼けています。","石垣の積み方は大きく «自然石積み»«粗加工石積み（打ち込みハギ）»«切石積み（切り込みハギ）» の3つ。場所によって時代と技術のちがいがわかります。","菱櫓は建物の平面が菱形（ひしがた）で、柱も菱形に削られています。復元では図面や古写真を手がかりに、釘に頼らない伝統工法が使われました。","戦後から1995年まで城内には金沢大学があり、«お城の中の大学» として知られていました。"],"look":["石川門（江戸時代の建物が残る国の重要文化財）","三十間長屋（現存の重要文化財）","菱櫓・五十間長屋の木造復元と内部の骨組み","«石垣めぐり»：色紙短冊積み石垣などの石垣","玉泉院丸庭園と鼠多門・鼠多門橋"],"q":["金沢城の天守は今どうなっている?","1602年に落雷で焼けてから一度も再建されず、天守はありません。かわりに三階櫓が建てられました。"],"koji":[{"w":"加賀百万石","m":"前田家の加賀藩の大きさをたたえることば。江戸時代の大名で一番大きな石高だった"}],"myth":"鉛瓦を «鉄砲玉にするため» とする話や、高山右近が城づくりにどこまで関わったかは諸説。","img":["石川門","前田利家","辰巳用水"],"wp":"金沢城","rel":{"ev":["sankin"],"grave":[]},"ph":[["c:7/7e/Kanazawa-M-5932.jpg",1500,1000,"金沢城"],["c:0/00/National_Crafts_Museum_in_Kanazawa_20201116-001.jpg",4867,3245],["c:a/ac/Kanazawa_Kanazawa-jo_Hishi_Yagura_Innen.jpg",4592,3098],["c:4/48/Kanazawa_Kanazawa-jo_Hishi_Yagura_Blick_aufs_Kahoku-mon_2.jpg",4580,3177],["c:f/f5/Kanazawa_Kanazawa-jo_Hishi_Yagura_Blick_aufs_Kahoku-mon_1.jpg",3988,3093],["c:8/89/Kanazawa_Castle_park_-_01_-_2016-04-16.jpg",4608,3456],["c:d/d8/Kanazawa_Castle_IMG_20161015_113925.jpg",4160,3120],["c:4/48/Kanazawa_Castle_-_16_-_2016-04-16.jpg",4608,3456]]},{"id":"17_kenrokuen","n":"兼六園","yomi":"けんろくえん","cat":"大名屋敷","rank":"S","y":1822,"era":["edo","meiji"],"sh":"国の特別名勝","ad":"金沢市兼六町","st":"JR金沢駅からバスで約15分「兼六園下・金沢城」下車、歩いて約5分","la":36.5621,"lo":136.6627,"hook":"«六つのよさ» を兼ね備えた庭。加賀藩主が約180年かけて育てた、日本三名園のひとつ。","lead":"兼六園は、加賀藩の前田家が金沢城のとなりにつくった大名庭園です。水戸の偕楽園、岡山の後楽園と並ぶ «日本三名園» のひとつ。«兼六» の名は、ひとつの庭の中に六つのよさがそろっていることから付けられました。","story":["庭の始まりは1676年ごろ、5代藩主・前田綱紀が金沢城に面した斜面に建てた «蓮池御亭» と、そのまわりの庭だといわれます。当時は «蓮池庭» とよばれ、藩主が月見をしたり、客をもてなしたりする特別な場所でした。","その後、火事で庭が焼けるなど浮き沈みがありましたが、12代藩主・前田斉広が隠居所 «竹沢御殿» を建てて庭を広げました。1822年、斉広は老中もつとめた松平定信に名前を頼みます。定信が選んだのが «兼六園» という名でした。","«六つのよさってなに?» それは中国・宋の時代の本『洛陽名園記』にある考え方です。広々とした «宏大» と、奥深く静かな «幽邃»。人の手による «人力» と、古びた味わいの «蒼古»。そして «水泉» と «眺望»。ふつうは両立しにくいこの六つを、兼ね備えた庭だというのです。","13代藩主・前田斉泰の時代に、庭はほぼ今の形になりました。霞ヶ池を広げ、琵琶湖の唐崎の松の種から育てたと伝わる «唐崎松» を植え、池の水の高低差を使った噴水もつくられます。この噴水は、日本に現存する噴水の中でもとても古いものといわれます。","明治になって1874年、兼六園は一般の人に開放されました。藩主だけの庭が、みんなの庭になったのです。冬になると、雪の重みで枝が折れないように縄を張る «雪吊り» が行われ、金沢の冬の風物詩になっています。池に足をかけた «徽軫灯籠» の前は、今も記念写真の人でにぎわいます。"],"tl":[["1676年","前田綱紀が «蓮池御亭» を建てたとされ、庭の始まりに"],["1759年","宝暦の大火で蓮池庭の建物も被害を受ける"],["1822年","前田斉広が竹沢御殿を建てる。松平定信が «兼六園» と名付ける"],["1861年ごろ","噴水がつくられたと伝わる"],["1863年","前田斉泰が母のために «巽御殿»（今の成巽閣）を建てる"],["1874年","一般に公開される"],["1922年","国の名勝に指定"],["1985年","国の特別名勝に指定"]],"who":[["前田綱紀","5代藩主。蓮池庭をつくり、庭の始まりをひらいたとされる"],["前田斉広","12代藩主。竹沢御殿を建て、庭を広げた"],["松平定信","元老中。«兼六園» の名付け親"],["前田斉泰","13代藩主。霞ヶ池を広げ、今の庭の形を整えた"]],"deep":["«六勝» の出典は宋の李格非『洛陽名園記』。«宏大と幽邃»«人力と蒼古»«水泉と眺望» が互いに相反しやすい性質だ、という考え方がもとになっています。","庭の水は、1632年に完成したと伝わる «辰巳用水» から来ています。犀川の上流から約10km以上かけて引いた水が、高低差を利用して庭中をめぐります。","噴水は霞ヶ池との高低差（水圧）だけで水を噴き上げるしくみで、電気もポンプも使いません。池の水位によって高さが変わるといわれます。","«徽軫灯籠» の名は、琴の糸を支える «琴柱（ことじ）» に形が似ていることから。片方の脚が短いのが特徴です。","園内の «成巽閣» は、斉泰が母・真龍院のために建てた御殿で、国の重要文化財。大名家の奥方の暮らしが見られる数少ない建物です。","雪吊りは «りんご吊り» ともよばれ、特に唐崎松は5本の芯柱から多くの縄を張る大がかりなもの。毎年11月ごろに始まります。"],"look":["徽軫灯籠と霞ヶ池","唐崎松の枝ぶり（冬は雪吊り）","日本最古級といわれる噴水","眺望台からの金沢の町と日本海方面の眺め","成巽閣（園の東どなり・別料金）"],"q":["«兼六園» の «六» は何のこと?","宏大・幽邃・人力・蒼古・水泉・眺望という、庭の六つのよさのこと。ふつうは両立しにくい六つを兼ね備えているという意味です。"],"koji":[{"w":"六勝を兼ねる","m":"相反する六つのすぐれた点をすべて備えていること。兼六園の名の由来"}],"myth":"庭の始まりの年や噴水の完成年には諸説がある。","img":["成巽閣","日本三名園","辰巳用水"],"wp":"兼六園","rel":{"ev":["sankin"],"grave":[]},"ph":[["c:f/fc/Kenrokuen10-r.jpg",1999,1333,"兼六園"],["c:2/2d/Kenrokuensiguretei01.jpg",4608,3072],["c:2/2b/Kenroku-en_20170131-2.jpg",5184,3456],["c:d/d4/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan11s3.jpg",4912,3264],["c:2/24/131109_Kenrokuen_Kanazawa_Ishikawa_pref_Japan12s3.jpg",4912,3264],["c:1/12/131109_Kenrokuen_Kanazawa_Ishikawa_pref_Japan11s3.jpg",4800,3200],["c:e/e8/131109_Kenrokuen_Kanazawa_Ishikawa_pref_Japan10s3.jpg",4650,3100],["c:5/5a/131109_Kenrokuen_Kanazawa_Ishikawa_pref_Japan05s3.jpg",4912,3264]]},{"id":"17_nodayama","n":"野田山墓地（前田利家と加賀藩主の墓所）","yomi":"のだやまぼち","cat":"墓所","rank":"S","y":1599,"era":["azuchi","edo"],"sh":"国指定史跡（加賀藩主前田家墓所）","ad":"金沢市野田町","st":"JR金沢駅からバスで約30分「野田」下車、歩いて約15分","la":36.5306,"lo":136.6565,"hook":"金沢の南の丘に、大名家の墓がずらりと並ぶ。その一番上で眠るのが、加賀百万石の祖・前田利家。","lead":"野田山は、金沢市の南にある小高い山です。ここには前田利家をはじめ、加賀藩主とその家族の墓が集まっています。さらに藩士や金沢の人びとの墓もたくさんあり、全体では数万基ともいわれる大きな墓地になっています。","story":["1599年、前田利家は大坂で亡くなりました。豊臣秀吉の死からわずか半年ほど。五大老として豊臣家を支えた重鎮の死は、天下の行方を大きく変えます。そして利家のなきがらは、はるばる金沢へ運ばれ、この野田山に葬られました。","じつは利家は生前、この山に兄の前田利久を葬っていたと伝わります。«自分もここに» と考えていたのかもしれません。以後、野田山は前田家の墓所となり、歴代藩主やその妻、子どもたちが次々とこの地に眠ることになりました。","山を登っていくと、ふつうのお墓とはまるで違う光景が広がります。前田家の墓は、四角い土を盛り上げた «墳墓» の形。前には石の鳥居や灯籠が立ち、まるで小さな古墳のようです。«なぜ大名が古墳のような墓を?» 仏教だけでなく、儒教や神道の考えも取り入れた葬り方だったと考えられています。","利家の墓のそばには、妻のまつ（芳春院）の墓もあります。まつは利家の死後、前田家を守るため自ら人質となって江戸へ行き、十数年を過ごしました。夫婦は、今も同じ山の上で並んで眠っているのです。","野田山には、前田家の家臣や、金沢ゆかりの文学者の墓もあります。作家の室生犀星もここに眠ります。静かな杉林の中を歩くと、«百万石» を支えた人びとの長い時間が、ひとつの山に積み重なっていることを感じられます。"],"tl":[["1587年","前田利家が兄・利久をこの地に葬ったと伝わる"],["1599年","前田利家が大坂で死去。野田山に葬られる"],["1617年","まつ（芳春院）が死去。のち野田山に墓がつくられる"],["江戸時代","歴代藩主と家族の墓が次々につくられる"],["2009年","«加賀藩主前田家墓所» として国の史跡に指定"]],"who":[["前田利家","加賀藩の祖。1599年没。野田山の最も高いところ近くに墓がある"],["まつ（芳春院）","利家の妻。夫の死後、江戸で人質となり前田家を守った"],["前田利長","2代藩主。墓は富山県高岡市にあり、同じく国史跡に含まれる"],["室生犀星","金沢出身の詩人・小説家。野田山に墓がある"]],"deep":["国の史跡 «加賀藩主前田家墓所» は、金沢の野田山と、富山県高岡市の前田利長墓所などからなります。利長の墓は高岡の町をひらいた縁で高岡にあります。","前田家の墓は土まんじゅう型の方形墳墓で、大きいものは一辺が20m近くあるといわれます。江戸時代の大名墓としては珍しい形で、研究者の注目を集めています。","野田山には明治以降の陸軍墓地もあり、戦争で亡くなった人びとが祀られています。前田家墓所とはエリアが分かれています。","墓所の近くには前田家ゆかりの寺もあり、法事の行列が城下から野田山へ向かう道は、藩にとって大切な道でした。","まつは利家の死後、1600年から十数年を江戸で過ごしたといわれます。これが «大名の妻子を江戸に置く» 仕組みの早い例のひとつとも説明されます。"],"look":["前田利家の墓（方形の墳墓と鳥居）","まつ（芳春院）の墓","歴代藩主の墓が並ぶ山の上の区画","室生犀星の墓","杉木立の参道の静けさ"],"q":["前田家の藩主の墓は、どんな形をしている?","土を四角く盛り上げた «墳墓» の形。前に鳥居や灯籠があり、小さな古墳のように見えます。"],"koji":[],"myth":"利久を最初に葬ったのが墓所の始まりという話は伝承。まつの江戸行きを «人質制度の始まり» とする説明は一説。","img":["前田利家","芳春院","室生犀星"],"wp":"野田山墓地","rel":{"ev":[],"grave":[]},"ph":[["c:7/7b/Mount_Noda_Grave_2023-07.jpg",2432,1824,"野田山墓地"],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:4/4b/H%C5%8Dshun-in_%28Matsu%29.jpg",4480,5280,"芳春院"],["c:a/ac/Saisei_Muro_01.jpg",660,950,"室生犀星"]]},{"id":"17_shirayamahime","n":"白山比咩神社（加賀一之宮）","yomi":"しらやまひめじんじゃ","cat":"寺社","rank":"S","y":717,"era":["nara","heian","muromachi"],"sh":"","ad":"白山市三宮町","st":"北陸鉄道石川線 鶴来駅から歩いて約25分（バス・タクシーもあり）","la":36.4402,"lo":136.6369,"hook":"全国に約3000ある «白山神社» の総本宮。祀られるのは、神話でイザナギとイザナミの間に立った謎の女神。","lead":"白山比咩神社は、霊峰・白山をご神体とする神社で、加賀の国の一之宮です。まつられている «白山比咩大神» は «菊理媛（くくりひめ）» とも言われ、人と人を結ぶ神様として信仰されています。全国の白山神社の総本宮です。","story":["加賀・越前・美濃にまたがる白山は、夏でも雪が残る美しい山。昔の人は «白い山には神がいる» と考え、ふもとから山を拝んできました。神社の始まりは、はるか昔、崇神天皇の時代だと伝わりますが、はっきりした年はわかりません。","奈良時代の717年、越前の僧・泰澄が初めて白山の頂上に登り、そこで女神に出会ったと伝わります。これを «白山開山» といいます。以後、白山は神と仏が一緒にまつられる修行の山となり、加賀・越前・美濃の三方から登る道 «三馬場» がひらかれました。","«くくりひめって、どんな神様?» 『日本書紀』のある一書に、たった一度だけ登場します。黄泉の国から逃げ帰ったイザナギと、追ってきたイザナミ。その二人の前に現れて何かを申し上げ、イザナギにほめられた女神、それが菊理媛です。何を言ったのかは書かれていません。この «謎» が、多くの人の想像をかき立ててきました。","平安時代から室町時代にかけて、白山の神社と寺は «白山宮» として大きな力を持ち、比叡山延暦寺とも結びつきました。しかし1480年、火事で社殿を失い、現在の場所へ移ったといわれます。戦国時代には一向一揆の時代の混乱の中で勢いが衰えましたが、江戸時代には前田家の保護を受けました。","今の境内は、手取川が山から平野に出る «鶴来» の町のそばにあります。杉の大木に囲まれた長い参道を歩くと、空気がすっと冷たくなるのを感じます。明治の神仏分離で仏教の要素は取り除かれましたが、白山を仰ぐ人びとの祈りは、1300年以上途切れず続いています。"],"tl":[["伝・崇神天皇の時代","神社のはじまりと伝わる"],["717年","泰澄が白山を開山したと伝わる"],["平安時代後期","白山の寺社が延暦寺と結びつく"],["1480年","火事で社殿を失い、現在地へ移ったとされる"],["江戸時代","加賀藩前田家の保護を受ける"],["明治時代","神仏分離で «白山比咩神社» に"]],"who":[["泰澄","奈良時代の越前の僧。白山を開いたと伝わる «越の大徳»"],["菊理媛尊","祭神とされる女神。『日本書紀』の一書に一度だけ登場"],["イザナギ・イザナミ","国生みの二神。あわせてまつられている"],["前田家","江戸時代の加賀藩主。神社を保護した"]],"deep":["神社は国宝の «剣 銘吉光» を所蔵しています。鎌倉時代の名工・粟田口吉光の作とされ、短刀の名手・吉光の数少ない剣として知られます。","白山の頂上（御前峰）には «奥宮» があり、夏の登山シーズンに多くの登山者が参拝します。里の本宮と山頂の奥宮が一組になっています。","«三馬場» は、加賀馬場（白山比咩神社）、越前馬場（平泉寺）、美濃馬場（長滝白山神社）。それぞれが白山への登り口として栄えました。","菊理媛の «くくり» は «くくる（結ぶ・まとめる）» に通じるとして、縁結びの神とされます。ただしこれは後の解釈で、名前の本当の意味は諸説あります。","泰澄の実在や伝記は『泰澄和尚伝記』などによりますが、書かれたのは後の時代で、どこまで史実かは議論があります。"],"look":["杉の大木に囲まれた表参道","本殿と拝殿（白山を背にした配置）","宝物館（公開の内容は時期による）","境内から流れる «白山霊水»","手取川の渓谷と鶴来の町並み"],"q":["菊理媛が『日本書紀』でイザナギに言ったことばは何?","じつは書かれていません。«何かを申し上げ、ほめられた» とあるだけで、その内容は謎です。"],"koji":[],"myth":"創建年・泰澄の開山・1480年の移転の経緯は伝承や後世の記録による。祭神を菊理媛とする点も諸説。","img":["白山","泰澄","菊理媛神"],"wp":"白山比咩神社","rel":{"ev":[],"grave":[]},"ph":[["j:d/d0/%E7%99%BD%E5%B1%B1%E6%AF%94%E5%92%A9%E7%A5%9E%E7%A4%BE_%E5%A4%96%E6%8B%9D%E6%AE%BF.JPG",3648,2736,"白山比咩神社"],["c:3/35/Shirayamahime_Okumiya.JPG",4000,3000],["c:b/b2/Shirayamahime-%E5%A2%83%E5%86%85-%E7%A5%9E%E9%96%80%E7%A5%9E%E9%A6%AC%E8%88%8E.JPG",6544,3680],["c:5/51/Shirayamahime-%E5%A2%83%E5%86%85-%E7%A5%9E%E9%96%80-%E7%A5%9E%E9%A6%AC%E5%83%8F.JPG",6544,3680],["c:3/36/Shirayamahime-%E5%A2%83%E5%86%85-%E6%AD%B3%E6%99%82%E8%A8%98-%E5%8A%A0%E8%B3%80%E7%8D%85%E5%AD%90%E8%88%9E%E5%A5%89%E7%B4%8D.JPG",6544,3680],["c:b/be/Shirayamahime-%E5%A2%83%E5%86%85-%E5%8C%97%E5%8F%82%E9%81%93%E6%89%8B%E6%B0%B4%E8%88%8E-1.JPG",6544,3680],["c:c/c5/Shirayamahime-%E9%A3%9B%E5%9C%B0%E5%A2%83%E5%86%85-%E8%88%9F%E5%B2%A1%E5%B1%B1-%E7%99%BD%E5%B1%B1%E6%AF%94%E3%82%81%E7%A5%9E%E7%A4%BE%E5%89%B5%E5%A7%8B%E3%81%AE%E5%9C%B0.JPG",3648,2736],["c:2/22/Shirayamahime-%E9%A3%9B%E5%9C%B0%E5%A2%83%E5%86%85-%E5%8F%A4%E5%AE%AE%E5%9D%80-%E7%A5%AD%E7%A5%80%E3%81%AE%E3%81%8B%E3%82%8F%E3%82%89%E3%81%91%E4%B8%AD%E4%B8%96%E9%81%BA%E8%B7%A1.JPG",3648,2736]]},{"id":"17_keta","n":"氣多大社（能登一之宮）","yomi":"けたたいしゃ","cat":"寺社","rank":"S","y":748,"era":["nara","azuchi","edo"],"sh":"国の重要文化財（本殿・拝殿・神門など）","ad":"羽咋市寺家町","st":"JR羽咋駅からバスで約10分「一の宮」下車、歩いて約5分","la":36.929,"lo":136.7555,"hook":"大伴家持も参った能登一之宮。人が入れない «入らずの森» に守られた、縁結びの古社。","lead":"氣多大社は、能登半島の入り口・羽咋にある古い神社で、能登の国の一之宮です。出雲の大国主と同じ神様 «大己貴命» をまつり、縁結びの神社として人気です。奈良時代の歌人・大伴家持が参拝したことが『万葉集』からわかります。","story":["むかしむかし、この地には怪しい鳥や大蛇があらわれ、人びとを苦しめていたといいます。そこへ出雲の国から大己貴命が船でやって来て、わざわいを退け、能登の国を平らかにした。神社にはそんな言い伝えが残っています。","奈良時代の748年、越中の国守だった大伴家持は、国内を見回る旅の途中でこの神社に参りました。そして «之乎路から ただ越え来れば 羽咋の海 朝なぎしたり 船梶もがも» と詠みます。«山を越えて来たら、羽咋の海が朝なぎで穏やか。船があったらなあ»。家持の目に映った海が、今も社殿の向こうに広がっています。","社殿の裏には、約3万平方メートルの森が広がります。昔から人が足を踏み入れてはいけない «入らずの森»。«なぜ入ってはいけないの?» そこは神様が鎮まる森とされ、昔から斧を入れることも禁じられてきたといわれます。おかげで、この土地本来の木々が残り、国の天然記念物になりました。","戦国時代が終わると、能登を治めた前田家がこの神社をあつく保護しました。神門は安土桃山時代、本殿や拝殿は江戸時代の建物で、どれも国の重要文化財です。能登の強い風と雪に耐えてきた、どっしりとした建物です。","冬の12月には «鵜祭» という不思議な神事が行われます。七尾の鵜浦で捕らえた一羽の鵜を、何日もかけて運び、夜明け前の本殿に放つ。鵜の動きで翌年を占うといわれます。能登の人びとは、千年以上も前からの祈りの形を大切に受け継いでいるのです。"],"tl":[["伝・古代","大己貴命が能登を平定したと伝わる"],["748年","大伴家持が参拝し歌を詠む（『万葉集』）"],["平安時代","能登国一之宮とされる"],["安土桃山時代","神門が建てられる（重要文化財）"],["江戸時代","前田家の保護のもと本殿・拝殿などが整う（重要文化財）"],["昭和時代","社叢 «入らずの森» が国の天然記念物に"]],"who":[["大己貴命","祭神。大国主命の別名。出雲から来て能登を平らげたと伝わる"],["大伴家持","奈良時代の歌人・越中守。参拝して歌を残した"],["前田利家","能登を領し、神社を保護した前田家の祖"],["前田家歴代藩主","江戸時代を通じて社殿の造営や修理を支えた"]],"deep":["家持の歌は『万葉集』巻17に収められ、題詞に «気太神宮に赴き参り» とあることから、奈良時代にすでに有名な神社だったことがわかります。","«鵜祭» は国の重要無形民俗文化財。鵜を運ぶ «鵜様道中» は、七尾市鵜浦町から羽咋まで、何日もかけて鵜を運ぶ道中です。","«入らずの森» はタブノキ・スダジイなどの照葉樹林。日本海側の北限に近い林として学術的にも貴重とされます。","3月の «平国祭（おいで祭り）» は、神様が能登の各地をめぐる大がかりな祭りで、大己貴命の能登平定の伝承にちなむといわれます。","神仏習合の時代には、神社と一緒に «正覚院» などの寺があり、神宮寺として神社を支えていました。"],"look":["安土桃山時代の神門","江戸時代の拝殿と本殿（重要文化財）","«入らずの森»（外から眺める。中へは入れない）","近くの羽咋の海岸と «千里浜なぎさドライブウェイ»"],"q":["大伴家持がこの神社を訪ねたことがわかる本は?","『万葉集』。巻17に、参拝の途中で羽咋の海を詠んだ歌がのっています。"],"koji":[],"myth":"大己貴命の渡来・怪鳥退治、入らずの森の禁忌は伝承。社殿の個々の建立年は諸説あり。","img":["大伴家持","鵜祭","大国主"],"wp":"氣多大社","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/Keta-taisha_keidai.JPG",3648,2736,"氣多大社"],["c:d/d8/Keta-taisha_zuishinmon.JPG",3648,2736],["c:1/13/Keta-taisha_torii.JPG",3648,2736],["c:8/88/Keta-taisha_shinmon.JPG",3648,2736],["c:c/c6/Keta-taisha_shinko.JPG",3648,2736],["c:5/57/Keta-taisha_sessha_Shirayama-jinja.JPG",3648,2736],["c:2/22/Keta-taisha_sessha_Ageta-jinja.JPG",3648,2736],["c:1/1f/Keta-taisha_ichinotorii.JPG",3648,2736]]},{"id":"17_nanaojo","n":"七尾城（能登畠山氏の巨城）","yomi":"ななおじょう","cat":"城","rank":"S","y":1577,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"七尾市古城町","st":"JR七尾駅から車で約15分（本丸近くに駐車場）。歩いて登ると1時間以上","la":36.999,"lo":136.9845,"hook":"上杉謙信でさえ一年がかりでしか落とせなかった山城。石垣の上から、能登の海が一望できる。","lead":"七尾城は、室町時代から戦国時代にかけて能登の国を治めた畠山氏の城です。七尾の町の南にそびえる山の尾根をまるごと城にした巨大な山城で、日本有数の山城に数えられます。1577年、上杉謙信に攻められて落城しました。","story":["室町時代のはじめ、足利一門の名門・畠山家の一族が能登の守護になりました。これが «能登畠山氏» です。彼らは七尾の港を見下ろす山に城を築き、しだいに尾根全体へと広げていきました。«七尾» という名は、七つの尾根に由来するといわれます。","16世紀前半、7代目の畠山義総の時代、七尾は大いに栄えました。京の都が戦乱で荒れると、公家や僧、連歌師たちが遠い能登まで訪ねてきます。«能登の小京都» の城下では、和歌や連歌の会が開かれ、都の文化が花開きました。","しかし義総の死後、家臣たちの争いが激しくなり、当主の力は弱まります。そこへ越後の上杉謙信が攻めてきました。1576年から続いた包囲は1年近くに及びます。城の中では疫病が広がり、幼い当主も亡くなったと伝わります。1577年9月、ついに城内の遊佐氏らが寝返り、城を守っていた長氏の一族は討たれ、七尾城は落ちました。","このとき謙信が詠んだとされる漢詩が «霜は軍営に満ちて秋気清し» で始まる『九月十三夜』です。月の下で能登と越中の山々を眺め、故郷を思う名詩として有名ですが、本当に謙信が作ったかどうかは疑問もあります。","謙信の死後、能登は織田信長の手に入り、1581年に前田利家が能登を与えられました。利家は海に近い小丸山に新しい城を築き、山の上の七尾城は役目を終えます。今は本丸・二の丸・三の丸などに見事な石垣が残り、本丸からは七尾湾と能登島を見わたせます。"],"tl":[["1408年ごろ","畠山満慶が能登守護となり、能登畠山氏が始まる"],["16世紀前半","畠山義総のもとで城と城下が栄える"],["1576年","上杉謙信が能登に攻め込み、七尾城を包囲"],["1577年9月","城内の内応により落城"],["1581年","前田利家が能登を与えられる"],["1580年代","利家が小丸山城へ移り、七尾城は廃城に"],["1934年","国の史跡に指定"]],"who":[["畠山義総","能登畠山氏7代。城と城下を整え、文化をさかえさせた"],["上杉謙信","越後の大名。1年近い包囲のすえ七尾城を落とした"],["長続連","畠山家の重臣。籠城を指揮したが、落城のとき一族とともに討たれた"],["遊佐続光","畠山家の重臣。謙信に内通して城を開いたといわれる"],["前田利家","謙信の後に能登を与えられ、七尾城から小丸山城へ移った"]],"deep":["城域は尾根づたいに南北約2.5kmにも及ぶといわれ、本丸・二の丸・三の丸のほか «調度丸»«桜馬場»«遊佐屋敷»«温井屋敷» など重臣の名がついた曲輪があります。","本丸付近の石垣は、戦国時代の山城としては規模が大きく、畠山氏の時代か、その後の上杉・前田の時代に積まれたものか、議論があります。","『九月十三夜』の詩は、江戸時代の頼山陽『日本外史』などを通じて広まったもので、謙信の作とする確かな同時代史料はないとされます。","落城のとき、長氏の一族は一人を除いて討たれたと伝わります。生き残った長連龍は、のちに前田家の重臣として活躍しました。","城下の «七尾城史資料館» には城から出土した遺物などが展示され、麓の «懐古館» は江戸時代の旧家の屋敷です。"],"look":["本丸跡の石垣と七尾湾・能登島の眺め","桜馬場・調度丸などの石垣群","尾根を切った堀切や曲輪の配置","七尾城史資料館"],"q":["七尾城が落城した直接のきっかけは?","城内の重臣（遊佐氏ら）が上杉謙信に寝返ったこと。長い籠城と疫病で城内は弱っていました。"],"koji":[{"w":"霜は軍営に満ちて秋気清し","m":"謙信の作とされる漢詩『九月十三夜』の一句。陣中に霜が降りて秋の空気が澄みわたる、という意味"}],"myth":"«七尾» の名の由来、疫病で当主が死んだ話、『九月十三夜』の作者は伝承・諸説。","img":["畠山義総","上杉謙信","小丸山城"],"wp":"七尾城","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/Nanaojo-tyoudomaru.JPG",1280,960,"七尾城"],["c:f/f6/Nanaojoshi.JPG",1280,960],["c:4/49/Nanaojo-tyodomaru2.JPG",1280,960],["c:e/e1/Nanaojo-old-rute.JPG",1280,960],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:a/a7/%E7%95%A0%E5%B1%B1%E7%BE%A9%E7%B7%8F%E3%81%AE%E4%BD%8D%E7%BD%B2%E3%81%A8%E8%8A%B1%E6%8A%BC.jpg",1137,2223,"畠山義総"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:6/6a/Komaruyama_castle.JPG",3648,2736,"小丸山城"]]},{"id":"17_takaojo","n":"高尾城跡（加賀一向一揆・富樫政親滅亡）","yomi":"たかおじょうあと","cat":"古戦場","rank":"S","y":1488,"era":["muromachi"],"sh":"","ad":"金沢市高尾町","st":"JR金沢駅からバスで約30分、高尾方面のバス停から丘を歩く（遺構はほとんど残らない）","la":36.5155,"lo":136.631,"hook":"守護大名が、一揆の門徒に攻め滅ぼされた。約90年も続く «百姓の持ちたる国» は、この丘から始まった。","lead":"高尾城は、加賀の守護・富樫政親の城でした。1488年、一向宗の門徒を中心とする大軍に囲まれ、政親は自害します。こうして加賀は、約90年にわたって門徒たちが治める «百姓の持ちたる国» となりました。城跡は宅地造成で多くが失われ、今は碑と案内板が残るだけです。","story":["15世紀の加賀では、守護の富樫家が兄弟で争っていました。1474年、兄の富樫政親は、力を伸ばしていた一向宗の門徒たちの力を借りて弟を倒します。«これで加賀は安泰だ»。ところが、力をつけた門徒たちは、やがて政親の言うことを聞かなくなっていきました。","一向宗（浄土真宗）の教えを広めたのは本願寺の蓮如です。蓮如は越前の吉崎に拠点を置き、やさしい手紙 «御文» で教えを説きました。«念仏を唱えれば誰でも救われる»。この教えは農民や武士、商人のあいだに急速に広がり、村ごとに «講» というまとまりができていきます。","政親は将軍・足利義尚の近江出陣に従うため、国の人びとに重い負担をかけました。不満は爆発します。1488年、門徒と、政親に反発する武士たちが連合し、大軍で高尾城を包囲しました。越前の朝倉氏などが援軍を送ろうとしましたが間に合わず、6月、政親は城の中で自ら命を絶ったと伝わります。","«守護を倒したあと、だれが国を治めたの?» 一揆の人びとは、富樫家の一族・泰高を名目上の守護に立てましたが、実際の力は本願寺と門徒たちが握りました。本願寺の記録には、加賀が «百姓の持ちたる国のようになった» と書かれています。","この体制は、1580年に織田信長の軍が金沢御堂（尾山御坊）を落とすまで、約90年も続きました。戦国時代の中でも、武士ではなく門徒たちが一国を動かしたとても珍しい例です。高尾の丘は、その始まりを見届けた場所なのです。戦いで命を落とした人びとを思いながら、静かに歩きたい場所です。"],"tl":[["1471年","蓮如が越前の吉崎に拠点を置く"],["1474年","富樫政親が門徒の力を借りて弟・幸千代を破る"],["1487年","政親が将軍足利義尚の近江出陣に参加"],["1488年6月","一揆勢が高尾城を包囲し、政親が自害"],["1488年以降","富樫泰高を名目上の守護に、門徒が実権を握る"],["1580年","柴田勝家らが金沢御堂を落とし、一揆の国が終わる"]],"who":[["富樫政親","加賀の守護。門徒と組んで権力を得たが、のちに門徒に攻められ自害"],["蓮如","本願寺8世。北陸で教えを広め、門徒の力を大きくした"],["富樫泰高","政親の大叔父にあたる一族。一揆後に名目上の守護に立てられた"],["足利義尚","室町幕府9代将軍。政親の滅亡に怒り、蓮如を責めたと伝わる"]],"deep":["«百姓ノ持タル国ノヤウニ» という有名なことばは、蓮如の子・実悟がまとめた記録『実悟記拾遺』に出てきます。ここでの «百姓» は農民だけでなく、地侍や門徒全体を指すと考えられています。","一揆勢の数は記録に «二十万» などとありますが、誇張と考えられています。","将軍の義尚は政親の滅亡を知って怒り、蓮如に門徒の処分を求めたといわれます。蓮如は門徒をいさめる «御叱りの御文» を出したと伝わります。","高尾城跡は丘陵の北端にあり、1960年代以降の宅地開発で遺構の大部分が失われました。発掘調査で堀などが確認されています。","富樫氏の館は、今の野々市市にあった «富樫館» とされ、野々市は古くから加賀の政治の中心地でした。"],"look":["高尾城跡の碑と案内板（丘の上）","丘から見わたす金沢平野（一揆勢が集まった方角）","近くの野々市市の «富樫館跡»","金沢城（のちの金沢御堂の跡）とあわせて歩くと流れがわかる"],"q":["加賀一向一揆のあと、加賀が何と言われるようになったか?","«百姓の持ちたる国»。武士の守護ではなく、門徒たちが実質的に国を動かしたためです。"],"koji":[{"w":"百姓の持ちたる国","m":"加賀一向一揆のあと、門徒たちが実権をもった加賀のようすを表したことば"}],"myth":"政親の最期の日付、一揆勢の人数、蓮如が一揆にどこまで関わったかは諸説。","img":["富樫政親","蓮如","高尾城"],"wp":"加賀一向一揆","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Tyoufukuj3.jpg",1375,1252],["c:a/ae/Rennyo5.1.JPG",998,1257,"蓮如"],["c:2/2c/Kanazawa_Institute_of_Technology.jpg",1600,1200,"近く: 金沢工業大学"],["c:5/50/Magae-station1.JPG",1600,1200,"近く: 馬替駅"],["c:d/dd/Nukajyutakumaeeki.jpg",3264,2448,"近く: 額住宅前駅"],["c:c/c2/Otomarueki.jpg",3264,2448,"近く: 乙丸駅"]]},{"id":"17_torigoejo","n":"鳥越城（一向一揆最後の砦）","yomi":"とりごえじょう","cat":"城","rank":"S","y":1582,"era":["azuchi"],"sh":"国指定史跡（鳥越城跡 附 二曲城跡）","ad":"白山市三坂町","st":"北陸鉄道石川線 鶴来駅から車で約20分。公共交通は不便で車がおすすめ","la":36.3592,"lo":136.6275,"hook":"織田軍に最後まで抵抗した門徒たちの山城。その結末は、あまりに悲しいものだった。","lead":"鳥越城は、白山のふもと、手取川の上流にある山城です。加賀一向一揆の門徒たちが織田信長の軍に最後まで抵抗した城として知られます。今は本丸の門などが復元され、ふもとの «鳥越一向一揆歴史館» で当時のことを学べます。","story":["1580年、信長の命を受けた柴田勝家の軍が金沢御堂を落とし、加賀一向一揆の国はほぼ終わりを迎えました。しかし、白山のふもとの山の村々に住む門徒たちは、まだあきらめていませんでした。その中心となったのが、鳥越城の鈴木出羽守です。","鳥越城は、大日川と手取川にはさまれた山の上にあります。三方を急な崖に囲まれ、下からは容易に近づけません。«ここなら守りきれる»。門徒たちは山の上に本丸や二の丸をつくり、近くの二曲城とも連携して、織田軍に立ち向かいました。","ところが1580年の冬、鈴木出羽守は柴田方の武将にだまされ、松任城に呼び出されて討たれたと伝わります。鳥越城は織田方の手に落ちました。けれども門徒たちは1581年、そして1582年と何度も城を取り返そうと立ち上がります。","1582年、再び落城した鳥越城のまわりでは、捕らえられた門徒たちが多数、処刑されたといわれます。その数は300人ともいわれます。«信じる教えを守りたかっただけなのに»。山の村々に残る言い伝えは、その悲しみを今に語り継いでいます。","戦いのあと、村々は長く苦しい時代を過ごしました。発掘調査では、焼けた米や武具などが見つかり、激しい戦いのようすが確かめられています。今、復元された門の前に立つと、白山から吹き下ろす風の中に、門徒たちの祈りが聞こえてくるような気がします。"],"tl":[["1570年代","鈴木出羽守らが鳥越城を築いたとされる"],["1580年","金沢御堂が落ちる。冬に鈴木出羽守が討たれ、鳥越城も落ちる"],["1581年","門徒が城を奪い返すが再び落とされる"],["1582年","最後の抵抗が鎮められ、多くの門徒が処刑されたと伝わる"],["1977年ごろから","発掘調査が進む"],["1985年","«鳥越城跡 附 二曲城跡» として国の史跡に"]],"who":[["鈴木出羽守","一向一揆の指導者。鳥越城を拠点に抵抗したが、だまし討ちにあったと伝わる"],["柴田勝家","織田軍の北陸方面の総大将"],["佐久間盛政","勝家のおい。加賀の一揆の平定を進めた"],["織田信長","本願寺と10年にわたり戦った天下人"]],"deep":["鈴木出羽守は紀伊の雑賀衆の出身ともいわれますが、確かではありません。本願寺から派遣された武将だった可能性も指摘されています。","城は標高約310mの山にあり、本丸の «枡形門» や石垣、空堀などが復元・整備されています。","発掘調査では、焼けた米・麦や陶磁器、鉄砲の玉などが出土し、城が焼き討ちにあったようすがうかがえます。","近くの二曲城は鳥越城と一体となって守りを固めた城で、あわせて国史跡に指定されています。","この地域には、一揆の悲劇を語る伝承や供養の行事が残り、«一向一揆まつり» なども行われてきました。"],"look":["復元された本丸の枡形門と石垣","本丸から見る手取川・大日川の谷","空堀や曲輪の地形","鳥越一向一揆歴史館"],"q":["鳥越城で戦ったのはどんな人たち?","加賀一向一揆の門徒たち。織田信長の軍に対し、最後まで抵抗しました。"],"koji":[],"myth":"鈴木出羽守の出自、だまし討ちの経緯、処刑された人数は伝承・諸説。","img":["加賀一向一揆","柴田勝家","佐久間盛政"],"wp":"鳥越城","rel":{"ev":[],"grave":[]},"ph":[["c:9/94/Torigoe01.jpg",800,531,"鳥越城"],["c:2/26/%E9%B3%A5%E8%B6%8A%E5%9F%8E%E6%9E%A1%E5%BD%A2%E9%96%80.JPG",3888,2592],["c:5/57/%E9%B3%A5%E8%B6%8A%E5%9F%8E%E6%9C%AC%E4%B8%B8%E9%96%80.JPG",3888,2592],["c:f/fc/%E9%B3%A5%E8%B6%8A%E5%9F%8E%E6%9C%AC%E4%B8%B8.JPG",3888,2592],["c:3/32/%E9%B3%A5%E8%B6%8A%E5%9F%8E%E5%A0%80%E5%88%87.JPG",3888,2592],["c:8/8f/%E9%B3%A5%E8%B6%8A%E5%9F%8E%E4%B8%AD%E3%81%AE%E4%B8%B8%E9%96%80.JPG",3888,2592],["c:d/d9/Torigoejo-stereo.jpg",2036,1364],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940]]},{"id":"17_ataka","n":"安宅の関（勧進帳の舞台）","yomi":"あたかのせき","cat":"伝承","rank":"S","y":1187,"era":["kamakura","muromachi","edo"],"sh":"","ad":"小松市安宅町","st":"JR小松駅からバスで約20分、安宅方面のバス停から歩いてすぐ","la":36.4108,"lo":136.4235,"hook":"白紙の巻物を読み上げ、主君をたたいてまで守った。歌舞伎『勧進帳』の名場面は、この海辺が舞台。","lead":"安宅の関は、源義経と弁慶が奥州へ逃げる途中、関所の役人に見とがめられたという物語の舞台です。弁慶の機転で切り抜けた話は、能『安宅』や歌舞伎『勧進帳』で有名になりました。ただし、関所が本当にあったかどうかははっきりしません。","story":["平家をほろぼした源義経は、兄の頼朝に追われる身になりました。1187年ごろ、義経は家来たちと山伏の姿に変装し、奥州の藤原秀衡をたよって北陸道を進んだといわれます。その途中にあったのが、日本海に面した安宅の関、という設定です。","関を守るのは富樫左衛門。«山伏に化けた義経一行を通すな» という命令が出ていました。弁慶は «われらは東大寺の大仏再建のために寄付を集める山伏だ» と言います。«それなら寄付を集める趣旨を書いた勧進帳を読んでみよ»。富樫の言葉に、弁慶は何も書いていない巻物を広げ、すらすらと読み上げてみせました。","それでも富樫の部下が «あの強力（荷物持ち）は義経に似ている» と言い出します。すると弁慶は、«おまえのせいで疑われるのだ!» と金剛杖で義経を打ちすえました。家来が主君をたたくなど、ふつうはありえないこと。«まさか本物の義経を打つはずがない»。富樫は一行を通しました。","«富樫は本当にだまされたの?» 歌舞伎の『勧進帳』では、富樫は義経だと気づきながら、弁慶の忠義に心を打たれて見逃したように描かれます。関を越えたあと、弁慶は主君を打ったことを泣いてわび、義経はそれを許しました。見る人の胸を熱くする名場面です。","今の安宅には、安宅住吉神社の近くに «安宅の関址» の碑と、弁慶・富樫・義経の像が立っています。«難関を突破した» 話にちなんで、受験生の合格祈願にも人気です。すぐそばには日本海が広がり、潮風の中で物語を思い浮かべることができます。"],"tl":[["1185年","平家滅亡。やがて義経は頼朝と対立"],["1187年ごろ","義経が奥州へ逃れたとされる"],["室町時代","能『安宅』がつくられる（観世信光の作ともいわれる）"],["1840年","七代目市川團十郎が歌舞伎『勧進帳』を初演"],["1966年ごろ","関址に弁慶・富樫・義経の像が建てられる"]],"who":[["源義経","平家を倒した英雄。兄の頼朝に追われ、山伏姿で奥州へ逃れた"],["武蔵坊弁慶","義経の家来。白紙の勧進帳を読み上げ、主君を打って危機を救った"],["富樫左衛門","関守として描かれる人物。加賀の富樫氏がモデルとされる"],["七代目市川團十郎","『勧進帳』を初演した歌舞伎役者。«歌舞伎十八番» に選んだ"]],"deep":["義経の逃避行を描く『義経記』では、弁慶が義経を打つ場面は越中の «如意の渡» で起こったことになっており、安宅の関の場面は能『安宅』から有名になったと考えられています。","安宅の関が実在したことを示す確かな史料は見つかっておらず、関所の正確な場所もわかっていません。現在の碑の場所は伝承地です。","『勧進帳』は、能の舞台を模した «松羽目物» と呼ばれる演目の代表作。最後の «飛び六方» で弁慶が花道を去る場面が見せ場です。","富樫左衛門のモデルとされる加賀の富樫氏は、のちに加賀の守護となり、1488年に一向一揆で滅びる政親の一族です。","東大寺の大仏殿は1180年の平重衡の焼き討ちで焼け、実際に重源が各地で勧進を行って再建を進めていました。物語はこの時代背景を使っています。"],"look":["«安宅の関址» の碑","弁慶・富樫・義経の像","安宅住吉神社（難関突破の祈願）","勧進帳ものがたり館","すぐそばの日本海の海岸"],"q":["弁慶が関所で読み上げた «勧進帳» には何が書いてあった?","何も書いていない白紙でした。弁慶はそれを本物のように読み上げたと物語では語られます。"],"koji":[{"w":"勧進帳","m":"寺の建立や修理のために寄付を集める目的を書いた巻物。転じて、弁慶のように機転でその場を切り抜けることのたとえにも"}],"myth":"安宅の関と一行の問答は能・歌舞伎など創作による物語で、史実とは確認されていない。関所の場所も伝承地。","img":["勧進帳","武蔵坊弁慶","源義経"],"wp":"安宅の関","rel":{"ev":[],"grave":[]},"ph":[["c:5/57/Ataka-no-seki.jpg",1296,972,"安宅の関"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["j:2/20/Atakanoseki.JPG",480,360],["c:a/a5/K%C5%8Dshir%C5%8D_Matsumoto_VII_as_Benkei.jpg",273,413,"勧進帳"],["c:a/a0/Kuniyoshi_Utagawa%2C_Heroes_of_china_and_Japan_3.jpg",1677,1221,"武蔵坊弁慶"],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"]]},{"id":"17_higashichaya","n":"ひがし茶屋街","yomi":"ひがしちゃやがい","cat":"町","rank":"S","y":1820,"era":["edo","meiji"],"sh":"国の重要伝統的建造物群保存地区","ad":"金沢市東山1丁目","st":"JR金沢駅からバスで約10分「橋場町」下車、歩いて約5分","la":36.5725,"lo":136.6668,"hook":"細い格子の向こうから、三味線の音が聞こえてきそう。江戸時代の «茶屋» の家並みがそのまま残る町。","lead":"ひがし茶屋街は、江戸時代の終わりごろ、加賀藩が浅野川の東側に茶屋を集めてできた町です。細かい木の格子がついた2階建ての家が並び、国の重要伝統的建造物群保存地区になっています。今もお茶屋が営まれ、芸妓さんの芸が受け継がれています。","story":["1820年、加賀藩は城下のあちこちにあった茶屋を2か所に集めることにしました。ひとつは浅野川の東、もうひとつは犀川の西。それが今の «ひがし茶屋街» と «にし茶屋街» の始まりです。«なぜわざわざ集めたの?» 町の風紀を取りしまるためだったといわれます。","茶屋というのは、ただお茶を飲む店ではありません。お客が座敷で料理を楽しみ、芸妓さんの踊りや三味線、笛などの芸を見る、大人の社交の場でした。お客は、商人や文人など、町のだんな衆でした。","家のつくりには特徴があります。1階の表には «きむすこ» とよばれる細い木の格子。外からは中が見えにくく、中からは外がよく見えるしくみです。2階はお客をもてなす座敷で、天井が高く、窓を開けると通りを見下ろせます。ふつうの町家とは逆に、2階が主役の建物なのです。","明治以降も、茶屋街は金沢の文化を支えてきました。金沢は、戦争中に大きな空襲を受けなかったこともあり、古い町並みがよく残っています。2001年、ひがし茶屋街は国の重要伝統的建造物群保存地区に選ばれました。","今では、昔の茶屋を公開する «志摩»（国の重要文化財）や «懐華樓»、金箔のお店やカフェが並び、観光客でにぎわいます。でも夕方になると、どこかの座敷から三味線の音が聞こえてくることも。200年前と同じように、芸の世界は今も生きているのです。"],"tl":[["1820年","加賀藩が茶屋を浅野川の東と犀川の西に集める"],["1820年","お茶屋 «志摩» が建てられる"],["明治時代","茶屋街として引き続き栄える"],["2001年","国の重要伝統的建造物群保存地区に選定"],["2003年","«志摩» が国の重要文化財に"]],"who":[["加賀藩","茶屋を集めて «ひがしの茶屋町» をつくった"],["芸妓","座敷で踊りや三味線などの芸を披露する。今も受け継がれている"],["泉鏡花","金沢出身の作家。浅野川界隈を作品にえがいた"]],"deep":["«きむすこ» は «木虫籠» と書き、細かい格子を虫かごに見立てた金沢のことばといわれます。","お茶屋 «志摩» は1820年の建物で、ほとんど建てられた当時のまま残る貴重な例として国の重要文化財に指定されています。座敷や、客の前で芸を見せる «控えの間» が見学できます。","金沢には «ひがし»«にし»«主計町» の3つの茶屋街があり、主計町も重要伝統的建造物群保存地区に選ばれています。","金沢は日本の金箔の生産量の大部分をしめるといわれ、茶屋街にも金箔のお店が多く並びます。","夜のお座敷は «一見さんお断り» の店が多く、ふつうの旅行者が入るには紹介などが必要です。観光向けの体験プランが用意されることもあります。"],"look":["«きむすこ» の格子が続く町並み","お茶屋 «志摩»（重要文化財）の座敷","懐華樓など公開されているお茶屋","浅野川と梅ノ橋、対岸の主計町茶屋街"],"q":["茶屋街の建物で、お客をもてなす座敷があるのは何階?","2階。天井が高く、窓から通りを見下ろせるつくりになっています。"],"koji":[{"w":"一見さんお断り","m":"はじめての客は紹介がないと入れない、というお茶屋などのしきたり"}],"myth":"茶屋を集めた目的は、風紀の取りしまりなど諸説。","img":["にし茶屋街","主計町","金沢箔"],"wp":"ひがし茶屋街","rel":{"ev":[],"grave":[]},"ph":[["c:2/25/Higashiyamahigashi_2015.JPG",2500,1638,"ひがし茶屋街"],["c:1/15/Higashiyama-higashi_Kanazawa_Ishikawa02n4272.jpg",3999,2666],["c:4/4d/Higashiyama-higashi_Kanazawa_Ishikawa03n3200.jpg",3200,2133],["c:b/b7/Higashiyamahigashi_2015_%E2%85%A1.JPG",3000,2000],["c:8/8d/Higashiyamahigashi_%28shima%29.JPG",3000,1920],["c:9/97/Shima_Geisha_House.JPG",2048,1536],["c:9/9d/Shima-Tsuboniwa.JPG",2048,1536],["c:8/83/Nishichayagai003.jpg",3861,2574,"にし茶屋街"]]},{"id":"17_mawaki","n":"真脇遺跡（縄文のイルカ漁とウッドサークル）","yomi":"まわきいせき","cat":"遺跡","rank":"S","y":-4000,"era":["jomon"],"sh":"国指定史跡","ad":"鳳珠郡能登町真脇","st":"公共交通は本数が少なく、車が便利（のと里山空港から車で約1時間）","la":37.296,"lo":137.208,"hook":"何百頭ものイルカの骨と、巨大な木の柱の輪。縄文の人びとが約4000年も住み続けた、能登の入り江の村。","lead":"真脇遺跡は、能登半島の先のほう、富山湾に面した入り江にある縄文時代の遺跡です。縄文時代の前期から晩期まで、約4000年ものあいだ人が暮らし続けました。たくさんのイルカの骨や、巨大な木の柱を輪のように立てた «環状木柱列» が見つかっています。","story":["真脇は、三方を山に囲まれ、前に穏やかな入り江が広がる小さな谷です。今から約6000年前、この場所に縄文の人びとがやって来て村をつくりました。そして驚くことに、村はそれから約4000年も続きます。ひとつの場所にこれほど長く人が住み続けた遺跡は、全国でも珍しいのです。","1982年から始まった発掘で、人びとは目を見張りました。地層の中から、イルカの骨が次々と出てきたのです。その数は数百頭分ともいわれます。«縄文人は本当にイルカをとっていたの?» 入り江に迷いこんだイルカの群れを、みんなで追いこんでとったのではないか、と考えられています。","とれたイルカは、肉を食べるだけでなく、脂を燃料にしたり、骨を道具にしたりしたのでしょう。ほかの村と交換する大切な «財産» だったかもしれません。真脇の人びとは、海の恵みを生かして豊かに暮らしていたのです。","縄文時代の終わりごろの地層からは、もうひとつの大発見がありました。クリの木を半分に割った太い柱が、直径約7mの円をえがくように立てられた跡です。これが «環状木柱列（ウッドサークル）»。何のためのものかはわかっていませんが、祭りや儀式の場だったと考える人が多いようです。","遺跡の土は水気が多く、木の柱や木の器、骨などが腐らずに残りました。そのおかげで、縄文人の暮らしが生き生きとわかるのです。今は公園として整備され、ウッドサークルも復元されています。能登の静かな入り江に立つと、4000年の時間の厚みを感じられます。"],"tl":[["約6000年前","縄文時代前期、村が始まる"],["約5000年前ごろ","イルカの骨がたくさん残る時期（前期末〜中期初め）"],["約2800年前ごろ","縄文時代晩期、環状木柱列がつくられる"],["約2000年前","縄文時代の終わりまで人が住み続ける"],["1982年","本格的な発掘調査が始まる"],["1989年","国の史跡に指定"],["1991年","出土品が国の重要文化財に指定"]],"who":[["真脇の縄文人","約4000年にわたり村を営み、イルカ漁を行った"],["発掘調査団","1980年代の調査で、イルカの骨やウッドサークルを発見した"]],"deep":["環状木柱列の柱は、クリの丸太を縦に半分に割り、平らな面を外側（または内側）に向けて立てたもの。太いものは直径90cm前後あったといわれます。","真脇の環状木柱列は、金沢市のチカモリ遺跡などと並んで北陸地方に特徴的な遺構で、同じような柱の輪は石川・富山の縄文遺跡で見つかっています。","イルカの骨の多くは、カマイルカやマイルカのなかまと考えられています。骨には解体の跡が残るものもあります。","遺跡からは «トーテムポール» のように彫刻がほどこされた木柱も出ています。何を表しているのかは不明です。","真脇遺跡は低い土地にあり、水をふくんだ土に守られて木製品が残りました。この条件がなければ、柱の根も消えていたはずです。","2024年の能登半島地震では、能登町も大きな被害を受けました。訪れる前に施設の開館状況を確かめましょう。"],"look":["復元された環状木柱列（ウッドサークル）","真脇遺跡縄文館の出土品（イルカの骨・土器・木柱）","入り江を見わたす遺跡公園の地形"],"q":["真脇遺跡から大量に見つかった動物の骨は何?","イルカ。数百頭分ともいわれ、縄文人がイルカ漁をしていたと考えられています。"],"koji":[],"myth":"イルカ漁の方法や環状木柱列の用途は推定で、諸説ある。","img":["環状木柱列","チカモリ遺跡","縄文時代"],"wp":"真脇遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:f/f6/Mawaki_Site.jpg",1200,912,"真脇遺跡"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:e/e9/%E3%83%81%E3%82%AB%E3%83%A2%E3%83%AA%E9%81%BA%E8%B7%A1_%E7%92%B0%E7%8A%B6%E6%9C%A8%E6%9F%B1_-_panoramio.jpg",2592,1944,"チカモリ遺跡"]]},{"id":"17_sojiji","n":"總持寺祖院（曹洞宗の旧大本山）","yomi":"そうじじそいん","cat":"寺社","rank":"S","y":1321,"era":["kamakura","muromachi","meiji"],"sh":"国の登録有形文化財（山門・仏殿など）","ad":"輪島市門前町門前","st":"輪島市街や穴水駅から路線バスで「総持寺前」下車すぐ（本数は少なめ）","la":37.2893,"lo":136.77,"hook":"能登の山あいの寺が、かつて全国1万数千の寺をたばねる大本山だった。いまは «祖院» として祈りを守る。","lead":"總持寺祖院は、曹洞宗の大本山 «總持寺» がもともとあった場所です。1321年に瑩山紹瑾がひらき、全国に広がる曹洞宗の寺の中心になりました。明治時代の火事のあと本山は横浜の鶴見へ移り、ここは «祖院» として受け継がれています。","story":["鎌倉時代の終わり、1321年。瑩山紹瑾という禅僧が、能登の門前にあった «諸嶽寺» という寺をゆずり受け、名前を «總持寺» と改めました。瑩山は、道元が伝えた曹洞宗を、武士だけでなく、ふつうの人びとにも広めようとした人物です。","翌年の1322年、後醍醐天皇から總持寺を «曹洞宗の出世道場» とする文書が出されたと伝わります。つまり、天皇が認めた特別な寺になったのです。こうして、能登の小さな寺は、全国の曹洞宗の中心へと歩み始めます。","瑩山のあとを継いだ峨山韶碩は、すぐれた弟子をたくさん育てました。弟子たちは全国に寺をひらき、そのまた弟子が寺をひらき…。こうして總持寺の流れをくむ寺は、全国に1万数千もあるといわれるほどに増えていきます。«なぜ能登の山の寺からこんなに広がったの?» 地方の人びとの祈りや葬儀にこたえる、身近な仏教だったからだと考えられています。","江戸時代には、加賀藩の前田家も總持寺を大切にしました。けれども1898年、大きな火事で伽藍の多くが焼けてしまいます。これをきっかけに、1911年、本山は神奈川県の鶴見へ移ることになりました。能登の人びとにとって、それはどれほどさびしい出来事だったでしょう。","それでも門前の寺は «總持寺祖院» として再建され、祈りの場であり続けました。2007年の能登半島地震で大きな被害を受け、長い修復を終えたあと、2024年の地震で再び傷つきました。何度倒れても立ち上がる祖院の姿は、能登の人びとの粘り強さそのものです。"],"tl":[["1321年","瑩山紹瑾が諸嶽寺をゆずり受け、總持寺とする"],["1322年","後醍醐天皇から «出世道場» とする綸旨が出たと伝わる"],["14世紀","峨山韶碩のもとで多くの弟子が育つ"],["江戸時代","加賀藩前田家の保護を受ける"],["1898年","大火で伽藍の多くが焼ける"],["1911年","本山が横浜・鶴見へ移る。能登は «祖院» に"],["2007年","能登半島地震で大きな被害。のち修復"],["2024年","能登半島地震で再び被害を受ける"]],"who":[["瑩山紹瑾","總持寺をひらいた禅僧。曹洞宗では道元と並ぶ «両祖» の一人"],["峨山韶碩","2世。多くの弟子を育て、教えを全国に広めた"],["後醍醐天皇","總持寺に特別な寺の地位を与えたと伝わる"],["前田家","江戸時代、加賀藩主として寺を保護した"]],"deep":["曹洞宗では、福井の永平寺を開いた道元を «高祖»、總持寺を開いた瑩山を «太祖» とよび、二人を «両祖» としてまつります。","峨山韶碩は、總持寺と、瑩山のもうひとつの寺・永光寺（羽咋市）の住職を兼ね、二つの寺の間の山道を毎朝行き来したと伝わり、その道は «峨山道» とよばれます。","總持寺と永平寺は、江戸時代にともに曹洞宗の大本山とされ、どちらが上かをめぐって争った時期もありました。","祖院の建物の多くは明治の火事のあとに再建されたもので、山門や仏殿など多くの建物が国の登録有形文化財になっています。","門前町の名は、文字どおり «總持寺の門前» の町であったことに由来します。"],"look":["山門と仏殿（修復の状況は訪問前に確認を）","長い回廊と伽藍の配置","門前町の町並み","峨山道の伝承"],"q":["總持寺の本山は、明治時代にどこへ移った?","神奈川県横浜市の鶴見。1898年の火事がきっかけで、1911年に移りました。"],"koji":[],"myth":"後醍醐天皇の綸旨の真偽、峨山道を一晩で往復した話は伝承・諸説。","img":["總持寺","瑩山紹瑾","峨山韶碩"],"wp":"總持寺祖院","rel":{"ev":[],"grave":[]},"ph":[["c:9/92/Souijisoinnsoudou.jpg",4000,3000,"總持寺祖院"],["c:9/9a/Soujjisoinsnmon.jpg",4000,3000],["c:2/28/Soujijisoinhatou.jpg",4000,3000],["c:5/57/Soujijisoinbutuden.jpg",4000,3000],["c:6/69/Soujijisoin_Temple_in_Wajima_with_its_gate.jpg",4896,3672],["c:5/5f/Souijisoinkyouzou.jpg",4000,3000],["c:b/b7/Kwasyouzu.jpg",4000,3000],["c:f/fe/S%C5%8Djiji_Daisodo_2009.jpg",3498,2256,"總持寺"]]},{"id":"17_suemori","n":"末森城（末森城の戦い）","yomi":"すえもりじょう","cat":"古戦場","rank":"S","y":1584,"era":["azuchi"],"sh":"","ad":"羽咋郡宝達志水町南吉田","st":"JR七尾線の最寄り駅から車で約10分。登山口から本丸まで歩いて約30分","la":36.823,"lo":136.778,"hook":"1万を超える大軍に囲まれた城を、わずかな兵で守り抜いた。前田家の運命を決めた一戦。","lead":"末森城は、加賀と能登の境にあった山城です。1584年、越中の佐々成政が大軍で攻めよせましたが、城将の奥村永福がよく守り、金沢から駆けつけた前田利家が成政軍を破りました。この勝利で、前田家は北陸での立場を固めました。","story":["1584年、天下は羽柴秀吉と、徳川家康・織田信雄の二つに分かれて争っていました（小牧・長久手の戦い）。北陸では、秀吉方の前田利家と、家康方についた越中の佐々成政が向かい合います。成政が狙ったのは、加賀と能登をつなぐ要の城・末森城でした。","9月、成政は1万5千ともいわれる大軍で末森城を囲みました。城を守るのは奥村永福。兵はわずか千数百人ほどだったといいます。城はたちまち追いつめられ、二の丸まで攻めこまれました。永福の妻は、城内を見回って兵たちに粥をふるまい、励ましたと伝わります。","知らせを受けた利家は、金沢で迷っていました。«敵は大軍、こちらは少ない…»。このとき妻のまつが、«日ごろから金銀をためこんでいるのだから、その金銀に槍を持たせて戦わせればよい» と言って、利家を奮い立たせたという逸話があります。","利家はわずかな兵をひきいて夜のうちに出発し、海ぞいの道を進んで、夜明けに成政軍の背後を突きました。城からも永福の兵が打って出ます。挟みうちにされた成政軍はくずれ、越中へ引き上げました。«前田は小勢で大軍を破った»。この勝利は、秀吉にも高く評価されました。","その翌年、秀吉は大軍で越中を攻め、成政は降伏します。やがて越中の多くも前田家のものとなり、«加賀百万石» への道が開かれました。今、末森山には本丸などの曲輪の跡が残り、頂上からは日本海と邑知潟方面が見わたせます。"],"tl":[["1584年3月","小牧・長久手の戦いが始まる"],["1584年9月","佐々成政が末森城を包囲"],["1584年9月","前田利家が救援に駆けつけ、成政軍を破る"],["1585年","秀吉が越中を攻め、成政が降伏"],["その後","末森城は廃城となる"]],"who":[["前田利家","加賀の大名。夜通し駆けつけて末森城を救った"],["奥村永福","末森城の城将。少ない兵で城を守り抜いた"],["佐々成政","越中の大名。家康方として末森城を攻めた"],["まつ（芳春院）","利家の妻。出陣をためらう利家をはげましたと伝わる"]],"deep":["両軍の兵力は記録によってまちまちで、佐々軍を1万5千、前田軍の救援を2千5百前後とする説が一般的ですが、正確な数はわかりません。","まつの «金銀に槍を持たせよ» という逸話は、江戸時代にまとめられた前田家の記録などに見えるもので、後世の脚色の可能性もあります。","佐々成政は、この翌年の冬に厳冬の北アルプスを越えて家康に会いに行った «さらさら越え» の伝説でも知られます。","末森城は海に近い末森山の上にあり、本丸・二の丸・三の丸などの曲輪が段々に並んでいたと考えられています。","この戦いで活躍した奥村家は、のちに加賀藩の重臣 «八家» の一つとして続きました。","末森城は、加賀から能登へ入る道と、海ぞいの道をおさえる場所にありました。ここを取られると能登と加賀が分断されるため、成政にとっても利家にとっても、どうしても譲れない城だったのです。"],"look":["本丸跡からの日本海の眺め","段々に並ぶ曲輪の跡","登山道の案内板と戦いの説明板"],"q":["末森城を守った城将は誰?","奥村永福。わずかな兵で大軍の攻撃に耐え、利家の救援を待ちました。"],"koji":[],"myth":"両軍の兵力、まつや永福の妻の逸話は後世の記録による伝承。","img":["前田利家","佐々成政","奥村永福"],"wp":"末森城の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:4/4e/Suemori_Castle.jpg",600,450,"末森城の戦い"],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:3/38/Sassa_Narimasa.JPG",408,484,"佐々成政"],["c:e/e2/Okumura_Nagatomi.jpg",1976,4228,"奥村永福"]]},{"id":"17_tedorigawa","n":"手取川の戦い（上杉謙信 vs 織田軍）","yomi":"てどりがわのたたかい","cat":"古戦場","rank":"S","y":1577,"era":["azuchi"],"sh":"","ad":"白山市（手取川流域）","st":"JR北陸線 美川駅・小舞子駅方面から車で約10〜20分（川ぞいに碑がある）","la":36.493,"lo":136.555,"hook":"«上杉に逢うては織田も手取川»。軍神・謙信と織田軍がぶつかったとされる、唯一の戦い。","lead":"手取川の戦いは、1577年、加賀の手取川で上杉謙信の軍が織田信長の軍を破ったとされる戦いです。謙信と信長の軍が直接ぶつかったのは、これが唯一といわれます。ただし、戦いの規模については研究者の間で意見が分かれています。","story":["1577年、上杉謙信は能登の七尾城を包囲していました。城を守る長氏は、織田信長に助けを求めます。信長はこれにこたえ、柴田勝家を大将に、羽柴秀吉・丹羽長秀・滝川一益ら、そうそうたる武将をつけた大軍を北陸へ送りました。","ところが途中で、秀吉が勝家と作戦をめぐって対立し、勝手に軍を引き上げてしまったと伝わります。信長は激怒したといいます。さらに悪いことに、織田軍が加賀に入ったころ、七尾城はすでに落城していました。«助けるはずの城が、もうない»。織田軍はそれを知らないまま進んでいたともいわれます。","七尾城を落とした謙信は、すばやく南へ向かいました。織田軍は手取川を渡ったあとで七尾城落城を知り、あわてて引き返そうとします。そこへ謙信の軍が襲いかかりました。夜の闇の中、雨で水かさの増した手取川を渡ろうとした織田軍の兵が、多く流されたと伝わります。","謙信は手紙の中で、«信長の軍は思っていたより弱い。この分なら天下を取るのも心配ない» といった意味のことを書いています。そして京の人びとは、«上杉に逢うては織田も手取川 はねる謙信 逃ぐるとぶ長» という落首（皮肉の歌）を作ってはやしたといいます。","しかし、この戦いを大きな合戦として記す信頼できる史料は多くありません。«本当は小さな戦いだったのでは?» という見方もあります。謙信は翌年春、次の遠征を前に急死しました。手取川の流れは、戦国の «もしも» を静かに運び続けています。"],"tl":[["1576年","上杉謙信が能登へ攻め込む"],["1577年8月","柴田勝家らの織田軍が北陸へ向かう。秀吉が離脱"],["1577年9月","七尾城が落城"],["1577年9月","手取川で上杉軍が織田軍を破ったとされる"],["1578年3月","上杉謙信が急死"]],"who":[["上杉謙信","越後の大名。七尾城を落とし、手取川で織田軍を破ったとされる"],["柴田勝家","織田軍の総大将として北陸へ出陣"],["羽柴秀吉","勝家と対立し、途中で軍を引き上げたと伝わる"],["織田信長","援軍を送ったが、謙信との直接対決にはのぞまなかった"]],"deep":["戦いの根拠のひとつは、謙信が家臣に送った書状で、«千余人を討ち取った» などと書かれています。ただし、勝った側の手紙なので誇張の可能性も指摘されています。","織田方の記録『信長公記』には、この戦いの大敗のようすははっきり書かれていません。このため «大規模な戦闘はなかった» とする説もあります。","秀吉が無断で帰った理由は、勝家との作戦の対立といわれますが、詳しいことはわかっていません。帰国後、秀吉は信長に叱られたと伝わります。","落首の «はねる謙信 逃ぐるとぶ長» は、«はねる» に «跳ねる»、«とぶ長» に «信長» をかけた言葉遊びです。","手取川は白山を水源とする急流で、昔から «暴れ川» として知られ、洪水をくりかえしてきました。"],"look":["手取川古戦場の碑（川ぞい）","手取川の広い河原と流れ","晴れた日に見える白山の山並み"],"q":["手取川の戦いで、織田軍から途中で帰ってしまったとされる武将は?","羽柴秀吉。総大将の柴田勝家と対立し、勝手に軍を引き上げたと伝わります。"],"koji":[{"w":"上杉に逢うては織田も手取川","m":"戦いのあとに作られたという落首。謙信の強さと織田軍の敗走をからかった"}],"myth":"戦いの規模や実態、秀吉の離脱の理由、落首は諸説・伝承。碑の場所は推定地。","img":["上杉謙信","柴田勝家","手取川"],"wp":"手取川の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Tedorigawayuki.jpg",640,480,"手取川の戦い"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"],["c:0/0c/Shibata_Katsuie_large.jpg",1386,2965,"柴田勝家"]]},{"id":"17_kurikara","n":"倶利伽羅峠（木曾義仲の火牛の計）","yomi":"くりからとうげ","cat":"古戦場","rank":"S","y":1183,"era":["heian"],"sh":"","ad":"河北郡津幡町倶利伽羅","st":"IRいしかわ鉄道 倶利伽羅駅から歩いて約1時間（車が便利）","la":36.67,"lo":136.833,"hook":"角にたいまつを結んだ牛の群れが、夜の平家の陣へ! 源平合戦の流れを変えた峠。","lead":"倶利伽羅峠は、今の石川県と富山県の境にある峠です。1183年、ここで木曾義仲の軍が平家の大軍を破りました。牛の角にたいまつを付けて敵陣に突っこませた «火牛の計» の話が有名ですが、これは後の軍記物語に出てくる話です。","story":["1183年、平家は源氏をたおすため、平維盛を大将に大軍を北陸へ送りました。『平家物語』には «十万余騎» とあります。迎え撃つのは、信濃の木曾で挙兵した源義仲、いわゆる木曾義仲です。","両軍は、加賀と越中の境にある砺波山の倶利伽羅峠で向かい合いました。義仲は、昼間は小ぜりあいだけで時間をかせぎ、平家軍を峠の上にとどめます。«夜まで待て»。そのあいだに、ひそかに兵を回りこませていました。","夜になると、義仲の軍はいっせいに攻めかかりました。『源平盛衰記』には、このとき角にたいまつを結んだ牛を何百頭も放ち、平家の陣へ突進させたと書かれています。これが有名な «火牛の計» です。«本当に牛を使ったの?» この話は『平家物語』にはなく、中国の古い兵法の話をもとにした脚色ではないかともいわれています。","暗闇の中、前後から攻められた平家軍は大混乱。逃げ道を求めて、深い谷へ次々と落ちていったと『平家物語』は伝えます。その谷は、のちに «地獄谷» ともよばれるようになりました。多くの命が失われた場所です。","この大勝利で義仲は勢いに乗り、加賀の篠原でも平家を破って、この年の夏には京へ入りました。けれども都での義仲の栄光は長く続かず、翌年、源義経らに討たれます。今の峠には、火牛の像や源平の史跡、倶利伽羅不動寺があり、春には八重桜が咲きます。"],"tl":[["1180年","源頼朝・木曾義仲らが平家打倒の兵を挙げる"],["1183年5月11日（旧暦）","倶利伽羅峠の戦い。義仲が平維盛の軍を破る"],["1183年6月","篠原の戦い。義仲がふたたび平家を破る"],["1183年7月","義仲が京へ入る。平家は都を落ちる"],["1184年1月","義仲が粟津で討たれる"],["1689年","松尾芭蕉が『おくのほそ道』の旅で峠を越える"]],"who":[["木曾義仲（源義仲）","信濃の源氏。夜襲で平家の大軍を破った"],["平維盛","平清盛の孫。平家軍の総大将"],["今井兼平","義仲の乳兄弟で重臣。義仲とともに戦った"],["巴御前","義仲に従った女武者として『平家物語』に登場する"]],"deep":["«火牛の計» は、中国の戦国時代に斉の田単が牛の尾に火をつけて敵を破ったという『史記』の話と似ており、それをまねた脚色と考えられています。","『平家物語』の «十万余騎» は誇張で、実際の平家軍はもっと少なかったと考えられています。","峠の上には平家が陣を置いたとされる «猿ヶ馬場» があり、源平の武将の名を記した碑などが並びます。","倶利伽羅の名は、不動明王の化身である «倶利伽羅竜王» に由来するといわれ、峠には倶利伽羅不動寺があります。","峠道は古代・中世の北陸道の一部で、江戸時代には加賀藩の参勤交代の道としても使われました。"],"look":["火牛の像","猿ヶ馬場（平家の本陣跡とされる）の碑群","倶利伽羅不動寺と峠からの眺め","春の八重桜","旧北陸道の山道（歩きやすい靴で）"],"q":["«火牛の計» が書かれているのは『平家物語』? それとも『源平盛衰記』?","『源平盛衰記』。『平家物語』には牛の話は出てきません。"],"koji":[],"myth":"火牛の計は『源平盛衰記』による脚色とみられる。兵力や地獄谷の話も軍記物の記述。","img":["源義仲","平維盛","倶利伽羅峠"],"wp":"倶利伽羅峠の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:c/c6/Battle_of_Kurikaradani_Kassen_Zu.jpg",8498,4293,"倶利伽羅峠の戦い"],["c:4/4e/Honden_shirayama_hime_shrine_ishikawa.jpg",750,500],["j:f/ff/Kiso-Yoshinaka%26Tomoe-gozen_statue_Kiso-t.jpg",480,640],["c:2/27/Minamoto_no_Yoshinaka.jpg",843,767,"源義仲"],["c:6/6a/Taira_no_Koremori.jpg",283,283,"平維盛"]]},{"id":"17_chikamori","n":"チカモリ遺跡（環状木柱列）","yomi":"ちかもりいせき","cat":"遺跡","rank":"A","y":-1000,"era":["jomon"],"sh":"国指定史跡","ad":"金沢市新保本町","st":"JR金沢駅から車で約15分。路線バスで近くまで行くこともできる","la":36.587,"lo":136.6075,"hook":"田んぼの下から、巨大なクリの柱の根が円をえがいて出てきた。縄文人は何のために柱を立てたのか。","lead":"チカモリ遺跡は、金沢市の西部、平野の中にある縄文時代後期から晩期の遺跡です。クリの大木を半分に割った柱を、円形にならべて立てた «環状木柱列» の根が見つかり、全国に知られるようになりました。今は遺跡公園として整備されています。","story":["1980年、金沢市の区画整理にともなう発掘調査で、ふしぎなものが見つかりました。水をふくんだ土の中に、太い木の柱の根元がいくつも残っていたのです。しかも、それらはきれいな円をえがくように並んでいました。","«これは何だ?» 調べてみると、柱はクリの丸太を縦に半分に割ったもので、太いものは直径80cmを超えていました。今から約3000年前後、縄文時代の終わりごろに立てられたものと考えられています。柱の輪は、場所を少しずつずらしながら何度も建て替えられていたこともわかりました。","縄文人は、石の斧しか持っていません。それでこんなに太いクリの木を切り倒し、割り、運び、深い穴を掘って立てたのです。«どれだけの人が力を合わせたのだろう»。一本の柱を立てるにも、村じゅう、あるいはいくつもの村の協力が必要だったはずです。","柱の輪が何のためのものだったかは、まだわかっていません。屋根のある建物だったという説、祭りや儀式の場だったという説などがあります。柱の割った面の向きや、輪の入り口のような部分から、ある方向を大切にしていたのでは、と考える研究者もいます。","チカモリ遺跡の発見のあと、能登の真脇遺跡などでも同じような柱の輪が見つかり、«北陸の縄文文化の特徴» として注目されるようになりました。今は公園の中に柱の輪が復元され、資料館で本物の柱根を見ることができます。"],"tl":[["約4000〜2500年前","縄文時代後期〜晩期、村が営まれる"],["約3000年前ごろ","環状木柱列がくりかえし建てられる"],["1980年","区画整理にともなう発掘で木柱根が見つかる"],["1987年","国の史跡に指定"],["その後","出土した木柱根が国の重要文化財に指定される"]],"who":[["チカモリの縄文人","クリの巨木で柱の輪をつくった人びと"],["金沢市の発掘調査団","1980年の調査で環状木柱列を発見した"]],"deep":["«チカモリ» は遺跡がある場所の小字（地名）からとられた名前です。","柱の輪は直径6〜7mほどで、10本前後の柱からなるものが多く、何度も場所をずらして建て替えられた跡が重なっています。","柱の根は地下水に守られて腐らずに残りました。北陸の低い平野の遺跡ならではの幸運です。","木柱列の性格については、大型の建物の柱だった説、柱だけを立てた祭りの施設だった説があり、決着していません。","真脇遺跡（能登町）、富山県の井口遺跡・桜町遺跡などでも同じような柱の輪が見つかり、日本海側の縄文文化のつながりがうかがえます。","近くの野々市市にある «御経塚遺跡» など、周辺にも縄文後期〜晩期の大きな遺跡があります。","柱を立てるための穴は深く掘られ、柱の根元には石や土をつめて固定した跡が見られるといわれます。重い柱をまっすぐ立てるための、縄文人の土木の知恵です。"],"look":["公園に復元された環状木柱列","資料館（チカモリ遺跡の出土品展示）の木柱根","平野の中の遺跡の立地"],"q":["チカモリ遺跡の柱は、何の木を割って作られていた?","クリ。太いクリの丸太を縦に半分に割って立てていました。"],"koji":[],"myth":"環状木柱列の用途や屋根の有無は推定で、諸説ある。","img":["環状木柱列","真脇遺跡","縄文時代"],"wp":"チカモリ遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/%E3%83%81%E3%82%AB%E3%83%A2%E3%83%AA%E9%81%BA%E8%B7%A1_%E7%92%B0%E7%8A%B6%E6%9C%A8%E6%9F%B1_-_panoramio.jpg",2592,1944,"チカモリ遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:f/f6/Mawaki_Site.jpg",1200,912,"真脇遺跡"]]},{"id":"17_nagamachi","n":"長町武家屋敷跡","yomi":"ながまちぶけやしきあと","cat":"町","rank":"A","y":1600,"era":["edo"],"sh":"","ad":"金沢市長町1丁目","st":"JR金沢駅からバスで約10分「香林坊」下車、歩いて約5分","la":36.5627,"lo":136.6493,"hook":"土塀と石畳の小路、そばを流れる用水。加賀藩の武士たちの暮らしの面影が、町の真ん中に残る。","lead":"長町武家屋敷跡は、金沢の繁華街・香林坊のすぐそばに残る、江戸時代の武士の屋敷町です。黄土色の土塀が続く細い道や、そばを流れる大野庄用水が昔の雰囲気を伝えています。中の屋敷の一部は公開されていて、武士の暮らしをのぞくことができます。","story":["加賀藩の城下町・金沢では、城のまわりに武士の屋敷がたくさんつくられました。長町は、城から少し離れた犀川寄りの場所で、中級・下級の藩士たちが住んだ町です。«城に何かあればすぐ駆けつけられるように»。屋敷は城下のあちこちに配置されていました。","町の道は細く、くねくねと曲がっています。«なぜまっすぐにしなかったの?» 敵が攻めてきたとき、まっすぐ城へ進めないようにするためだったといわれます。行き止まりや鍵の手（直角の曲がり角）も、城下町ならではの工夫です。","長町を歩くと、そばを流れる用水に気づきます。これが «大野庄用水»。金沢で最も古い用水のひとつといわれ、犀川から水を引いて、物を運んだり、火事にそなえたりするのに使われました。屋敷の庭に水を引き入れているところもあります。","冬になると、土塀に «こも» というわらのむしろが掛けられます。雪や凍結で土塀がくずれないようにするためです。この «こも掛け» は、金沢の冬の始まりを告げる風景になっています。","明治になり武士の世が終わると、多くの屋敷は売られたり建て替えられたりしました。それでも長町には土塀や門が残り、町の人びとが大切に守ってきました。今は «野村家» や «足軽資料館» などを見学でき、上級武士と足軽の暮らしのちがいを比べることができます。"],"tl":[["1583年以降","前田利家の入城後、城下町づくりが進む"],["江戸時代","中級・下級藩士の屋敷町として整う"],["1871年","廃藩置県で武士の身分がなくなる"],["昭和時代","金沢市が伝統的な町並みの保存に取り組む"],["現在","野村家・足軽資料館などが公開される"]],"who":[["加賀藩の藩士たち","長町に屋敷を構えて暮らした中級・下級の武士"],["野村伝兵衛","前田利家に仕えたと伝わる野村家の初代"],["足軽","藩の下級の兵士。足軽資料館で暮らしぶりがわかる"]],"deep":["大野庄用水は、天正年間（1570〜90年代）ごろにつくられたともいわれ、城の建設に使う木材を運んだという説もあります。","«野村家» の屋敷は、明治以降に移り住んだ人が手を加えたもので、庭園は用水の水を引き入れた曲水が見どころです。建物の一部は北前船の豪商の屋敷から移したものといわれます。","«金沢市足軽資料館» は、もともと別の場所にあった足軽の家を移築したもの。庭付きの一戸建てで、足軽でも独立した家を持っていたことがわかります。","近くの «前田土佐守家資料館» は、前田利家の次男・利政の流れをくむ家に伝わる資料を展示しています。","こも掛けは、例年12月ごろに行われ、翌年3月ごろに外されます。","長町の屋敷は、身分によって敷地の広さや門の形が決められていました。立派な長屋門をもつ屋敷は比較的身分の高い武士、簡素な門は下級武士というように、門を見れば住む人の格がわかったのです。"],"look":["土塀と石畳が続く小路","大野庄用水の流れ","野村家の庭園","金沢市足軽資料館","冬の «こも掛け»"],"q":["冬に長町の土塀に掛けられるわらのむしろを何という?","«こも»。雪や凍結から土塀を守るために掛けられます。"],"koji":[],"myth":"曲がった道が防衛のためという説明や、大野庄用水の成立年代は諸説。","img":["大野庄用水","金沢城","香林坊"],"wp":"長町武家屋敷跡","rel":{"ev":[],"grave":[]},"ph":[["c:2/24/Nagamachi_Bukeyashiki.jpg",1600,1200,"長町武家屋敷跡"],["c:e/e2/%E9%95%B7%E7%94%BA%E6%AD%A6%E5%AE%B6%E5%B1%8B%E6%95%B7%E8%B7%A1_-_%E8%96%A6%E6%8E%9B%E3%81%91.jpg",3264,2448],["c:0/09/%E9%95%B7%E7%94%BA%E6%AD%A6%E5%AE%B6%E5%B1%8B%E6%95%B7%E8%B7%A1_-_%E6%97%A7%E5%8A%A0%E8%B3%80%E8%97%A9%E5%A3%AB%E9%AB%98%E7%94%B0%E5%AE%B6%E8%B7%A1%E5%85%A5%E5%8F%A3.jpg",3264,2448],["c:7/7e/Kanazawa-M-5932.jpg",1500,1000,"金沢城"],["c:b/b2/K%C5%8Drinb%C5%8D_Crossing.jpg",2048,1530,"香林坊"]]},{"id":"17_oyama","n":"尾山神社（前田利家を祀る・ギヤマンの神門）","yomi":"おやまじんじゃ","cat":"寺社","rank":"A","y":1873,"era":["meiji"],"sh":"国の重要文化財（神門）","ad":"金沢市尾山町","st":"JR金沢駅からバスで約10分「南町・尾山神社」下車、歩いて約3分","la":36.5639,"lo":136.6548,"hook":"和風の石段の上に、ステンドグラスの窓が光る門。明治の金沢が生んだ、和と洋がまじりあう不思議な神社。","lead":"尾山神社は、加賀藩の祖・前田利家と、妻のまつをまつる神社です。明治時代に創建され、ステンドグラスをはめこんだ和漢洋折衷の神門で有名です。この神門は国の重要文化財に指定されています。","story":["前田利家が亡くなったあと、息子の利長は父をまつる社を建てたいと考えました。けれども徳川家の目を気にして、はっきり «利家の神社» とはせず、卯辰山のふもとの八幡社に、ひそかに父をまつったといわれます。","明治時代になり、徳川の世が終わると、旧加賀藩の人びとは «藩祖をきちんとおまつりしよう» と考えました。1873年、金沢城の近くの «金谷御殿» の跡地に社を移し、名前を «尾山神社» としました。«尾山» とは、金沢城のあった丘の古い名前です。","1875年に完成した神門は、町の人びとを驚かせました。1階と2階は石と木で造られた和風と中国風の門。ところが、一番上の3階には色とりどりのガラス «ギヤマン» がはめこまれていたのです。«これは神社の門なのか、西洋の教会なのか?» 人びとは目を丸くしたことでしょう。","3階には避雷針もつけられ、夜は明かりをともして灯台の役目もしたといわれます。設計したのは、金沢の大工・津田吉之助。西洋の建物をほとんど見たことがなかったかもしれない大工が、新しい時代の空気を形にしたのです。","境内の奥には、金谷御殿の庭をもとにした池泉回遊式の神苑があり、池には琵琶や琴などの楽器をかたどった島が浮かびます。本殿の東にある東神門は、金沢城の二の丸から移された唐門だと伝わります。明治の新しさと藩政時代の記憶が、ひとつの境内に同居しているのです。"],"tl":[["1599年","前田利家が死去"],["江戸時代","卯辰八幡社で利家がひそかにまつられたと伝わる"],["1873年","金谷御殿跡に社を移し、尾山神社とする"],["1875年","ステンドグラスのある神門が完成"],["昭和時代","神門が国の重要文化財に指定される"]],"who":[["前田利家","加賀藩の祖。尾山神社の祭神"],["まつ（芳春院）","利家の妻。あわせてまつられている"],["前田利長","利家の長男。父をまつる社を建てたと伝わる"],["津田吉之助","金沢の大工。神門を設計したとされる"]],"deep":["神門は3層構造で、1層目が石造のアーチ、2・3層目が木造。和・漢・洋の要素がまじった «和漢洋折衷» 様式の代表例です。","神門の最上層のギヤマンは、日本のステンドグラスとしてもかなり早い例といわれますが、当初のガラスがどれだけ残っているかははっきりしません。","神門の避雷針は、日本最古級の避雷針ともいわれます。","東神門は金沢城二の丸御殿の唐門を移したものと伝わり、«竜が彫られていて火事を防いだ» という伝説があります。","神苑は、もとの金谷御殿（藩主の隠居所などに使われた）の庭の名残をとどめるといわれます。","神門の3層目のギヤマンは赤・青・黄・緑などの色ガラスで、夕方から夜にかけて明かりがともると、町から見上げた人びとの目に美しく映ったといわれます。今も夜のライトアップで見ることができます。"],"look":["ステンドグラスの神門（夜のライトアップも）","利家の騎馬像と、まつの像","東神門（金沢城から移されたと伝わる唐門）","池泉回遊式の神苑"],"q":["尾山神社の神門の3階には、何がはめこまれている?","色とりどりのギヤマン（ステンドグラス）。避雷針もついています。"],"koji":[],"myth":"江戸時代にひそかに利家をまつった話、灯台として使われた話、東神門の由来は伝承。","img":["前田利家","芳春院","金沢城"],"wp":"尾山神社","rel":{"ev":["sankin","basho"],"grave":[]},"ph":[["c:0/0c/Ishikawa_Kanazawa_Oyama03.jpg",2816,2120,"尾山神社"],["c:1/1e/Oyama-jinja%2C_shinmon.jpg",5568,3712],["c:0/06/Oyama_jinja_higashi_shin_mon.jpg",2048,1536],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:4/4b/H%C5%8Dshun-in_%28Matsu%29.jpg",4480,5280,"芳春院"],["c:7/7e/Kanazawa-M-5932.jpg",1500,1000,"金沢城"]]},{"id":"17_myoryuji","n":"妙立寺（忍者寺）","yomi":"みょうりゅうじ","cat":"寺社","rank":"A","y":1643,"era":["edo"],"sh":"","ad":"金沢市野町1丁目","st":"JR金沢駅からバスで約15分「広小路」下車、歩いて約5分（見学は電話予約制）","la":36.556,"lo":136.6493,"hook":"外から見ると2階建て、中に入ると迷路のような4階建て。隠し階段と落とし穴だらけの «忍者寺»。","lead":"妙立寺は、金沢の寺町にある日蓮宗の寺です。建物の中に隠し階段や落とし穴、隠し部屋がたくさんあり、«忍者寺» とよばれています。ただし忍者と直接の関係はありません。見学は電話での予約制で、案内の人と一緒に回ります。","story":["1643年、加賀藩3代藩主・前田利常は、金沢城の中にあった祈願所を、犀川の南の寺町に移しました。これが今の妙立寺です。«なぜわざわざ移したの?» ここには、ある大きな狙いがあったといわれています。","当時、幕府は «城を勝手に増やしたり、高い建物を建てたりしてはいけない» と、大名を厳しく見張っていました。加賀藩は日本一大きな藩。幕府に疑われれば取りつぶされるかもしれません。利常は «鼻毛をのばして、わざとおろかなふりをした» という話が残るほど、用心深い殿様でした。","妙立寺の本堂は、外から見ると2階建てです。ところが中に入ると、階段を上ったり下りたりするうちに、いったい何階にいるのかわからなくなります。中は4階建て7層ともいわれる複雑なつくりで、部屋は約29、階段は約23もあるといわれます。","お賽銭箱の下が落とし穴になった «落とし穴階段»、壁のように見える隠し階段、外から見えない物見の部屋…。«お寺なのになぜこんな仕掛けが?» いざというときに城下の南を守る出城や、見張りの役目を持たせていたのではないか、と考えられています。","寺町のあたりには、たくさんの寺が集められ、城下の守りの一部になっていたともいわれます。妙立寺の仕掛けは、見ためはのどかな寺町に隠された、加賀藩のしたたかさを物語っているのかもしれません。寺町一帯は国の重要伝統的建造物群保存地区にも選ばれています。"],"tl":[["1643年","前田利常が祈願所を寺町に移し、妙立寺とする"],["江戸時代","複雑なつくりの本堂が整えられる"],["昭和時代","«忍者寺» の名で知られるようになる"],["2012年","寺町一帯が «寺町台» として重要伝統的建造物群保存地区に"]],"who":[["前田利常","加賀藩3代藩主。妙立寺をこの地に移した"],["日蓮宗の僧たち","寺を守り、今も祈りと見学の案内を続ける"]],"deep":["«忍者寺» はあくまで通称で、忍者が住んでいたわけではありません。仕掛けの多いつくりが忍者屋敷を思わせることから付いた名前です。","本堂の «4階建て7層» は、中二階のような空間を数えた言い方で、数え方によって表現が変わります。","本堂の屋根の上には «望楼»（見張り台）があり、かつては金沢の町や遠くの海を見わたせたともいわれます。","寺の井戸は «金沢城までつながる抜け穴になっている» という伝説がありますが、確かめられていません。","前田利常の «鼻毛の殿様» の逸話は、幕府に油断させるためにわざとおろかに見せたという話で、江戸時代の随筆などに伝わります。","妙立寺の本堂は、金沢城に近い寺町の台地の上にあり、犀川をはさんで城下の南の入口を見わたせる位置にあります。寺町に寺を集めたこと自体が、城下の南の守りを固めるためだったとする説もあります。"],"look":["落とし穴階段（賽銭箱の下）","隠し階段と隠し部屋","見張りの部屋と望楼（外から）","寺町の寺院群の町並み"],"q":["妙立寺はなぜ «忍者寺» とよばれる?","隠し階段や落とし穴などの仕掛けがたくさんあるため。忍者と直接の関係はありません。"],"koji":[],"myth":"出城・見張りとしての役割、城への抜け穴、利常の鼻毛の逸話は伝承・推測。","img":["前田利常","寺町寺院群"],"wp":"妙立寺 (金沢市)","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Maeda_Toshitsune.png",1294,1725,"前田利常"],["c:f/f5/Kanazawa_Nodamichi_20160618.jpg",5456,3632,"寺町寺院群"],["c:e/e5/Katamachi_Kirara.jpg",3456,2304,"近く: 大和 (百貨店)"],["c:7/7c/Nomachi_Station_2020.jpg",3456,2304,"近く: 野町駅"],["c:8/86/Ninja-dera_1.jpg",4320,3240,"近く: 妙立寺"],["c:e/e1/LABBRO_Katamachi.jpg",2128,2832,"近く: ラブロ片町"],["c:4/42/Fushimiji.jpg",4608,3456,"近く: 伏見寺"],["c:7/7c/Saigawaohashi004.jpg",3861,2574,"近く: 犀川大橋"]]},{"id":"17_natadera","n":"那谷寺","yomi":"なたでら","cat":"寺社","rank":"A","y":717,"era":["nara","heian","edo"],"sh":"国の重要文化財（本殿・三重塔など）・国の名勝（庭園）","ad":"小松市那谷町","st":"JR加賀温泉駅または小松駅からバスで約40分「那谷寺」下車すぐ","la":36.3295,"lo":136.534,"hook":"«石山の石より白し秋の風»。芭蕉が詠んだ白い岩山の寺は、洞窟の中に本殿がある。","lead":"那谷寺は、小松市の山あいにある真言宗の寺です。奈良時代に泰澄がひらいたと伝わり、白い岩山と洞窟、紅葉の美しさで知られます。江戸時代に前田利常が再興し、本殿や三重塔などが国の重要文化財になっています。","story":["奈良時代の717年、白山をひらいた僧・泰澄が、この岩山に観音さまをまつったのが始まりと伝わります。はじめは «岩屋寺» とよばれていました。ごつごつとした白い岩が重なる山は、昔の人にとって神や仏が宿る特別な場所に見えたのでしょう。","平安時代、花山法皇がこの寺を訪れ、名前を «那谷寺» に改めたといわれます。«那谷ってどういう意味?» 西国三十三所の観音霊場のうち、1番の那智山（青岸渡寺）の «那» と、33番の谷汲山（華厳寺）の «谷» をとったのだそうです。ここにお参りすれば、三十三所すべてをめぐったのと同じ功徳がある、という意味がこめられています。","しかし戦国時代、加賀の一向一揆などの戦乱の中で、寺はすっかり荒れてしまいました。この寺を立て直したのが、加賀藩3代藩主・前田利常です。1640年ごろ、利常は本殿や三重塔、護摩堂などを次々と建てました。これらの建物が、今も境内に残っています。","本殿は、岩山の洞窟を利用した «岩屋» の中にあります。胎内くぐりのように暗い岩屋を抜けると、生まれ変わって清らかになる、と信じられてきました。三重塔は岩山の上に立ち、細かな彫刻がほどこされています。","1689年、『おくのほそ道』の旅の途中で松尾芭蕉がここを訪れ、«石山の 石より白し 秋の風» と詠みました。白く輝く岩山と、秋の風の冷たさ。その句碑が境内に立っています。今も秋には紅葉が岩山を彩り、多くの人が芭蕉と同じ景色を見に訪れます。"],"tl":[["717年","泰澄が観音をまつり、岩屋寺をひらいたと伝わる"],["平安時代","花山法皇が訪れ、那谷寺と名付けたと伝わる"],["戦国時代","戦乱で荒廃する"],["1640年ごろ","前田利常が本殿・三重塔などを再建"],["1689年","松尾芭蕉が訪れ «石山の石より白し秋の風» と詠む"]],"who":[["泰澄","白山をひらいた奈良時代の僧。那谷寺の開山と伝わる"],["花山法皇","平安時代の天皇。寺の名を那谷寺と改めたと伝わる"],["前田利常","加賀藩3代藩主。荒れた寺を再興した"],["松尾芭蕉","俳人。『おくのほそ道』の旅で訪れ、句を残した"]],"deep":["利常が再建した本殿・拝殿、三重塔、護摩堂、鐘楼、書院などが国の重要文化財に指定されています。","境内の «奇岩遊仙境» は、海底の火山活動でできた凝灰岩が長い年月で浸食されたもの。岩山と庭園は国の名勝に指定されています。","芭蕉の句の «石山» は、近江の石山寺の石を指すとする説と、那谷寺の岩山そのものを指すとする説があります。","花山法皇が西国三十三所をめぐったという話は、三十三所巡礼を広めた人物として語られる伝説で、史実かどうかははっきりしません。","那谷寺は真言宗別格本山で、白山信仰とも深いつながりを持っています。"],"look":["奇岩遊仙境の白い岩山","岩屋の中の本殿（胎内くぐり）","岩山の上の三重塔","芭蕉の句碑","秋の紅葉"],"q":["«那谷寺» の名前は、どの二つの寺からとられた?","西国三十三所の1番・那智山と、33番・谷汲山。«那» と «谷» をとったと伝わります。"],"koji":[{"w":"石山の石より白し秋の風","m":"芭蕉の句。白い岩山と秋風の冷たさ、さびしさを重ねて詠んだ"}],"myth":"泰澄の開山、花山法皇の命名は伝承。句の «石山» の解釈は諸説。","img":["泰澄","前田利常","おくのほそ道"],"wp":"那谷寺","rel":{"ev":[],"grave":[]},"ph":[["c:1/15/260719_Natadera_Komatsu_Ishikawa_pref_Japan27s3.jpg",5472,3648,"那谷寺"],["c:0/08/260719_Natadera_Komatsu_Ishikawa_pref_Japan63s3.jpg",5472,3648],["c:1/17/260719_Natadera_Komatsu_Ishikawa_pref_Japan52s3.jpg",5472,3648],["c:c/c4/260719_Natadera_Komatsu_Ishikawa_pref_Japan43s4.jpg",5472,3648],["c:4/4f/260719_Natadera_Komatsu_Ishikawa_pref_Japan38s3.jpg",3500,5250],["c:f/fc/260719_Natadera_Komatsu_Ishikawa_pref_Japan19s3.jpg",5472,3648],["c:0/09/260719_Natadera_Komatsu_Ishikawa_pref_Japan10s3.jpg",5472,3648],["c:4/46/260719_Natadera_Komatsu_Ishikawa_pref_Japan07s3.jpg",5472,3648]]},{"id":"17_myojoji","n":"妙成寺（能登の日蓮宗大寺・五重塔）","yomi":"みょうじょうじ","cat":"寺社","rank":"A","y":1618,"era":["kamakura","edo"],"sh":"国の重要文化財（五重塔・本堂など10棟）","ad":"羽咋市滝谷町","st":"JR羽咋駅からバスで約15分「妙成寺口」下車、歩いて約10分","la":36.9395,"lo":136.78,"hook":"能登の田園に、すっと立つ五重塔。一人の側室の祈りが、北陸屈指の大伽藍を生んだ。","lead":"妙成寺は、羽咋市にある日蓮宗の寺です。鎌倉時代の終わりに日像がひらき、江戸時代のはじめに加賀藩の前田家の保護を受けて大きな伽藍が整いました。五重塔をはじめ10棟の建物が国の重要文化財に指定されています。","story":["鎌倉時代の終わりの1294年、日蓮の弟子の日像は、京都で教えを広める前に、北陸を回って布教していました。その途中、能登の滝谷で、真言宗の僧だった乗微という人物が日像に弟子入りし、寺をひらいたと伝わります。これが妙成寺の始まりです。","寺が大きく変わったのは江戸時代のはじめ。前田利家の側室で、3代藩主・前田利常の生母である寿福院が、この寺をあつく信仰しました。寿福院は日蓮宗の熱心な信者でした。«母のために»。利常は母の願いにこたえ、寺の建物を次々と建てていきます。","1618年に建てられた五重塔は、高さ約34m。能登で唯一の五重塔です。まわりは田んぼと山。高い建物がほとんどない中に、ぽつんと、しかし堂々と立つ塔の姿は、遠くからでもよく目立ちます。«なぜこんな静かな場所に、これほど立派な塔を?» そこには、加賀藩の力と母を思う心が重なっていたのでしょう。","境内には、本堂、祖師堂、二王門、鐘楼、経堂、三十番神堂など、江戸時代初期の建物がそろっています。これだけの建物がまとまって残る寺は、北陸ではとても貴重です。建物の配置は、山のふもとから斜面にそって、段々に並べられています。","境内の奥には寿福院の墓所もあり、今も利常の母を静かにしのぶことができます。春の桜、秋の紅葉の季節には、五重塔と自然が美しく重なります。能登の人びとは、この寺を «滝谷の妙成寺» とよんで親しんできました。"],"tl":[["1294年","日像の教えを受けた乗微が寺をひらいたと伝わる"],["江戸時代初め","寿福院が帰依し、前田利常が伽藍を整える"],["1618年","五重塔が建てられる"],["1600年代前半","本堂・祖師堂・二王門などが次々に建てられる"],["昭和時代","五重塔など10棟が国の重要文化財に"]],"who":[["日像","日蓮の孫弟子。京都で日蓮宗を広めた僧。妙成寺の開山とされる"],["寿福院","前田利家の側室で利常の母。寺をあつく信仰した"],["前田利常","加賀藩3代藩主。母の願いにこたえ伽藍を整えた"],["乗微","日像に帰依したとされる僧。寺の最初の住職と伝わる"]],"deep":["重要文化財の10棟には五重塔・本堂・祖師堂・二王門・鐘楼・経堂などがふくまれ、江戸時代初期の伽藍がまとまって残る例として評価されています。","五重塔は、初重に «ひさし» をつけた珍しい形とされ、塔の内部には日蓮の像などがまつられていると伝わります。","寿福院は、利常が徳川家から正室（珠姫）を迎えた後も、日蓮宗の寺を各地で支えたことで知られます。","本堂は畳が敷かれた大きな空間で、日蓮宗の寺院建築の特徴をよく示しているといわれます。","近年、妙成寺の建物群を国宝に指定する動きが報じられたことがあります。最新の指定状況は訪問前に確かめてください。","羽咋市には、同じく加賀藩ゆかりの氣多大社もあり、あわせてめぐることができます。"],"look":["五重塔（能登唯一）","本堂と祖師堂","二王門の仁王像","寿福院の墓所","田園の中に立つ伽藍の遠景"],"q":["妙成寺の伽藍を整えるきっかけとなった女性は?","寿福院。前田利家の側室で、3代藩主・前田利常の母です。"],"koji":[],"myth":"開創の経緯と乗微の話は寺伝。建物ごとの建立年には諸説ある。","img":["日像","寿福院","前田利常"],"wp":"妙成寺","rel":{"ev":[],"grave":[]},"ph":[["c:e/e1/Myojoji.jpg",600,800,"妙成寺"],["c:0/0b/Five-storied_Pagoda%2C_Myojo-ji_20170816140359.jpg",2750,3666],["c:b/b0/%E5%A6%99%E6%88%90%E5%AF%BA202306%E9%90%98%E6%A5%BC.jpg",2432,1824],["c:e/ee/%E5%A6%99%E6%88%90%E5%AF%BA202306%E7%B5%8C%E5%A0%82.jpg",2432,1824],["c:4/49/%E5%A6%99%E6%88%90%E5%AF%BA202306%E7%A5%96%E5%B8%AB%E5%A0%82.jpg",2432,1824],["c:c/c9/%E5%A6%99%E6%88%90%E5%AF%BA202306%E6%9C%AC%E5%A0%82.jpg",2432,1824],["c:8/8e/%E5%A6%99%E6%88%90%E5%AF%BA202306%E6%9B%B8%E9%99%A2.jpg",2432,1824],["c:3/39/%E5%A6%99%E6%88%90%E5%AF%BA202306%E5%BA%AB%E8%A3%8F.jpg",2432,1824]]},{"id":"17_shinohara","n":"篠原古戦場（斎藤実盛の最期・首洗池）","yomi":"しのはらこせんじょう","cat":"古戦場","rank":"A","y":1183,"era":["heian"],"sh":"","ad":"加賀市手塚町・篠原町付近","st":"JR加賀温泉駅から車で約15分（首洗池は片山津温泉の近く）","la":36.318,"lo":136.352,"hook":"白髪を墨で黒く染めて、老武者は最後の戦いにのぞんだ。首を洗うと、その髪は真っ白だった。","lead":"篠原は、1183年に木曾義仲の軍が平家の軍を破った «篠原の戦い» の地です。この戦いで、平家方の老武者・斎藤実盛が討たれました。実盛の首を洗ったと伝わる «首洗池» が残り、『平家物語』の名場面の舞台として知られます。","story":["倶利伽羅峠で大敗した平家の軍は、加賀へと逃れました。義仲の軍はそれを追い、篠原で再び戦いが起こります。平家の兵が次々と逃げていく中、ただ一騎、踏みとどまって戦う武者がいました。錦の直垂を着た、立派ないでたちの武者です。","義仲の家来・手塚光盛が «名を名のれ» と呼びかけても、武者は名を言いません。二人は組み合い、ついに光盛が武者を討ち取りました。首を見た義仲は «これは斎藤実盛ではないか。しかし実盛なら白髪のはず。髪が黒いのはなぜだ» と首をかしげます。","実盛を知る樋口兼光が呼ばれ、首を見て涙を流しました。«実盛は、年をとって戦に出るなら髪を黒く染めて若く見せたい、と言っていました»。近くの池で首を洗うと、墨が落ちて真っ白な髪があらわれました。このとき実盛は、七十歳を超えていたといわれます。","じつは実盛は、義仲の命の恩人でした。義仲が2歳のとき、父・源義賢が討たれ、幼い義仲も命を狙われました。そのとき、義仲を助けて信濃の木曾へ逃がしたのが実盛だったと『平家物語』は伝えます。«恩人を、自分の軍が討ってしまった»。義仲は涙を流したといいます。","実盛はなぜ錦の直垂を着ていたのか。故郷の越前に錦を着て帰る、という思いで、平家の主君に願い出て許されたのだと語られます。首洗池のほとりには、首を洗う場面の像と芭蕉の句碑が立ち、近くには実盛の塚も残ります。戦いで命を落とした人びとを静かに思う場所です。"],"tl":[["1155年ごろ","実盛が幼い義仲（駒王丸）を木曾へ逃がしたと伝わる"],["1183年5月","倶利伽羅峠の戦い。平家が大敗"],["1183年6月","篠原の戦い。斎藤実盛が討たれる"],["室町時代","世阿弥が能『実盛』をつくる"],["1689年","松尾芭蕉が小松の多太神社で実盛の兜を見て句を詠む"]],"who":[["斎藤実盛","平家方の老武者。白髪を染めて戦い、篠原で討たれた"],["木曾義仲","源氏の武将。幼いころ実盛に命を救われたと伝わる"],["手塚光盛","義仲の家来。実盛を討ち取った"],["樋口兼光","義仲の重臣。首が実盛だと見分けた"]],"deep":["実盛の年齢は『平家物語』に «七十に余る» とあり、73歳という説が広く知られていますが、確かな生年はわかりません。","世阿弥の能『実盛』は、篠原で遊行上人の前に実盛の霊が現れる話。室町時代に «篠原に実盛の霊が出た» といううわさが京で評判になったことが、作品の背景にあるとされます。","実盛は、稲を食い荒らす害虫の «実盛虫» の伝説でも知られ、各地の «虫送り» の行事で実盛の人形が使われてきました。稲の株につまずいて討たれた恨みが虫になった、という俗信です。","実盛は越前の生まれとされ、のちに武蔵の長井（今の埼玉県熊谷市あたり）を本拠にしました。","首洗池は、今の加賀市の柴山潟に近いあたりにあり、池の名前は実盛の伝承にちなんだものです。"],"look":["首洗池と、首を洗う場面の像","芭蕉の句碑 «むざんやな甲の下のきりぎりす»","実盛塚","近くの柴山潟と片山津温泉の風景"],"q":["斎藤実盛は、なぜ髪を黒く染めていた?","年寄りだとあなどられないよう、若く見せて戦うため。首を洗うと白髪があらわれたと伝わります。"],"koji":[{"w":"故郷へ錦を飾る","m":"出世して、立派な姿で故郷に帰ること。実盛が錦の直垂を着て戦った話と結びつけて語られる"}],"myth":"実盛の年齢、黒髪の話、義仲を助けた話は『平家物語』など軍記物による。実盛虫は俗信。","img":["斎藤実盛","源義仲","実盛 (能)"],"wp":"篠原の戦い","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:9/9a/%E5%AE%9F%E7%9B%9B%E7%9F%B3%E5%83%8F.jpg",450,600,"斎藤実盛"],["c:2/27/Minamoto_no_Yoshinaka.jpg",843,767,"源義仲"]]},{"id":"17_tada","n":"多太神社（実盛の兜）","yomi":"ただじんじゃ","cat":"寺社","rank":"A","y":1183,"era":["heian","edo"],"sh":"国の重要文化財（兜）","ad":"小松市上本折町","st":"JR小松駅から歩いて約15分","la":36.4108,"lo":136.4492,"hook":"«むざんやな甲の下のきりぎりす»。芭蕉が涙した老武者の兜が、今も町の神社に眠る。","lead":"多太神社は、小松市の町中にある古い神社です。篠原の戦いで討たれた斎藤実盛の兜と伝わるものが伝わり、国の重要文化財になっています。1689年、松尾芭蕉がこの兜を見て句を詠んだことで知られます。","story":["1183年、篠原の戦いで斎藤実盛を討った木曾義仲は、実盛が自分の命の恩人だったことを知り、深く悲しみました。義仲は、実盛がつけていた兜を、戦勝祈願の願状とともに近くの神社に奉納したと伝わります。その神社が多太神社です。","兜の使者になったのは、実盛の首を見分けた義仲の重臣・樋口兼光だったといわれます。平家を追って京へ急ぐ途中、義仲はわざわざ兜を神社に納めました。«恩人の魂を、せめてここで鎮めてほしい»。そんな思いがあったのかもしれません。","それから500年ほどたった1689年の夏、『おくのほそ道』の旅をしていた松尾芭蕉が小松に立ち寄り、この神社で兜を見せてもらいました。錦の切れはしがつき、菊唐草の彫り物に金がちりばめられた、みごとな兜。芭蕉は «ふつうの武士のものではない» と感じたと書いています。","芭蕉は兜を前に «むざんやな 甲の下の きりぎりす» と詠みました。«むざんやな» は、実盛の首を見た樋口兼光が言ったとされることば。兜の下で鳴くこおろぎの声に、老武者のあわれな最期を重ねたのです。句碑は今も境内に立っています。","兜は神社の宝物として大切に守られ、ふだんは公開されていません。境内には芭蕉と実盛の像も立ち、毎年夏には実盛をしのぶ行事も行われてきました。小さな町の神社に、源平の悲話と、俳諧の名句が静かに息づいているのです。"],"tl":[["平安時代","延喜式に名がのる古い神社とされる"],["1183年","木曾義仲が実盛の兜などを奉納したと伝わる"],["1689年","松尾芭蕉が参拝し、兜を見て句を詠む"],["近代","兜が国の重要文化財に指定される"]],"who":[["斎藤実盛","篠原で討たれた平家方の老武者。兜の持ち主と伝わる"],["木曾義仲","兜を神社に奉納したと伝わる"],["樋口兼光","義仲の使者として兜を納めたといわれる"],["松尾芭蕉","兜を見て «むざんやな» の句を詠んだ"]],"deep":["『おくのほそ道』には、この神社で兜と錦の切れを見たこと、兜に竜頭や菊唐草の飾りがあったことが書かれています。","兜が本当に実盛のものかどうかは確かめられていません。重要文化財としての名称にも «伝» などの語が付けられ、伝承の品として扱われています。","多太神社は、平安時代の『延喜式』の «神名帳» にある加賀国の神社とされ、1000年以上の歴史をもつ古社です。","«むざんやな» の句は、はじめ «あなむざんやな» と詠まれ、のちに推敲されたといわれます。","兜や宝物の公開は限られた機会だけで、ふだんは見られません。見学を希望する場合は事前に確かめる必要があります。","実盛の兜は、平安時代の終わりごろの形式をよく残す貴重な武具とも評価されます。«竜頭» の前立てや、錦の切れはしがそえられていることが、実盛の «錦の直垂» の話と結びつけて語られてきました。"],"look":["芭蕉の句碑","実盛・芭蕉ゆかりの像","境内の落ち着いた雰囲気（兜はふだん非公開）","小松駅周辺の町並み（芭蕉が歩いた小松の町）"],"q":["芭蕉が多太神社で詠んだ句は?","«むざんやな 甲の下の きりぎりす»。実盛の兜を見て、その最期をしのんだ句です。"],"koji":[{"w":"むざんやな","m":"«なんといたましいことだ» という意味。実盛の首を見た樋口兼光のことばとして伝わり、芭蕉が句に使った"}],"myth":"兜が実盛のものであること、義仲の奉納、樋口兼光が使者だった話は伝承。","img":["斎藤実盛","おくのほそ道","松尾芭蕉"],"wp":"多太神社","rel":{"ev":[],"grave":[]},"ph":[["c:9/9a/%E5%AE%9F%E7%9B%9B%E7%9F%B3%E5%83%8F.jpg",450,600,"斎藤実盛"],["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"],["c:c/c4/260719_Natadera_Komatsu_Ishikawa_pref_Japan43s4.jpg",5472,3648,"近く: 小松市"],["c:e/e5/260719_Komatsu_Station_Komatsu_Ishikawa_pref_Japan02s3.jpg",5472,3648,"近く: 小松駅"],["c:9/9a/OTABI_MATSURI_FESTIVAL_KOMATSU_002.JPG",2240,1680,"近く: お旅まつり"],["c:3/3a/Komatsu_High_School.jpg",1600,1200,"近く: 石川県立小松高等学校"],["c:9/9c/20210721_171937-COLLAGE.jpg",1024,1024,"近く: 小松城"],["c:b/ba/Komatsu_city_Rojo_jhs.jpg",1542,1150,"近く: 小松市立芦城中学校"]]},{"id":"17_komatsujo","n":"小松城（前田利常の隠居城）","yomi":"こまつじょう","cat":"城","rank":"A","y":1639,"era":["azuchi","edo"],"sh":"","ad":"小松市丸の内町","st":"JR小松駅から歩いて約15分（天守台は県立小松高校の敷地内）","la":36.406,"lo":136.44,"hook":"湖に浮かぶように見えた «浮城»。百万石の殿様が、隠居しながら藩をにらみ続けた城。","lead":"小松城は、加賀藩3代藩主・前田利常が隠居後に暮らした城です。湿地や川の水を堀にした城で、水に浮かぶように見えたことから «浮城»、あるいは «芦城» とよばれました。今は天守台の石垣が残り、一部は県立高校の敷地や公園になっています。","story":["小松城の始まりは戦国時代、加賀一向一揆のころにさかのぼるといわれます。その後、織田方の武将が入り、関ヶ原の戦いのころには丹羽長重が城主でした。1600年、長重は前田利長の軍と浅井畷で戦い、前田家に一歩もひかなかったと伝わります。","1639年、前田利常は家督を長男の光高にゆずり、自分は小松城で隠居することにしました。«隠居なのに、なぜわざわざ大きな城に?» このとき、利常は城を大きく作り直しています。幕府は «一国一城令» で城の数を制限していましたが、小松城は特別に認められました。","城のまわりは、湿地や川、潟が広がる土地でした。利常はその水を生かして、いくつもの島のような曲輪を橋でつなぐ城を作りました。水の上に浮かぶように見えることから «浮城» とよばれたのです。","隠居したとはいえ、利常は小松から藩の政治に目を光らせ続けました。長男の光高が若くして亡くなると、幼い孫・綱紀の後見役となり、藩の改革 «改作法» を進めます。小松の町は、利常のもとで産業や文化がさかえ、今につながる城下町の基礎ができました。","1658年、利常は小松城で亡くなりました。その後、城は明治まで残りましたが、廃城後に建物は取りこわされ、堀も埋められました。今は小松高校の敷地に天守台の石垣が残り、近くの芦城公園がわずかに往時の面影を伝えています。"],"tl":[["戦国時代","一向一揆の時代に築かれたと伝わる"],["1600年","城主・丹羽長重が浅井畷で前田利長軍と戦う"],["1639年","前田利常が隠居し、小松城に入って大改修"],["1658年","前田利常が小松城で死去"],["明治時代","廃城となり、建物がこわされる"]],"who":[["前田利常","加賀藩3代藩主。隠居後に小松城を整え、藩政を見守った"],["丹羽長重","関ヶ原のころの小松城主。浅井畷で前田軍と戦った"],["前田光高","利常の長男で4代藩主。若くして亡くなった"],["前田綱紀","5代藩主。祖父・利常の後見で藩政を学んだ"]],"deep":["«一国一城令»（1615年）のもとでも、加賀藩では金沢城のほかに小松城の存続が認められ、利常の隠居城として特別あつかいされました。","天守台は «本丸櫓台» ともよばれ、切り石をすき間なく積んだ石垣がみごと。ただし高校の敷地内のため、見学には制限があります。","利常が進めた «改作法» は、農村の年貢の仕組みを立て直す大改革で、加賀藩の財政の基礎を固めたと評価されます。","小松の町の «小松うどん» や九谷焼、絹織物などは、利常の時代に育まれたと語られることがありますが、どこまでが利常の功績かは諸説あります。","城の建物の一部は、廃城後に市内の寺などに移されたと伝わります。"],"look":["天守台（本丸櫓台）の石垣（高校敷地のため見学は制限あり）","芦城公園","小松の城下町の町並み"],"q":["小松城が «浮城» とよばれたのはなぜ?","湿地や川の水を利用した城で、水の上に浮かんでいるように見えたからです。"],"koji":[],"myth":"築城の時期、城の建物の移築先、小松の産業を利常の功績とする話は諸説。","img":["前田利常","丹羽長重","浅井畷の戦い"],"wp":"小松城","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/20210721_171937-COLLAGE.jpg",1024,1024,"小松城"],["c:f/ff/Komatsu_castle_yaguraato.JPG",4000,3000],["c:2/2a/Komatsu_castle_odozou.JPG",4000,3000],["c:b/ba/Komatsu_castle_kawaragomon.JPG",4000,3000],["c:5/5f/Komatsu_castle_ishigaki.JPG",4000,3000],["c:e/ea/Komatsu_castle_honmarugoten.JPG",4000,3000],["c:7/74/Komatsu_castle_hakusansuiido.JPG",4000,3000],["c:f/f3/DSC_2164~2.jpg",4000,3000]]},{"id":"17_kutani","n":"九谷焼（古九谷の窯跡）","yomi":"くたにやき","cat":"産業","rank":"A","y":1655,"era":["edo","meiji"],"sh":"国指定史跡（九谷磁器窯跡）","ad":"加賀市山中温泉九谷町","st":"山中温泉から車で約20分。公共交通はなく車で行く必要がある","la":36.225,"lo":136.4,"hook":"緑・黄・紺青・紫・赤。山奥の小さな村から生まれた «五彩» の焼き物は、約50年でこつぜんと姿を消した。","lead":"九谷焼は、石川県を代表する焼き物です。江戸時代の前期、大聖寺藩の九谷村（今の加賀市山中温泉九谷町）で焼かれた «古九谷» が始まりとされます。その窯跡は国の史跡です。古九谷は約50年で途絶えますが、のちに復活し、今につながっています。","story":["江戸時代の前期、加賀藩の分家である大聖寺藩の山奥、九谷村で、磁器の原料となる石が見つかったといわれます。初代藩主の前田利治は、ここで焼き物を作ろうと考えました。伝えられるところでは、藩士の後藤才次郎を肥前の有田に送り、磁器の技術を学ばせたといいます。","1655年ごろ、九谷村に窯が開かれ、焼き物づくりが始まりました。緑・黄・紺青・紫・赤の «五彩» を大胆に使い、皿いっぱいに山水や花鳥、幾何学的な文様をえがいた作品は、力強く華やかでした。これが今 «古九谷» とよばれる焼き物です。","ところが、九谷の窯は1700年ごろまでに突然途絶えてしまいます。«なぜやめてしまったの?» 藩の財政の問題とも、技術者がいなくなったからともいわれますが、はっきりした理由はわかっていません。この «謎の廃窯» が、古九谷をいっそう神秘的なものにしています。","それから約100年後の1807年、加賀藩は京都から陶工の青木木米を招いて金沢に «春日山窯» を開き、九谷焼は復活します。1824年には大聖寺の豪商・豊田伝右衛門が九谷村に «吉田屋窯» を開き、古九谷の再興をめざしました。明治には九谷庄三らの華やかな «彩色金襴» が海外にも輸出され、«ジャパン・クタニ» として人気を集めました。","古九谷の窯跡は、大聖寺川の上流の山あいにあります。発掘調査で窯の跡や、たくさんの焼き物のかけらが見つかり、九谷村で磁器が作られていたことが確かめられました。静かな山の中の窯跡に立つと、五彩の器を生んだ職人たちの熱気が想像できます。"],"tl":[["1655年ごろ","九谷村で窯が開かれ、古九谷の生産が始まったとされる"],["1700年ごろ","九谷の窯が途絶える"],["1807年","金沢に春日山窯が開かれ、九谷焼が再興"],["1824年","豊田伝右衛門が九谷村に吉田屋窯を開く"],["明治時代","九谷庄三らの作品が海外へ輸出される"],["1979年","九谷磁器窯跡が国の史跡に指定"]],"who":[["前田利治","大聖寺藩の初代藩主。九谷での焼き物づくりを始めたとされる"],["後藤才次郎","大聖寺藩士。有田で技術を学んだと伝わる"],["青木木米","京都の文人陶工。春日山窯で九谷焼を再興した"],["豊田伝右衛門","大聖寺の豪商。吉田屋窯を開いた"],["九谷庄三","明治の陶工。華やかな彩色金襴で知られる"]],"deep":["«古九谷» の多くは、じつは肥前の有田で焼かれたのではないか、という «古九谷伊万里説» が昭和時代から議論されてきました。九谷の窯跡の発掘で九谷での生産も確かめられましたが、どの作品がどこで焼かれたかは、今も研究が続いています。","古九谷の特徴は、器の全面を色で塗りこめる «青手» と、白い地を生かして絵をえがく «色絵» の二つのタイプです。","九谷焼の «五彩» は、緑・黄・紺青・紫・赤。とくに緑・黄・紫を中心にした «青手» は、九谷ならではの深い色合いです。","吉田屋窯は数年で閉じましたが、古九谷の青手を受け継いだ作品は高く評価され、再興九谷の代表とされます。","加賀市大聖寺には «石川県九谷焼美術館»、能美市には «能美市九谷焼資料館» があり、各時代の九谷焼を見比べられます。"],"look":["九谷磁器窯跡（山あいの窯跡・説明板）","加賀市山代温泉の九谷焼窯跡展示館（再興九谷の窯跡）","加賀市大聖寺の石川県九谷焼美術館"],"q":["九谷焼の «五彩» とは何色?","緑・黄・紺青・紫・赤の5色。古九谷はこの色を大胆に使いました。"],"koji":[],"myth":"後藤才次郎が有田で学んだ話、廃窯の理由、古九谷の産地（九谷か有田か）は諸説。","img":["古九谷","青木木米","九谷庄三"],"wp":"九谷焼","rel":{"ev":[],"grave":[]},"ph":[["c:4/4f/KUTANI_Ewer.JPG",852,627,"九谷焼"],["c:6/69/Kutani-Ware_Plate%2C_late_17th_century%2C_Japan%2C_porcelain_with_enamel_-_Art_Institute_of_Chicago_-_DSC00224.JPG",4320,3240],["c:5/56/Dish%2C_Kutani_ware%2C_Yoshidaya_style_-_Ishikawa_Prefectural_Museum_of_Traditional_Arts_and_Crafts_-_Kanazawa%2C_Japan_-_DSC09855.jpg",3203,3150],["c:e/e6/Dish%2C_Kutani_ware%2C_Shoza_style_-_Ishikawa_Prefectural_Museum_of_Traditional_Arts_and_Crafts_-_Kanazawa%2C_Japan_-_DSC09847.jpg",3291,3195],["c:a/a5/Dish%2C_Kutani_ware%2C_Mokubei_style_-_Ishikawa_Prefectural_Museum_of_Traditional_Arts_and_Crafts_-_Kanazawa%2C_Japan_-_DSC09859.jpg",3272,3185],["c:e/ef/Dish%2C_Kutani_ware%2C_Iidaya_%28Aka-e%29_style_-_Ishikawa_Prefectural_Museum_of_Traditional_Arts_and_Crafts_-_Kanazawa%2C_Japan_-_DSC09851.jpg",3517,3462],["c:3/3e/260605_Ishikawa_Prefectural_Kutani_Ware_Museum_Kaga_Ishikawa_pref_Japan02s3.jpg",5472,3648],["c:2/2d/Memorial_of_Saijirou_Goto_and_Old-Kutani_furnace.jpg",3840,2560]]},{"id":"17_hashitate","n":"加賀橋立（北前船主の集落と北前船の里資料館）","yomi":"かがはしたて","cat":"町","rank":"A","y":1850,"era":["edo","meiji"],"sh":"国の重要伝統的建造物群保存地区","ad":"加賀市橋立町","st":"JR加賀温泉駅からバス・車で約20分（本数が少ないので車かタクシーが便利）","la":36.3285,"lo":136.3345,"hook":"日本海の小さな漁村に、赤い瓦と石垣の «船主屋敷» がずらり。ここはかつて «日本一の富豪村» とうわさされた村です。","lead":"江戸時代の後半から明治にかけて、大阪と北海道を日本海回りで結んだ «北前船»。その船主や船頭がたくさん住んでいたのが加賀橋立です。今も大きな屋敷や蔵、石垣の町並みが残り、船主の家だった建物が «北前船の里資料館» になっています。","story":["橋立は、加賀の海に面した小さな岬の村です。田んぼは少なく、昔から男たちは船に乗って働きました。やがて彼らは、ただの船乗りではなく、自分の船で商売をする «船主» になっていきます。春に大阪を出て、瀬戸内海から関門海峡をまわり、日本海を北へ。各地の港で品物を買っては売り、夏に蝦夷地（北海道）へ着くと、ニシンや昆布を積んで秋に戻ってきました。","«一航海で千両»。北前船はそう言われるほどもうかる商売でした。なぜそんなにもうかったのでしょう? 答えは «運賃ではなく、売り買いの差» です。北前船は荷物を運んで運賃をもらうのではなく、船主自身が安い土地で買って高い土地で売る «買積み» という方法をとりました。米や塩、木綿を北へ、ニシンや昆布を南へ。うまくいけば一度の航海で大きな財産になりましたが、嵐で船を失えば一気にすべてを失う、命がけのばくちでもありました。","村に残る屋敷は、その成功のあかしです。屋根は赤みがかった瓦、壁は板張り、敷地は «笏谷石»（しゃくだにいし）という越前の青みがかった石の石垣で囲まれています。石は北前船が帰りの荷の «重し» として積んできたものともいわれます。屋敷の中には、太い梁（はり）や立派な仏間、蔵には船の道具や各地の品々。«海でかせいだお金で、陸に宝を残した» 人びとの暮らしがよくわかります。","明治になると、雑誌で «日本一の富豪村» と紹介されたと伝わります。しかし鉄道が延び、蒸気船や電信が広まると、«安く買って高く売る» 北前船の商売は成り立たなくなっていきました。船主の中には、汽船会社や銀行、保険などの近代の仕事に進んだ人もいます。橋立の人びとは、時代の波にも船をこぎ出していったのです。","2005年、橋立の町並みは国の重要伝統的建造物群保存地区に選ばれました。資料館の広い座敷に座ると、玄関の土間から海風が入ってきます。«ここの主人は、今ごろどの海の上だろう» と家族が待った日々を想像しながら歩いてみてください。"],"tl":[["江戸時代中ごろ","橋立の船乗りたちが北前船の商売にかかわり始める"],["江戸時代後期","北前船の最盛期。橋立に船主の屋敷が建ち並ぶ"],["1876年","のちに資料館となる酒谷長兵衛の屋敷が建てられる"],["明治時代","«日本一の富豪村» と紹介されたと伝わる"],["明治時代後半","鉄道・汽船の発達で北前船がおとろえる"],["昭和時代後期","旧酒谷家が «北前船の里資料館» として公開される"],["2005年","国の重要伝統的建造物群保存地区に選定"]],"who":[["酒谷長兵衛","橋立の北前船主。屋敷が今の北前船の里資料館になっている"],["久保彦兵衛","橋立を代表する船主の一人として知られる"],["西出孫左衛門","橋立の船主。明治以後は近代の海運業にもかかわった"],["北前船の船頭・水夫","橋立の男たちの多くが船に乗り、各地の港をめぐった"]],"deep":["«北前船» はもともと上方（大阪）側からの呼び名で、日本海側の人は «ベザイ船» などと呼んだといわれます。船の形としては «弁才船» が中心でした。","«買積み» 方式が北前船の特徴。運賃で稼ぐ «運賃積み» と違い、船主が自分で商品を売買したので、相場を読む力と各港の情報が大切でした。","笏谷石は福井市の足羽山周辺でとれた凝灰岩。青緑がかった色で、橋立の石垣や敷石に多く使われています。","2017年、北前船の寄港地・船主集落が «日本遺産» に認定され、加賀市もその構成地域になっています。","資料館の近くには、船主・酒谷家の屋敷と庭が «蔵六園» として公開されています（公開日は要確認）。","橋立の家の多くは、屋根の妻側を通りに向けず、敷地の奥に主屋を置く配置で、石垣と塀が道に沿って続く独特の景観をつくっています。"],"look":["北前船の里資料館（旧酒谷長兵衛家）の座敷と太い梁","集落に続く笏谷石の石垣と赤瓦の屋根","資料館の船の模型、引札（広告）、船箪笥","蔵六園（酒谷家の庭園）","集落の先にある橋立漁港と日本海"],"q":["北前船が大きなもうけを出した理由は？","荷物を運ぶ «運賃» ではなく、船主が安い港で買い、高い港で売る «買積み» で商売したからです。"],"koji":[{"w":"一航海千両","m":"北前船が一度の航海で千両ももうけることがある、という意味の言い回し"}],"myth":"«日本一の富豪村» の出典や、笏谷石が船の重しとして運ばれたという話は伝承・通説を含む。","img":["弁才船","加賀市"],"wp":"北前船","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:b/bf/Img%E8%BE%B0%E6%82%A6%E4%B8%B8.jpg",5170,3516],["c:f/fc/Kitamaekan01s3900.jpg",2500,3900],["c:c/c1/A_Kai-sen_ship%2C_Engaku-ji_temple_%28Kamakura%29%2C_1633.jpg",1103,713],["c:6/6a/%E5%8C%97%E5%89%8D%E8%88%B9%E4%B8%BB%E4%B9%85%E4%BF%9D%E9%82%B8.jpg",800,600],["c:1/18/Michinoku_Maru_01.jpg",533,800],["c:f/fa/Ueno_junks.jpg",2560,1980,"弁才船"],["c:9/9f/Ishikawa_Kaga_Kagahashidate00.jpg",2816,2120,"加賀市"]]},{"id":"17_oyamagobo","n":"金沢御堂（尾山御坊）跡","yomi":"かなざわみどう（おやまごぼう）あと","cat":"寺社","rank":"A","y":1546,"era":["muromachi","azuchi"],"sh":"","ad":"金沢市丸の内（金沢城公園内とされる）","st":"JR金沢駅からバスで «兼六園下・金沢城» まで約15分、徒歩すぐ","la":36.5645,"lo":136.6592,"hook":"金沢城のまえ、この丘には «百姓の持ちたる国» の本部がありました。お寺が国をおさめた100年のはじまりの場所です。","lead":"«金沢御堂»（尾山御坊）は、戦国時代に本願寺が加賀に置いた一向宗の拠点です。加賀の一向一揆はおよそ100年ものあいだ国を実質的に治めました。お寺は織田軍に攻め落とされ、その跡に金沢城が築かれたため、建物は残っていません。","story":["1488年、加賀国で大事件が起こります。浄土真宗（一向宗）の門徒たちと武士たちが立ち上がり、守護の富樫政親を高尾城に攻めて自害に追い込んだのです。こうして加賀は、守護ではなく門徒たちの力で動く国になりました。のちの記録には «百姓の持ちたる国のようになりゆき候» と書かれています。","1546年、本願寺はこの加賀を治める中心として、小高い丘の上に «金沢御堂» を建てました。それまでの寺とちがい、御堂のまわりには堀や土塁があり、門前には町ができていたと考えられています。«寺でありながら、城でもあった» のです。まわりの台地は «尾山» と呼ばれ、御堂は «尾山御坊» とも呼ばれました。","なぜこんな場所に? この丘は、犀川と浅野川という二つの川にはさまれた台地の先っぽ。守りやすく、見晴らしがよく、しかも川で物が運べます。のちに前田利家が «ここに城を» と決めたのも、同じ理由でした。お寺を選んだ人たちの目は、城づくりの目と同じだったのです。","しかし戦国の終わり、天下統一をめざす織田信長と本願寺ははげしく争います。1580年、信長の家臣・柴田勝家の軍勢が加賀に攻め込み、佐久間盛政が金沢御堂を落としました。100年近く続いた «門徒の国» はここで終わります。盛政はそのまま御堂の跡を城とし、これが «金沢城» の始まりとなりました。","1583年、賤ヶ岳の戦いのあと、前田利家が金沢城に入ります。城は大きく作り直され、御堂の建物は姿を消しました。正確な場所も、今の本丸付近か二の丸付近かなど、はっきりわかっていません。けれど、金沢城の石垣の足もとには、«百姓の持ちたる国» の記憶がねむっています。"],"tl":[["1488年","加賀一向一揆が守護・富樫政親を高尾城で自害させる"],["1546年","本願寺が尾山に金沢御堂を建てる"],["1570年","石山合戦が始まり、本願寺と信長が対立"],["1580年","柴田勝家の軍が金沢御堂を落とし、佐久間盛政が入る"],["1583年","前田利家が金沢城に入る"],["2008年","金沢城跡が国指定史跡となる"]],"who":[["富樫政親","加賀の守護。一向一揆に攻められ高尾城で自害"],["証如","本願寺10世。金沢御堂が建てられたときの本願寺の門主"],["柴田勝家","織田信長の重臣。北陸方面の総大将として加賀を攻めた"],["佐久間盛政","勝家のおい。金沢御堂を落とし、最初の金沢城主となる"],["前田利家","盛政のあとに金沢城主となり、加賀藩の基礎をつくる"]],"deep":["«百姓の持ちたる国» は、本願寺の蓮如の子・実悟が書き残したとされる記録にある言葉として知られます。«百姓» は農民だけでなく、地侍や商人もふくむ言葉です。","金沢御堂の門前には «後町»«南町» などの寺内町があったと考えられ、のちの金沢の町名にその名残を見る説もあります。","«尾山» という地名は、尾山神社（前田利家をまつる）の名前に今も生きています。«金沢» の名は «金洗沢» の伝説から来たといわれますが、これは伝承です。","金沢城の発掘調査では、城以前の遺構をさがす調査も行われていますが、御堂の建物跡は確定していません。","金沢御堂が落ちた1580年は、石山本願寺と信長が和睦した年でもあります。本拠地の和睦の前後に、地方の拠点が次々と攻略されました。"],"look":["金沢城公園の石川門と三十間長屋","本丸付近の台地の高さ（御堂が建った地形を体で感じる）","尾山神社（«尾山» の名が残る）","金沢城の «いもり堀» や «百間堀» 跡（川と台地の関係）"],"q":["加賀の一向一揆が治めた国は、記録で何と書かれた？","«百姓の持ちたる国» です。守護を倒し、門徒たちが力を持った国のようすを表しています。"],"koji":[{"w":"百姓の持ちたる国","m":"守護大名ではなく、門徒の農民や地侍たちが実際に国を動かしているようす"}],"myth":"御堂の正確な位置は諸説あり未確定。«金洗沢» 地名由来は伝承。","img":["加賀一向一揆","金沢城"],"wp":"金沢御堂","rel":{"ev":["sankin","basho"],"grave":[]},"ph":[["c:7/7e/Kanazawa-M-5932.jpg",1500,1000,"金沢城"],["c:f/fc/Kenrokuen10-r.jpg",1999,1333,"近く: 兼六園"],["c:e/ef/2024-10-26_Kanazawa_Castle%2C_Ishikawa-mon.jpg",4968,3312,"近く: 金沢市"],["c:0/0c/Ishikawa_Kanazawa_Oyama03.jpg",2816,2120,"近く: 尾山神社"],["c:b/b8/Gyokusenen_Kanazawa_Ishikawa09n3200.jpg",4110,2740,"近く: 玉泉園"],["c:a/ac/The_Forth_High_School_Memorial_Museum_of_Cultural_Exchange_Ishikawa05s3s3750.jpg",3750,2500,"近く: 石川近代文学館"]]},{"id":"17_teramachi","n":"寺町寺院群","yomi":"てらまちじいんぐん","cat":"町","rank":"A","y":1643,"era":["edo"],"sh":"国の重要伝統的建造物群保存地区（金沢市寺町台）","ad":"金沢市野町・寺町","st":"JR金沢駅からバスで «広小路» まで約15分、徒歩すぐ","la":36.5535,"lo":136.648,"hook":"犀川を渡った高台に、70ほどのお寺がぎっしり。これは信仰の町であり、城下町を守る «もう一つの城壁» でもありました。","lead":"寺町寺院群は、金沢の城下町の南西、犀川の向こうの台地に集められたお寺の町です。江戸時代の初め、加賀藩がお寺をこの場所に集めました。«忍者寺» と呼ばれる妙立寺もここにあり、町並みは国の重要伝統的建造物群保存地区に選ばれています。","story":["金沢の町を歩くと、犀川の南の高台に、お寺の屋根がどこまでも続く一帯があります。細い道の両側に山門、また山門。数えるとおよそ70ものお寺があると言われます。なぜこんなに集まっているのでしょう?","答えのひとつは «城下町の守り» です。江戸時代の初め、加賀藩はばらばらにあったお寺を、城下のはずれの台地に集めました。お寺は大きな建物と塀、広い敷地を持っています。いざ敵が南から攻めてきたとき、お寺の境内は兵をおく陣地になり、塀は防壁になる。«寺の町は、城の外堀のようなもの» という考え方です。ただし、これは後の人の解釈も多く、火事の多い城下からお寺を離すためなど、ほかの理由もあったと考えられています。","寺町でいちばん有名なのが、日蓮宗の妙立寺です。3代藩主・前田利常のころにこの地に移されたと伝わります。外から見ると2階建てなのに、中は4階7層ともいわれる複雑なつくり。隠し階段、落とし穴のような仕掛け、見張りの部屋……。人びとはここを «忍者寺» と呼ぶようになりました。","«本当に忍者がいたの?» と思うかもしれません。じつは忍者とは関係ありません。«忍者寺» はあとから付いたあだ名です。けれど、見張りや防御の工夫がされているのは確かで、«いざというときの砦（とりで）の役目も考えたのでは» という説があります。寺町全体が守りの町だったとすれば、その中心にふさわしいお寺です。","今の寺町は、静かなお墓参りの町です。夕方、犀川から坂を上ると、鐘の音と線香のかおり。2012年、町並みは «金沢市寺町台» として国の重要伝統的建造物群保存地区になりました。ひがし茶屋街のにぎわいとはまったく違う、«祈りの金沢» の顔を見ることができます。"],"tl":[["1583年","前田利家が金沢城に入り、城下町づくりが進む"],["江戸時代初め","加賀藩が城下のお寺を犀川南の台地などに集める"],["1643年","妙立寺がこの地に移されたと伝わる"],["1820年","近くの野町に «にし茶屋街» が公認される"],["2012年","«金沢市寺町台» が国の重要伝統的建造物群保存地区に選定"]],"who":[["前田利常","加賀藩3代藩主。妙立寺をこの地に移したと伝わる"],["前田利家","加賀藩の祖。城下町の基礎をつくった"],["寺町の僧侶と檀家","江戸時代から今までお寺と墓地を守ってきた人びと"]],"deep":["金沢には寺院群が3か所あります。犀川南の «寺町»、浅野川東の «卯辰山麓»、城の東の «小立野»。どれも城下のはずれの台地にあり、守りと関係づけて説明されることが多いです。","妙立寺の内部は «4階7層»、階段は29か所ともいわれます。見学は予約制の案内付きで、自由には歩けません（最新情報を確認）。","«寺町が城下の防衛拠点だった» という説は広く知られますが、はっきり書いた当時の史料は少なく、後の解釈も含まれます。","寺町の鐘は、金沢の町に時を知らせる役目もありました。お寺の鐘は昔の «時計» でもあったのです。","寺町台の重伝建地区には、お寺だけでなく、野町・泉などの町家の町並みもふくまれています。"],"look":["妙立寺（忍者寺）の外観と、予約制の内部見学","寺町通りに続く山門と塀","犀川大橋から見える寺町の台地","にし茶屋街とあわせた散策"],"q":["妙立寺はなぜ «忍者寺» と呼ばれる？","隠し階段や落とし穴のような仕掛けがあるからで、忍者が住んでいたわけではありません。"],"koji":[],"myth":"寺町の防衛拠点説、妙立寺の移転年や «砦» 説は諸説・通説を含む。","img":["妙立寺","犀川 (石川県)"],"wp":"寺町寺院群","rel":{"ev":[],"grave":[]},"ph":[["c:f/f5/Kanazawa_Nodamichi_20160618.jpg",5456,3632,"寺町寺院群"],["c:d/dc/Kanazawa_Tsurugimichi_20160618b.jpg",5456,3632],["c:4/4c/Kanazawa_Tsurugimichi_20160618a.jpg",5456,3632],["c:3/35/Kanazawa_Teramachidai_20160618.jpg",5456,3632],["c:3/38/W-zaka02.jpg",2048,1536],["c:6/61/W-zaka01.jpg",2048,1536],["c:8/86/Ninja-dera_1.jpg",4320,3240,"妙立寺"],["c:4/4e/Saigawa_River01-r.jpg",1890,1260,"犀川 (石川県)"]]},{"id":"17_tatsumi","n":"辰巳用水","yomi":"たつみようすい","cat":"産業","rank":"A","y":1632,"era":["edo"],"sh":"国指定史跡","ad":"金沢市上辰巳町〜兼六町","st":"取水口付近へはJR金沢駅からバスで約40分（本数少なめ）。兼六園内の曲水は «兼六園下» バス停から徒歩すぐ","la":36.5195,"lo":136.7065,"hook":"山の川の水を、トンネルと «水が坂をのぼる» しかけで城まで運んだ。江戸時代の日本人の土木の知恵がつまった用水です。","lead":"辰巳用水は、1632年に完成した金沢の用水です。犀川の上流から水を取り、トンネルや水路で約11km先の兼六園や金沢城まで運びました。お城の火事をきっかけにつくられたと伝わり、今も兼六園の池や曲水をうるおしています。","story":["1631年、金沢の町は大火に見舞われ、金沢城にも燃え広がったと伝わります。«城に水があれば……»。3代藩主・前田利常は、城に水を引く大工事を命じました。それが辰巳用水です。城の南東、«辰巳»（たつみ）の方角から水を引いたので、この名があります。","工事をまかされたのは、小松の町人・板屋兵四郎と伝わります。犀川の上流、上辰巳の山の中で水を取り入れ、山の中を手掘りのトンネルで進みます。トンネルの長さは約4km。明かりはろうそくや油の火、道具はのみとつち。«どうやって方向をまちがえずに掘ったの?» 途中にいくつも横穴を掘り、そこから左右に進んだと考えられています。","いちばんの見どころは、兼六園から金沢城へ水を渡すところです。兼六園の台地と城のあいだには低い谷（今の «百間堀» の道路）があります。水は高い所から低い所へしか流れません。そこで使われたのが «伏越（ふせこし）» のしくみ。管の中を水で満たしておけば、出口が入口より低ければ、水は谷を下って、また向こう側を上がっていきます。今でいう «逆サイフォン» の原理です。","最初は木の管だったといわれ、のちに石の管にかえられました。兼六園や城の中から、その石管が見つかっています。江戸時代の人が、この原理を知っていて城まで水を届けた。それはまさに «見えない水の橋» でした。","用水は、城の水だけでなく、田んぼや町の防火にも使われました。2010年、辰巳用水は国の史跡に指定されます。兼六園の曲水をさらさら流れる水は、380年以上前に山のトンネルをくぐってきた水と同じ道を通っています。"],"tl":[["1631年","金沢で大火。城にも被害が出たと伝わる"],["1632年","辰巳用水が完成する"],["江戸時代","兼六園の池や曲水の水源となる"],["1844年ごろ","城へ渡す管が木管から石管にかえられたといわれる"],["2010年","国の史跡に指定される"]],"who":[["前田利常","加賀藩3代藩主。用水の工事を命じた"],["板屋兵四郎","小松の町人。用水をつくった技術者と伝わる"],["用水を守る人びと","江戸時代から今まで水路の手入れを続けてきた地元の人たち"]],"deep":["全長は約11km、そのうち約4kmがトンネルといわれます。トンネルは後にかなりの部分が開水路（ふたのない水路）に変えられました。","伏越の原理（逆サイフォン）は、入口と出口の高さの差で水を押し上げるしくみ。兼六園側の取水と城の二の丸側の高さの差が利用されました。","板屋兵四郎は «秘密を守るため工事のあとで消された» という話がありますが、これは伝説で、確かな史料はありません。","兼六園の «霞ヶ池» や «曲水»、有名な噴水（日本最古級といわれる）も、辰巳用水の水の高低差を使っています。","用水の取水口は、今は昭和期に改修された構造になっており、江戸時代の姿そのままではありません。"],"look":["兼六園の曲水と霞ヶ池（辰巳用水の水）","兼六園の噴水（水の高低差だけで吹き上がる）","石川県立歴史博物館などで展示される石管","上辰巳町の取水口と、用水沿いの散策路"],"q":["辰巳用水で、谷をこえて城まで水を渡した仕組みの名前は？","«伏越（ふせこし）»。今でいう逆サイフォンの原理です。"],"koji":[],"myth":"大火の年・城への延焼、板屋兵四郎の人物像と «消された» 話、石管への交換年は伝承・諸説を含む。","img":["兼六園","前田利常"],"wp":"辰巳用水","rel":{"ev":[],"grave":[]},"ph":[["c:8/8f/Tatsumi_canal.jpg",480,640,"辰巳用水"],["c:0/0d/%E8%BE%B0%E5%B7%B3%E7%94%A8%E6%B0%B4%E7%9F%B3%E7%AE%A1.jpg",480,360],["c:f/fc/Kenrokuen10-r.jpg",1999,1333,"兼六園"],["c:b/b9/Maeda_Toshitsune.png",1294,1725,"前田利常"]]},{"id":"17_seisonkaku","n":"成巽閣","yomi":"せいそんかく","cat":"大名屋敷","rank":"A","y":1863,"era":["edo","meiji"],"sh":"国の重要文化財","ad":"金沢市兼六町","st":"JR金沢駅からバスで «出羽町» または «広坂» まで約15分、徒歩約5分","la":36.5608,"lo":136.664,"hook":"天井いっぱいの «群青» の青。幕末、加賀藩主が母のために建てた御殿は、今も色あざやかなまま残っています。","lead":"成巽閣は、1863年に加賀藩13代藩主・前田斉泰が、母の真龍院のために兼六園のとなりに建てた隠居所です。武家の書院造りに、数寄屋風のやわらかな工夫を合わせた建物で、国の重要文化財。今は加賀前田家の品々を伝える美術館として公開されています。","story":["幕末の1863年。日本じゅうが開国か攘夷かでゆれていたころ、金沢では一つの御殿が完成しました。藩主・前田斉泰が、12代斉広の正室で自分の母である真龍院（隆子）のために建てた隠居所です。«母上には、城の外で、静かに、美しく暮らしていただきたい»。そんな思いがこもった建物です。","建てられたのは金沢城の «巽»（たつみ・南東）の方角。はじめは «巽御殿» と呼ばれ、明治になって «成巽閣» と名を改めました。1階は武家らしい書院造り。格式ある «謁見の間» は、欄間に花鳥の彫刻、ふすまや壁には豪華な飾り。女性の住まいらしい、やわらかな華やかさがあります。","2階に上がると、目の前に青い天井が広がります。«群青の間»。天井に使われたのは «ウルトラマリンブルー»、当時ヨーロッパから入ってきたばかりの顔料とされます。«なぜ幕末の金沢に、ヨーロッパの青が?» 北前船や長崎を通じ、加賀藩は新しい品をいち早く手に入れていたのです。群青の天井に、紫や朱の壁。まるで宝石箱の中にいるようです。","もう一つの名物が «つくしの縁»。庭に面した長い縁側には、軒を支える柱がありません。だから庭をさえぎるものがなく、まるで絵のように景色が広がります。柱をなくすため、屋根を支える工夫がかくされています。つくしの芽が出る小さな庭をながめながら、真龍院はここで季節を楽しんだのでしょう。","明治になって多くの大名屋敷がこわされていく中、成巽閣は前田家の手で守られ、今も昔の姿のまま残っています。兼六園の散歩のあとに立ち寄ると、«大名の奥の暮らし» をのぞき見るような気持ちになれます。"],"tl":[["1822年","兼六園のあたりに竹沢御殿が建てられる（のちに取りこわし）"],["1863年","前田斉泰が母・真龍院のために巽御殿を建てる"],["1870年","真龍院が亡くなる"],["明治時代","«成巽閣» と名を改める"],["昭和時代","国の重要文化財に指定され、美術館として一般公開される"]],"who":[["前田斉泰","加賀藩13代藩主。母のために御殿を建てた"],["真龍院（隆子）","12代斉広の正室で、斉泰の母。成巽閣で晩年を過ごした"],["前田斉広","加賀藩12代藩主。兼六園の竹沢御殿を建てた"]],"deep":["«群青の間» の青は、天然の鉱物ではなく、ヨーロッパで作られた人工の «ウルトラマリン» だとされます。当時とても高価で、日本の建築での早い使用例として注目されます。","1階の «謁見の間» の欄間は、一枚の檜から透かし彫りで花鳥を彫り出したとされ、極彩色がよく残っています。","«つくしの縁» は長い縁側に柱がなく、桁（けた）を長く渡して屋根を支えています。","庭園 «飛鶴庭»（ひかくてい）は、辰巳用水の分流を取り入れた庭として知られます。","成巽閣は加賀前田家ゆかりの調度品・ひな人形などを所蔵し、季節ごとに展示替えがあります。"],"look":["2階 «群青の間» の天井","1階 «謁見の間» の彩色欄間","柱のない «つくしの縁» と飛鶴庭","季節の特別展（春のひな人形など）"],"q":["成巽閣の名前の «巽» は何の方角？","南東です。金沢城から見て南東（たつみ）に建てられたことから名づけられました。"],"koji":[],"myth":"群青の顔料の来歴、庭の水源などは説明によって異なる場合がある。","img":["前田斉泰","兼六園"],"wp":"成巽閣","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan10s3.jpg",4800,3200,"成巽閣"],["c:e/e0/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan09s3.jpg",4912,3264],["c:b/b1/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan07s3.jpg",4800,3200],["c:0/0d/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan05n.jpg",4912,3264],["c:2/26/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan04s3.jpg",4912,3264],["c:3/36/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan02s3.jpg",4912,3264],["c:8/8f/131109_Seisonkaku_Kanazawa_Ishikawa_pref_Japan00s3.jpg",4912,3264],["c:a/a7/Maeda_Nariyasu.JPG",250,389,"前田斉泰"]]},{"id":"17_shiko","n":"旧第四高等学校（四高記念館）","yomi":"きゅうだいよんこうとうがっこう（しこうきねんかん）","cat":"学び","rank":"A","y":1891,"era":["meiji","taisho","showa"],"sh":"国の重要文化財","ad":"金沢市広坂","st":"JR金沢駅からバスで «香林坊» または «広坂» まで約10分、徒歩すぐ","la":36.5628,"lo":136.6568,"hook":"«北の都に秋たけて»。赤れんがの校舎から、日本を代表する哲学者や作家が巣立っていきました。","lead":"旧第四高等学校は、明治時代に金沢につくられた旧制高校です。1891年に建てられた赤れんがの校舎が残り、国の重要文化財。今は «石川四高記念文化交流館» として、四高の歴史や石川の文学を紹介しています。","story":["明治の日本は、国を動かす人材を育てるため、全国にいくつかの «高等中学校» を置きました。1887年、北陸の中心として金沢に «第四高等中学校» ができます。1894年には «第四高等学校»、略して «四高»（しこう）に。«一高» の東京、«二高» の仙台、«三高» の京都とならぶ、ナンバースクールの一つでした。","1891年に完成した校舎は、赤いれんがに白い石の帯が入った、明治らしいハイカラな建物です。広坂の通りに面して建つその姿は、城下町・金沢に «新しい時代が来た» ことを告げるものでした。«ここで学べば、日本の未来をになえる»。北陸じゅうから、そして全国から、若者たちが集まりました。","四高の卒業生・関係者の中でいちばん有名なのが、哲学者の西田幾多郎でしょう。金沢近くの宇ノ気（今のかほく市）に生まれ、第四高等中学校で学び、のちに四高の先生として教えました。友人の鈴木大拙も同じ学校で学び、のちに «禅» を世界に紹介します。«なぜ金沢から世界的な思想家が?» 城下町の学問の伝統と、若者どうしのはげしい議論が、二人をきたえたのかもしれません。","作家の井上靖も四高の卒業生です。柔道部で練習に明け暮れた日々は、のちに小説『北の海』に描かれました。寮では夜な夜な寮歌を歌い、議論し、ときに町へくり出す。«バンカラ» と呼ばれた、旧制高校生らしい青春がここにありました。","1950年、学制改革で四高は金沢大学に引きつがれ、その歴史を閉じます。校舎は大学や記念館として使われたのち、2008年から «石川四高記念文化交流館» に。れんがの廊下を歩くと、木の床がきしむ音に、明治の若者たちの足音が重なるようです。"],"tl":[["1887年","第四高等中学校が金沢に設置される"],["1891年","赤れんがの本館が完成"],["1894年","第四高等学校（四高）となる"],["1899年","西田幾多郎が四高の教授となる"],["1950年","学制改革により四高が廃止され、金沢大学へ"],["1969年","校舎が国の重要文化財に指定"],["2008年","石川四高記念文化交流館として開館"]],"who":[["西田幾多郎","哲学者。第四高等中学校で学び、のちに四高で教えた"],["鈴木大拙","仏教学者。第四高等中学校で学び、禅を世界に広めた"],["井上靖","作家。四高の柔道部員で、その経験を『北の海』に書いた"],["中野重治","作家・詩人。四高の卒業生"]],"deep":["«ナンバースクール» は、一高〜八高まで番号がついた旧制高校のこと。四高は北陸・信越地方を代表する存在でした。","校舎の設計には文部省の技師がかかわり、れんが造り2階建て。同じ時期の旧制高校の校舎で、これほど当時の姿で残るものは多くありません。","四高の寮歌 «南下軍の歌» の «北の都に秋たけて» の一節は、今も金沢で広く知られています。","西田幾多郎は四高教授時代に坐禅に打ち込み、その体験がのちの『善の研究』につながったといわれます。","記念館の一部は «石川近代文学館» として、泉鏡花・徳田秋声・室生犀星など石川ゆかりの作家を紹介しています。"],"look":["赤れんがと白い石の帯の外観","四高の教室や廊下（木の床と階段）","石川近代文学館の展示","正面のしいのき迎賓館・金沢21世紀美術館とあわせた広坂の散策"],"q":["«四高» の「四」はどういう意味？","明治につくられた番号つきの旧制高校（ナンバースクール）の4番目、という意味です。"],"koji":[{"w":"北の都に秋たけて","m":"四高の寮歌の歌い出し。金沢を «北の都» と呼んでいる"}],"myth":"","img":["西田幾多郎","井上靖"],"wp":"第四高等学校 (旧制)","rel":{"ev":["sankin","basho"],"grave":[]},"ph":[["c:9/9a/The_Fourth_High_School_Memorial_Museum_of_Cultural_Exchange_Ishikawa.jpg",4110,2740,"第四高等学校 (旧制)"],["c:d/de/Daisetsu_Teitar%C5%8D_Suzuki_photographed_by_Shigeru_Tamura.jpg",2059,2809],["c:5/5c/Nakano_Shigeharu.jpg",1145,1725],["c:1/13/Portrait-of-Kitaro-Nishida.png",1078,1456],["c:3/36/Shinkichi_Uesugi.jpg",899,1400],["c:4/41/Kiyoshi_Hiraizumi%2C_circa_1928.jpg",700,700],["c:6/68/Fourth_Higher_School%2C_Japan.jpg",971,454],["c:1/11/Yasushi_Inoue_01.jpg",620,700]]},{"id":"17_rekihaku","n":"石川県立歴史博物館（旧陸軍兵器庫）","yomi":"いしかわけんりつれきしはくぶつかん","cat":"近代","rank":"A","y":1910,"era":["meiji","taisho","showa"],"sh":"国の重要文化財","ad":"金沢市出羽町","st":"JR金沢駅からバスで «出羽町» まで約15分、徒歩約3分","la":36.5588,"lo":136.6608,"hook":"3棟ならんだ赤れんがの倉庫。もとは陸軍の武器をしまう兵器庫でした。今は石川の歴史をまるごと語る博物館です。","lead":"石川県立歴史博物館は、明治の終わりから大正にかけて建てられた陸軍の兵器庫を使った博物館です。3棟の赤れんが建物は国の重要文化財。«いしかわ赤レンガミュージアム» として、加賀本多博物館といっしょに公開されています。","story":["明治時代、金沢には陸軍の第九師団が置かれました。金沢城の中や兼六園のまわりは、兵隊の町に変わっていきます。そして兼六園の南の台地に、武器や弾薬をしまうための大きな倉庫が建てられました。それが今の博物館の赤れんが建物です。","建物は3棟。どれも長さのある2階建てで、れんがを «イギリス積み» で積み上げ、窓には鉄のとびら。«火事にも強く、しっかりと鍵がかかる» 兵器庫らしいつくりです。れんがの色は季節や時間で表情を変え、夕方には赤がいっそう深くなります。","«なぜ金沢に大きな兵器庫が?» 第九師団は、日露戦争などで多くの兵を送り出した師団です。北陸の兵士たちは遠い戦場へ向かい、たくさんの人が帰りませんでした。兵器庫は、そうした時代のただ中で使われていた建物です。私たちはここで、戦争の歴史にも向き合うことになります。","戦争が終わると、陸軍はなくなりました。赤れんがの建物は、金沢美術工芸大学の校舎として使われます。兵器をしまっていた倉庫で、今度は若い画家や工芸家が学んだのです。«武器の倉庫が、芸術の学校に»。建物の運命の変わり方そのものが、日本の近代を物語っています。","1986年、建物は石川県立歴史博物館として新しい役目を持ちました。2015年にはリニューアルされ、ワークショップや体験の展示も増えました。縄文の土器から加賀藩の時代、近代の暮らしまで。赤れんがの中で、石川の長い時間を歩いて旅することができます。"],"tl":[["1898年","金沢に陸軍第九師団の司令部が置かれる"],["1909年〜1914年","兵器庫の赤れんが建物3棟が建てられる"],["1945年","終戦。陸軍がなくなる"],["戦後","金沢美術工芸大学の校舎として使われる"],["1986年","石川県立歴史博物館として開館"],["1990年","3棟が国の重要文化財に指定"],["2015年","リニューアルオープン"]],"who":[["陸軍第九師団","金沢に置かれた師団。兵器庫はその関係施設"],["金沢美術工芸大学の学生たち","戦後、赤れんが建物で学んだ"],["加賀本多家","加賀藩の重臣。となりの加賀本多博物館で家の品々を伝える"]],"deep":["正式な旧名は «旧金沢陸軍兵器支廠» の兵器庫。3棟とも国の重要文化財で、明治末〜大正のれんが造り倉庫群として貴重です。","れんがの積み方は «イギリス積み»。長い面の列と短い面の列を一段ごとに交互に積む方法で、強度が高いとされます。","建物の内部は、保存と展示のために改修されていますが、太い木の柱や床組みなど、倉庫時代のつくりが見られる所もあります。","兼六園周辺には、第九師団司令部庁舎や将校の社交場だった偕行社など、陸軍関係の建物もいくつか残っています（移築されたものもある）。","加賀本多博物館は、加賀藩の筆頭家老・本多家の甲冑や道具を展示。同じ赤れんが群の中にあります。"],"look":["3棟ならぶ赤れんがの外観（正面の広場から全体を）","鉄のとびらと窓のつくり","常設展の加賀藩・近代の展示","加賀本多博物館"],"q":["博物館の赤れんが建物は、もともと何に使われていた？","陸軍の兵器庫です。武器や弾薬をしまう倉庫でした。"],"koji":[],"myth":"","img":["第9師団 (日本軍)","金沢美術工芸大学"],"wp":"石川県立歴史博物館","rel":{"ev":[],"grave":[]},"ph":[["c:d/db/Ishikawa-ken_History_Museum03s3s4272b.jpg",4272,2848,"石川県立歴史博物館"],["c:b/ba/Ishikawa-ken_History_Museum01s3s4272.jpg",4272,2848],["c:c/ca/Kanazawa_College_of_Art.jpg",1600,1200,"金沢美術工芸大学"]]},{"id":"17_sekidosan","n":"石動山（天平寺と石動山合戦）","yomi":"せきどうさん","cat":"寺社","rank":"A","y":1582,"era":["heian","muromachi","azuchi"],"sh":"国指定史跡","ad":"鹿島郡中能登町石動山","st":"JR七尾線 良川駅などから車で約30分（公共交通では行きにくい）","la":36.9585,"lo":136.938,"hook":"«院坊三百六十、衆徒三千» と伝わる山の寺。戦国の炎に焼かれ、明治に仏が去り、今は森の中に跡だけが残ります。","lead":"石動山（せきどうさん）は、能登と越中の境にある標高約565mの山です。中世には天平寺を中心に多くの坊が並ぶ山岳信仰の聖地でした。1582年、前田利家の軍との戦いで焼かれ、のちに再建されましたが、明治の神仏分離で寺はなくなりました。","story":["能登半島のつけ根、深い森の中に、苔むした石段や坊の跡が点々と残る山があります。石動山。«いするぎやま» とも読まれ、古くから神のすむ山とされてきました。中世には天平寺という寺を中心に «院坊三百六十、衆徒三千» がいたと伝わります。山の上に一つの町があったようなものです。","山伏たちは能登・越中・越後へと出かけ、お札を配り、信者を集めました。石動山の力は信仰だけでなく、人と情報のネットワークでもありました。だからこそ戦国大名たちは、この山を味方につけたがったのです。","1582年、本能寺の変で織田信長が倒れると、能登の情勢は一気に不安定になります。かつて能登を治めた畠山氏の旧臣たちは、越後の上杉氏と結び、石動山の衆徒とともに立ち上がりました。«信長亡き今こそ、能登を取り戻す»。対するは、能登を与えられたばかりの前田利家と、加賀の佐久間盛政でした。","戦いは前田・佐久間方の勝利に終わります。近くの荒山の砦が落とされ、石動山は焼き討ちにあいました。多くの坊が燃え、多くの人が命を落としたと伝わります。«荒山合戦»、あるいは «石動山合戦» と呼ばれる戦いです。","その後、石動山は前田家の保護で再建されました。しかし明治の神仏分離で寺は廃され、山の信仰は «伊須流岐比古神社» に引きつがれます。今、山には復元された «大宮坊»、坊の石垣、古い参道が残り、国の史跡になっています。森の静けさの中で、かつての鐘の音を想像してみてください。"],"tl":[["奈良時代","泰澄が開いたと伝わる"],["中世","天平寺を中心に多くの坊が並ぶ山岳信仰の聖地となる"],["1582年6月","本能寺の変"],["1582年","石動山・荒山合戦。前田利家・佐久間盛政の軍が石動山を焼く"],["江戸時代","前田家の保護のもとで再建される"],["明治初め","神仏分離で天平寺が廃され、伊須流岐比古神社が残る"]],"who":[["泰澄","白山を開いた僧。石動山も泰澄が開いたと伝わる"],["前田利家","能登の新しい領主。石動山の衆徒と戦った"],["佐久間盛政","加賀の金沢城主。利家を助けて出陣した"],["温井景隆・三宅長盛","能登畠山氏の旧臣。上杉方と結んで挙兵した"]],"deep":["«院坊三百六十、衆徒三千» は最盛期を表す言い伝えで、正確な数はわかっていません。発掘では多くの坊の跡が確認されています。","«石動» を «いするぎ» と読むのは、神社名 «伊須流岐比古» に通じます。«せきどう» は仏教側の読み方として広まりました。","戦いの舞台の «荒山» は石動山の近くの峠で、そこに砦があったとされます。合戦の呼び名は «荒山合戦» と «石動山合戦» の両方が使われます。","石動山の山伏は能登・越中などに信仰の «檀那場（だんなば）» を持ち、各地に石動山信仰を広めました。","山中には、江戸時代の坊の建物を移築・復元した «大宮坊» があり、見学できます（冬季は閉鎖の可能性、事前確認を）。"],"look":["復元された大宮坊","伊須流岐比古神社と古い参道の石段","点在する坊の跡の石垣","山頂の大御前（おおごぜん）付近からの眺め"],"q":["石動山の最盛期について、どんな言い伝えがある？","«院坊三百六十、衆徒三千» と、たくさんの坊と僧がいたと伝わります。"],"koji":[],"myth":"泰澄開山、最盛期の坊・衆徒の数、焼き討ちの被害規模は伝承を含む。","img":["伊須流岐比古神社","前田利家"],"wp":"石動山","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/Isurugihiko-jinja_shrine.jpg",5472,3648,"伊須流岐比古神社"],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:5/5d/Hudotaki_Water_Fall%2C_Nakanoto.jpg",1824,2432,"近く: 中能登町"],["c:1/1b/Noto-Ninomiya_Station_2020.jpg",3456,2304,"近く: 能登二宮駅"],["c:6/60/Yoshikawa_Station_2020.jpg",3456,2304,"近く: 良川駅"],["c:6/60/Alksh20.4.jpg",1132,530,"近く: アル・プラザ鹿島"]]},{"id":"17_komaruyama","n":"小丸山城（前田利家最初の居城）","yomi":"こまるやまじょう","cat":"城","rank":"A","y":1582,"era":["azuchi"],"sh":"","ad":"七尾市馬出町","st":"JR七尾駅から徒歩約10分","la":37.0435,"lo":136.964,"hook":"«加賀百万石» の出発点は、金沢ではなく七尾の小さな丘でした。前田利家が大名として最初に築いた城です。","lead":"小丸山城は、織田信長から能登一国を与えられた前田利家が築いた城です。山の上の七尾城ではなく、港に近い小さな丘に城を移しました。利家が金沢に移ったあとに廃城となり、今は «小丸山城址公園» として整備されています。","story":["1581年、前田利家は織田信長から能登一国を与えられました。それまで信長の家臣として戦い続けてきた利家が、いよいよ一国の主、«大名» になったのです。«又左、能登を治めよ»。又左衛門と呼ばれた利家は、妻のまつとともに能登へ向かいました。","能登にはすでに、畠山氏が築いた大きな山城・七尾城がありました。日本五大山城の一つに数えられることもある堅固な城です。ところが利家は、その山城から下りて、港町・所口（今の七尾市街）のそばの小さな丘に新しい城を築きます。それが小丸山城です。","«なぜ強い山城を捨てたの?» 答えは «戦いの時代から、治める時代へ»。山の上の城は守りには強いけれど、町や港からは遠く、物や人を動かすのに不便です。港に近い丘に城を置けば、城下町をつくり、船で米や品物を運び、商人を集められます。利家は、国を豊かにするための城を選んだのです。","しかし利家がここにいた時間は長くありませんでした。1583年、賤ヶ岳の戦いのあと、羽柴（豊臣）秀吉から加賀の地を加えられ、利家は金沢城へ移ります。小丸山城には一族や家臣が置かれましたが、やがて一国一城令のころまでに城としての役目を終えました。","今の城跡は公園になり、利家とまつの像が七尾の町を見下ろしています。小さな丘ですが、ここから «加賀百万石» への道が始まりました。«最初の一歩を、港のそばに» 置いた利家の判断が、その後の加賀藩の繁栄につながっていったのかもしれません。"],"tl":[["1581年","前田利家が織田信長から能登一国を与えられる"],["1582年ごろ","小丸山城の築城を始める"],["1582年","本能寺の変。石動山・荒山合戦"],["1583年","賤ヶ岳の戦い後、利家が金沢城に移る"],["江戸時代初め","城としての役目を終え廃城となる"],["現在","小丸山城址公園として整備"]],"who":[["前田利家","城を築いた能登の領主。のちの加賀藩の祖"],["まつ（芳春院）","利家の妻。夫とともに能登で暮らした"],["前田安勝","利家の兄。利家が金沢に移ったあと七尾を守ったとされる"],["織田信長","利家に能登一国を与えた"]],"deep":["小丸山城の築城開始は1582年ごろとされますが、細かな時期や完成時期は諸説あります。","七尾城は標高約300mの山城で、国指定史跡。畠山氏の本拠でしたが、1577年に上杉謙信に攻め落とされました。","利家が山城から平地近くの城に移したことは、同じころの信長の安土城、のちの近世城郭へと続く «山から平地へ» の流れの一例といえます。","公園の中には、利家・まつの像のほか、郭（くるわ）の段差など城の地形がわずかに残っています。","«所口» は七尾港まわりの古い地名で、江戸時代には «七尾» と «所口» の呼び名が入りまじっていました。"],"look":["前田利家とまつの像","丘の上から見る七尾の町と七尾湾","公園内の段差（郭の名残）","あわせて訪ねたい七尾城跡（車で約20分）"],"q":["前田利家はなぜ山の上の七尾城から小丸山城に移った？","港や町に近い場所で、城下町づくりや物流をしやすくするためと考えられています。"],"koji":[],"myth":"築城年・廃城年や兄・安勝の在城については諸説がある。","img":["前田利家","七尾城"],"wp":"小丸山城","rel":{"ev":[],"grave":[]},"ph":[["c:6/6a/Komaruyama_castle.JPG",3648,2736,"小丸山城"],["c:1/1a/Komaruyama_Park_in_Nanao.JPG",1600,1200],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:9/9a/Nanaojo-tyoudomaru.JPG",1280,960,"七尾城"]]},{"id":"17_noto_kokubunji","n":"能登国分寺跡","yomi":"のとこくぶんじあと","cat":"遺跡","rank":"A","y":843,"era":["nara","heian"],"sh":"国指定史跡","ad":"七尾市国分町","st":"JR七尾駅から車で約10分（能登国分寺公園）","la":37.033,"lo":136.927,"hook":"日本の国分寺の中で、いちばん遅く生まれた国分寺の一つ。能登の «国の成り立ち» の遅さが、そのまま寺の歴史になっています。","lead":"能登国分寺は、平安時代の843年に、もとからあった «大興寺» を国分寺にしてできたお寺です。建物は残っていませんが、発掘された塔や金堂の跡が公園として整備され、南門や塀が復元されています。国の史跡です。","story":["741年、聖武天皇は «国ごとに国分寺をつくれ» という命令を出しました。疫病や飢饉、反乱が続く中、仏の力で国を守ろうとしたのです。全国の国に、七重の塔を持つ国分寺と国分尼寺がつくられていきました。","ところがそのころ、«能登国» は存在しませんでした。能登は718年にいったん越前国から分けられて国になったのに、741年に越中国に合わせられてしまったのです。«国がないのだから、国分寺もない»。能登が再び独立したのは757年のことでした。","独立したあとも、能登にはなかなか国分寺ができませんでした。国の力が小さく、大きな寺を一からつくるのはたいへんだったのでしょう。そこで843年、国府の近くにあった «大興寺» という寺を、そのまま能登国分寺にすることが決まります。«新しく建てるのではなく、今ある寺を格上げする»。能登らしい工夫です。","発掘調査では、塔の跡、金堂の跡、講堂の跡などが見つかりました。瓦の文様からは、寺そのものが国分寺になる前から建っていたこともうかがえます。寺はやがておとろえ、いつしか建物は失われましたが、地下には平安の人びとの祈りの跡が残っていました。","今、跡地は «能登国分寺公園» となり、朱色の南門と塀が復元されています。展示館では出土した瓦などを見られます。広い芝生に立って、七重の塔があったかもしれない空を見上げると、«小さな国の大きな願い» が感じられます。"],"tl":[["718年","能登国が越前国から分かれて置かれる"],["741年","聖武天皇が国分寺建立の詔を出す／能登が越中国に合わせられる"],["757年","能登国が再び置かれる"],["843年","大興寺が能登国分寺となる"],["中世","寺がおとろえ、やがて廃絶する"],["昭和時代","発掘調査が行われ、国の史跡に指定される"],["現在","能登国分寺公園として南門などを復元"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["能登国司","能登国を治めた役人。国分寺の運営にかかわった"],["大興寺の僧たち","国分寺に格上げされる前からこの寺を守っていた"]],"deep":["定額寺（じょうがくじ）など既存の寺を国分寺にあてる例は、能登のほかにもあり、財政の厳しい国の工夫と考えられています。","能登国分寺跡の伽藍配置は、塔・金堂・講堂が並ぶ配置で、発掘により塔の心礎（しんそ）の位置などが確認されています。","能登の国府は七尾市の古府・国分周辺にあったと考えられていますが、国府の正確な位置はまだ確定していません。","能登国分寺は «最後の国分寺» と呼ばれることがありますが、国分寺の成立時期は国によってさまざまで、厳密な順番を言うのは難しいです。","能登国分寺公園には展示館があり、瓦や土器などの出土品と復元模型を見ることができます。"],"look":["復元された朱色の南門と築地塀","塔跡・金堂跡の基壇（きだん）","展示館の瓦と伽藍の模型","公園から見える七尾の平野と山なみ"],"q":["能登国分寺は、何という寺を格上げしてできた？","«大興寺» です。843年に国分寺となりました。"],"koji":[],"myth":"«最後の国分寺» という呼び方は通説的な表現。能登国府の位置は未確定。","img":["国分寺","能登国"],"wp":"能登国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/0b/%E8%83%BD%E7%99%BB%E5%9B%BD%E5%88%86%E5%AF%BA_%281%29.jpg",3872,2592,"能登国分寺"],["c:c/cf/%E8%83%BD%E7%99%BB%E5%9B%BD%E5%88%86%E5%AF%BA_%282%29.jpg",3872,2592],["c:a/a0/Bitchu_Kokubunji%2C_zenkei.jpg",6010,3990,"国分寺"]]},{"id":"17_wajimanuri","n":"輪島塗","yomi":"わじまぬり","cat":"産業","rank":"A","y":1700,"era":["muromachi","edo","reiwa"],"sh":"国の重要無形文化財","ad":"輪島市河井町ほか（輪島漆芸美術館は輪島市水守町）","st":"金沢駅から特急バスで約2時間半（震災後は運行状況を要確認）","la":37.3905,"lo":136.8995,"hook":"«地の粉» と «布着せ»。何十回も塗っては研ぐ手しごとが、落としても割れにくい丈夫なうるしの器を生みました。","lead":"輪島塗は、能登半島の北の町・輪島でつくられる漆器です。輪島の土からつくる «地の粉» を下地にまぜ、傷みやすい所に布を貼る «布着せ» で、とても丈夫なのが特長。百を超える工程を分業で仕上げます。2024年の能登半島地震で大きな被害を受け、いま復興に取り組んでいます。","story":["輪島の町に朝が来ると、あちこちの工房で木地をけずる音、うるしを塗る刷毛の音が聞こえてきました。輪島塗は、一人の名人がつくるのではありません。木地師、下地をつける人、塗る人、研ぐ人、沈金や蒔絵で飾る人……。たくさんの職人が順番に手を入れ、百以上の工程を重ねて、一つの器が生まれます。","輪島塗の秘密は «下地» にあります。輪島の小峰山あたりでとれる珪藻土を焼いて粉にしたものを «地の粉»（じのこ）といいます。これを生うるしにまぜて何度も塗り重ねると、硬くて丈夫な下地ができます。さらに、お椀のふちや底など傷みやすい所には、麻などの布をうるしで貼る «布着せ»。«なぜそこまで?» 毎日使う器だから、長く使えることがいちばん大切だったのです。","輪島でいつごろ漆器づくりが始まったのか、はっきりとはわかっていません。町の «重蔵神社» には、室町時代の漆塗りの扉が伝わり、輪島塗の古い例といわれています。江戸時代になると、輪島の塗師屋（ぬしや）は器を背負って全国を行商し、北前船にも積まれて各地へ広まりました。«輪島の椀は丈夫だ» という評判が、日本じゅうに届いていったのです。","表面を飾る技も発達しました。のみで線を彫ってそこに金箔や金粉をうめこむ «沈金»、うるしで絵を描いて金粉をまく «蒔絵»。黒や朱の地に、金の模様がきらりと光ります。1977年、輪島塗は国の重要無形文化財に指定されました。","2024年1月1日、能登半島地震が輪島をおそいました。多くの方が亡くなり、朝市の通りは大きな火災で焼け、工房や職人の家も被害を受けました。それでも職人たちは «また塗りたい» と、仮設の工房で仕事を再開しています。輪島塗の器を手に取ることは、この町の復興をささえることにもつながっています。"],"tl":[["室町時代","重蔵神社に漆塗りの扉がつくられたと伝わる（古い輪島の漆器の例）"],["江戸時代","地の粉を使った丈夫な下地の技法が広まり、行商で全国へ"],["江戸時代後期","沈金の技法が輪島で発達したといわれる"],["1977年","国の重要無形文化財に指定（保持団体は輪島塗技術保存会）"],["平成時代","石川県輪島漆芸美術館が開館"],["2024年1月1日","能登半島地震で輪島の町と工房が大きな被害を受ける"]],"who":[["輪島の塗師屋","職人をまとめ、器を売り歩いた親方・商人"],["木地師・塗師・沈金師・蒔絵師","分業で一つの器をつくりあげる職人たち"],["輪島塗技術保存会","重要無形文化財の保持団体として技を伝える"]],"deep":["«地の粉» は珪藻土を焼いて砕いたもの。細かい穴の多い粒がうるしをよく吸い、硬い下地になるといわれます。","輪島塗の工程は «124工程» などと紹介されることがありますが、数え方によって変わり、«百以上» と言われるのが一般的です。","重蔵神社の扉を «最古の輪島塗» とする説明がありますが、年代や技法の評価については諸説があります。","北前船の寄港地や行商先の記録から、輪島の漆器が東北や北海道まで運ばれていたことがわかっています。","国の重要無形文化財には、ほかに «人間国宝» として個人が認定される分野もあり、輪島の漆芸家から沈金や蒔絵の人間国宝が出ています。"],"look":["石川県輪島漆芸美術館（再開状況を要確認）","輪島塗会館などでの工程の展示","沈金・蒔絵の実演や体験（受け入れ状況を要確認）","重蔵神社"],"q":["輪島塗の丈夫な下地に使う、輪島の土からつくる粉を何という？","«地の粉（じのこ）» です。珪藻土を焼いて粉にし、うるしにまぜて使います。"],"koji":[],"myth":"起源の時期、重蔵神社の扉の評価、工程数は諸説あり。震災後の施設の公開状況は変わりやすい。","img":["沈金","輪島市"],"wp":"輪島塗","rel":{"ev":[],"grave":[]},"ph":[["c:2/22/Wajimanurie.JPG",646,604,"輪島塗"],["c:e/e8/Chinkin.jpg",3030,2721,"沈金"],["c:5/50/Wajima_Asaichi_ac_%2810%29.jpg",5953,3959,"輪島市"]]},{"id":"17_senmaida","n":"白米千枚田","yomi":"しろよねせんまいだ","cat":"産業","rank":"A","y":1700,"era":["edo","heisei","reiwa"],"sh":"国指定名勝","ad":"輪島市白米町","st":"輪島市街から車で約20分（バスは本数が少ない）","la":37.414,"lo":136.9545,"hook":"日本海に向かって、小さな田んぼが階段のように落ちていく。1枚1枚を手で守ってきた、能登の人びとの粘り強さの風景です。","lead":"白米千枚田は、能登半島の北の海岸にある棚田です。急な斜面に1,000枚ほどの小さな田が重なり、海のすぐそばまで続きます。国の名勝で、«能登の里山里海» は世界農業遺産にも認定されています。2024年の地震で大きな被害を受け、いまボランティアとともに復旧が進められています。","story":["輪島の町から海沿いの道を東へ。やがて、目の前の斜面いっぱいに、小さな田んぼがうろこのように重なって見えてきます。白米千枚田です。«千枚» といっても大げさではありません。1,000枚をこえる田が、海に向かって落ちていきます。","«なぜこんな急な斜面に田んぼを?» 能登の北の海岸は、山がすぐ海にせまり、平らな土地がほとんどありません。それでも米をつくりたい。人びとは斜面を少しずつ削り、石や土でふちを固め、水をためられる平らな場所を一枚ずつつくっていきました。いつごろ始まったのかははっきりしませんが、江戸時代にはすでに棚田があったと考えられています。","田んぼの中には、畳一枚ほどしかない小さなものもあります。«一枚足りないと思ったら、脱いだ笠の下にあった» という笑い話は、各地の棚田に伝わるお話で、ここ千枚田でも語られます。牛や機械が入れないので、田おこしも田植えも稲刈りも、ほとんど人の手です。","時代が進み、お米づくりをする人が減ると、千枚田も荒れそうになりました。そこで地元の人と «オーナー制度» で集まった人たちが、いっしょに田を守るようになります。2001年に国の名勝に。2011年には «能登の里山里海» が世界農業遺産に認定され、千枚田はその代表的な風景となりました。秋から冬には、あぜ道に明かりをともす «あぜのきらめき» も行われています。","2024年1月1日の能登半島地震で、千枚田には多くのひびや崩れができ、水を引く道も壊れました。それでも «また米をつくろう» と、地元の人とボランティアが少しずつ田を直し、一部の田で田植えが再開されました。海と空と人の手がつくる風景は、今も守られようとしています。"],"tl":[["江戸時代","棚田がすでにつくられていたと考えられる"],["昭和時代後半","米づくりの担い手が減り、荒れる田が増える"],["2001年","国の名勝に指定"],["2011年","«能登の里山里海» が世界農業遺産に認定"],["2024年1月1日","能登半島地震で大きな被害"],["2024年以降","地元とボランティアによる復旧と田植えの再開"]],"who":[["白米町の人びと","代々、斜面の田を手で守ってきた"],["千枚田のオーナー・ボランティア","田植えや稲刈りに参加し、保全をささえる"],["輪島市","保全活動や «あぜのきらめき» などを進める"]],"deep":["田の枚数は «1,004枚» と紹介されることが多いですが、区画の数え方や年によって変わります。","千枚田の田は、海に近いので潮風の影響を受けやすく、一般の田よりも手入れがたいへんです。","棚田の水は山からの湧き水や沢の水を引いています。«地すべり地» を利用して棚田がつくられたと考えられる例は、能登に多く見られます。","世界農業遺産（GIAHS）は国連食糧農業機関（FAO）が認定する制度で、2011年、«能登の里山里海» は «トキと共生する佐渡の里山» とともに日本で初めて認定されました。","«笠の下の田» の笑い話（笠田）は、全国の棚田に似た話があり、白米千枚田独自の史実ではありません。"],"look":["道の駅 «千枚田ポケットパーク» の展望所から全景","あぜ道を歩いて小さな田の大きさを体感（立入可能範囲を要確認）","夕日の時間の海と棚田","冬の «あぜのきらめき»（開催状況を要確認）"],"q":["白米千枚田をふくむ «能登の里山里海» が認定された、国際的な遺産は何？","世界農業遺産（GIAHS）です。2011年に日本で初めて認定されました。"],"koji":[],"myth":"起源の年代は不明。«笠の下の田» は各地に伝わる笑い話。震災後の見学条件は変わりやすい。","img":["棚田","能登の里山里海"],"wp":"白米千枚田","rel":{"ev":[],"grave":[]},"ph":[["c:9/98/Shiroyone_Senmaida_200906.jpg",4032,3024,"白米千枚田"],["c:b/b0/Shiroyone-Senmaida_sunset.jpg",5472,3648],["c:5/51/Shiroyone_Senmaida_%288266941838%29.jpg",4288,2848],["c:0/0c/%E7%99%BD%E7%B1%B3%E5%8D%83%E6%9E%9A%E7%94%B0.JPG",3008,2000],["c:4/4b/%E7%99%BD%E7%B1%B3%E5%8D%83%E6%9E%9A%E7%94%B0%E4%B8%87%E7%87%88%E3%81%BE%E3%81%A4%E3%82%8A_%28Candle_night_at_Hakumai_Senmaida%29_19_Oct%2C_2013_-_panoramio.jpg",2800,2100],["c:2/2e/Shiroyone_rice_terraces%2C_Noto_peninsula_%284042818640%29.jpg",2000,1500],["c:4/4c/%E7%99%BD%E7%B1%B3%E3%81%AE%E5%8D%83%E6%9E%9A%E7%94%B0_-_panoramio.jpg",1600,900],["c:2/2b/Wajima-senmaida_stereo.jpg",1114,880]]},{"id":"17_tokikuni","n":"時国家（平時忠の子孫の豪農屋敷）","yomi":"ときくにけ","cat":"町","rank":"A","y":1831,"era":["heian","edo"],"sh":"国の重要文化財","ad":"輪島市町野町","st":"輪島市街から車で約40分（公共交通では行きにくい）","la":37.429,"lo":137.058,"hook":"«平家にあらずんば人にあらず»。そう言ったと伝わる平時忠の子孫が、能登の奥で大きな屋敷を守ってきました。","lead":"時国家は、能登半島の奥・輪島市町野町にある大きな農家の屋敷です。壇ノ浦で敗れて能登に流された平家の武将・平時忠の子孫と伝わります。江戸時代に二つの家に分かれ、«上時国家» と «下時国家» の屋敷はどちらも国の重要文化財です。2024年の能登半島地震で大きな被害を受けました。","story":["平清盛の妻・時子の弟が、平時忠です。平家が栄えていたころ、時忠は «この一門にあらざらむ人は、みな人非人なるべし» と言ったと『平家物語』に書かれています。のちに «平家にあらずんば人にあらず» として有名になった言葉です。","1185年、壇ノ浦の戦いで平家はほろびました。時忠は捕らえられましたが、三種の神器の «神鏡» を守ったことなどから命を助けられ、能登へ流されます。1189年、時忠は能登で亡くなりました。«都の栄華から、日本海の果ての地へ»。その落差を思うと、胸がしめつけられます。","時忠の子・時国がこの地にとどまり、家を開いたと伝わります。これが «時国家» の始まりです。一族は奥能登で土地を開き、塩づくりや海運などで力をつけ、大きな農家、«豪農» となっていきました。江戸時代の初め、家は二つに分かれ、«上時国家» と «下時国家» が生まれます。","上時国家の主屋は1831年ごろに完成したと伝わる、茅葺きの巨大な屋敷でした。大きな入母屋の屋根、広い土間、格式の高い «御前の間»。加賀藩の役人を迎えるため、武家屋敷のような部屋も備えていました。下時国家はより古く、江戸時代前期の建物とされます。«農家なのに、まるで大名屋敷» と驚かれました。","2024年1月1日の能登半島地震で、時国家の屋敷は大きな被害を受け、上時国家の主屋は倒壊したと報じられました。800年以上この地で続いてきた家の歴史が、大きな試練を迎えています。訪ねる前には最新の公開状況を確かめ、被災した地域への思いやりを持って歩きましょう。"],"tl":[["1185年","壇ノ浦の戦いで平家がほろびる。時忠は捕らえられる"],["1185年","時忠が能登へ流される"],["1189年","時忠が能登で亡くなる"],["江戸時代初め","時国家が上時国家と下時国家に分かれる"],["1831年ごろ","上時国家の主屋が完成したと伝わる"],["2024年1月1日","能登半島地震で屋敷が大きな被害を受ける"]],"who":[["平時忠","平清盛の義弟。能登に流され、この地で亡くなった"],["平時国","時忠の子と伝わる。時国家の祖"],["平時子（二位尼）","清盛の妻で時忠の姉。壇ノ浦で安徳天皇を抱いて入水"],["時国家の歴代当主","奥能登の豪農として、地域の農業や経営をになった"]],"deep":["«平家にあらずんば人にあらず» は、『平家物語』の «この一門にあらざらむ人は、みな人非人なるべし» を短くした言い方です。時忠が本当にそう言ったかは物語の記述です。","時忠の墓とされる場所は珠洲市大谷町にあり、近くには時忠一族の墓所として伝わる所があります。","時国家の文書（時国家文書）は、中世から近世の奥能登の社会や経済を知る重要な史料として、歴史学の研究に使われてきました。","上時国家と下時国家（本家）の分立の時期は、寛永年間（1630年代）とされます。","2024年の震災による被害状況や公開再開の見通しは、時期によって変わるため、最新情報の確認が必要です。"],"look":["上時国家・下時国家の屋敷の外観（公開状況を要確認）","茅葺き屋根と広い土間のつくり","近くの町野川の流れと奥能登の農村風景","珠洲市大谷の平時忠の墓（車で移動）"],"q":["«平家にあらずんば人にあらず» と言ったと伝わる、時国家の祖先は誰？","平時忠です。平清盛の妻・時子の弟でした。"],"koji":[{"w":"平家にあらずんば人にあらず","m":"平家の一門でなければ人ではない、というほどの平家の勢いを表す言葉。『平家物語』に由来"}],"myth":"時国を時忠の子とする系譜、上時国家の建築年は伝承を含む。震災被害と公開状況は最新情報を要確認。","img":["平時忠","平家物語"],"wp":"時国家","rel":{"ev":[],"grave":[]},"ph":[["c:7/73/%E5%B9%B3%E5%AE%B6%E7%89%A9%E8%AA%9E%EF%BD%A5%E7%A5%87%E5%9C%92%E7%B2%BE%E8%88%8E%E3%82%B5%E3%83%B3%E3%83%97%E3%83%AB.png",974,732,"平家物語"],["c:e/e5/Tarumi_Fall_%26_Yasenodomon.jpg",1600,1200,"近く: 曽々木海岸"]]},{"id":"17_sozo","n":"須曽蝦夷穴古墳（能登島）","yomi":"すそえぞあなこふん","cat":"島","rank":"A","y":650,"era":["asuka","kofun"],"sh":"国指定史跡","ad":"七尾市能登島須曽町","st":"JR七尾駅から車で約25分（能登島大橋を渡る）","la":37.086,"lo":136.969,"hook":"«えぞあな» という不思議な名前の古墳。中に入ると、T字形の石の部屋が二つ。海の向こうの国とのつながりを思わせる古墳です。","lead":"須曽蝦夷穴古墳は、七尾湾に浮かぶ能登島にある7世紀中ごろの方墳（四角い古墳）です。一つの墳丘の中に、横穴式石室が二つ並んでいます。石室の形が朝鮮半島の高句麗の古墳に似ていると指摘され、国の史跡に指定されています。","story":["能登島は、七尾湾に浮かぶおだやかな島です。その丘の上に、四角い古墳が一つあります。«須曽蝦夷穴（すそえぞあな）古墳»。«蝦夷の穴» という名前は、昔の人がこの石室を «蝦夷（えみし）が住んでいた穴» と考えたことから付いたといわれます。もちろん、実際はお墓です。","古墳がつくられたのは7世紀の中ごろ。大きな前方後円墳がつくられなくなり、日本が «飛鳥時代» に入って、国のしくみが整えられていくころです。一辺約20m前後の四角い墳丘の中に、横穴式の石室が二つ、並んでつくられています。","石室の形がとても変わっています。奥の部屋の前に、横に長い前の部屋がつき、上から見ると «T» の字のようになっています。天井は石を少しずつ内側にせり出させて積む、ドームのようなつくり。«こんな形、ほかでは見ない» と研究者たちは驚きました。そして、朝鮮半島北部の高句麗の古墳の石室に似ている、と考えたのです。","«なぜ能登の島に、高句麗風の古墳が?» 当時の日本海は、大陸と日本を結ぶ海の道でした。朝鮮半島や大陸から人や技術が伝わり、能登はその玄関口の一つだったのかもしれません。ここに眠る人は、海を越えた交流をになった有力者だったのではないか、という説もあります。ただし、埋葬された人物ははっきりわかっていません。","古墳は修復・整備され、石室の中をのぞくことができます。そばには資料館もあります。潮風に吹かれながら石の部屋の入口に立つと、1,300年以上前、この島から海の向こうを見ていた人びとの姿が浮かんでくるようです。"],"tl":[["7世紀中ごろ","古墳がつくられる"],["江戸時代以前","«蝦夷穴» と呼ばれ、石室の入口が知られていた"],["昭和時代","国の史跡に指定"],["昭和〜平成","発掘・修復が行われ、史跡公園として整備"],["現在","石室の見学と資料館での展示"]],"who":[["古墳に葬られた人","能登島や七尾湾一帯の有力者と考えられるが、名前は不明"],["高句麗","朝鮮半島北部にあった国。石室の形が似ているとされる"],["発掘・整備にかかわった研究者","石室の構造を明らかにし、公開を可能にした"]],"deep":["墳丘は方墳で、一辺は約18〜20m程度とされます。数値は報告によって少し差があります。","二つの石室はいずれも、前室と奥の玄室からなる «T字形» の平面で、天井は持ち送り（せり出し）式に積まれています。","高句麗の石室との類似は多くの研究者が指摘していますが、在地の工夫や畿内の影響を重視する見方もあり、系譜については諸説あります。","出土品には、須恵器や金銅製の装身具の破片などがあったと報告されています。","«蝦夷穴» という名前は、古代の «蝦夷» と直接の関係はなく、後世の呼び名と考えられています。"],"look":["T字形の横穴式石室（入口からのぞける）","持ち送り式の天井の石組み","併設の資料館の模型と出土品","古墳の丘から見る七尾湾"],"q":["須曽蝦夷穴古墳の石室は、上から見るとどんな形？","«T» の字の形です。横長の前室の奥に玄室がつながっています。"],"koji":[],"myth":"«蝦夷穴» の名の由来、高句麗との系譜、被葬者像は諸説・推測を含む。","img":["能登島","横穴式石室"],"wp":"須曽蝦夷穴古墳","rel":{"ev":[],"grave":[]},"ph":[["c:0/03/Susoezoanakofun_corner.jpg",800,600,"須曽蝦夷穴古墳"],["c:e/e0/Ezosusoanakohun.JPG",3264,2448],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:f/f0/Notojima_Island_Aerial_photograph.2014.jpg",30250,17605,"能登島"],["c:5/59/Monjuin_Nishi_Kofun%2C_sendou-1.jpg",6002,3978,"横穴式石室"]]},{"id":"17_hakusan","n":"白山（白山信仰と禅定道）","yomi":"はくさん","cat":"寺社","rank":"A","y":717,"era":["nara","heian","kamakura"],"sh":"","ad":"白山市三宮町（白山比咩神社）ほか","st":"北陸鉄道石川線 鶴来駅から白山比咩神社までバス・タクシーで約5分","la":36.447,"lo":136.6375,"hook":"«しらやま» と呼ばれた真っ白な山。1300年前、一人の僧が山頂をめざしたときから、白山は祈りの山になりました。","lead":"白山は、石川・岐阜・福井にまたがる標高2,702mの山です。雪をいただく姿から «白山» と呼ばれ、古くから神の山として信仰されてきました。717年に泰澄が初めて登ったと伝わり、加賀・越前・美濃の三方から山頂へ向かう «禅定道» がつくられました。加賀側のふもとには白山比咩神社があります。","story":["加賀の平野から南を見ると、夏でも雪を残す白い山が見えます。白山。人びとはこの山を «しらやま» と呼び、水をもたらす神の山としてあがめてきました。山から流れ出る手取川は田んぼをうるおし、人びとの暮らしを支えています。«山は水の源、水は命の源»。白山信仰の根っこには、そんな感謝の気持ちがありました。","717年、越前の僧・泰澄が、この山に初めて登ったと伝わります。山頂の池のほとりで祈っていると、池から九つの頭を持つ竜が現れ、やがて十一面観音の姿になった……という不思議な話が残されています。«白山妙理大権現»。泰澄が出会ったとされる神仏の名前です。","その後、山頂をめざす修行の道が三つつくられました。加賀から登る «加賀禅定道»、越前からの «越前禅定道»、美濃からの «美濃禅定道»。それぞれの登り口には «馬場（ばんば）» と呼ばれる拠点が置かれ、加賀の馬場の中心が、今の白山比咩神社です。«禅定» とは、山頂に登り、心をしずめて悟りに近づくこと。人びとは何日もかけて山を歩きました。","中世には、白山の寺社は大きな力を持ちました。加賀の «白山本宮» は延暦寺とも結びつき、僧兵をかかえていたといわれます。やがて戦乱や一向一揆の時代をへて、江戸時代には山頂の支配をめぐって加賀・越前側が争う場面もありました。明治の神仏分離では、山の仏像が下ろされ、白山は神社の山になりました。","今、白山比咩神社は全国の白山神社の総本宮として、多くの参拝者を集めています。夏になると登山者たちが山頂の御前峰（ごぜんがみね）で御来光を待ちます。昔の修行者と同じように、朝日に照らされる白い山を見上げてみてください。"],"tl":[["717年","泰澄が白山に初めて登ったと伝わる"],["平安時代","加賀・越前・美濃の三馬場と禅定道が整う"],["中世","白山本宮が延暦寺と結び勢力を持つ"],["1480年","大火で白山本宮が焼け、のちに今の地に移ったと伝わる"],["明治初め","神仏分離で山上の仏像が下ろされる"],["1962年","白山国立公園に指定"],["2023年","白山手取川ジオパークがユネスコ世界ジオパークに認定"]],"who":[["泰澄","越前の僧。白山を開いたと伝わる «越の大徳»"],["白山比咩大神（菊理媛神）","白山比咩神社にまつられる神。菊理媛神と同じ神とされる"],["加賀馬場の衆徒","白山本宮を中心に、中世の白山信仰をになった人びと"]],"deep":["白山の最高峰は御前峰（2,702m）。大汝峰・剣ヶ峰とあわせた一帯を «白山» と呼びます。","泰澄の伝記『泰澄和尚伝記』は後の時代にまとめられたもので、泰澄の実在や事績には史料上の議論があります。","«日本三名山» として、富士山・立山とならべて白山を数える言い方が古くからあります（«三霊山» とも）。","白山比咩神社の祭神 «菊理媛神»（くくりひめのかみ）は、『日本書紀』の一書にわずかに登場する神で、«くくる（結ぶ）» の意味から縁結びの神ともされます。","白山信仰は全国に広がり、白山神社は全国で2,000社をこえるといわれます。"],"look":["白山比咩神社の表参道の杉並木","神社近くの «禊場（みそぎば）» と手取川の流れ","白山の山頂・御前峰（夏山シーズンの登山）","白山市の «白山比咩神社宝物館»（開館状況を要確認）"],"q":["白山に初めて登ったと伝わる僧は誰？","泰澄です。717年に登ったと伝わります。"],"koji":[],"myth":"泰澄の開山と九頭竜の話、白山本宮の移転の経緯は伝承・諸説を含む。","img":["白山比咩神社","泰澄"],"wp":"白山","rel":{"ev":[],"grave":[]},"ph":[["c:e/eb/Mount_Haku_from_Onanjimine_2011-07-17.jpg",2560,1707,"白山"],["c:4/43/%E5%BE%A1%E5%89%8D%E5%B3%B0%E3%81%8B%E3%82%89%E6%9C%9B%E3%82%80%E5%A4%A7%E6%B1%9D%E5%B3%B0%E3%81%A8%E5%89%A3%E3%83%B6%E5%B3%B0_2024.jpg",4032,3024],["c:7/70/Pond_Konyagaike.JPG",5184,3456],["c:5/51/Pond_Hyakushoike_from_Mount_Gozen.JPG",5000,3200],["c:4/43/Mt.Haku_in_summer.JPG",4288,2848],["c:a/a8/Pond_Chinoike.JPG",3888,2592],["c:f/ff/Pond_Aburagaike.JPG",3888,2592],["c:9/94/Mount_Kengamine_and_Pond_Midorigaike.jpg",3888,2592]]},{"id":"17_zeniya","n":"銭屋五兵衛と宮腰（金石）","yomi":"ぜにやごへえとみやのこし（かないわ）","cat":"産業","rank":"A","y":1852,"era":["edo"],"sh":"","ad":"金沢市金石本町（銭屋五兵衛記念館ほか）","st":"JR金沢駅からバスで «金石» 方面へ約30分","la":36.6005,"lo":136.606,"hook":"«海の百万石» と呼ばれた大商人は、最後は牢の中で80年の生涯を終えました。港町・金石に、その夢と悲劇が残ります。","lead":"銭屋五兵衛は、江戸時代後期に金沢の外港・宮腰（今の金石）で活躍した豪商です。北前船などの海運で巨万の富をきずき、加賀藩の財政も助けました。しかし晩年、河北潟の埋め立て工事をめぐる疑いで捕らえられ、牢の中で亡くなりました。","story":["1773年、五兵衛は宮腰の商家に生まれました。家は両替や質屋、呉服などを営んでいて、«銭屋» の屋号はそこから来ています。家業をついだ五兵衛は、もう若くはない年齢から海運業に乗り出しました。«陸の商いだけでは小さい。海には、もっと大きな商いがある»。","五兵衛の船は、北前船の航路を行き来し、米や木材、海産物を運んで売り買いしました。持ち船は大小あわせて数十そうにのぼったといわれ、全国の港に支店のような拠点を置いたと伝わります。人びとは彼を «海の百万石» と呼びました。加賀藩の «百万石» にならぶほどの財力、という意味です。","五兵衛の富は、財政に苦しむ加賀藩にとってもありがたいものでした。藩の重臣・奥村栄実（てるざね）らとのつながりの中で、五兵衛は藩の御用を引き受け、大きなお金を納めたといわれます。いっぽうで、«藩とかくれて外国と密貿易をしていたのでは» といううわさも生まれました。ただし、これを確かに示す史料はなく、伝説とされています。","晩年、五兵衛は金沢の北にある河北潟を埋め立て、新しい田をつくる大工事に取りかかりました。ところが工事中、潟の魚が大量に死に、それを食べた人が亡くなったといううわさが広がります。«銭屋が潟に毒を流したのでは»。五兵衛と一族は捕らえられ、1852年、五兵衛は取り調べのさなか、牢の中で亡くなりました。80歳でした。","«なぜ、あれほどの商人が?» 後ろ盾だった奥村栄実がすでに亡くなり、藩の中の政治的な争いに巻きこまれた、とする見方があります。本当の理由は、今もはっきりしません。金石の町には、銭屋五兵衛記念館や銅像があり、港を見つめています。海に夢をかけた男の栄光と転落を、ゆっくりたどってみてください。"],"tl":[["1773年","宮腰に生まれる"],["江戸時代後期","海運業に乗り出し、北前船の航路で商売を広げる"],["1840年代","加賀藩の御用を務め、«海の百万石» と呼ばれる"],["1851年ごろ","河北潟の埋め立て工事に取りかかる"],["1852年","毒流しの疑いで捕らえられ、牢の中で死去（80歳）"],["昭和〜平成","金石に記念館がつくられ、業績が紹介される"]],"who":[["銭屋五兵衛","宮腰の豪商。海運で財をなし «海の百万石» と呼ばれた"],["銭屋要蔵","五兵衛の息子。父とともに捕らえられた"],["奥村栄実","加賀藩の重臣。五兵衛の後ろ盾だったといわれる"],["前田斉泰","当時の加賀藩主"]],"deep":["«宮腰» は金沢の外港で、明治以後 «金石» と改められました。犀川の河口にあり、城下と海を結ぶ港でした。","五兵衛が本格的に海運業を始めたのは50代以降ともいわれ、晩年に大成功した商人として知られます。","«樺太や外国との密貿易» の話は、明治以降の小説や講談で広まった面が大きく、史料では確かめられていません。","河北潟の事件では、五兵衛のほか一族や関係者も処罰され、銭屋は家財を没収されてほぼ断絶しました。","石川県の近代の史家や作家が五兵衛を «悲劇の豪商» として再評価し、戯曲や小説の題材にもなりました。"],"look":["銭屋五兵衛記念館（船の模型や道具）","金石の町並みと本龍寺など銭屋ゆかりの寺","銭屋五兵衛の銅像","犀川河口と金石港"],"q":["銭屋五兵衛は、その財力から何と呼ばれた？","«海の百万石» です。加賀藩の百万石にならぶほどの財力という意味です。"],"koji":[],"myth":"持ち船数、密貿易説、毒流し事件の真相は伝承・諸説を含む。","img":["北前船","河北潟"],"wp":"銭屋五兵衛","rel":{"ev":[],"grave":[]},"ph":[["c:1/16/Zeniya_Gohei.jpg",250,334,"銭屋五兵衛"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:5/5f/Y%C5%8Dsh%C5%AB_Chikanobu_Chikako.jpg",562,800],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"],["c:c/c3/KahokuGata.jpg",1280,960,"河北潟"]]},{"id":"17_youkaichi","n":"八日市地方遺跡（弥生の大集落）","yomi":"ようかいちじかたいせき","cat":"遺跡","rank":"A","y":-200,"era":["yayoi"],"sh":"国の重要文化財（出土品）","ad":"小松市日の出町・八日市町ほか（JR小松駅東側一帯）","st":"JR小松駅のすぐ東側一帯。出土品の展示は小松市埋蔵文化財センターなど","la":36.404,"lo":136.456,"hook":"駅前の地下から、2000年以上前の «弥生の町» が丸ごと出てきた。木の道具がこんなに残る遺跡は、全国でもめずらしい。","lead":"八日市地方遺跡は、小松駅の東側の地下に広がる弥生時代中期の大きな集落の跡です。まわりを堀で囲んだ «環濠集落» で、土器や石器のほか、ふつうは腐ってなくなる木の道具がたくさん見つかりました。玉づくりの跡もあり、出土品の多くが国の重要文化財になっています。","story":["小松駅の東側で、町づくりのための工事が始まりました。地面を掘ってみると、次々と土器のかけらや木の板が出てきます。«これはただごとではない»。本格的な発掘調査が行われ、姿をあらわしたのは、2000年以上前の弥生時代の大きなむらでした。","むらのまわりには、深い堀（環濠）がめぐらされていました。«なぜ堀で囲んだの?» 弥生時代には米づくりが広がり、土地や水、たくわえた米をめぐってむら同士が争うこともありました。堀は敵やけものから身を守るためのもの、と考えられています。むらの中には住まいや、高い床の倉庫があったとみられます。","この遺跡がとくにすごいのは、木の道具がたくさん残っていたことです。ふつう木は土の中で腐ってしまいますが、ここは地下水が多く、空気にふれなかったため、くわやすき、器、建物の柱などが残りました。うるしを塗った赤い器もあり、弥生の人びとが美しいものを大切にしていたことがわかります。","もう一つの特長が «玉づくり» です。小松のまわりの山では、緑色の «碧玉（へきぎょく）» がとれます。むらの人びとはこれを細い筒の形の «管玉（くだたま）» に加工していました。石に小さな穴をあける道具や、作りかけの玉も見つかっています。«ここでつくった玉が、遠くのむらの首飾りになったのかもしれない»。北陸の玉は、広い地域に運ばれていたと考えられています。","今、遺跡の上には駅や町があり、当時の様子を地上で見ることはできません。けれども出土品は大切に保存され、展示で見ることができます。小松駅の近くを歩くとき、足の下に弥生の町が眠っていることを思い出してみてください。"],"tl":[["弥生時代中期","環濠に囲まれた大きな集落が営まれる"],["弥生時代中期","碧玉を使った管玉づくりが盛んに行われる"],["弥生時代中期の終わりごろ","集落がおとろえる"],["1990年代〜2000年代","小松駅東側の区画整理事業にともない大規模な発掘調査"],["平成時代","出土品の多くが国の重要文化財に指定される"]],"who":[["八日市地方のむらの人びと","米づくりと玉づくりをしながら暮らした弥生の人たち"],["玉づくりの職人","碧玉を加工して管玉をつくった"],["発掘調査にかかわった人びと","膨大な出土品を掘り出し、整理した"]],"deep":["«地方» は «じかた» と読みます。«八日市地方» は、もとは地名（小字）に由来します。","遺跡は弥生時代中期（おおよそ紀元前3〜前1世紀ごろ）を中心とし、北陸を代表する大集落の一つとされます。","木製品は農具・容器・建築部材など多種類で、弥生時代の木工技術を知る上で重要な資料となっています。","碧玉製の管玉づくりは、北陸の弥生遺跡の大きな特長で、八日市地方遺跡はその拠点の一つと考えられています。","出土品の点数や重要文化財の指定件数は膨大で、正確な数字は資料によって示し方が異なります。"],"look":["小松市埋蔵文化財センター・小松市立博物館などでの出土品展示（展示状況を要確認）","管玉と作りかけの玉、穴をあける道具","漆塗りの木製容器","小松駅東側の町並み（遺跡の上に立つ）"],"q":["八日市地方遺跡で木の道具がたくさん残ったのはなぜ？","地下水が多く、木が空気にふれずに保存されたからです。"],"koji":[],"myth":"時期の幅や重要文化財の指定年・点数は資料によって示し方が異なる。","img":["環濠集落","管玉"],"wp":"八日市地方遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:7/76/%E5%90%89%E9%87%8E%E3%83%B6%E9%87%8C%E9%81%BA%E8%B7%A1%E7%92%B0%E6%BF%A0.JPG",3456,2304,"環濠集落"],["c:7/7e/Necklace_with_Claw-Shaped_Beads_%28Magatama%29.jpg",900,619,"管玉"],["c:c/c4/260719_Natadera_Komatsu_Ishikawa_pref_Japan43s4.jpg",5472,3648,"近く: 小松市"],["c:e/e5/260719_Komatsu_Station_Komatsu_Ishikawa_pref_Japan02s3.jpg",5472,3648,"近く: 小松駅"],["c:9/9a/OTABI_MATSURI_FESTIVAL_KOMATSU_002.JPG",2240,1680,"近く: お旅まつり"],["c:4/4d/Komatsu_City_FD.jpg",3456,2304,"近く: 小松市消防本部"],["c:9/9e/Komatsu_municipal_library.jpg",640,480,"近く: 小松市立図書館"],["c:5/58/JA_Komatsu-shi_hall.jpg",2432,1824,"近く: 小松市農業協同組合"]]},{"id":"17_wadayama","n":"和田山・末寺山古墳群","yomi":"わだやま・まつじやまこふんぐん","cat":"遺跡","rank":"A","y":450,"era":["kofun"],"sh":"国指定史跡（能美古墳群）","ad":"能美市寺井地区の丘陵（能美ふるさとミュージアム周辺）","st":"JR能美根上駅から車で約10分。近くに能美ふるさとミュージアム","la":36.442,"lo":136.526,"hook":"加賀の平野を見わたす丘の上に、古墳が点々と。ここは «能美の王たち» が眠る場所でした。","lead":"和田山・末寺山古墳群は、能美市の丘の上にある古墳時代の古墳のまとまりです。前方後円墳や円墳、方墳などが集まり、よろいやかぶと、武器などが見つかりました。周辺の古墳群とあわせて «能美古墳群» として国の史跡になっています。","story":["手取川がつくった加賀の平野。その東のはしに、低い丘がいくつも並んでいます。和田山と末寺山。今は木々におおわれた静かな丘ですが、よく見ると、ところどころに土がこんもりと盛り上がった所があります。それが古墳です。","«どうして丘の上につくったの?» 古墳は、ただのお墓ではありません。そのむらを治めた王の力を、まわりの人びとに見せるための記念碑でもありました。平野から見上げる丘の上に古墳を並べれば、遠くからでもよく見えます。«ここを治めるのは、我らの一族だ» と、古墳は語っていたのです。","発掘調査では、古墳の中から鉄のよろいやかぶと、剣やほこ、馬具などが見つかりました。とくに鉄のよろいは、ヤマト王権と強いつながりを持つ有力者に与えられたものと考えられています。能美の王たちは、遠く大和の王とも結びついていたのかもしれません。","和田山・末寺山の古墳は、何代にもわたってつくられたと考えられています。古い時代の古墳から新しい時代の古墳へ、丘の上を少しずつ移りながら、一族の王たちが眠りについていきました。近くの秋常山古墳（石川県最大級の前方後円墳）などとあわせ、能美の地に大きな力を持った人びとがいたことがわかります。","丘は史跡公園として整備され、散策路を歩いて古墳の形を観察できます。ふもとの能美ふるさとミュージアムでは、出土品や古墳の模型を見ることができます。1500年以上前の王たちと同じように、丘の上から加賀の平野を見わたしてみてください。"],"tl":[["古墳時代前期〜中期","和田山・末寺山の丘に古墳がつくられ始める"],["古墳時代中期","よろい・かぶとなど鉄の武具が副葬される"],["古墳時代後期","古墳づくりがおとろえる"],["昭和時代","発掘調査が行われ、国の史跡に指定される"],["平成時代","秋常山古墳群などとあわせ «能美古墳群» として史跡がまとめられる"]],"who":[["能美の有力者たち","丘の上の古墳に葬られた地域の首長"],["ヤマト王権","武具などを通じて地方の首長と結びついていたと考えられる"],["発掘・整備にかかわった人びと","古墳の姿を明らかにし、史跡公園として整えた"]],"deep":["«能美古墳群» は、秋常山古墳群・和田山・末寺山古墳群・寺井山古墳群などをまとめた国の史跡の名称です（指定の経緯は資料で確認を）。","秋常山1号墳は全長約140mの前方後円墳で、石川県最大級とされます。","和田山・末寺山の古墳からは、短甲（たんこう）とよばれる鉄のよろいが出土しており、古墳時代中期の武具の資料として注目されます。","古墳群全体では数十基の古墳が確認されており、前方後円墳・円墳・方墳など形がさまざまです。","能美ふるさとミュージアムでは、古墳群の出土品とともに、九谷焼など能美市の文化も紹介しています。"],"look":["丘の散策路から見る古墳の形","丘の上からの加賀平野の眺め","能美ふるさとミュージアムの出土品（よろい・武器など）","あわせて訪ねたい秋常山古墳"],"q":["古墳が丘の上につくられることが多かったのはなぜ？","遠くからよく見え、王の力をまわりに示すことができたからと考えられています。"],"koji":[],"myth":"古墳の基数・築造順、史跡指定の経緯は資料により異なる。","img":["能美古墳群","短甲"],"wp":"和田山・末寺山古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:0/09/Asuka_Museum_Keik%C3%B4.jpg",3096,4128,"短甲"],["c:e/e9/Nomi_city_Yuno_elem-sch.jpg",1555,1166,"近く: 能美市立湯野小学校"],["c:c/c6/Ishikawazoo_%281%29.jpg",640,428,"近く: 辰口町"],["c:2/2f/Tedori_Fish_Land.jpg",3456,2304,"近く: 手取フィッシュランド"],["c:e/eb/Ishikawazoo01.jpg",3492,2064,"近く: いしかわ動物園"],["c:4/4d/%E8%BE%B0%E5%8F%A3%E6%B8%A9%E6%B3%89%E7%B7%8F%E6%B9%AF_%E9%87%8C%E5%B1%B1%E3%81%AE%E6%B9%AF.jpg",3135,2351,"近く: 辰口温泉"]]},{"id":"17_amenomiya","n":"雨の宮古墳群（能登最大の前方後方墳）","yomi":"あめのみやこふんぐん","cat":"遺跡","rank":"A","y":370,"era":["kofun"],"sh":"国指定史跡","ad":"鹿島郡中能登町西馬場・能登部上","st":"JR七尾線 能登部駅から車で約10分（史跡公園の駐車場から尾根へ歩く）","la":36.979,"lo":136.886,"hook":"眉丈山の尾根の上、四角い頭の古墳が能登の平野を見下ろしています。千数百年前、この地の王がここに眠りました。","lead":"雨の宮古墳群は、中能登町の眉丈山（びじょうざん）の尾根にある古墳群です。1号墳は全長約64mの前方後方墳で、能登でいちばん大きな古墳。4世紀ごろにつくられ、盗掘されずに残っていた棺の中から鏡や武器、腕輪形の石製品などが見つかりました。国の史跡です。","story":["能登半島の真ん中、邑知潟（おうちがた）の平野をはさんで、細長い眉丈山が横たわっています。その尾根の上に、30基あまりの古墳が並んでいます。いちばん大きいのが1号墳、«能登最大の古墳» です。","1号墳は «前方後方墳»。前も後ろも四角い、めずらしい形です。«前方後円墳じゃないの?» 前方後方墳は、古墳時代の初めごろに東日本や日本海側に多い形で、前方後円墳と並んでヤマト王権の秩序の中に組み込まれた首長の墓と考えられています。全長は約64m。そばの2号墳は、全長約65mの前方後円墳で、四角い頭と丸い頭の大きな古墳が並んでいます。","1号墳の発掘では、後方部の頂上から、木の棺をおさめた跡が見つかりました。盗掘をまぬがれていた棺の中からは、青銅の鏡、鉄の剣やよろい、そして «車輪石» や «石釧（いしくしろ）» と呼ばれる、緑色の石でつくった腕輪形の宝物が出てきました。«この人は、ただの村長ではない»。これらはヤマト王権と結びついた有力者の持ち物と考えられています。","«なぜ山の上に?» 眉丈山の尾根からは、邑知潟の平野と、遠く七尾湾まで見わたせます。平野の人びとから見上げれば、尾根の古墳はいつもそこにある。王は死んでもなお、国を見守っているように見えたのでしょう。","古墳は史跡公園として、つくられた当時のように葺石（ふきいし）を並べた姿に復元されています。ふもとには «雨の宮能登王墓の館» があり、出土品のレプリカなどを見られます。尾根に立って、1600年前の能登の王がながめた景色を感じてみてください。"],"tl":[["4世紀後半ごろ","1号墳（前方後方墳）がつくられる"],["4世紀後半〜5世紀","2号墳（前方後円墳）などがつくられる"],["昭和時代","1号墳などが国の史跡に指定される"],["平成時代","1号墳の発掘調査で未盗掘の埋葬施設が見つかる"],["平成時代","史跡公園として葺石をふくめた復元整備"]],"who":[["1号墳に葬られた首長","能登の有力者。名前はわかっていない"],["ヤマト王権","鏡や石製品を通じて地方の首長と結びついていたとされる"],["発掘・整備にかかわった人びと","未盗掘の棺を調べ、古墳を復元した"]],"deep":["1号墳は全長約64mの前方後方墳、2号墳は全長約65mの前方後円墳とされます。能登最大の古墳は、どちらを数えるかで表現が分かれることがあります。","車輪石・石釧は碧玉などでつくられた腕輪形石製品で、古墳時代前期の有力者の墓によく見られる宝物です。","古墳群の数は30基あまりとされ、前方後方墳・前方後円墳・円墳・方墳がふくまれます。","眉丈山の尾根は、邑知潟地溝帯の北西側の山並みで、古墳群はその地形の高まりを利用しています。","«雨の宮» の名は、山の上にあった雨乞いの神（雨の宮）に由来するといわれます。"],"look":["復元された1号墳の葺石と四角い後方部","並んで立つ2号墳（前方後円墳）との比較","尾根から見る邑知潟の平野","雨の宮能登王墓の館の展示"],"q":["雨の宮1号墳は、前も後ろも四角い古墳。何という形？","«前方後方墳» です。能登でいちばん大きな古墳の一つです。"],"koji":[],"myth":"«雨の宮» 名の由来は伝承。発掘年・指定年などの細部は資料で確認を。","img":["前方後方墳","車輪石"],"wp":"雨の宮古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:7/70/Amenomiya1-20_2010.jpg",1494,1000,"雨の宮古墳群"],["c:0/01/100509_Amenomiya_3goufun.jpg",3872,2592],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:f/f7/Amenomiya_kofungun_1975.jpg",1928,2440],["c:c/ce/CG_Amenomiya_2goufun-4_7p.jpg",2560,1484],["c:7/75/CG_Amenomiya_2goufun-3_7p.jpg",2560,1484],["c:0/01/CG_Amenomiya_2goufun-2_7p.jpg",2560,1484],["c:1/14/CG_Amenomiya_2goufun-1_7p.jpg",2560,1484]]},{"id":"17_fukuura","n":"福浦港（渤海使の福良津）","yomi":"ふくらこう（ふくらのつ）","cat":"伝承","rank":"A","y":800,"era":["nara","heian","edo"],"sh":"","ad":"羽咋郡志賀町福浦港","st":"JR羽咋駅から車で約40分（バスは本数が少ない）","la":37.093,"lo":136.72,"hook":"1200年以上前、海の向こうの国 «渤海» から使いの船がやってきた。能登の小さな入江は、日本の «外国への玄関» の一つでした。","lead":"福浦港は、能登半島の西の海岸にある、入江の奥の小さな港です。奈良〜平安時代、中国東北部から朝鮮半島北部にあった国 «渤海» の使節が、この港（福良津）から帰国したことが記録に残ります。江戸時代には北前船の風待ちの港としてにぎわいました。","story":["能登半島の西の海岸は、けわしい崖が続く «能登金剛» の海です。その中に、切れこんだ細長い入江がぽつんとあります。波がおだやかで、風をよけられる天然の良港。それが福浦です。昔は «福良（ふくら）» と書かれました。","7世紀の末、今の中国東北部から朝鮮半島北部に «渤海» という国が生まれます。渤海は日本とたびたび使者をやりとりしました。使者たちは日本海を渡り、北陸や出羽などの海岸に着きました。«どうして北陸に?» 渤海から見ると、日本海を横切ってまっすぐ来ると、ちょうど北陸や東北にぶつかるのです。","奈良時代、渤海の使者が帰るための船が能登で造られ、その船に «能登» という名前がつけられた、という記録があります。しかもこの船は、無事に航海を終えたことで、なんと位（くらい）を与えられたと伝わります。«船に位を?» それほど、海を越える旅は命がけで、神仏の守りが大切にされていたのです。平安時代の初めには、能登国に使節を迎える客院をつくるよう命じられた記録もあり、福良津はその候補地と考えられています。","時代は下って江戸時代。福浦は、北前船が嵐を避けて風を待つ港として大いににぎわいました。港には船乗りたちの宿や遊郭もあったといわれます。港を見下ろす丘には、木造の «旧福浦灯台» が今も立っています。明治時代に建てられたとされる、日本に現存する古い木造灯台の一つです。","今の福浦は、静かな漁港です。けれど入江の水面を見ていると、渤海の使者の船、北前船、そして灯台の明かりを頼りに帰ってきた漁船……。1000年をこえて、たくさんの船がこの港に命を預けてきたことが感じられます。"],"tl":[["698年ごろ","渤海が建国される"],["727年","渤海の最初の使者が日本に来る"],["奈良時代","能登で造られた船 «能登» が渤海使を送り、のちに位を与えられたと記録される"],["平安時代初め","能登国に渤海使を迎える客院をつくるよう命じられる（福良津が候補地とされる）"],["926年","渤海がほろびる"],["江戸時代","北前船の風待ち港としてにぎわう"],["明治時代","旧福浦灯台が建てられる"]],"who":[["渤海の使者たち","日本海を渡って日本を訪れた外交使節"],["能登国の役人","使節の迎えや帰国の船の準備にかかわった"],["北前船の船乗り","江戸時代、福浦で風を待ち、航海の準備をした"],["日野家（灯台守）","福浦の灯台を代々守ったと伝わる家"]],"deep":["船 «能登» の話は『続日本紀』に見え、渤海使を送った船に従五位下の位が授けられたと記されています。","能登の «客院» の場所は確定しておらず、福良津（福浦）周辺をその候補とする説が有力とされます。","旧福浦灯台は、明治初めに建てられた木造の灯台とされ、日本で現存最古級の木造洋式灯台といわれます（年代は資料で確認を）。","江戸時代、福浦には日野長兵衛が航海の目印となる灯明を置いたのが灯台の始まりと伝わります。","渤海使の来航地は北陸・出羽・隠岐などに広がり、能登のほか加賀や越前にも迎えの施設が置かれた記録があります。"],"look":["入江の奥の福浦港と周りの崖","丘の上の旧福浦灯台","近くの海岸景勝地 «能登金剛»（巌門など）","港まわりの古い家並み"],"q":["奈良時代、能登で造られた渤海使の船は何と名づけられた？","«能登» です。無事な航海の功で位を与えられたと記録されています。"],"koji":[],"myth":"客院の場所、灯台の起源（日野長兵衛）や建築年は諸説・伝承を含む。","img":["渤海 (国)","渤海使"],"wp":"福浦港","rel":{"ev":[],"grave":[]},"ph":[["c:d/dc/Fukura01.jpg",3008,2000,"福浦港"],["c:2/26/Former_Fukura_Lighthouse_20060814103945.jpg",2272,1704],["c:0/05/Balhae-Territory_in_830_jp.png",1045,868,"渤海 (国)"]]},{"id":"17_daijoji","n":"大乗寺（曹洞宗の古刹）","yomi":"だいじょうじ","cat":"寺社","rank":"A","y":1289,"era":["kamakura","edo"],"sh":"国の重要文化財（仏殿）","ad":"金沢市長坂町","st":"JR金沢駅からバスで «大乗寺口» 方面へ約30分、徒歩約15分","la":36.532,"lo":136.644,"hook":"«規矩大乗（きくだいじょう）»。作法のきびしさで知られた禅寺は、道元の教えを北陸に根づかせた出発点の一つでした。","lead":"大乗寺は、金沢の南の丘・長坂町にある曹洞宗の古いお寺です。鎌倉時代、はじめは真言宗の寺として開かれ、のちに永平寺の徹通義介を迎えて曹洞宗の寺になりました。江戸時代に今の地に移り、仏殿は国の重要文化財です。","story":["鎌倉時代、加賀の守護だった富樫家尚が、野々市のあたりに一つの寺を建てました。はじめは真言宗の寺で、名を大乗寺といいました。やがて寺は大きな転機を迎えます。越前の永平寺で道元の教えを受けついだ僧・徹通義介（てっつうぎかい）を、住職として迎えたのです。","義介は、永平寺の3代目の住職でしたが、寺の中の考え方の違いから永平寺を離れていました。«道元禅師の教えを、この加賀の地で生かしたい»。義介は大乗寺を曹洞宗の寺に改め、きびしい修行の場としました。その弟子が瑩山紹瑾（けいざんじょうきん）です。瑩山はのちに能登に總持寺を開き、曹洞宗を全国に広める大きな役割を果たしました。","«大乗寺がなければ、今の曹洞宗の広がりはなかったかもしれない»。そういわれるほど、この寺は重要な位置にあります。道元・懐奘・義介・瑩山と続く教えの流れが、ここを通って能登の總持寺へ、そして日本じゅうの寺へと伝わっていったのです。","戦国時代の戦乱で寺は何度も場所を移しました。江戸時代、加賀藩の家老・本多家の菩提寺となり、今の長坂の丘に移されました。住職には月舟宗胡（げっしゅうそうこ）や卍山道白（まんざんどうはく）といった名僧がつき、道元の古い作法を見直す運動の中心となります。修行の作法が細かく厳しいことから、«規矩大乗» と呼ばれるようになりました。","今の大乗寺は、杉木立に囲まれた静かな禅寺です。山門をくぐると、落ち着いた仏殿や法堂が並びます。修行僧が暮らす寺なので、見学の際は静かに、決められた場所だけを歩きましょう。«一つひとつの動作を、ていねいに»。そんな禅の心を感じられる場所です。"],"tl":[["1263年ごろ","富樫家尚が野々市のあたりに大乗寺を開いたと伝わる（はじめ真言宗）"],["1289年ごろ","徹通義介を迎え、曹洞宗の寺となる"],["鎌倉時代後期","瑩山紹瑾が住職を継ぐ"],["戦国時代","戦乱で寺地を移す"],["江戸時代前期","加賀藩家老・本多家の支援で今の長坂に移る"],["江戸時代前期","月舟宗胡・卍山道白が住職となり、«規矩大乗» と呼ばれる"]],"who":[["富樫家尚","加賀の守護。大乗寺を開いたと伝わる"],["徹通義介","永平寺3世。大乗寺を曹洞宗の寺に改めた"],["瑩山紹瑾","義介の弟子。のちに總持寺を開き曹洞宗を広めた"],["月舟宗胡・卍山道白","江戸時代の住職。道元の作法を見直す «宗統復古» にかかわった"],["本多政長","加賀藩の家老。大乗寺を菩提寺として支えた"]],"deep":["«規矩» とは «ものさしとコンパス» のことで、転じて «決まり・作法» の意味。大乗寺の修行の厳格さを表すあだ名です。","義介が永平寺を離れた背景には、«三代相論» と呼ばれる、寺の方針をめぐる争いがあったとされます（内容は諸説）。","仏殿は江戸時代中ごろの建築で、禅宗様の建物として国の重要文化財に指定されています。","卍山道白は、曹洞宗で «師から弟子へ一人だけに法を伝える» という原則を立て直した «宗統復古» 運動で知られます。","瑩山紹瑾が開いた總持寺は、明治の火災後、本山の機能が横浜市鶴見に移され、能登の地は «總持寺祖院» となりました。"],"look":["杉木立の参道と山門","国重要文化財の仏殿","法堂や僧堂など禅宗の伽藍配置","丘の上の静かな境内（修行の場なので静かに）"],"q":["大乗寺が作法のきびしさから呼ばれたあだ名は？","«規矩大乗（きくだいじょう）» です。"],"koji":[{"w":"規矩準縄","m":"ものごとの手本やきまり。«規矩» は大乗寺のあだ名にも使われた"}],"myth":"創建年・曹洞宗への改宗年、移転の年代は諸説ある。","img":["徹通義介","瑩山紹瑾"],"wp":"大乗寺 (金沢市)","rel":{"ev":[],"grave":[]},"ph":[["c:d/d7/Tettsu_Gikai_image_zen.jpg",353,358,"徹通義介"],["c:b/bf/Keizan-SotoZen-Net.jpg",122,161,"瑩山紹瑾"],["c:8/8d/Kanazawa_Technical_College.jpg",1600,1200,"近く: 国際高等専門学校"],["c:5/56/Kanazawa_Nishikigaoka_School.jpg",3456,2304,"近く: 石川県立金沢錦丘中学校・高等学校"],["c:5/5a/Ishikawa_Daijyouji_Butuden.jpg",2048,1536,"近く: 大乗寺"],["c:e/e2/Ishikawa_Prefectural_Deaf_School_1.jpg",5184,3888,"近く: 石川県立ろう学校"],["c:0/0b/Kanazawa_South_Post_Office_%28Ishikawa%29.jpg",2000,1500,"近く: 金沢南郵便局"],["c:8/84/Nagasaka-futago_1975.jpg",1304,1316,"近く: 長坂二子塚古墳"]]},{"id":"17_suematsu","n":"末松廃寺跡","yomi":"すえまつはいじあと","cat":"遺跡","rank":"A","y":670,"era":["asuka","nara"],"sh":"国指定史跡","ad":"野々市市末松","st":"JR野々市駅または北陸鉄道石川線の駅から車で約10分","la":36.509,"lo":136.598,"hook":"田んぼの真ん中にぽつんと置かれた巨大な石。それは、1300年前に建っていた塔の «心柱» をささえた礎石でした。","lead":"末松廃寺跡は、野々市市にある飛鳥時代の終わりから奈良時代ごろのお寺の跡です。建物は残っていませんが、塔や金堂の基壇、大きな塔の心礎が見つかりました。北陸でもとても古い本格的な寺院の一つで、国の史跡。今は史跡公園になっています。","story":["加賀平野の田んぼの中に、少し小高い芝生の広場があります。その真ん中に、どっしりとした大きな石。中央にくぼみがあります。«これは何?» 答えは、塔の真ん中の柱 «心柱» を立てるための礎石、«心礎（しんそ）» です。この石の上に、かつて高い塔がそびえていました。","寺がつくられたのは7世紀の後半ごろと考えられています。飛鳥時代の終わり、仏教が広がり、各地の有力な豪族たちが競うように寺を建てた時代です。当時の建物は、瓦ぶきで柱を朱に塗った、まったく新しい外国風の建築でした。«田んぼとかやぶきの家ばかりの平野に、突然、朱色の塔があらわれた»。人びとはどれほど驚いたでしょう。","発掘調査では、塔と金堂が東西に並ぶ «法起寺式» に近い配置だったことがわかりました。瓦もたくさん出ています。そして調査の中で、とてもめずらしいものが見つかります。日本の古いお金、«和同開珎» の銀のお金です。«なぜ寺の跡から銀銭が?» 寺の建物を建てるときのおまじないとして埋められたのでは、とする説などがあります。","だれがこの寺を建てたのかは、記録に残っていません。加賀の地を治めていた豪族、たとえば «道君（みちのきみ）» のような一族が建てたのではないか、とも考えられていますが、はっきりしません。寺の名前も伝わらず、地名から «末松廃寺» と呼ばれています。«廃寺» とは、今はなくなった寺、という意味です。","寺はいつしかなくなり、長いあいだ田んぼの下に眠っていました。けれど心礎だけは地上に残り、地元の人びとに大切にされてきました。今は史跡公園として基壇が復元されています。巨大な心礎に手を近づけると、1300年前の職人たちの息づかいが伝わってくるようです。"],"tl":[["7世紀後半ごろ","寺が建てられる"],["奈良時代","寺が営まれる"],["平安時代以降","寺がおとろえ、やがて廃絶する"],["1939年","国の史跡に指定"],["1960年代","発掘調査が行われ、和同開珎の銀銭が出土"],["現在","史跡公園として基壇を復元整備"]],"who":[["寺を建てた加賀の豪族","名前は伝わらないが、地域の有力者と考えられる"],["道君","古代の加賀の豪族。建立者の候補とする説がある"],["寺の職人たち","瓦を焼き、塔や金堂を建てた"]],"deep":["心礎は大きな自然石で、中央に心柱を受ける穴が彫られています。塔の高さは推定で、確かな数字はわかっていません。","和同開珎の銀銭は発行期間が短く、出土例が少ないため、寺の年代や性格を考える上で注目されています。","伽藍配置は、塔と金堂が東西に並ぶ形で、法起寺式や法隆寺式との関係が議論されています。","出土した瓦の文様は、畿内や他地域の寺院の瓦と比較され、建立時期を7世紀後半とする根拠の一つになっています。","末松廃寺は、北陸地方で最も古い本格的寺院の一つとして、白鳳期の地方寺院を考える重要な史跡です。"],"look":["大きな塔の心礎","復元された塔跡・金堂跡の基壇","史跡公園から見る白山の山なみ（晴れた日）","野々市市内の資料館などでの出土品展示（展示状況を要確認）"],"q":["末松廃寺跡に残る大きな石は、何のための石？","塔の真ん中の柱（心柱）をささえる «心礎» です。"],"koji":[],"myth":"建立者（道君など）、銀銭が埋められた理由は推測・諸説。","img":["和同開珎","心礎"],"wp":"末松廃寺","rel":{"ev":[],"grave":[]},"ph":[["c:3/33/Wad%C5%8Dkaichin_found_at_S%C5%ABfuku-ji_Temple_Site_TNM_front.jpg",3000,2600,"和同開珎"],["c:5/57/Ishikawa_Prefectural_University.jpg",1600,1200,"近く: 石川県立大学"],["c:8/8f/%E9%87%8E%E3%80%85%E5%B8%82%E5%B8%82%E7%AB%8B%E5%AF%8C%E9%99%BD%E5%B0%8F%E5%AD%A6%E6%A0%A1%282022%E5%B9%B4%29.jpg",3648,2432,"近く: 野々市市立富陽小学校"],["c:6/6b/JA%E3%81%AE%E3%81%AE%E3%81%84%E3%81%A1%E6%9C%AC%E5%BA%97.jpg",4160,3120,"近く: 野々市農業協同組合"],["c:8/8e/Aida_engineering_Hakusan_office.jpg",2432,1824,"近く: アクセス (石川県の企業)"]]},{"id":"17_uchinada","n":"内灘闘争（米軍試射場反対）","yomi":"うちなだとうそう","cat":"昭和","rank":"A","y":1953,"era":["showa"],"sh":"","ad":"河北郡内灘町（権現森・着弾地観測所跡ほか）","st":"北陸鉄道浅野川線 内灘駅から徒歩・車で約15〜20分","la":36.656,"lo":136.639,"hook":"«金は一年、土地は万年»。砂丘の村の人びとは、アメリカ軍の砲弾が飛ぶ浜に座りこみました。","lead":"内灘闘争は、1952〜1957年ごろ、石川県内灘村（今の内灘町）の砂丘に、アメリカ軍の砲弾の試射場がつくられたことに反対した住民運動です。全国から支援者も集まり、戦後日本の基地反対運動の先がけとなりました。試射場は1957年に返還され、今も着弾地観測所の跡が残っています。","story":["1952年、日本は独立を回復しましたが、アメリカ軍は日本に残りました。そのころ朝鮮戦争が続き、アメリカ軍が使う砲弾を試し撃ちする場所が必要になります。政府が選んだのが、日本海に面した石川県内灘村の広い砂丘でした。","内灘は、漁業と、砂丘での小さな畑でくらす村でした。«浜がなくなれば、漁ができない»。村の人びとははげしく反対します。しかし国はお金を出して村を説得し、1953年、試射場の使用が始まりました。浜に大きな砲声がひびき、砂丘の上を砲弾が飛んでいきます。","やがて使用が期間を決めずに続けられることになると、住民たちは立ち上がりました。村の女性や漁師たちが、砲弾が着弾する浜近くの «権現森» などに座りこみます。«金は一年、土地は万年»。お金はすぐになくなるが、土地は子や孫の代まで続く。このことばが、運動の合言葉になりました。","内灘の運動は新聞で大きく報じられ、労働組合や学生など、全国から多くの支援者がかけつけました。«なぜ、小さな村の問題が全国の運動になったの?» 戦争が終わって数年、人びとの中には «二度と戦争の道具に土地を使わせたくない» という強い思いがあったからです。内灘は、その後各地で起こった基地反対運動の先がけとなりました。","1957年、試射場はついに日本に返還されました。今の内灘の砂丘には、砲弾の着弾を観測したコンクリートの «着弾地観測所» の建物が、記念物として残されています。細い窓から海を見ると、70年前、ここで砲弾を見つめた人たちと、浜で声をあげた村の人たちの両方の時間が重なって見えてきます。"],"tl":[["1952年","政府が内灘砂丘をアメリカ軍の試射場とする方針を示す"],["1953年","試射場の使用が始まり、反対運動が高まる"],["1953年","期間を定めない使用が決まり、住民の座りこみが続く"],["1957年","試射場が日本に返還される"],["昭和時代後半","内灘町が着弾地観測所跡などを保存"]],"who":[["内灘村の住民","漁師や女性たちを中心に、座りこみで反対した"],["全国の支援者","労働組合・学生などが内灘にかけつけた"],["五木寛之","小説『内灘夫人』で内灘闘争を題材にした作家"]],"deep":["«金は一年、土地は万年» は内灘闘争を象徴する言葉として知られ、その後の各地の基地反対運動でも使われました。","着弾地観測所跡は鉄筋コンクリート造の建物で、砲弾の着弾を観測するための細長い窓があります。","内灘の試射場は、朝鮮戦争の特需で国内でつくられた砲弾の性能を試すため、という性格もあったとされます。","闘争は村の中でも賛成・反対で意見が分かれ、補償をめぐる複雑な事情がありました。一面的な «英雄物語» ではないことに注意が必要です。","内灘闘争は、のちの砂川闘争（東京都立川市）など、1950年代の基地反対運動の先がけと位置づけられています。"],"look":["着弾地観測所跡（コンクリートの建物）","内灘砂丘と日本海","記念碑や説明板","内灘町歴史民俗資料館（開館状況を要確認）"],"q":["内灘闘争で住民たちの合言葉になったことばは？","«金は一年、土地は万年» です。"],"koji":[{"w":"金は一年、土地は万年","m":"お金はすぐなくなるが、土地は子孫の代まで続く。土地を手放すことへの反対を表した"}],"myth":"期間・経緯の細部（使用開始日、返還日）は資料で確認を。","img":["内灘町","五木寛之"],"wp":"内灘闘争","rel":{"ev":[],"grave":[]},"ph":[["c:5/57/Uchinada_Incident.JPG",534,444,"内灘闘争"],["c:0/00/Uchinada_Bridge.jpg",2048,1536,"内灘町"],["c:c/c2/Chunichi1967-02-22-2.jpg",1078,1243,"五木寛之"]]},{"id":"17_nishichaya","n":"にし茶屋街","yomi":"にしちゃやがい","cat":"町","rank":"A","y":1820,"era":["edo","taisho"],"sh":"","ad":"金沢市野町","st":"JR金沢駅からバスで «広小路» まで約15分、徒歩約3分","la":36.553,"lo":136.65,"hook":"紅がら格子の町並みに、三味線の音がひびく。ひがし茶屋街より小さく静かな、«もう一つの金沢の花街» です。","lead":"にし茶屋街は、犀川の西側、寺町の近くにある茶屋町です。1820年、加賀藩がひがし茶屋街とともに茶屋町として認めました。細い格子の «きむすこ» がならぶ町並みが残り、今も芸妓さんがいます。作家・島田清次郎が少年時代を過ごした場所でもあります。","story":["金沢には «茶屋街» と呼ばれる町が三つあります。ひがし茶屋街、主計町茶屋街、そしてにし茶屋街。茶屋とは、芸妓さんが歌や踊り、三味線でお客をもてなす店のこと。にし茶屋街は、その中でもこぢんまりとして、落ち着いた空気の町です。","江戸時代、城下にはあちこちに茶屋が散らばっていました。1820年、加賀藩は «茶屋をまとめて管理しよう» と、浅野川の東と犀川の西の二か所に茶屋町をつくります。これが «ひがし» と «にし» の始まりです。«なぜ町のはずれに?» 城下の中心から少し離し、風紀を取りしまりやすくするためだったと考えられます。","にし茶屋街の建物の表には、細い木の格子 «きむすこ» がびっしり。外からは中が見えにくいのに、中からは外がよく見える、という工夫です。2階は天井が高く、客をもてなす座敷になっています。夕方、格子戸の向こうから三味線と太鼓の音が聞こえてくると、町の空気がふっと変わります。","大正時代、この町で育った少年がいました。島田清次郎。母が茶屋で働き、清次郎はその家で少年時代を過ごします。20歳のときに書いた小説『地上』は大ベストセラーになり、«天才» ともてはやされました。しかし、その後の人生は転落続き。若くして病院で亡くなります。«光と影» の両方を生きた作家の記念館が、この町にあります。","今、にし茶屋街では、昔ながらのお茶屋のほか、和菓子屋や甘味処も営まれています。夜はお座敷に、一見さんは入れないお店が多いですが、昼には町並みを歩いたり、お茶屋の建物を見学したりできます。すぐ近くの寺町の静けさとあわせて、«金沢の奥ゆかしさ» を味わえる場所です。"],"tl":[["江戸時代","城下のあちこちに茶屋が点在する"],["1820年","加賀藩がひがし・にしの茶屋町を認める"],["明治〜大正時代","にし茶屋街が花街としてにぎわう"],["1919年","にし茶屋街で育った島田清次郎が『地上』を出版、大ベストセラーに"],["平成時代","金沢市西茶屋資料館が開館"]],"who":[["島田清次郎","作家。にし茶屋街で少年時代を過ごし、『地上』で一躍有名に"],["にし茶屋街の芸妓たち","江戸時代から今まで、芸を受けつぎ町を守る"],["前田斉広","加賀藩12代藩主。茶屋町が公認されたときの藩主"]],"deep":["«きむすこ» は金沢の茶屋建築に特有の細い格子の呼び名で、断面が台形の細い木を密に並べてつくります。","1820年の茶屋町公認は、文政3年のこと。茶屋を一か所に集めて管理する政策で、ひがし茶屋街と同時でした。","金沢市西茶屋資料館は、島田清次郎が暮らした茶屋 «吉米楼» の跡に建てられ、清次郎の資料と茶屋の座敷を紹介しています。","ひがし茶屋街と主計町は国の重要伝統的建造物群保存地区ですが、にし茶屋街は選定されておらず、金沢市独自の制度で町並みが守られています。","にし茶屋街は、ひがしに比べて規模が小さく、観光客も比較的少ないため、茶屋町の落ち着いた雰囲気が残るといわれます。"],"look":["きむすこ（細い格子）の町並み","金沢市西茶屋資料館（島田清次郎とお茶屋の座敷）","夕方の町並みと芸妓さんの行き来（写真撮影のマナーに注意）","近くの寺町寺院群・妙立寺"],"q":["金沢の茶屋建築に見られる、細い木の格子の呼び名は？","«きむすこ» です。中から外は見えて、外から中は見えにくい工夫です。"],"koji":[],"myth":"","img":["島田清次郎","ひがし茶屋街"],"wp":"にし茶屋街","rel":{"ev":[],"grave":[]},"ph":[["c:8/83/Nishichayagai003.jpg",3861,2574,"にし茶屋街"],["c:1/10/Kanazawa_Nishi_Chaya_Dusk_%2845916568732%29.jpg",5707,3805],["c:2/25/Higashiyamahigashi_2015.JPG",2500,1638,"ひがし茶屋街"]]},{"id":"17_kazuemachi","n":"主計町茶屋街","yomi":"かずえまちちゃやがい","cat":"町","rank":"A","y":1869,"era":["edo","meiji","heisei"],"sh":"国の重要伝統的建造物群保存地区","ad":"金沢市主計町","st":"JR金沢駅からバスで «橋場町» まで約10分、徒歩約2分","la":36.5718,"lo":136.6638,"hook":"一度は地図から消えた町の名前が、住民の願いで帰ってきた。浅野川のほとりの、小さな茶屋町の物語です。","lead":"主計町（かずえまち）は、金沢の浅野川の岸に沿った小さな茶屋町です。江戸時代、加賀藩士・富田主計の屋敷があったことから名がつきました。一度は町名がなくなりましたが、1999年に全国で初めて旧町名が復活。町並みは国の重要伝統的建造物群保存地区です。","story":["浅野川にかかる «中の橋» のたもと。川沿いに、2階建て・3階建ての木の茶屋がすき間なく並んでいます。窓の下にはやなぎ、川の流れの音、夕暮れには灯りがともります。主計町茶屋街です。ひがし茶屋街から川をはさんで向かい側にありながら、ずっと小さく、しっとりとした町です。","«かずえまち» という不思議な名前。これは江戸時代のはじめ、加賀藩の武士・富田主計（とだかずえ）の屋敷がここにあったことに由来します。«主計» は役職の名前から来た呼び名です。武家屋敷の跡が、やがて町人の町になり、江戸の終わりから明治のはじめにかけて茶屋町としてにぎわうようになりました。","ところが1970年、全国で進められた住所の整理（住居表示）で、«主計町» という町名は «尾張町» の一部になり、地図から消えてしまいます。«町の名前は、町の歴史そのものなのに»。住民たちは、名前を取り戻す運動を続けました。そして1999年、«主計町» の名が復活。これは、なくなった町名が元にもどった全国で最初の例となりました。","町のうしろには、細い坂道が二つあります。一つは «暗がり坂»。昼でも薄暗い石段で、昔、旦那衆が人目をしのんで茶屋に通った道といわれます。もう一つの坂は長く名前がありませんでしたが、2008年、作家・五木寛之によって «あかり坂» と名づけられました。«暗がり» と «あかり»。二つの坂の名前が、町の物語を静かに語っています。","すぐ近くには、作家・泉鏡花が生まれた家の跡があり、泉鏡花記念館が建っています。鏡花の小説には、浅野川と茶屋町の風景がたびたび登場します。夕暮れ、中の橋から主計町の灯りをながめれば、鏡花の物語の中に入りこんだような気持ちになれるでしょう。"],"tl":[["江戸時代はじめ","加賀藩士・富田主計の屋敷があり、«主計町» の名が生まれる"],["1869年ごろ","茶屋町として認められたといわれる"],["1873年","近くの下新町に泉鏡花が生まれる"],["1970年","住居表示で町名が消え、尾張町の一部となる"],["1999年","全国で初めて旧町名 «主計町» が復活"],["2008年","国の重要伝統的建造物群保存地区に選定。«あかり坂» が名づけられる"]],"who":[["富田主計","加賀藩士。屋敷の場所が町名の由来となった"],["泉鏡花","近くで生まれた作家。浅野川と茶屋町を作品に描いた"],["五木寛之","金沢ゆかりの作家。«あかり坂» の名づけ親"],["主計町の住民","町名復活の運動を続けた"]],"deep":["«主計» は律令制の官職名 «主計寮» に由来する呼び名で、富田主計重家の通称とされます。","1999年の町名復活は、住居表示で消えた旧町名を元にもどした全国初の例とされ、その後金沢市では複数の旧町名が復活しました。","主計町の茶屋は川側に面して建ち、2階・3階の座敷から浅野川をながめる造りが特長です。","主計町の茶屋町としての公認時期は明治のはじめとする説明が多いものの、細かな年については資料によって差があります。","重要伝統的建造物群保存地区には、主計町とひがし茶屋街がそれぞれ別に選定されています（東山ひがし・主計町）。"],"look":["浅野川沿いに並ぶ茶屋の町並み（中の橋・浅野川大橋から）","暗がり坂とあかり坂","泉鏡花記念館","夕暮れの灯りと川の流れ"],"q":["主計町の名前は何に由来する？","江戸時代の加賀藩士・富田主計の屋敷があったことに由来します。"],"koji":[],"myth":"茶屋町公認の年、暗がり坂の «旦那衆がしのんで通った» 話は伝承・諸説を含む。","img":["泉鏡花","浅野川"],"wp":"主計町","rel":{"ev":[],"grave":[]},"ph":[["c:8/84/Kyoka_Izumi.jpg",822,1207,"泉鏡花"],["c:7/7e/Asanogawa.jpg",600,450,"浅野川"],["c:3/34/NHK_Kanazawa_Broadcasting_Hall_20201115-001.jpg",4954,3303,"近く: NHK金沢放送局"],["c:2/25/%E6%B3%89%E9%8F%A1%E8%8A%B1%E8%A8%98%E5%BF%B5%E9%A4%A8004.jpg",3861,2574,"近く: 泉鏡花記念館"],["c:1/18/Kanazawa_District_Court_01.JPG",3648,2736,"近く: 名古屋高等裁判所金沢支部"],["c:2/26/Kanazawa_Law_Joint_Building%2C_Feb._2016.jpg",4608,3456,"近く: 名古屋高等検察庁金沢支部"]]},{"id":"17_utatsuyama","n":"卯辰山（卯辰山開拓と幕末の養生所）","yomi":"うたつやま","cat":"幕末","rank":"A","y":1867,"era":["edo","meiji"],"sh":"","ad":"金沢市卯辰町ほか（卯辰山公園一帯）","st":"JR金沢駅からバスで «東山» 方面へ約10分、そこから坂道を歩いて山の上まで約30分。車なら山頂近くまで行ける","la":36.5731,"lo":136.6778,"hook":"城を見下ろすので «登ってはいけない山» だった場所が、幕末にいきなり病院と福祉の町に生まれ変わった。","lead":"卯辰山は金沢の東にある標高140mほどの山です。江戸時代はお城を見下ろせるため、町の人が登ることは禁止されていました。ところが幕末の1867年、加賀藩主の前田慶寧がこの山を開き、病院（養生所）や、まずしい人を助ける施設、職人の工房などをまとめてつくりました。","story":["金沢の町を歩くと、浅野川の向こうにこんもりとした山が見えます。これが卯辰山。お城の東の方角（卯辰）にあるから、という名前の由来が伝わりますが、じつは方角はぴったりではありません。江戸時代、この山は町の人にとって «見えるのに登れない山» でした。お城の中がのぞけてしまうからです。","1858年（安政5年）、米の値段が急に上がり、町の人びとは食べるものに困りました。そのとき、大勢の人が禁じられた卯辰山に登り、お城に向かって «ひもじい» と泣き叫んだと伝わります。のちに «安政の泣き一揆» とよばれる出来事で、首謀者とされた7人が死罪になりました。山は、町の人の苦しみを殿様に届けようとした場所でもあったのです。","それから9年後の1867年（慶応3年）。藩主になったばかりの前田慶寧は、なんとこの山を開くことを決めました。«なぜ、禁じられた山を?» 山の上と山すそに、西洋の医学で病人をみる «養生所»、行き場のない人やまずしい人を助ける «撫育所»、職人が物をつくる工房、芝居小屋や茶店まで置いたのです。人が集まり、働き、治療を受けられる、今でいう «福祉と産業の町» づくりでした。","時代はちょうど大政奉還の年。全国がゆれるなかで、加賀藩は «民の暮らしを立て直す» ことで町を守ろうとしたのかもしれません。養生所で学んだ人たちは、のちの金沢の医学教育の流れにつながっていきました。いま山の中腹には «卯辰山養生所跡» の碑が立ち、ここが病院の出発点だったことを伝えています。","明治になると、戊辰戦争で亡くなった加賀藩の人びとをまつる招魂社も、この山に置かれました（のちの石川護国神社）。さらに山すそには «卯辰山山麓寺院群» とよばれる寺町が広がり、泉鏡花や徳田秋声ら金沢の文学者の碑も並びます。登れなかった山は、いまでは金沢の歴史が一度に見わたせる «展望台» になっています。"],"tl":[["江戸時代","お城を見下ろせるため、町人の登山は禁止"],["文化・文政年間","青木木米が春日山窯を開き、九谷焼の再興のきっかけに"],["1858年","米価の高騰で «安政の泣き一揆»。首謀者7人が死罪"],["1867年","前田慶寧が卯辰山を開拓。養生所・撫育所・工房などを設ける"],["1870年","戊辰戦争の戦死者をまつる招魂社が卯辰山に創建"],["1935年","招魂社が小立野へ移る（石川護国神社）"],["1947年","徳田秋声文学碑が建てられる"]],"who":[["前田慶寧","加賀藩14代藩主。卯辰山開拓を命じ、養生所などを設けた"],["青木木米","京都の陶工。卯辰山に春日山窯を開いた"],["徳田秋声","金沢出身の小説家。山に文学碑がある"],["泉鏡花","金沢出身の作家。卯辰山のふもとの町と縁が深い"]],"deep":["«卯辰» は十二支の方角で東を指すが、実際の卯辰山は金沢城から見て真東ではない。名前の由来は «卯辰の方角» 説のほかにも諸説あり、宇多須山・向山・臥竜山など別名がとても多い。","卯辰山開拓は1867年。大政奉還と同じ年で、藩が «富国» と «救民» を同時にねらった総合開発だった点が注目される。病院・救貧・工芸・娯楽がワンセットなのは全国的にも珍しい。","«安政の泣き一揆» は、打ちこわしではなく «泣き叫ぶ» という形の訴えだったと伝わる。卯辰山がお城から見える場所だったからこそ、声を届ける舞台になった。","青木木米が開いた春日山窯は、いちど途絶えていた九谷焼が再びさかんになるきっかけの一つとされる。卯辰山は工芸の町・金沢の «ものづくり» の出発点でもある。","山頂近くの徳田秋声文学碑は、室生犀星の字、谷口吉郎の設計。金沢の三文豪のうち二人と、建築家が一つの碑に関わっている。"],"look":["卯辰山養生所跡の碑","望湖台・見晴らし台から見る金沢の町と日本海","徳田秋声文学碑","山すその卯辰山山麓寺院群（寺町歩き）"],"q":["江戸時代、卯辰山に町の人が登れなかった理由は？","お城（金沢城）の中を見下ろせてしまうからです。1867年の開拓で、ようやく人が集まる山になりました。"],"koji":[],"myth":"山名の由来は諸説。«泣き一揆» の細かな様子は伝承をふくむ。","img":["前田慶寧","卯辰山山麓寺院群","石川護国神社"],"wp":"卯辰山","rel":{"ev":[],"grave":[]},"ph":[["c:c/cb/%E5%8D%AF%E8%BE%B0%E5%B1%B1%E5%85%AC%E5%9C%92%EF%BC%94.jpg",4800,3203,"卯辰山"],["c:d/df/070317_utatsuyama.jpg",3872,2592],["c:5/53/Maeda_Yoshiyasu_Photo_restored.jpg",2610,3985,"前田慶寧"],["c:5/5a/Kanazawa-shi_Utatsu-sanroku%2C_Ishikawa%2C_temple_district.JPG",6016,4016,"卯辰山山麓寺院群"],["c:3/34/%E7%9F%B3%E5%B7%9D%E8%AD%B7%E5%9B%BD%E7%A5%9E%E7%A4%BE.jpg",600,450,"石川護国神社"]]},{"id":"17_nanao_gunkan","n":"七尾軍艦所跡（加賀藩の洋式海軍拠点）","yomi":"ななおぐんかんしょあと","cat":"幕末","rank":"A","y":1862,"era":["edo","meiji"],"sh":"","ad":"七尾市府中町付近（七尾港一帯）","st":"JR・のと鉄道七尾駅から歩いて約15分（港の周辺）","la":37.0548,"lo":136.9771,"hook":"加賀百万石が本気で «海軍» をつくろうとした港。蒸気船と、英語を学ぶ若者たちがここにいた。","lead":"幕末の1862年、加賀藩は七尾の港に «七尾軍艦所» をつくりました。船をなおす造船所や鉄をつくる施設、英語などを学ぶ学校まであり、藩の洋式の海の基地でした。建物は残っておらず、いまは港の町に «跡» として記録が残っています。","story":["七尾湾は、能登島が波をふせぐ天然の良港です。奈良時代に能登国ができたとき、ここは国の港 «香島津（かしまつ）» とされ、江戸時代には北前船が出入りしてにぎわいました。«黒船» の時代がくると、この港は急に日本じゅうの注目を集めます。","開国のあと、幕府は外国船が入れる港の候補として七尾に目をつけ、加賀藩に «能登にある幕府の領地と七尾港を取りかえないか» ともちかけたといわれます。加賀藩の答えは «ノー»。自分たちの港は自分たちで守る、というわけです。そして1862年（文久2年）、藩はここに «七尾軍艦所» を開きました。","軍艦所には、船をなおす施設や製鉄の施設のほか、金沢の洋式学問所 «壮猶館» の分校として «七尾語学所» が置かれました。ここで英語や西洋の学問を学んだ若者の中から、のちに海軍の提督になる瓜生外吉、化学者の桜井錠二、鉄道技術者の平井晴二郎らが育ちました。«なぜ、港に学校を?» 船を動かすにも、外国と話すにも、まず言葉と科学が必要だったからです。","1867年には、イギリス公使パークスの一行が船で七尾を訪れ、通訳のアーネスト・サトウらが七尾から陸路で大坂へ向かったことが、サトウの回想録に書かれています。能登の小さな港町に、世界の大国の外交官がやって来たのです。","けれど時代は急に変わります。明治になって藩がなくなると、1876年（明治9年）に軍艦所は廃止されました。建物は残っていません。それでも七尾はその後、開港場（1899年）となり、北陸の重要な港として生き続けています。港を歩きながら、蒸気船の煙と、英語の発音練習をする若者たちの声を想像してみてください。"],"tl":[["718年","能登国の国の港として «香島津» と名づけられる"],["江戸時代","北前船の寄港地としてにぎわう"],["1858年ごろ","幕府が七尾港と天領の交換をもちかけるが、加賀藩は断る"],["1862年","加賀藩が七尾軍艦所を開く。七尾語学所も置かれる"],["1867年","イギリス公使パークスの一行が七尾を訪れる"],["1876年","七尾軍艦所が廃止される"],["1899年","七尾港が開港場に指定される"]],"who":[["瓜生外吉","七尾語学所で学んだ。のちの海軍大将"],["桜井錠二","七尾語学所で学んだ化学者。日本の化学研究の基礎を築いた"],["平井晴二郎","七尾語学所で学んだ鉄道技術者"],["アーネスト・サトウ","イギリスの外交官・通訳。七尾を訪れた記録を残した"]],"deep":["七尾語学所は金沢の «壮猶館»（加賀藩の洋式兵学・砲術などの学問所）の分校という位置づけ。港の軍事施設と学校がセットだった点に、藩の «人づくり» の考えが見える。","ここで学んだ人びとの顔ぶれは、海軍・化学・鉄道・工学と幅広い。石黒五十二（土木）、高山甚太郎（化学）もここで学んだとされ、明治の技術者の «ゆりかご» になった。","幕府による七尾港と天領の交換話は、開港地候補をめぐる動き。加賀藩が断ったことで、七尾は藩の軍港としての道を進むことになった。","サトウの回想録『一外交官の見た明治維新』には、七尾訪問と、そこから加賀・越前を通って大坂へ向かう陸路の旅がえがかれている。外国人が北陸を歩いた早い記録の一つ。","七尾港はいま、石川県内で取りあつかう貨物量がいちばん多い港。幕末の «軍港» の選び方は、湾の深さと波の静かさという点で、今にも通じている。"],"look":["七尾港の岸壁から見る七尾湾と能登島","港周辺に立つ七尾軍艦所・語学所ゆかりの案内","能登食祭市場（港のにぎわい）","七尾市内の資料館で幕末の七尾の展示があれば合わせて"],"q":["七尾軍艦所に置かれた学校で、若者たちは主に何を学んだ？","英語などの外国語や西洋の学問です。«七尾語学所» とよばれ、海軍や化学の分野で活やくする人が育ちました。"],"koji":[],"myth":"軍艦所跡の正確な位置や、港の案内板の場所は現地で確認を。幕府の交換話の細部は諸説。","img":["壮猶館","桜井錠二","瓜生外吉"],"wp":"七尾港","rel":{"ev":[],"grave":[]},"ph":[["c:7/70/Nanao_port.JPG",3648,2736,"七尾港"],["c:6/6b/Notojima.jpg",1024,768],["c:e/ee/Sakurai_Joji.jpg",266,341,"桜井錠二"],["c:6/62/Sotokichi_Uryu.jpg",320,475,"瓜生外吉"]]},{"id":"17_wajima_asaichi","n":"輪島朝市","yomi":"わじまあさいち","cat":"町","rank":"A","y":1000,"era":["heian","muromachi","reiwa"],"sh":"","ad":"輪島市河井町（朝市通り）","st":"金沢駅から輪島行きの特急バスで約2〜3時間。現在は朝市通りの復旧中のため、市内の «出張輪島朝市» の会場を確認して訪ねる","la":37.3964,"lo":136.902,"hook":"«買うてくだー»。千年つづいたといわれる海辺の朝市は、2024年の地震と火災をこえて、もう一度歩き出そうとしている。","lead":"輪島朝市は、平安時代に神社のお祭りの日に物を持ちより交換したのが始まりと伝わる、日本三大朝市の一つです。約360mの通りに魚や野菜、輪島塗などの店が並びました。2024年1月1日の能登半島地震で起きた大火事で通りは焼けてしまい、いまは再開をめざして準備が進んでいます。","story":["朝8時。細い通りの両側に、とれたての魚、干物、野菜、輪島塗のおわんが並びます。店に立つのは多くが地元のおばあちゃんたち。«買うてくだー» という呼び声と、ねぎるお客さんとのやりとりが、この朝市の名物でした。","始まりは平安時代といわれます。神社のお祭りの日に、人びとがとれた物を持ちよって、物々交換をしたのが起こりだと伝わります。室町時代には毎月 «4» と «9» のつく日に開かれるようになり、明治になると毎日の市になりました。«なぜ、こんなに長く続いたの?» 海の幸と山の幸、そして漆器の町の品物が、ここで自然に出会ったからでしょう。","昭和の中ごろ、輪島が映画のロケ地になると観光客がどっと増え、1980年には年間およそ270万人が訪れたといわれます。2015年には朝ドラ『まれ』の舞台として、ふたたび注目されました。地元の台所は、いつのまにか日本じゅうの人が集まる場所になっていたのです。","2024年1月1日、能登半島地震が起きました。その日の夕方、朝市通りの近くから火が出て、消火に使う水が地震で出なくなっていたこともあり、火は夜通し燃え広がりました。およそ300棟、5万㎡ほどが焼け、多くの方が亡くなりました。長い歴史をもつ通りは、一晩で失われたのです。","それでも朝市の人たちは立ち止まりませんでした。地震から約3か月後、金沢で «出張輪島朝市» が開かれ、その後は輪島市内の商業施設などでも店が出ています。朝市通りでは道路の工事が始まり、数年後の再開をめざす計画がまとめられました。訪れるときは、ここで失われた命と暮らしに思いをよせながら、今ひらいている市へ足を運んでみてください。"],"tl":[["平安時代","神社の祭りの日の物々交換が始まりと伝わる"],["室町時代","毎月4と9のつく日に開かれる市に"],["明治時代","毎日開かれるようになる"],["1980年","訪れる人が年間約270万人に"],["2015年","朝ドラ『まれ』の舞台として注目"],["2024年1月1日","能登半島地震と大規模火災で朝市通りが焼失"],["2024年3月","金沢で «出張輪島朝市» が始まる"],["2026年","朝市通りの復興計画がまとまり、道路工事が始まる"]],"who":[["朝市の売り手の人びと","何代にもわたって店に立ち、朝市の文化を守ってきた"],["輪島塗の職人たち","朝市に並ぶ漆器をつくり、町の名を広めた"],["輪島市朝市組合","出店者の団体。出張朝市などで営業を続けてきた"]],"deep":["日本三大朝市は、輪島朝市・千葉県勝浦市の勝浦朝市・岐阜県高山市の宮川朝市とされる。どれも «地元の暮らしの市» が観光地になった例。","朝市通りは約360m。店が道ばたに並び、通りぞいの商店とも共存する独特の形だった。道路をそのまま市場にする使い方は全国でも珍しい。","«4と9のつく日» に開く六斎市（月に6回の市）の形は、中世の各地に見られた。輪島もその一つで、明治に毎日の市へ変わった。","2024年の火災では、地震による断水で消火栓が使えず、近くの川も水位が下がってくみ上げられなかったなど、悪い条件が重なった。都市の防災を考えるうえで大切な教訓とされる。","2026年にまとまった計画では、朝市通りの北側に屋根つきの広場を整え、通りと広場の両方を使って、2029〜2030年ごろの再開をめざすとされている。"],"look":["現在ひらかれている «出張輪島朝市»（会場は事前に確認）","復旧が進む朝市通り（工事中の場所には入らない）","輪島塗の器や工房（輪島塗の資料館など）","周辺の追悼の場所では静かに手を合わせる"],"q":["室町時代の輪島朝市は、毎月どの日に開かれていた？","«4» と «9» のつく日です。明治になってから毎日開かれるようになりました。"],"koji":[],"myth":"«平安時代から» という始まりは伝承。再開の時期は計画段階で、変わる可能性がある。","img":["輪島市","輪島塗","令和6年能登半島地震"],"wp":"輪島朝市","rel":{"ev":[],"grave":[]},"ph":[["c:d/df/Wajima_Asaichi.jpg",1600,1200,"輪島朝市"],["c:9/98/Shuccho_Wajima_Asaichi.jpg",6240,3120],["c:5/5c/Air_Self-Defense_Force_drone_search_operation_at_Wajima_Asaichi.jpg",855,560],["c:5/50/Wajima_Asaichi_ac_%2810%29.jpg",5953,3959,"輪島市"],["c:2/22/Wajimanurie.JPG",646,604,"輪島塗"]]},{"id":"17_yamanaka","n":"山中温泉（芭蕉が逗留した湯）","yomi":"やまなかおんせん","cat":"町","rank":"A","y":1689,"era":["nara","kamakura","edo"],"sh":"","ad":"加賀市山中温泉湯の出町ほか","st":"JR加賀温泉駅からバスで約30分","la":36.248,"lo":136.3765,"hook":"温泉ぎらいといわれた芭蕉が、ここでは8泊もした。«菊を折らなくても、湯の香りで長生きできる» と詠んだ湯。","lead":"山中温泉は加賀市の山あいにある温泉町です。奈良時代に行基が見つけたという話が伝わり、1689年には『おくのほそ道』の旅の松尾芭蕉が8泊して、湯をほめる句を残しました。こおろぎ橋のかかる谷 «鶴仙渓» の景色でも知られます。","story":["大聖寺川がきざんだ深い谷。そこに旅館が寄りそうように並ぶのが山中温泉です。開湯の話は奈良時代にさかのぼり、僧の行基が薬師如来のみちびきで見つけたと伝わります。その後いったんさびれますが、鎌倉時代のはじめに長谷部信連が、足をけがした白鷺が湯で傷をいやしているのを見て、ふたたび開いたといわれます。","1689年（元禄2年）の夏の終わり、弟子の曾良をつれた松尾芭蕉がやって来ました。東北から北陸へ、長い旅の終わりが近づいていたころです。芭蕉は宿の若い主人・久米之助をかわいがり、«桃妖» という俳号をあたえました。そしてこの湯を、有馬・草津と並ぶ名湯だとほめたと伝わります。","ここで詠まれたのが «山中や 菊はたおらぬ 湯の匂»。«なぜ菊?» 昔から菊には長生きの力があると考えられ、九月九日の重陽の節句には菊を飾りました。芭蕉は «ここでは菊を折らなくてもいい。この湯の香りだけで命がのびる» と、湯をたたえたのです。共同浴場の名前 «菊の湯» は、この句にちなんでいます。","しかし山中では別れもありました。おなかをこわした曾良が、ひと足先に旅を離れることになったのです。曾良は «行き行きて たふれ伏すとも 萩の原»、芭蕉は «今日よりや 書付消さん 笠の露» と詠みかわしました。笠に書いた «同行二人» の文字を、涙の露で消そう、という悲しい一句です。","江戸時代の山中は大聖寺藩の領地。やがて山中漆器や民謡 «山中節» が育ち、湯の町の文化になりました。いまも鶴仙渓の遊歩道を歩き、こおろぎ橋を渡れば、芭蕉が見たかもしれない谷の景色に出会えます。"],"tl":[["奈良時代","行基が見つけたという開湯伝説"],["1185〜1190年ごろ","長谷部信連が白鷺の伝説とともに湯を再興したと伝わる"],["1580年","柴田勝家が軍勢に «山中湯» での乱暴を禁じたとされる"],["1689年","松尾芭蕉と曾良が訪れ、芭蕉は8泊する"],["江戸時代","大聖寺藩の領地となる"],["1931年","町の大火"],["1941年","山中海軍病院が開かれる（のちの山中温泉医療センター）"]],"who":[["松尾芭蕉","俳人。『おくのほそ道』の旅で8泊し、湯をほめる句を詠んだ"],["河合曾良","芭蕉の弟子。山中で体調をくずし、芭蕉と別れた"],["久米之助（桃妖）","芭蕉が泊まった宿の若い主人。芭蕉から俳号をもらった"],["行基","奈良時代の僧。開湯伝説の主人公"],["長谷部信連","鎌倉時代の武士。湯を再興したと伝わる"]],"deep":["芭蕉が山中に8泊したのは『おくのほそ道』の旅でも長い滞在の一つ。旅の疲れと、曾良の体調が関係したとも考えられる。","«扶桑三名湯»（有馬・草津・山中）は、芭蕉がほめたことに由来するといわれる。一般的な «日本三名泉» は有馬・草津・下呂で、山中は芭蕉版の三名湯。","共同浴場 «菊の湯» の名は芭蕉の句から。北陸では共同浴場を «総湯» とよび、この呼び名は北陸3県に多く残る。","白鷺伝説は、のちに北陸本線の特急 «しらさぎ» の名の由来の一つにもなったといわれる。","泉質は硫酸塩泉。昭和の初めまでは、宿に内湯がなく、みんなが «湯ざや» とよばれる共同浴場に通っていた。"],"look":["総湯 «菊の湯» と山中座","鶴仙渓の遊歩道とこおろぎ橋","芭蕉ゆかりの展示施設（芭蕉の館）","足湯 «笠の露»（芭蕉と曾良の別れの句にちなむ）"],"q":["芭蕉の句 «山中や 菊はたおらぬ 湯の匂» で、菊を折らないのはなぜ？","菊には長生きの力があると考えられていましたが、山中の湯の香りだけで十分に長生きできる、と湯をほめたからです。"],"koji":[{"w":"同行二人","m":"旅の笠に書く «二人で一緒に行く» という言葉。芭蕉は曾良との別れで、これを露（涙）で消そうと詠んだ"}],"myth":"行基の開湯、白鷺の話は伝説。«扶桑三名湯» を芭蕉がどう言ったかは伝えによる。","img":["松尾芭蕉","おくのほそ道","鶴仙渓"],"wp":"山中温泉","rel":{"ev":[],"grave":[]},"ph":[["c:4/40/260606_Kikuno-yu_Yamanaka_Onsen_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648,"山中温泉"],["c:c/c3/260606_Yamanaka_Onsen_Kaga_Ishikawa_pref_Japan02s3.jpg",5472,3648],["c:5/5d/260606_Doumyogafuchi_Kakusenkei_Kaga_Ishikawa_pref_Japan03s3.jpg",5472,3648],["c:d/d3/260606_Basho-no-Yakata_Yamanaka_Onsen_Kaga_Ishikawa_pref_Japan04s3.jpg",5472,3648],["c:1/12/260606_Basho-do_Yamanaka_Onsen_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648],["c:1/19/Shokoku_Onsen_Kounou_Kan-2.jpg",2300,3075],["c:6/62/Oku_no_Hosomichi-_separate_at_Yamanaka.jpg",2048,1536],["c:c/c1/20090913%E5%8A%A0%E8%B3%80%E4%B8%89%E6%B9%96Tagged.jpg",1280,960]]},{"id":"17_zenshoji","n":"全昌寺（芭蕉・曾良と五百羅漢）","yomi":"ぜんしょうじ","cat":"寺社","rank":"A","y":1689,"era":["azuchi","edo"],"sh":"","ad":"加賀市大聖寺神明町","st":"IRいしかわ鉄道・ハピラインふくい大聖寺駅から歩いて約10分","la":36.3063,"lo":136.3118,"hook":"先に旅立った弟子・曾良が泊まった翌晩、師匠の芭蕉が同じ寺に泊まった。«一夜ちがい» の寺。","lead":"全昌寺は加賀市大聖寺にある曹洞宗のお寺で、大聖寺城主・山口宗永の家の菩提寺です。1689年、『おくのほそ道』の旅で山中温泉で別れた曾良と芭蕉が、一晩ちがいでこの寺に泊まりました。境内の羅漢堂には、たくさんの羅漢像が並んでいます。","story":["大聖寺の町は、お寺がたくさん集まる町です。その一つ全昌寺は、戦国時代の終わりにこの地を治めた大聖寺城主・山口宗永の家の菩提寺として知られます。宗永は関ヶ原の戦いのとき西軍につき、前田利長に攻められて大聖寺城で自害しました。お寺には、その山口家の歴史が静かに眠っています。","1689年の秋。山中温泉で体をこわした曾良は、師匠の芭蕉と別れ、ひと足先に旅立ちました。その夜に泊まったのが、この全昌寺です。一人で寝る寺の夜、裏山から風の音が聞こえてきます。曾良は «終夜 秋風聞くや うらの山» と詠みました。«なぜ一晩じゅう風を聞いていたの?» 師匠と離れたさびしさで、眠れなかったのかもしれません。","そして次の晩。芭蕉が同じ全昌寺に泊まりました。«一夜のへだて、千里に同じ» ―― たった一晩のちがいでも、千里はなれているのと同じだ、と芭蕉は『おくのほそ道』に書いています。","朝、芭蕉が出発しようとすると、若いお坊さんたちが紙と硯を持って追いかけてきました。«一句お願いします»。ちょうど庭には柳の葉が散っていました。芭蕉は «庭掃いて 出でばや寺に 散る柳» と書いてわたしたと伝わります。泊めてもらったお礼に、せめて庭をはいてから出ていきたい、という旅人のあいさつです。","境内の羅漢堂には、江戸時代の終わりごろにつくられた五百羅漢がずらりと並びます。泣き顔、笑い顔、考えこむ顔……。一体ずつ見ていくと、自分に似た顔が見つかるともいわれます。芭蕉と曾良の句碑と合わせて、旅の気分を味わえるお寺です。"],"tl":[["戦国時代末","大聖寺城主・山口宗永の家の菩提寺となる"],["1600年","山口宗永が大聖寺城で前田利長に攻められ自害"],["1639年","大聖寺藩が成立し、大聖寺が城下町（陣屋町）として整う"],["1689年","『おくのほそ道』の旅で曾良、翌晩に芭蕉が泊まる"],["江戸時代後期","羅漢堂の五百羅漢がつくられる"]],"who":[["松尾芭蕉","俳人。曾良の翌晩に泊まり、«庭掃いて» の句を残した"],["河合曾良","芭蕉の弟子。一足先に泊まり、«終夜» の句を詠んだ"],["山口宗永","大聖寺城主。全昌寺はその家の菩提寺"]],"deep":["『おくのほそ道』の «全昌寺» の段は短いが、曾良の句と «一夜の隔て千里に同じ» の一文で、師弟の別れを強く印象づける名場面。","曾良の旅日記（『曾良旅日記』）には、実際の行程が記録されている。『おくのほそ道』は作品として手が加えられており、日記と比べると芭蕉の «演出» が見えてくる。","«庭掃いて» の句は、禅寺では出立の前に庭を掃いてお礼をする習わしがあることをふまえたものといわれる。","羅漢堂の像は500体をこえるといわれ、江戸時代の末ごろにつくられたと伝わる。表情が一体ずつちがい、見くらべるだけで時間がたつ。","全昌寺のある大聖寺の «山ノ下寺院群» は、藩の城下にお寺を集めた町並み。お寺めぐりの散歩道になっている。"],"look":["羅漢堂の五百羅漢（拝観は受付で）","芭蕉と曾良の句碑","山口宗永ゆかりの墓所","周辺の山ノ下寺院群の町並み"],"q":["芭蕉が『おくのほそ道』で «一夜の隔て千里に同じ» と書いたのは、誰のこと？","弟子の曾良です。曾良が泊まった翌晩に芭蕉が同じ寺に泊まり、一晩ちがいでも千里はなれているようだとさびしさを書きました。"],"koji":[{"w":"一夜の隔て、千里に同じ","m":"たった一晩はなれただけでも、千里はなれているのと同じくらい遠く感じる、という芭蕉の言葉"}],"myth":"五百羅漢の数・作者は伝えによる。«庭掃いて» の句の場面は『おくのほそ道』の記述による。","img":["おくのほそ道","河合曾良","大聖寺城"],"wp":"全昌寺","rel":{"ev":[],"grave":[]},"ph":[["c:3/3c/Kawai_Sora.jpg",1024,768,"河合曾良"],["c:9/9f/Ishikawa_Kaga_Kagahashidate00.jpg",2816,2120,"近く: 加賀市"],["c:b/bd/Daishoji_sta_2024.jpg",4032,2268,"近く: 大聖寺駅"],["c:2/21/260718_Ishikawa_Prefectural_Kutani_Ware_Museum_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648,"近く: 石川県九谷焼美術館"],["c:0/0f/Jishu-jiritsu.jpg",583,386,"近く: 石川県立大聖寺高等学校"],["c:8/89/260718_At_Daishoji_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648,"近く: 大聖寺町"],["c:b/bc/Daido_Kogyo_ac_%282%29.jpg",5663,3765,"近く: 大同工業"]]},{"id":"17_shiinoki","n":"旧石川県庁舎（しいのき迎賓館）","yomi":"きゅういしかわけんちょうしゃ（しいのきげいひんかん）","cat":"近代","rank":"A","y":1924,"era":["taisho","showa","heisei"],"sh":"国の登録有形文化財","ad":"金沢市広坂2丁目","st":"JR金沢駅からバスで «広坂・21世紀美術館» 下車すぐ","la":36.5624,"lo":136.6578,"hook":"正面は大正のレトロな県庁、裏にまわると全面ガラス。二つの顔をもつ建物の前で、300年の大木がずっと見守っている。","lead":"しいのき迎賓館は、1924年に建てられた旧石川県庁舎を生かした施設です。石川県で初めての本格的な鉄筋コンクリートの建物で、今ある県庁舎としては全国でもいちばん古い鉄筋コンクリートの庁舎でした。玄関前の2本のシイノキは国の天然記念物です。","story":["金沢の中心、広坂。兼六園と金沢城にはさまれた場所に、茶色いタイルの落ち着いた建物が立っています。1924年（大正13年）に完成した石川県庁舎です。設計にかかわったのは、のちに国会議事堂の設計にも関わった矢橋賢吉。左右対称の堂々とした姿は、«県の顔» にふさわしいものでした。","«なぜ鉄筋コンクリートだったの?» 大正時代、関東大震災（1923年）の前後で、火事や地震に強い建物が求められていました。この庁舎は石川県で最初の本格的な鉄筋コンクリート造り。水洗トイレや電気ストーブなど、当時の最新設備もそなえた «ハイテク庁舎» だったのです。上から見ると «日» の字を横にしたような形をしています。","玄関の前には、2本の大きなシイノキがそびえています。«堂形のシイノキ» とよばれ、樹齢は約300年。江戸時代、ここには加賀藩の «堂形» という建物があり、そのころから立っていた木だといわれます。県庁が建つずっと前から、この場所の移り変わりを見てきた «生き証人» です。","2003年、県庁は金沢の郊外・鞍月へ引っ越しました。古い庁舎はこわされるのか ―― 県は、正面の部分を残して生かす道を選びます。お城側はガラス張りに作りかえ、2010年に «しいのき迎賓館» として生まれ変わりました。名前は1200件をこえる公募から選ばれ、シイノキと «もてなし» の気持ちがこめられています。","正面から見ると大正、裏から見ると平成。二つの時代が背中合わせになったこの建物は、2021年に国の登録有形文化財になりました。いまはレストランやギャラリー、休けいスペースとして、だれでも気軽に入れる «町の応接間» です。"],"tl":[["江戸時代","加賀藩の «堂形» の建物があった場所。シイノキが育つ"],["1924年","石川県庁舎が完成（鉄筋コンクリート造）"],["2003年","県庁が鞍月へ移転"],["2010年","«しいのき迎賓館» として開館"],["2021年","国の登録有形文化財になる"],["2024年","能登半島地震で通用口の階段がこわれる被害"]],"who":[["矢橋賢吉","建築家。旧石川県庁舎の設計にかかわった"],["石川県","旧庁舎を保存・活用し、迎賓館として再生した"]],"deep":["旧石川県庁舎は、現存・過去を通じて日本で最も古い鉄筋コンクリート造の県庁舎とされる。","外壁のスクラッチタイル（表面に細いみぞのあるタイル）は愛知県の武豊でつくられたもの。大正から昭和初めに流行した仕上げ。","改修では免震構造を取り入れ、2011年度にグッドデザイン賞を受賞した。«古い正面+新しいガラス» の組み合わせは、歴史的建物の活用例としてよく紹介される。","«堂形» の名は、京都・三十三間堂を模した弓の練習場（堂形）が置かれ、のちに米蔵などとしても使われたことに由来するといわれる。","正式名称は «石川県政記念しいのき迎賓館»。«県政記念» には、明治から県政の中心だった土地の記憶を残す意味がある。"],"look":["正面の左右対称のファサードとスクラッチタイル","国の天然記念物 «堂形のシイノキ»（2本）","裏側（金沢城側）のガラス張りの増築部分","内部に残る旧庁舎の階段や意匠"],"q":["しいのき迎賓館の前に立つ2本の木は、何という名前でよばれている？","«堂形のシイノキ» です。樹齢約300年で、国の天然記念物に指定されています。"],"koji":[],"myth":"«堂形» の由来には諸説ある。","img":["石川県政記念しいのき迎賓館","堂形のシイノキ","金沢城"],"wp":"しいのき迎賓館","rel":{"ev":["sankin","basho"],"grave":[]},"ph":[["c:6/61/Shiinoki_Geihinkan.jpg",1600,1200,"しいのき迎賓館"],["c:f/f7/Shiinoki_Geihinkan_Front.jpg",1600,1200],["c:0/01/Grand_chinquapin_tree_in_front_of_Shiinoki_Cultural_Complex_of_Ishikawa_Prefecture.JPG",3264,2448,"堂形のシイノキ"],["c:7/7e/Kanazawa-M-5932.jpg",1500,1000,"金沢城"]]},{"id":"17_gokoku","n":"石川護国神社","yomi":"いしかわごこくじんじゃ","cat":"昭和","rank":"A","y":1870,"era":["meiji","showa"],"sh":"","ad":"金沢市石引4丁目","st":"JR金沢駅からバスで «出羽町» 付近下車、歩いて約5分","la":36.5593,"lo":136.6639,"hook":"戊辰戦争で亡くなった加賀藩の107人から始まり、昭和の戦争へ。まつられる人の数とともに、日本の近代がきざまれた神社。","lead":"石川護国神社は、戊辰戦争で亡くなった加賀藩の人びとをまつるため、明治3年に藩知事の前田慶寧がつくった «招魂社» が始まりです。はじめは卯辰山にありましたが、1935年に兼六園の近くの今の場所に移りました。のちの戦争で亡くなった石川県ゆかりの人びともまつられています。","story":["1868年に始まった戊辰戦争。加賀藩も新政府側として北越などへ兵を送り、多くの藩士や兵が命を落としました。明治3年（1870年）の暮れ、藩知事となっていた前田慶寧は、亡くなった107人の霊をなぐさめるため、卯辰山に «招魂社» をたてます。«ふるさとのために戦った人を忘れない» ―― それがこの神社の出発点でした。","時代が進むと、日清・日露、そして昭和の戦争へと、戦いで亡くなる人の数はふくらんでいきました。卯辰山の境内はせまく、大きな式典を開くのがむずかしくなります。そこで1935年（昭和10年）、陸軍の小立野練兵場の一角だった今の場所に移りました。兼六園のすぐとなりです。","1939年、全国の招魂社は «護国神社» と名前を変え、ここも «石川護国神社» になりました。«なぜ名前が何度も変わったの?» 戦争が終わると、軍とのつながりを見直す動きのなかで、一時 «石川神社» と名のりました。そして1952年、もとの名前にもどっています。名前の移り変わりそのものが、戦前と戦後の日本の歩みを映しているのです。","境内は石川県でもいちばん広いといわれる神社の敷地です。参道には、さまざまな戦争や部隊の慰霊碑が並びます。その一つ一つに、帰ってこられなかった家族を思う人びとの気持ちがこめられています。","境内には2000年に建てられた大きな碑もあり、その碑文や名前をめぐっては、歴史の見方のちがいから議論もあります。訪れるときは、どんな立場であっても、ここにまつられた一人ひとりの命の重さを、静かに考える時間にしたい場所です。"],"tl":[["1868〜1869年","戊辰戦争。加賀藩からも多くの戦死者が出る"],["1870年（明治3年12月）","前田慶寧が卯辰山に招魂社を創建（新暦では1871年2月）"],["1901年","官祭招魂社となる"],["1935年","小立野の練兵場跡の一角（現在地）へ移る"],["1939年","石川護国神社と改称"],["1949年","«石川神社» と改称"],["1952年","«石川護国神社» にもどる"]],"who":[["前田慶寧","加賀藩最後の藩主・藩知事。招魂社を創建した"],["水野徳三郎","戊辰戦争で亡くなった加賀藩士。最初にまつられた107人の一人"],["戦没者の遺族","慰霊祭や碑の建立を通じて神社を支えてきた"]],"deep":["創建の日付は明治3年12月15日。当時はまだ旧暦で、新暦に直すと1871年2月4日になる。年をまたぐので資料によって «1870年» «1871年» の表記がある。","招魂社から護国神社への一斉改称は1939年の内務省の制度による。全国の多くの護国神社が同じ年に名前を変えた。","戦後、占領下で «護国» の名をさけて改称した護国神社は各地にあり、サンフランシスコ平和条約の発効（1952年）前後に元の名にもどした例が多い。","今の場所は旧陸軍の小立野練兵場の一部。近くには旧第九師団の建物（現在の国立工芸館）など、金沢が «軍都» だった時代の施設が集まっていた。","境内の «大東亜聖戦大碑»（2000年建立）は、その名称や碑文をめぐり評価が分かれる。史跡として見るときは、建てた人びとの主張と、それへの批判の両方を知っておきたい。"],"look":["社殿と広い境内","参道に並ぶ部隊・戦没者の慰霊碑","となりの兼六園・本多の森との位置関係","卯辰山の旧地（招魂社があった場所）と合わせてたどる"],"q":["石川護国神社は、最初はどこの山にあった？","卯辰山です。1935年に今の兼六園の近くへ移りました。"],"koji":[],"myth":"碑の名称・碑文の評価には見方の対立がある。","img":["護国神社","前田慶寧","戊辰戦争"],"wp":"石川護国神社","rel":{"ev":[],"grave":[]},"ph":[["c:3/34/%E7%9F%B3%E5%B7%9D%E8%AD%B7%E5%9B%BD%E7%A5%9E%E7%A4%BE.jpg",600,450,"石川護国神社"],["c:5/53/Maeda_Yoshiyasu_Photo_restored.jpg",2610,3985,"前田慶寧"],["c:4/46/Monument_of_Meijiishin_Fushimi_no_senseki.jpg",3024,3780,"戊辰戦争"]]},{"id":"17_daishojijo","n":"大聖寺城（錦城山）","yomi":"だいしょうじじょう","cat":"城","rank":"A","y":1600,"era":["muromachi","azuchi"],"sh":"国指定史跡","ad":"加賀市大聖寺錦町","st":"IRいしかわ鉄道・ハピラインふくい大聖寺駅から歩いて約15分","la":36.3108,"lo":136.3062,"hook":"一向一揆、朝倉、織田、上杉、そして関ヶ原。加賀の南の入り口にあったため、持ち主が次々と変わった «国境の城»。","lead":"大聖寺城は、加賀市の錦城山（標高約70m）にあった山の城です。加賀と越前（福井県）の境にあるため、戦国時代には一向一揆や織田信長の軍などが何度も取りあいました。1600年の関ヶ原の戦いのとき落城し、その後廃城に。いまは公園になっており、国の史跡です。","story":["加賀の南のはし、大聖寺川のそばにぽつんと立つ小山、錦城山。ここが大聖寺城のあとです。越前から加賀へ入る道をおさえる場所で、«加賀の玄関口» ともいえる城でした。南北朝時代にはもう戦いの舞台になっていたと記録にあります。","戦国時代、加賀は «百姓の持ちたる国» とよばれる一向一揆の国でした。大聖寺城も一揆の拠点になります。1555年、越前の名将・朝倉宗滴が攻めこみ、城は一日で落ちたと伝わります。その後も越前の朝倉と加賀の一揆は、ここをはさんでせめぎあいを続けました。","1575年、越前を手に入れた織田信長の軍が加賀へ入ります。柴田勝家は大聖寺城を修理し、武将を置いて一揆とたたかいました。1577年には手取川の戦いで上杉謙信が織田軍を破り、城も上杉方の手にわたったといわれます。«なぜ、こんなに持ち主が変わるの?» それだけ、ここをおさえることが加賀全体をおさえる近道だったのです。","豊臣秀吉の時代をへて、最後の城主になったのは山口宗永。1600年の関ヶ原の戦いで宗永は西軍につき、東軍の前田利長の大軍に囲まれました。城は落ち、宗永は自害したと伝わります。城あとには «山口玄蕃頭宗永公» の碑が立ち、最後まで城を守った武将をしのんでいます。","その後、1615年の一国一城令で城は廃止されます。やがて加賀藩の分家・大聖寺藩ができ、山のふもとに陣屋（藩の役所）が置かれました。山の上には今も土塁や空堀、くるわ（平らな区画）がよく残り、戦国の山城の迫力を感じることができます。"],"tl":[["1335年","中先代の乱にからみ、大聖寺城で戦いがあったとされる"],["1555年","朝倉宗滴が加賀に攻めこみ、大聖寺城が一日で落ちる"],["1575年","織田信長の軍が加賀へ。柴田勝家が城を修理"],["1577年","手取川の戦いのあと、上杉方が城を取る"],["1598年","山口宗永が城主となる"],["1600年","関ヶ原の戦いの際、前田利長に攻められ落城。宗永自害"],["1615年","一国一城令で廃城"],["1639年","大聖寺藩が成立し、ふもとに陣屋が置かれる"]],"who":[["山口宗永","最後の城主。関ヶ原で西軍につき、前田利長に攻められて自害"],["前田利長","加賀藩の2代目。東軍として大聖寺城を攻め落とした"],["朝倉宗滴","越前朝倉家の名将。1555年に城を落とした"],["柴田勝家","織田信長の重臣。加賀攻めで城を修理した"],["佐久間盛政","勝家の甥。一時、城主となった"]],"deep":["城は錦城山の尾根に本丸・二の丸・西の丸・鐘ヶ丸・東丸などがならぶ連郭式。鐘ヶ丸は東西約100mの最大の郭で、長さ約70m・高さ3〜4mの大きな土塁が残る。","本丸は東西約45m・南北約17m。高さ約4mのかぎ形の土塁があった。規模は大きくないが、遺構の残り方がよい山城として評価されている。","『朝倉始末記』は1555年に落ちた城を «津葉城» と書く。これが大聖寺城の別名か、となりの砦かは議論がある。","1600年の前田利長の南下は、その直後の «浅井畷の戦い»（小松付近）へつながる。関ヶ原の本戦と同じ時期に、北陸でも東西の戦いがあった。","城のふもとの大聖寺藩関係の史跡には、3代藩主・前田利直がつくった茶室風の別邸 «長流亭»（国の重要文化財）がある。"],"look":["本丸跡と «山口玄蕃頭宗永公» の碑","鐘ヶ丸の大土塁","空堀・切岸などの山城の遺構","東丸跡から見る加賀の町並み"],"q":["関ヶ原の戦いのとき、大聖寺城を攻め落としたのはだれ？","東軍についた前田利長です。西軍の城主・山口宗永は自害したと伝わります。"],"koji":[{"w":"百姓の持ちたる国","m":"一向一揆が治めた戦国時代の加賀をさす言葉。武士ではなく門徒たちが国を動かしているようすをあらわした"}],"myth":"«津葉城» との関係は諸説。","img":["朝倉宗滴","山口宗永","大聖寺藩"],"wp":"大聖寺城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/92/260718_Yamanoshita_Jiingun_Kaga_Ishikawa_pref_Japan03s3.jpg",5472,3648,"大聖寺藩"]]},{"id":"17_yusenji","n":"遊泉寺銅山跡（コマツ創業の地）","yomi":"ゆうせんじどうざんあと","cat":"産業","rank":"A","y":1917,"era":["meiji","taisho"],"sh":"","ad":"小松市鵜川町","st":"JR小松駅から車で約20分（公共交通では行きにくい）","la":36.37,"lo":136.51,"hook":"世界の建設機械メーカー «コマツ» は、山の中の銅山の «修理工場» から始まった。","lead":"遊泉寺銅山は、小松市の山あいにあった銅山です。明治の終わりに実業家の竹内明太郎が本格的に開発し、1917年には鉱山の機械をつくる «小松鉄工所» をつくりました。これが今の世界的な会社 «小松製作所（コマツ）» の始まりです。鉱山は大正時代に閉山し、いまは跡地が公園として整えられています。","story":["小松の町から山のほうへ入った静かな谷。ここにかつて、たくさんの人が働く銅山がありました。遊泉寺銅山です。明治のなかごろ、この山に目をつけたのが、高知出身の実業家・竹内明太郎でした。","竹内は1902年ごろから遊泉寺銅山の開発に取りかかります。欧米の鉱山を見て回り、新しい機械を買ってきた人物でした。«山から銅を掘り出すには、機械がいる。機械がこわれたら、なおす工場がいる»。そう考えた竹内は、1917年、銅山の付属施設として小松の町に «小松鉄工所» をつくります。","ところが第一次世界大戦が終わると、銅の値段が大きく下がりました。遊泉寺銅山は大正時代の中ごろに閉山します。«山がなくなったら、工場もおしまい?» ―― 竹内はそう考えませんでした。1921年、鉄工所を独立させて «株式会社小松製作所» を立ち上げたのです。","竹内は «地方に産業を育て、技術者を育てる» ことを大切にした人でした。早稲田大学の理工科の創設を支えたり、ふるさと高知に工業学校をつくったりしています。国産自動車 «ダット（DAT）» の «T» は、竹内の頭文字だともいわれます。じつは竹内は、のちに総理大臣になる吉田茂の実の兄でした。","銅山のあとには、煙突の土台や建物の基礎などが残り、近年、跡地は公園として整えられました。小さな谷の «修理工場» が、ブルドーザーをつくり、世界じゅうに工場をもつ会社へ。その出発点に立つと、産業の歴史のおもしろさがわかります。"],"tl":[["江戸時代","銅山として掘られていたと伝わる"],["1902年","竹内明太郎が遊泉寺銅山の開発に着手"],["1917年","銅山の付属施設として小松鉄工所をつくる"],["大正時代中ごろ","銅の値下がりなどで閉山"],["1921年","小松鉄工所が独立し、株式会社小松製作所が生まれる"],["1932年","国産初のトラクターを開発"],["近年","銅山跡が公園として整えられ、見学できるようになる"]],"who":[["竹内明太郎","実業家。遊泉寺銅山を開発し、小松製作所を創業した"],["吉田茂","竹内明太郎の弟。のちの総理大臣"],["橋本増治郎","自動車技術者。小松鉄工所の初代所長を兼ねた"]],"deep":["小松鉄工所は «銅山で使う機械を自分でつくる» ための施設だった。ここで工作機械や採掘機械をつくった経験が、のちの建設機械づくりにつながった。","竹内明太郎は、自動車メーカー «快進社» の設立にも関わり、国産車 «DAT» の名は出資者3人（田・青山・竹内）の頭文字からとされる。","竹内は父・竹内綱の長男で、吉田茂は綱の五男（吉田家の養子）。兄弟で «産業» と «政治» の道に分かれた。","コマツの本社は1951年に東京へ移ったが、小松市は今もコマツの企業城下町。旧本社の建物を復元した «こまつの杜» が小松駅の近くにある。","閉山の年は資料によって1920年とされることが多い。第一次世界大戦後の不況は、日本各地の鉱山を閉山に追いこんだ。"],"look":["銅山跡に残る煙突の土台や施設の基礎","銅山跡の公園に立つ説明板","小松駅近くの «こまつの杜»（旧本社社屋の復元と大型ダンプ）","周辺の里山の景色（鉱山町があった谷）"],"q":["コマツ（小松製作所）の始まりになった «小松鉄工所» は、何のためにつくられた？","遊泉寺銅山で使う機械をつくったり、なおしたりするためです。"],"koji":[],"myth":"江戸時代の採掘の始まり、閉山年、遺構の内容は資料で細部が異なる。","img":["竹内明太郎","小松製作所","吉田茂"],"wp":"遊泉寺銅山","rel":{"ev":[],"grave":[]},"ph":[["c:b/b8/Meitar%C5%8D_Takeuchi.jpg",1072,1200,"竹内明太郎"],["c:3/33/KOMATSU_Buildng%2C_2017.jpg",4160,3120,"小松製作所"],["c:3/3d/Yoshida_Shigeru_ca._1950.jpg",720,927,"吉田茂"]]},{"id":"17_jike","n":"寺家遺跡（気多神社の祭祀遺跡）","yomi":"じけいせき","cat":"遺跡","rank":"A","y":800,"era":["nara","heian"],"sh":"国指定史跡","ad":"羽咋市寺家町","st":"JR羽咋駅からバスで «一の宮» 下車、歩いて約10分","la":36.92,"lo":136.7725,"hook":"砂にうもれた «神さまの工房»。能登一之宮・気多大社のそばで、奈良・平安の祭りの道具がつくられていた。","lead":"寺家遺跡は、羽咋市の海岸の砂丘にある遺跡です。能登国一宮・気多大社と深い関係があり、奈良・平安時代には神社のお祭りに使う塩や鉄の道具などをつくる工房がありました。縄文時代から室町時代までの跡が重なっていて、2012年に国の史跡になりました。","story":["羽咋の海ぞいには、なだらかな砂丘が続きます。1978年、海ぞいの道路をつくる工事にあわせて発掘をしてみると、砂の下から次々と建物の跡があらわれました。これが寺家遺跡です。すぐそばには、能登でいちばん格の高い神社・気多大社があります。","見つかったのは、竪穴の建物37軒、柱を立てた建物44棟、それに塩をつくる炉や、小さな鍛冶の炉。«なぜ神社の近くに工房が?» 古代のお祭りには、塩や鉄の道具、木の器やガラスの品がたくさん必要でした。ここは神社に仕える人びと（神戸）が暮らし、祭りの品をつくる «神さまの工房» だったと考えられています。","出土品もはなやかです。中国風の «海獣葡萄鏡»、三彩や緑釉の焼き物、銅の鈴、お金、ガラス製品……。能登の小さな海辺に、都や大陸につながる品が集まっていました。気多の神は、奈良時代から都でも知られる大きな神でした。万葉集には、越中国の役人だった大伴家持が気多の神に参ったときの歌がのっています。","さらに、気多大社は日本海の向こうの国 «渤海» との交流と関わりがあったとされ、ここに渤海からの使いをむかえる施設があったのでは、という説もあります。海の向こうからの客人を、能登の神さまがむかえていたのかもしれません。","ところがこの工房の村は、10世紀と15世紀の二度、砂におそわれました。風が運ぶ砂丘の砂にうもれ、人びとは暮らしをやめたとみられています。砂が遺跡を消し、そして千年後まで守ってくれたのです。"],"tl":[["縄文時代","人びとの活動が始まる"],["748年","大伴家持が気多の神に参り、歌をよむ（万葉集）"],["奈良〜平安時代","祭祀に使う塩・鉄・ガラスなどの工房がいとなまれる"],["10世紀","砂丘の砂が進入し、いったん衰える"],["15世紀","ふたたび砂におおわれ、廃絶"],["1978年","道路建設にともない3年間の大規模な発掘が始まる"],["2012年","国の史跡に指定"]],"who":[["大伴家持","越中国守。気多の神に参った歌が万葉集にある"],["気多大社の神戸","神社に仕えた人びと。工房で祭りの品をつくったと考えられる"],["発掘調査の担当者","1978年からの調査で遺跡の全体像を明らかにした"]],"deep":["見つかった遺構は竪穴建物37軒・掘立柱建物44棟・土塁つきの中世建物22棟など。古代だけでなく中世の神社経営の施設も推定されている。","出土した «海獣葡萄鏡» は唐の鏡の文様をもつもので、奈良時代の都と同じ系統の祭祀品が能登にもたらされていたことを示す。","製塩炉の存在は、祭りに使う塩を神社の近くで自前でつくっていたことを物語る。能登は古代から塩の産地だった。","渤海使の «能登客院» と関わる施設があったという説は、気多と日本海交流のつながりから出されたもので、確定はしていない。","廃絶の原因が «砂丘の進入» とされる点は、日本海側の砂丘地帯の遺跡に共通する特徴。砂が遺構をパックして保存状態をよくした。"],"look":["遺跡の説明板と史跡の範囲","近くの気多大社と «入らずの森»","海ぞいの砂丘の地形（遺跡をうめた砂の正体）","羽咋市の資料館で出土品の展示があれば合わせて"],"q":["寺家遺跡の工房が使われなくなった主な原因は？","砂丘の砂におおわれたことです。10世紀と15世紀の二度、砂が進入したとみられています。"],"koji":[],"myth":"渤海使の施設があったという説は仮説の段階。","img":["気多大社","大伴家持","渤海 (国)"],"wp":"寺家遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:2/2f/Jike_ruin.jpg",2432,1824,"寺家遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:7/7c/Keta-taisha_keidai.JPG",3648,2736,"気多大社"],["c:3/3e/Sanj%C5%ABrokkasen-gaku_-_5_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Ch%C5%ABnagon_Yakamochi.jpg",1000,1450,"大伴家持"],["c:0/05/Balhae-Territory_in_830_jp.png",1045,868,"渤海 (国)"]]},{"id":"17_daishoji_han","n":"大聖寺陣屋跡（大聖寺藩）","yomi":"だいしょうじじんやあと","cat":"大名屋敷","rank":"B","y":1639,"era":["edo"],"sh":"","ad":"加賀市大聖寺八間道（江沼神社一帯）","st":"IRいしかわ鉄道・ハピラインふくい大聖寺駅から歩いて約15分","la":36.3091,"lo":136.3078,"hook":"城をもたない10万石。大聖寺藩は «日本一大きな陣屋» の藩だった。","lead":"大聖寺藩は、加賀藩の分家として1639年に生まれた藩です。一国一城令で城がこわされていたため、藩主は錦城山のふもとの «陣屋» で政治をしました。のちに石高は10万石になり、城のない大名としては最大級でした。いまは江沼神社や公園になり、石垣や庭園の一部が残ります。","story":["1639年（寛永16年）、加賀藩の3代目・前田利常は隠居するとき、二人の息子に領地を分けました。次男の利次には富山10万石、三男の利治には大聖寺7万石。こうして生まれたのが大聖寺藩です。«本家を分家が支える» ―― 加賀百万石を守るための、利常の知恵でした。","ところが大聖寺には、もうお城がありませんでした。関ヶ原のあとに廃城となり、1615年の一国一城令で使えなくなっていたのです。そこで利治は、錦城山（大聖寺城あと）のふもとに «陣屋» をかまえました。陣屋は城よりも小さな役所と屋敷です。山のほうは人が入らないようにして、川を堀のかわりにしました。","初代の利治は、領内の九谷村で焼き物づくりを始めさせたといわれます。これがのちに «古九谷» とよばれる、あざやかな色絵の磁器です。«なぜ小さな藩が焼き物を?» 米だけにたよらず、特産品で藩をゆたかにしたいという思いがあったのかもしれません。","江戸時代のなかごろ、事件も起きます。3代藩主・利直の弟の利昌は «大聖寺新田藩» 1万石をもらっていましたが、1709年、将軍の法事の場で別の大名を刺し殺してしまい、切腹。新田藩は取りつぶされ、領地は大聖寺藩にもどりました。","1821年、9代藩主・利之のときに藩は7万石から10万石へと «格上げ» されます。新田開発と本家・加賀藩の支援で数字をそろえたものでした。こうして大聖寺藩は、陣屋の大名としては最大級のまま明治をむかえます。陣屋あとには江沼神社がまつられ、藩邸の庭園や石垣が当時のおもかげを伝えています。"],"tl":[["1615年","一国一城令で大聖寺城が廃城に"],["1639年","前田利常が隠居し、三男の利治に7万石を分けて大聖寺藩が成立"],["1655年ごろ","九谷村で色絵磁器（古九谷）の焼成が始まったとされる"],["1660年","領地の交換で江沼郡全域と能美郡の一部を領する"],["1709年","大聖寺新田藩が取りつぶされ、領地が大聖寺藩にもどる"],["1709年","3代利直が別邸 «長流亭» を建てる"],["1821年","7万石から10万石に高直し"],["1871年","廃藩置県で大聖寺県となる"]],"who":[["前田利治","初代大聖寺藩主。前田利常の三男"],["前田利常","加賀藩3代藩主。隠居の際に大聖寺藩と富山藩を分けた"],["前田利直","3代藩主。別邸 «長流亭» を建てた"],["前田利昌","利直の弟。大聖寺新田藩主。事件を起こし切腹"],["前田利之","9代藩主。10万石への高直しを行った"]],"deep":["«高直し» は実際の収入を増やすというより、藩の格（石高）を上げる手続き。1821年の10万石化は、新田開発分1万石と加賀藩からの支援米などで計算をそろえたとされる。格が上がると、江戸での役目や出費も増えた。","1709年の事件では、前田利昌が大和柳本藩主の織田秀親を、将軍綱吉の法会の場（上野・寛永寺）で刺殺した。原因ははっきりしない。","長流亭（川端御亭）は1709年に建てられた数寄屋風の小さな建物で、国の重要文化財。«小堀遠州の設計» と伝えられるが、遠州は1647年に亡くなっており、遠州流の作風を受けついだものとみるのが自然。","古九谷は、大聖寺藩領の九谷村でつくられたとする説と、有田（佐賀県）でつくられたとする説があり、長く論争が続いている。","陣屋あとの北側の石垣と、藩邸内の川のあとは加賀市指定史跡、庭園は «旧大聖寺藩邸庭園» として市指定名勝。"],"look":["江沼神社と旧大聖寺藩邸庭園","陣屋あとに残る石垣と土塁","近くの長流亭（国の重要文化財）","背後の錦城山（大聖寺城跡）"],"q":["大聖寺藩の藩主が城ではなく «陣屋» で政治をしたのはなぜ？","大聖寺城が関ヶ原のあとに廃城となり、一国一城令で城を使えなかったからです。"],"koji":[],"myth":"長流亭の設計者、古九谷の産地は諸説。","img":["前田利治","古九谷"],"wp":"大聖寺藩","rel":{"ev":[],"grave":[]},"ph":[["c:9/92/260718_Yamanoshita_Jiingun_Kaga_Ishikawa_pref_Japan03s3.jpg",5472,3648,"大聖寺藩"],["c:8/89/260718_At_Daishoji_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648],["c:a/ad/260605_Choryu-tei%2C_Enuma-jinja_Kaga_Ishikawa_pref_Japan02s3.jpg",5472,3648],["c:4/4f/KUTANI_Ewer.JPG",852,627,"古九谷"]]},{"id":"17_kiriyamajo","n":"切山城","yomi":"きりやまじょう","cat":"城","rank":"B","y":1584,"era":["azuchi"],"sh":"国指定史跡","ad":"金沢市宮野町","st":"IRいしかわ鉄道森本駅から車で約20分（公共交通では行きにくい）","la":36.6006,"lo":136.7451,"hook":"道を見張り、道を城に取りこむ。前田利家と佐々成政がにらみ合った «国境の最前線»。","lead":"切山城は、金沢市の山あいにある戦国時代の終わりの山城です。1584年、前田利家（加賀）と佐々成政（越中）が対立したとき、国境の最前線として使われました。近くの松根城や古道 «小原越» とともに、2015年に国の史跡になりました。","story":["1582年、本能寺の変で織田信長がたおれました。天下は羽柴秀吉のほうへ動いていきます。1584年、秀吉と徳川家康がぶつかる «小牧・長久手の戦い» が起きると、越中（富山県）の佐々成政は家康の側につきました。となりの加賀には、秀吉の味方・前田利家。二人はもともと信長の家来どうしでした。","こうして加賀と越中の境の山々は、一気に緊張につつまれます。«いつ攻めてくるか分からない»。両軍は国境の尾根に次々と城をつくりました。その最前線の一つが、この切山城です。森下川と支流の谷にはさまれた、標高139mの丘の上にあります。","切山城には、ふしぎな特徴があります。城のはしを、加賀と越中を結ぶ山越えの道 «小原越» が通っていて、道の一部は城の区画の中に取りこまれているのです。«なぜ道を城の中に?» 通る人や敵の動きを見張り、いざとなれば道そのものを守りの一部にするためだったと考えられます。","城の東側、つまり越中側には、大きな横堀がほられています。越中からの攻撃を強く意識したつくりです。そのため、この城は前田側の城だと考えられています。江戸時代の地誌には、前田の家臣・不破彦三が守ったと伝えられています。","1585年、秀吉みずから大軍をひきいて越中へ向かうと、成政は降伏しました。国境の緊張はとけ、切山城もその役目を終えます。わずかな期間しか使われなかったからこそ、戦国の最後の «にらみ合い» の姿が、そのまま山の中に残ったのです。"],"tl":[["1582年","本能寺の変。信長がたおれる"],["1583年","賤ヶ岳の戦い。秀吉が柴田勝家をやぶる"],["1584年","小牧・長久手の戦い。前田利家と佐々成政が対立し、国境に城が築かれる"],["1585年","秀吉が越中へ出陣し、成政が降伏（富山の役）"],["2011年ごろ","金沢市による発掘・調査が進む"],["2015年","松根城・小原越とともに国の史跡に指定"]],"who":[["前田利家","加賀の大名。秀吉側として国境を固めた"],["佐々成政","越中の大名。家康側について秀吉・利家と対立した"],["不破彦三","前田家の家臣。切山城を守ったと伝わる"],["羽柴秀吉","1585年に越中へ出陣し、成政を降伏させた"]],"deep":["城域は南北約250m×東西約200m。曲輪・切岸・堀切・土塁・櫓台・虎口などがそろって残る。","史跡名は «加越国境城跡群及び道»。城だけでなく «道» まで一緒に指定されたのが大きな特徴。","東（越中）側に大きな横堀がある切山城は前田方、西（加賀）側に横堀がある松根城は佐々方と考えられ、二つの城が小原越をはさんでにらみ合う構図が推定されている。","松根城側では、古い小原越の道が幅25mの大堀切で断ち切られており、«戦時に道を封鎖した» 遺構として初めて確認された例とされる。","城が使われたのは1584〜1585年のごく短い期間と考えられ、築城技術の «その時点の姿» を知るよい資料になっている。"],"look":["城の南端に沿って通る古道 «小原越»","越中側（東）に掘られた大きな横堀","曲輪と櫓台のあと","松根城の方向を望む尾根の地形"],"q":["切山城と松根城の間を通っていた山越えの古道の名前は？","«小原越（おはらごえ）» です。城と道がセットで国の史跡になっています。"],"koji":[],"myth":"不破彦三が守ったという話は近世の地誌による伝え。","img":["佐々成政","前田利家","松根城"],"wp":"切山城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/38/Sassa_Narimasa.JPG",408,484,"佐々成政"],["c:9/96/Maeda_Toshiie.jpg",495,658,"前田利家"],["c:c/c2/Matsune_Castle.jpg",480,782,"松根城"]]},{"id":"17_matsunejo","n":"松根城","yomi":"まつねじょう","cat":"城","rank":"B","y":1584,"era":["heian","muromachi","azuchi"],"sh":"国指定史跡","ad":"金沢市松根町（富山県小矢部市との境）","st":"IRいしかわ鉄道森本駅から車で約30分（公共交通では行きにくい）","la":36.6162,"lo":136.7835,"hook":"城の中を通る街道を、幅25mの堀でばっさり断ち切った。«道を封鎖した» 跡が見つかった日本初の城。","lead":"松根城は、石川県金沢市と富山県小矢部市の境、標高約308mの尾根にあった山城です。一向一揆の城として使われたのち、1584年には越中の佐々成政が前田利家に対する最前線として大きく作りかえました。切山城・小原越とともに国の史跡です。","story":["加賀と越中の境にのびる尾根。ここは昔から、二つの国を結ぶ道が通る大事な場所でした。1183年、木曽義仲が倶利伽羅峠の戦いのころにこの山に陣をしいたという言い伝えもありますが、確かなことは分かっていません。","戦国時代になると、この城は一向一揆の城として記録にあらわれます。1550年には一揆の洲崎兵庫が城主になったといわれます。やがて織田信長の軍が加賀の一揆をしずめると、城は織田方のものになりました。","そして1584年。越中の佐々成政と、加賀の前田利家がにらみ合います。松根城は佐々方の前線として、大きく作りかえられました。発掘でおどろくべきものが見つかります。城の中を通っていた古い街道 «小原越» が、幅25mもの大きな堀切で断ち切られていたのです。«なぜ道を切ったの?» 敵が道を通って攻めこめないように、道そのものを «通行止め» にしたと考えられています。","城の西側、つまり加賀側には大きな横堀がほられていて、前田方からの攻撃にそなえたつくりです。尾根を少し下れば、前田方の切山城。二つの城は、同じ古道をはさんで、まさに «目と鼻の先» で向き合っていました。","1585年、豊臣秀吉が越中へ出陣し、成政が降伏すると、国境の緊張はとけました。松根城は役目を終え、いまは城址公園として整えられています。本丸には三角点があり、晴れた日には加賀と越中の両方を見わたせます。"],"tl":[["1183年","木曽義仲が陣を張ったと伝わる（確かではない）"],["15世紀ごろ","一向一揆の城となる"],["1550年","一揆の洲崎兵庫が城主になったとされる"],["1580年ごろ","織田方が加賀の一揆をしずめ、属城となる"],["1584年","佐々成政の前線として大改修。街道を大堀切で断つ"],["1585年","成政が秀吉に降伏し、城は役目を終える"],["2015年","切山城・小原越とともに国の史跡に指定"]],"who":[["佐々成政","越中の大名。松根城を前線として作りかえた"],["前田利家","加賀の大名。切山城などで対抗した"],["洲崎兵庫","一向一揆側の城主と伝わる"],["木曽義仲","この地に陣を張ったという伝説がある"]],"deep":["道を大堀切で断ち切った遺構は «道路を戦時封鎖した状況を示す遺構» として初めての確認例とされる。幅25mという規模は、単なる通路の切断をこえた本格的な工事。","西（加賀）側の大きな横堀は、佐々方の城であることを示す手がかり。城のつくりから «どちらの味方の城か» を読みとる、縄張り研究のよい例。","本丸には国土地理院の三等三角点 «内山» がある。標高約308m。","富山県側では «とやま城郭カード» に選ばれるなど、県境をまたいで両県から親しまれている城。","木曽義仲の布陣伝承は、近くの倶利伽羅峠の戦い（1183年）と結びついて語られるが、史料による裏づけはない。"],"look":["小原越を断ち切る大堀切","加賀側（西）の横堀","本丸跡と三角点","尾根から見る加賀・越中の眺め"],"q":["松根城の発掘で見つかった、全国初の遺構とは？","城の中を通る古道を、幅25mの堀切で断ち切った «道路の戦時封鎖» のあとです。"],"koji":[],"myth":"木曽義仲の布陣、洲崎兵庫の城主就任は伝承をふくむ。","img":["切山城","佐々成政","倶利伽羅峠の戦い"],"wp":"松根城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c2/Matsune_Castle.jpg",480,782,"松根城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:a/ae/Matsunejo-stereo.jpg",1572,1060],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:3/38/Sassa_Narimasa.JPG",408,484,"佐々成政"],["c:c/c6/Battle_of_Kurikaradani_Kassen_Zu.jpg",8498,4293,"倶利伽羅峠の戦い"]]},{"id":"17_sunagozaka","n":"砂子坂道場（蓮如ゆかりの一向宗道場）","yomi":"すなござかどうじょう","cat":"寺社","rank":"B","y":1471,"era":["muromachi"],"sh":"","ad":"金沢市砂子坂町","st":"IRいしかわ鉄道森本駅から車で約25分（公共交通では行きにくい）","la":36.5687,"lo":136.8024,"hook":"お寺なのに、背後の尾根には800mの空堀。祈りの場と «城» が一体になった一向一揆の拠点。","lead":"砂子坂道場は、金沢市の山あい、加賀と越中の境にあった浄土真宗の道場（小さな寺）です。室町時代、蓮如の布教のころに開かれたと伝わり、のちの富山県の大きなお寺のもとになりました。発掘で、道場の背後の尾根に約800mもの空堀などの守りの施設が見つかっています。","story":["室町時代の後半、加賀と越中の境の砂子坂という山里に、高坂氏という土地の有力者がいました。記録によると、その一族の高坂治郎尉は1471年、越前の吉崎にいた本願寺の蓮如のもとをたずね、«道乗» という法名と阿弥陀如来の絵像をさずかったといいます。","蓮如は、わかりやすい言葉で «南無阿弥陀仏ととなえれば救われる» と説き、北陸の農民や武士の心をつかみました。村々には «道場» とよばれる念仏の集まりの場ができていきます。砂子坂にも道場がひらかれ、蓮如の一族である蓮真がここに入ったと伝えられています。","しかし時代は戦国。加賀の守護・富樫政親は、力をつけた門徒たちを警戒し、1475年ごろに弾圧を始めました。後ろ盾を失った蓮真は、やがて越中の法林寺へうつります。これがのちの «城端別院善徳寺»（富山県南砺市）の始まりです。一方、道乗の子孫は砂子坂に残り、のちの «光徳寺» につながっていきました。","2013年から始まった発掘で、おどろくことが分かりました。道場のあとの背後の尾根、つまり今の石川県と富山県の境に、約800mにわたって空堀や土塁、切岸（人工のがけ）がつくられていたのです。«なぜお寺に堀が?» 越中側で一揆と敵対した石黒氏の攻撃にそなえた、と考えられています。祈りの場は、同時に «とりで» でもあったのです。","1590年、砂子坂の堂は雷で焼けてしまいます。そのとき、ご本尊だけが炎の中から飛び出し、ツツジの上にとまって無事だったと伝わります。今の砂子坂は静かな山里ですが、尾根の空堀は、門徒たちが生きた緊張の時代を語りかけてきます。"],"tl":[["1471年","高坂治郎尉が吉崎の蓮如から法名 «道乗» をさずかったと伝わる"],["1470年代","蓮如の一族・蓮真が砂子坂の道場に入る"],["1475年ごろ","富樫政親が真宗門徒を弾圧"],["1477年以降","蓮真が越中へうつる（のちの城端善徳寺）"],["1590年","砂子坂の堂宇が落雷で焼失"],["1595年","道乗の子孫が砂子坂を去る（のちの光徳寺）"],["2013〜2016年","金沢市などが発掘調査。尾根に約800mの空堀などを確認"]],"who":[["蓮如","本願寺8代。北陸で布教し、門徒をふやした"],["高坂治郎尉（道乗）","砂子坂の土豪。蓮如から法名をさずかったと伝わる"],["蓮真","蓮如の一族。砂子坂の道場に入り、のちに越中へ移った"],["富樫政親","加賀の守護。門徒を弾圧し、のちに一向一揆にたおされる"]],"deep":["史料としては『元和九年光徳寺縁起之記録』や『栄玄聞書』、善徳寺の寺伝などがあり、道乗が最初は越前の照護寺の門徒だったことが読みとれる。","尾根の空堀・土塁・切岸・虎口は、出土品から15世紀後半の短い期間に使われたと判明。«道場» という呼び名にも再検討の余地があるとされるほど、城に近いつくり。","空堀は使われなくなった後、«釜中越» とよばれる山道として再利用された。軍事施設が生活の道に変わった例。","善徳寺と光徳寺、富山県の二つの寺のルーツが、この石川県の山里にある。県境をまたぐ «信仰のネットワーク» が見える。","富山県の «とやま城郭カード» に選ばれており、一向一揆の軍事拠点としての評価も高まっている。"],"look":["伝善徳寺地区・伝光徳寺地区のあと","県境の尾根に続く空堀と土塁","人工的に平らにした堂のあとや池・井戸のあと","砂子坂の山里の景色"],"q":["砂子坂道場から始まり、いま富山県南砺市にある大きなお寺は？","城端別院善徳寺です。蓮真が越中へうつったことが始まりとされます。"],"koji":[],"myth":"ご本尊がツツジの上に飛んだ話は寺伝。道場の開創年は記録による伝え。","img":["蓮如","城端別院善徳寺","加賀一向一揆"],"wp":"砂子坂道場","rel":{"ev":[],"grave":[]},"ph":[["c:c/c2/Ruins_of_kotoku-ji_in_Sunakozaka%28%E7%A0%82%E5%B0%8F%E5%9D%82%E5%85%89%E5%BE%B3%E5%AF%BA%E8%B7%A1%29.jpg",4032,3024,"砂子坂道場"],["c:8/83/Sunakozaka_zentokuji%28%E7%A0%82%E5%AD%90%E5%9D%82%E5%96%84%E5%BE%B3%E5%AF%BA%E8%B7%A1%29.jpg",3024,4032],["c:e/e7/Ruins_of_tataraba_in_Sunakozaka.jpg",3024,4032],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:a/ae/Rennyo5.1.JPG",998,1257,"蓮如"],["c:6/68/Johana_zentokuji%28%E5%9F%8E%E7%AB%AF%E5%88%A5%E9%99%A2%E5%96%84%E5%BE%B3%E5%AF%BA%29.jpg",3264,2448,"城端別院善徳寺"]]},{"id":"17_tentokuin","n":"天徳院（珠姫の菩提寺）","yomi":"てんとくいん","cat":"寺社","rank":"B","y":1623,"era":["edo"],"sh":"県指定有形文化財（山門）","ad":"金沢市小立野4丁目","st":"JR金沢駅からバスで «天徳院前» 下車、歩いて約2分","la":36.5515,"lo":136.677,"hook":"3歳で江戸から金沢へ嫁いだ将軍の娘。24歳で亡くなった妻のために、前田利常がたてた寺。","lead":"天徳院は、加賀藩3代藩主・前田利常が、亡くなった正室・珠姫のために1623年にたてた曹洞宗のお寺です。珠姫は2代将軍・徳川秀忠の娘で、わずか3歳で前田家に嫁ぎました。1693年に建てられた山門は、火事でも焼け残った貴重な建物です。","story":["1601年、江戸から北陸へ、長い花嫁行列が向かいました。花嫁は、徳川秀忠の娘・珠姫。まだ3歳でした。相手は前田利家の子で、のちの加賀藩3代藩主・前田利常。関ヶ原の戦いの翌年、徳川と前田を結ぶための結婚でした。","«3歳の花嫁なんて?» 戦国から江戸へうつる時代、大名家どうしの結婚は «同盟のあかし» でした。けれど珠姫と利常は、大きくなってから仲むつまじい夫婦になったと伝わります。二人の間にはたくさんの子どもが生まれ、長男の光高は4代藩主になりました。","1622年、珠姫は24歳の若さで亡くなります。悲しんだ利常は翌1623年、珠姫の菩提をとむらうため、このお寺をたてました。寺の名前 «天徳院» は、珠姫のおくりな（亡くなった後の名前）からとられています。のちに息子の光高や、9代藩主・重靖もここに葬られました。","1768年、大きな火事で本堂などが焼けてしまいます。けれど1693年に5代藩主・綱紀が建てさせた山門だけは焼け残りました。瑞龍寺（高岡市）を手がけた名工の流れをくむ大工が建てた、どっしりとした二重の門で、石川県の文化財になっています。«なぜ門だけ残ったの?» 寺では、珠姫が守ってくれたのだ、と語られることもあります。","境内では、珠姫の生涯を人形で演じる «からくり人形劇» を見ることができます。庭園では5月に «なんじゃもんじゃ» の白い花がさきます。毎年8月には珠姫をしのぶ法要も開かれています。江戸と金沢、二つの家を結んだ少女の物語が、今も語りつがれているのです。"],"tl":[["1601年","3歳の珠姫が前田利常に嫁ぐ"],["1622年","珠姫が24歳で亡くなる"],["1623年","前田利常が珠姫の菩提寺として天徳院を創建"],["1624年","巨山泉滴を開山にまねく"],["1693年","5代綱紀が伽藍を改築。山門が建つ"],["1768年","火災で山門以外の主な建物を焼失"],["1769年","本堂などが再建される"],["1923年","関東大震災から逃れた室生犀星が滞在"]],"who":[["珠姫","徳川秀忠の娘。前田利常の正室。天徳院の名のもと"],["前田利常","加賀藩3代藩主。珠姫のために天徳院をたてた"],["前田光高","珠姫の長男。4代藩主。天徳院に葬られた"],["前田綱紀","5代藩主。伽藍を改築させ、今の山門を残した"],["室生犀星","金沢出身の詩人。関東大震災のあと一時滞在した"]],"deep":["山門は入母屋造・本瓦葺の三間一戸二重門。禅宗様と和様をあわせた様式で、創建期の建物として唯一残る。当初は鉛瓦だったが、財政難で普通の瓦にかえられたといわれる。","梵鐘は、もとは1823年に竹沢御殿（今の兼六園の場所）の «時の鐘» としてつくられたもの。12代藩主・斉広の夢にあらわれて «天徳院へ行きたい» と告げたと伝わり、«霊鐘» とよばれる。","1689年には明の僧・高泉性潡のもとで黄檗式の建物に整えられたこともあり、扁額に彼の字が残る。","珠姫の死については、乳母が夫婦の仲をさまたげたなどの話が伝わるが、史実として確かめられたものではない。","天徳院のある小立野台地には、加賀藩ゆかりの寺が多い。前田家と徳川家の結びつきを示す寺として、金沢の寺院史の中でも特別な位置にある。"],"look":["県指定文化財の山門（仁王像）","珠姫のからくり人形劇（有料・時間を確認）","枯山水の庭 «黙照禅庭» となんじゃもんじゃの木","霊鐘（梵鐘）"],"q":["珠姫が前田家に嫁いだのは何歳のとき？","3歳です。1601年、徳川と前田を結ぶ結婚でした。"],"koji":[],"myth":"山門が焼け残った理由、乳母の話、霊鐘の夢の話は伝承。","img":["珠姫","前田利常","前田光高"],"wp":"天徳院 (金沢市)","rel":{"ev":[],"grave":[]},"ph":[["c:a/a9/Tentokuin%2C_in_Kanazawa_1.jpg",3264,2448,"天徳院 (金沢市)"],["c:8/8e/%E9%AD%9A%E9%BC%93%EF%BC%88%E5%A4%A9%E5%BE%B3%E9%99%A2%EF%BC%89.jpg",4032,3024],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:d/d4/%E3%81%8A%E3%81%A8%E3%82%8A%E7%9F%B3%EF%BC%A0%E5%A4%A9%E5%BE%B3%E9%99%A2.jpg",640,480],["c:b/b9/Maeda_Toshitsune.png",1294,1725,"前田利常"]]},{"id":"17_dai9shidan","n":"旧陸軍第九師団司令部庁舎","yomi":"きゅうりくぐんだいくしだんしれいぶちょうしゃ","cat":"近代","rank":"B","y":1898,"era":["meiji","taisho","showa"],"sh":"国の登録有形文化財","ad":"金沢市出羽町（国立工芸館）","st":"JR金沢駅からバスで «出羽町» 下車、歩いて約5分","la":36.5592,"lo":136.6618,"hook":"«軍都・金沢» の司令塔だった洋館が、いまは工芸の美術館。赤と白のレトロな建物に、二つの時代が重なる。","lead":"旧陸軍第九師団司令部庁舎は、1898年に金沢にできた陸軍・第九師団の司令部の建物です。北陸3県の兵士でつくられた師団で、日露戦争などにも出征しました。建物は戦後いくどか使い道を変え、2020年からは «国立工芸館» の建物として生かされています。","story":["日清戦争のあと、日本は軍をふやすために新しい師団をつくりました。その一つが1898年（明治31年）に金沢にできた第九師団です。富山・石川・福井の若者たちが兵士となり、金沢城の中などに司令部や兵舎が置かれました。こうして金沢は «軍都» とよばれるようになります。","司令部庁舎は、師団の «頭脳» ともいえる建物でした。左右対称の2階建ての洋館で、ここで作戦や命令が考えられました。1904年、日露戦争が始まると、第九師団は乃木希典の第三軍の一部として旅順の攻撃に加わります。旅順ではとても激しい戦いになり、多くの兵士が亡くなりました。","その後も第九師団は、上海や南京など中国大陸の戦場に送られました。太平洋戦争の終わりには、沖縄を守る中心の部隊として期待されていましたが、1944年の末に台湾へ移るよう命じられ、アメリカ軍が沖縄に上陸したとき、そこにはいませんでした。«なぜ移したのか» ―― 当時の作戦の担当者は、のちに大きな後悔を語ったと伝えられます。","戦争が終わると、師団はなくなりました。建物は取りこわされずに残り、戦後は県の施設などとして使われていきます。そして2020年、東京にあった国立近代美術館の工芸館が金沢へうつってくるとき、この庁舎ととなりの旧偕行社（将校の社交場）が移築・修復され、美術館の建物として生まれ変わりました。","かつて兵士の命令が出されていた部屋で、いまは陶磁器や漆、ガラスの美しい作品が展示されています。建物の色も、昔の姿を調べて復元されました。戦争の記憶と、工芸の町・金沢の今が、一つの建物の中で出会っています。"],"tl":[["1898年","第九師団が金沢で編成。司令部が開庁"],["1904〜1905年","日露戦争。旅順攻囲戦・奉天会戦に参加"],["1932年","第一次上海事変に出動"],["1937年","日中戦争。上海・南京の戦いに参加"],["1944年","沖縄の第32軍に入るが、年末に台湾へ移る"],["1945年","台湾で終戦をむかえる"],["2020年","旧偕行社とともに移築・修復され、国立工芸館として開館"]],"who":[["大島久直","初代の第九師団長。日露戦争で師団をひきいた"],["乃木希典","第三軍司令官。旅順攻囲戦で第九師団を指揮下に置いた"],["渡辺錠太郎","第九師団の中隊長として旅順で負傷。のちに二・二六事件で亡くなる"],["樋口季一郎","1939〜1942年の師団長"]],"deep":["第九師団は日清戦争後に新設された6個師団の一つ。久留米の第18師団と並んで «精鋭» といわれた。","旅順攻囲戦では、師団に属する歩兵連隊長が全員負傷するほどの激戦だったとされる。","1944年11月、第32軍から1個師団を他の戦場へ回すことになり、第九師団が台湾へ移された。大本営の作戦課長だった服部卓四郎は、のちにこれを «一世一代の不覚» と振り返ったと伝えられる。","国立工芸館は日本海側で初めての国立美術館。司令部庁舎と旧金沢偕行社の2棟を移築して再利用し、展示室部分は新築。","旧金沢偕行社は1909年の建物で、将校のための社交・研修の場。司令部と並んで、軍都の «表の顔» だった。"],"look":["司令部庁舎の左右対称の外観と復元された外壁の色","となりの旧金沢偕行社","館内に残る階段や天井の意匠","周辺の本多の森公園・石川県立美術館・兼六園"],"q":["太平洋戦争の終わり、第九師団は沖縄からどこへ移された？","台湾です。そのため沖縄戦には参加せず、台湾で終戦をむかえました。"],"koji":[],"myth":"建物が戦後どこでどう使われたか、移築の経緯の細部は現地の解説で確認を。","img":["国立工芸館","旅順攻囲戦"],"wp":"第9師団 (日本軍)","rel":{"ev":[],"grave":[]},"ph":[["c:d/db/Ishikawa-ken_History_Museum03s3s4272b.jpg",4272,2848,"第9師団 (日本軍)"],["c:0/00/National_Crafts_Museum_in_Kanazawa_20201116-001.jpg",4867,3245,"国立工芸館"],["c:c/ce/203_Meter_Hill.jpg",1600,1109,"旅順攻囲戦"]]},{"id":"17_suzuyaki","n":"珠洲焼の窯跡","yomi":"すずやきのかまあと","cat":"産業","rank":"B","y":1200,"era":["heian","kamakura","muromachi"],"sh":"","ad":"珠洲市蛸島町（珠洲焼資料館）ほか市内各地","st":"のと里山空港から車で約1時間。金沢駅から珠洲行きの特急バスで約3時間","la":37.4509,"lo":137.2972,"hook":"釉薬をかけないのに、黒くしっとり光る。400年つくられて、ある日こつぜんと消えた «幻のやきもの»。","lead":"珠洲焼は、平安時代の終わり（12世紀後半）から室町時代の終わり（15世紀末）ごろまで、珠洲市のあたりで焼かれた焼き物です。古墳時代からの須恵器の技術を受けつぎ、灰黒色のかたい焼き物で、日本海ぞいの広い地域へ運ばれました。いったん途絶えましたが、1976年に復活しました。","story":["能登半島の先、珠洲の山の斜面には、昔の窯のあとがねむっています。穴を掘ったトンネルのような窯で、平安時代の終わりから、たくさんの壺やかめ、すり鉢が焼かれました。これが珠洲焼です。","珠洲焼のとくちょうは、灰色から黒のしっとりした色。釉薬（うわぐすり）をかけず、窯の最後に空気を止めて «いぶす» ように焼くことで、この色が生まれます。古墳時代から続く «須恵器» の焼き方を受けついだものです。表面には、たたいて形を整えたときの細かな模様が残っています。","«なぜ能登の先っぽで?» 珠洲には焼き物に向いた土と、燃料になる森、そして日本海の船の道がありました。珠洲焼は船にのせられ、北陸から東北、北海道の南のほうまで、日本海ぞいの広い地域へ運ばれました。中世の日本海は、焼き物が行き来する «海の道» だったのです。","ところが15世紀の終わりごろ、珠洲焼はこつぜんと姿を消します。理由ははっきりしていません。ほかの産地の焼き物に押されたとも、社会の変化で窯をささえる仕組みがくずれたともいわれます。それから約400年、珠洲焼は «幻の焼き物» になりました。","1976年、珠洲市は珠洲焼を復活させます。昔のかけらを調べ、同じような土と焼き方で、現代の陶工たちが作品を生み出してきました。2024年の能登半島地震では、多くの窯や工房が大きな被害を受けましたが、作り手たちは再び火を入れようと取り組んでいます。資料館で中世の珠洲焼と向き合うと、千年近く前の職人の手のあとが見えてきます。"],"tl":[["12世紀後半","珠洲焼の生産が始まる"],["13〜14世紀","最盛期。日本海ぞいの広い地域に運ばれる"],["15世紀末ごろ","生産が途絶える"],["1976年","珠洲市が珠洲焼を復興"],["1989年","石川県指定伝統的工芸品になる"],["2024年","能登半島地震で窯や工房が大きな被害を受ける"]],"who":[["中世の珠洲の陶工たち","名前は伝わらないが、窯を築き、焼き物を送り出した"],["現代の珠洲焼作家","1976年の復興以後、技術を再現し新しい作品をつくってきた"],["珠洲市","珠洲焼を復興し、資料館や陶芸センターを運営してきた"]],"deep":["珠洲焼は «還元焔焼成»（酸素を少なくして焼く）で黒灰色に仕上がる。これは須恵器と同じ系統の技術で、中世の «六古窯»（瀬戸・常滑など）とは別の流れにある。","主な器種は甕・壺・すり鉢。貯蔵用の大きなかめは、港町や城館の遺跡から多く出土している。","分布は日本海側に偏り、北は北海道南部まで及ぶとされる。中世の日本海交易の広がりを示す重要な指標になっている。","窯は丘の斜面を掘りこんだ «窖窯（あながま）»。窯のあとからは失敗品のかけら（物原）が大量に見つかり、生産の規模が分かる。","突然の衰退の理由は諸説あり、越前焼など他産地との競合、生産をささえた荘園・寺社の仕組みの変化などが挙げられている。"],"look":["珠洲市立珠洲焼資料館の中世の珠洲焼","表面のたたき目の模様と、灰黒色の肌","珠洲焼館で現代の作品","市内の窯跡の案内（見学は資料館で確認）"],"q":["珠洲焼が灰色や黒っぽい色になるのは、どんな焼き方をするから？","釉薬をかけず、窯の空気を止めていぶすように焼く «還元焔焼成» だからです。"],"koji":[],"myth":"消えた理由は諸説。窯跡の文化財指定の範囲は資料館で確認を。","img":["須恵器","珠洲市"],"wp":"珠洲焼","rel":{"ev":[],"grave":[]},"ph":[["c:7/71/Large_jar%2C_Suzu_ware%2C_Heian_period%2C_12th_century%2C_excavated_from_Sekiyama-jinja_sutra_mound%2C_Myoko-shi%2C_Niigata_-_Tokyo_National_Museum_-_DSC05240.JPG",3423,3680,"珠洲焼"],["c:5/5a/Suzu_Ware_Shop_2014-10.jpg",4608,3456],["c:4/40/Suzu_Ware_Museum_2014-10.jpg",4608,3456],["c:9/98/Jar%2C_Suzu_ware%2C_Kamakura_period%2C_1200s-1300s_AD%2C_ceramic_-_Hakone_Museum_of_Art_-_Hakone%2C_Kanagawa%2C_Japan_-_DSC08227.jpg",3588,4385],["c:3/3d/Suzuyaki_Kiln_at_Shoin.jpg",3264,2448],["c:4/47/131123_Hyogo_Prefectural_Museum_of_Archaeology_Japan24s5.jpg",4912,3264,"須恵器"],["c:d/d4/Mitsukejima_%28Ishikawa%29_4.jpg",2894,1632,"珠洲市"]]},{"id":"17_tohaku","n":"長谷川等伯ゆかりの七尾（本延寺）","yomi":"はせがわとうはくゆかりのななお（ほんねんじ）","cat":"学び","rank":"B","y":1564,"era":["muromachi","azuchi"],"sh":"","ad":"七尾市小島町（山の寺寺院群）","st":"JR・のと鉄道七尾駅から歩いて約20分","la":37.0497,"lo":136.9525,"hook":"国宝『松林図屏風』をえがいた天才絵師は、能登・七尾の染物屋で育った。若き日の作品が、今もふるさとの寺にある。","lead":"長谷川等伯は、安土桃山時代を代表する絵師で、国宝『松林図屏風』で知られます。1539年に七尾で生まれ、30歳ごろまで七尾で仏画などをえがいていました。本延寺は等伯の生家・奥村家の菩提寺で、等伯が26歳のときに色をぬった日蓮聖人の像が残っています。","story":["1539年、能登の七尾で一人の男の子が生まれました。父は能登の戦国大名・畠山氏に仕える武士、奥村家。男の子はやがて、染物屋を営む長谷川家の養子になります。養父は絵もかく人でした。これがのちの長谷川等伯。若いころは «信春» と名のっていました。","当時の七尾は、畠山氏のもとで都の公家や文化人が集まる «小さな京都» のような町でした。信春は、熱心な日蓮宗の信者だった養家の縁で、仏画や肖像画をえがき始めます。1564年、26歳のとき、生家の菩提寺・本延寺の «日蓮聖人坐像» に色をぬって寄進しました。«なぜ地方の若者が、こんなに上手なの?» と、研究者もおどろくほどの出来ばえです。","1571年ごろ、養父母を亡くした信春は、妻と息子の久蔵をつれて京都へ向かいます。たよったのは本延寺の本山、本法寺でした。京では狩野派の画風を学び、千利休らと知りあい、中国の名画にもふれて、少しずつ自分の画風をつくっていきます。","やがて «等伯» と名のった彼は、豊臣秀吉にもみとめられ、当時いちばんの画家集団・狩野派と肩を並べるようになります。しかし跡つぎと期待した息子の久蔵を若くして亡くしました。その悲しみのあとにえがかれたといわれるのが、霧の中に松林がうかぶ『松林図屏風』です。","晩年、等伯は自分を «雪舟五代» と名のり、1610年、旅先の江戸で亡くなりました。七尾の町には等伯の像が立ち、本延寺をふくむ «山の寺寺院群» には、若き日の等伯の気配が残っています。天才の原点は、この能登の港町にあったのです。"],"tl":[["1464年","日親が本延寺を開いたと伝わる"],["1539年","等伯、七尾に生まれる"],["1564年","26歳で本延寺の日蓮聖人坐像に彩色し寄進"],["1571年ごろ","妻子をつれて京都へ。本法寺をたよる"],["1591年","祥雲寺（現・智積院）の障壁画を手がける"],["1593年","息子・久蔵が亡くなる"],["1593〜1595年ごろ","『松林図屏風』がえがかれたとされる"],["1610年","江戸で亡くなる"]],"who":[["長谷川等伯","七尾出身の絵師。『松林図屏風』（国宝）の作者"],["長谷川久蔵","等伯の長男。才能をみとめられたが若くして亡くなる"],["長谷川宗清","等伯の養父。染物屋を営み、仏画もえがいた"],["日親","本延寺を開いたと伝わる日蓮宗の僧"],["千利休","茶人。京での等伯の後ろ盾の一人"]],"deep":["本延寺の «日蓮聖人坐像» は、像そのものは別の作者で、等伯（信春）は彩色を担当した。永禄7年（1564年）の銘があり、七尾時代の等伯の確かな仕事として重要。","七尾時代の信春の作品は、能登を中心に石川・富山で十数点が確認されている。都でもめったに見られない上質な顔料が使われていると指摘される。","画論『等伯画説』は、等伯の話を日通（本法寺の僧）が書きとめたもの。等伯の画系や考え方を知る一級の史料。","«雪舟五代» は、雪舟−等春−法淳（養祖父）−道浄（養父）−等伯という系譜を名のったもの。自分の家系を雪舟につなげる、巧みな «ブランド戦略» ともいわれる。","本延寺を開いた日親は、きびしい布教で «なべかむり日親»（焼けた鍋をかぶせられた伝説）の名で知られる。"],"look":["本延寺（日蓮聖人坐像は七尾市指定文化財。拝観は事前に確認）","七尾駅前の長谷川等伯像","山の寺寺院群の寺町の散歩道","石川県七尾美術館の等伯関係の展示（企画展時）"],"q":["長谷川等伯が若いころ名のっていた名前は？","«信春（のぶはる）» です。京都へ出て活やくするようになってから «等伯» と名のりました。"],"koji":[{"w":"雪舟五代","m":"等伯が自分を名画家・雪舟から5代目にあたると名のった言葉"}],"myth":"«なべかむり» は日親の伝説。等伯が本延寺をどこまで身近にしていたかは推測をふくむ。","img":["松林図屏風","本延寺 (七尾市)"],"wp":"長谷川等伯","rel":{"ev":[],"grave":[]},"ph":[["c:3/36/Sen_no_Rikyu_JPN.jpg",3723,8379],["c:a/ab/Koboku_Enk%C5%8D-zu_right_part_1.jpg",4949,6695],["c:c/c4/Koboku_Enk%C5%8D-zu_left_part.jpg",4927,6699],["c:2/23/Hasegawa_Tohaku_-_Pine_Trees_%28Sh%C5%8Drin-zu_by%C5%8Dbu%29_-_right_hand_screen.jpg",16723,7828],["c:3/32/Hasegawa_Tohaku_-_Pine_Trees_%28Sh%C5%8Drin-zu_by%C5%8Dbu%29_-_left_hand_screen.jpg",16729,7817],["c:a/ae/Tohaku_Hasegawa_-_Crows_and_Herons_%28Important_Cultural_Property%29_-_Google_Art_Project.jpg",6646,1433],["c:b/b9/Inaba_Yoshimichi.jpg",1423,2450],["c:9/9a/Zennyo_Ryuo_-_Hasegawa_Touhaku.jpg",934,1734]]},{"id":"17_agehama","n":"揚げ浜式製塩","yomi":"あげはましきせいえん","cat":"産業","rank":"B","y":1700,"era":["edo","showa"],"sh":"国の重要無形民俗文化財（能登の揚浜式製塩の技術）","ad":"珠洲市清水町（道の駅すず塩田村）ほか","st":"のと里山空港から車で約1時間（公共交通では行きにくい）","la":37.4863,"lo":137.1138,"hook":"海水を桶でくみ、砂の上に «さぁっ» とまく。江戸時代と同じ手作業の塩づくりが、能登の海辺に生き残った。","lead":"揚げ浜式製塩は、海水を人の手で浜へ運び、砂にまいて太陽と風でかわかし、塩のこい水をつくって煮つめる塩づくりの方法です。能登では江戸時代にさかんで、全国でほとんど消えた今も珠洲の海辺で続けられています。技術は国の重要無形民俗文化財です。","story":["夏の朝、珠洲の海辺。浜士（はまじ）とよばれる人が、肩に二つの桶をかついで海へ下り、海水をくんで塩田へ運びます。平らにならした砂の上に、桶から海水を大きな弧をえがくようにまく ―― «潮まき» です。熟練の人がまくと、霧のように細かい水が、砂の上にむらなく広がります。","砂は太陽と風でかわき、表面に塩の結晶がつきます。それをかき集めて、木の箱にいれ、上から海水をかけてこすと、海水よりずっとこい «かん水» ができます。これを釜屋の大きな釜で、長い時間かけて煮つめると、ようやく白い塩があらわれるのです。«なぜ、こんなに手間をかけるの?» 能登の海辺は潮の満ち干の差が小さく、瀬戸内のように潮を自然に引きこむ «入浜式» ができなかったからです。","江戸時代、加賀藩は能登の塩づくりをとても大切にしました。藩が塩をつくる人に米を先に貸し、できた塩で返させる «塩手米» という仕組みがあったといわれます。塩は藩の大事な財源でした。能登の海岸には、たくさんの塩田が並んでいました。","けれど明治になると塩は国の専売になり、昭和には機械で塩をつくる時代が来ます。国が塩田の整理を進めたとき、能登の揚げ浜の塩田もほとんどが姿を消しました。そんな中で、珠洲の角花家は昔ながらの揚げ浜を続けたと伝わります。«親から受けついだ技を、ここで絶やしたくない» ―― その思いが、この技術を今につないだのです。","いまでは珠洲の «道の駅すず塩田村» などで、揚げ浜の作業を見たり、体験したりすることができます。2024年の能登半島地震では塩田や釜屋も被害を受けましたが、塩づくりの人たちは再開に向けて動いています。一つまみの塩に、何百年分もの海辺の暮らしがつまっています。"],"tl":[["古代","土器で海水を煮つめる塩づくりが各地で行われる"],["江戸時代","能登の海岸で揚げ浜式製塩がさかんに。加賀藩が生産をささえる"],["1905年","塩が国の専売になる"],["昭和30年代","塩田の整理が進み、能登の揚げ浜の多くがなくなる"],["2008年","«能登の揚浜式製塩の技術» が国の重要無形民俗文化財に"],["2024年","能登半島地震で塩田や施設が被害を受ける"]],"who":[["浜士（はまじ）","塩田で働く人。海水運びや潮まきをになう"],["角花家","昔ながらの揚げ浜を続け、技術を守ってきた珠洲の家と伝わる"],["加賀藩","江戸時代、能登の塩づくりを財源としてささえた"]],"deep":["揚浜式は、海水を人力で塩田にくみ上げる方式。潮の干満を利用して海水を引きこむ «入浜式» が広まったあとも、干満差の小さい能登では揚浜式が残った。","塩田の砂の下には粘土などで水がしみこまない層をつくる。砂は «塩砂» とよばれ、細かい粒のものが使われる。","1塩戸の塩田の広さは、江戸時代の揚浜で平均1反（約990㎡）前後だったとされる。入浜式ではずっと大きくなった。","«塩手米» は、藩が米を前貸しして塩で回収する制度とされ、加賀藩の塩の専売的な仕組みとして知られる。","日本で塩の専売が始まったのは1905年（日露戦争の戦費のため）。1997年に専売制は廃止された。"],"look":["潮まきの作業（実演の時期は夏が中心。事前に確認）","塩田の砂と、かん水をこす木の箱","釜屋で煮つめるようす","道の駅すず塩田村の資料館"],"q":["揚げ浜式製塩で、砂の上に海水をまく作業を何という？","«潮まき（しおまき）» です。熟練の浜士は、海水を霧のように細かくまきます。"],"koji":[],"myth":"«角花家だけが残った» という経緯や塩手米の細部は伝えによる。","img":["塩田","珠洲市","道の駅すず塩田村"],"wp":"揚浜式製塩","rel":{"ev":[],"grave":[]},"ph":[["c:9/93/Marakkanam_Salt_Pans.JPG",4055,2693,"塩田"],["c:d/d4/Mitsukejima_%28Ishikawa%29_4.jpg",2894,1632,"珠洲市"],["c:e/e4/Michinoeki_SuzuEnden.JPG",3648,2052,"道の駅すず塩田村"]]},{"id":"17_hegura","n":"舳倉島（海女の島）","yomi":"へぐらじま","cat":"島","rank":"B","y":1649,"era":["jomon","nara","edo"],"sh":"","ad":"輪島市海士町（舳倉島）","st":"輪島港から定期船で約1時間25分（運航の状況は事前に確認）","la":37.8514,"lo":136.9186,"hook":"能登半島の北48km。夏になると海女たちが海をわたってきて、島が «もう一つの町» になった。","lead":"舳倉島は、能登半島の北約48kmの日本海にうかぶ、周囲約5kmの小さな島です。輪島の海女の漁場として知られ、昔は夏のあいだだけ本土から人がうつり住みました。縄文時代から人が来ていた跡があり、渡り鳥の中継地としても有名です。","story":["輪島の港から船で北へ1時間半。水平線の上に、平たい島があらわれます。舳倉島です。いちばん高いところでも12mほど。木も少なく、まるで海にうかぶ板のような島です。それでもこの島には、縄文時代の終わりごろから人が来ていた跡があり、古くから日本海の船の目印だったと考えられています。","島の海女のルーツには、おもしろい話が伝わります。戦国時代、九州の筑前・鐘ヶ崎の漁師たちが能登に流れつき、北へ移りながら漁をしたというのです。1617年に輪島に住むことをゆるされ、1649年には加賀藩から今の輪島市海士町の土地をもらったといわれます。«なぜ九州から?» 海に生きる人びとは、よい漁場を求めて海の道を旅していたのです。","海女たちは、アワビやサザエ、ワカメをとるために素もぐりをします。昔は漁の季節の夏になると、海士町の家族ごと島へわたり、秋になると本土へ帰りました。島が «夏だけの町» になるのです。昭和30年代までは、一年じゅう住む人はほとんどいなかったといわれます。","島の南には、延喜式にものる古い神社 «奥津比咩神社» があります。近くの遺跡からは5世紀や8〜9世紀の品が見つかり、遠い昔から海の神をまつってきたことが分かります。また島は、大陸と日本を行き来する渡り鳥の休み場所。360種類以上の野鳥が記録され、バードウォッチャーのあこがれの島でもあります。","2024年1月1日の能登半島地震では、島の港も大きな被害を受け、定期船は長いあいだ止まりました。島に残っていた人たちは孤立し、約2週間後にヘリコプターで島を出ました。2025年にようやく船が動き始め、島は少しずつ日常を取りもどそうとしています。"],"tl":[["縄文時代晩期","人が活動していた跡がある"],["5世紀・8〜9世紀","シラスナ遺跡に祭祀などの跡"],["戦国時代","筑前・鐘ヶ崎の漁民が能登に来たと伝わる"],["1617年","漁民が輪島に住むことをゆるされる"],["1649年","加賀藩から海士町の土地をもらう"],["1931年","舳倉島灯台が点灯"],["2024年","能登半島地震。定期船が長く止まる"],["2025年","定期船が段階的に運航を再開"]],"who":[["輪島の海女たち","素もぐりでアワビやサザエをとる。島と本土を行き来してきた"],["筑前・鐘ヶ崎の漁民","海女の祖先と伝わる九州の漁師たち"],["瀬川清子","民俗学者。輪島・舳倉島の海女の暮らしを記録した"]],"deep":["面積は約0.55㎢、周囲約5km、最高地点は約12.4m。島の北の小さな岩礁（小瀬・大黒瀬）は、日本の排他的経済水域の基点になっている。","2000万年ほど前の火山活動でできた島で、西の海の中に火口のあとがある。最終氷期（約2万年前）には能登半島と陸続きだったとされる。","«輪島の海女漁の技術» は国の重要無形民俗文化財。本土から通う «通い海女» と、島に住む «定住海女» がいる。","島が本土側の «海士町» の一部になっているのは、海女の町の人びとが季節ごとに島へ移り住んだ歴史による。郵便番号も同じ。","石川県で見られる野鳥の約8割が観察できるといわれ、春と秋の渡りの季節には全国から愛鳥家が訪れる。"],"look":["奥津比咩神社","舳倉島灯台と島の平たい地形","港から見る海女漁のようす（漁のじゃまをしない）","渡り鳥の季節の野鳥観察"],"q":["輪島の海女の祖先と伝わる漁民は、どこから来た？","九州の筑前・鐘ヶ崎（今の福岡県）から来たと伝わります。"],"koji":[],"myth":"筑前鐘ヶ崎からの来住の話は伝承。定期船の運航状況は変わる。","img":["海女","輪島市","七ツ島"],"wp":"舳倉島","rel":{"ev":[],"grave":[]},"ph":[["c:d/de/Hegura_20091001.jpg",1839,1496,"舳倉島"],["c:4/46/Ferry_nozomi.jpg",3648,2736],["c:a/aa/Amamachi%2C_Wajima%2C_Ishikawa_Prefecture_928-0072%2C_Japan_-_panoramio_%2899%29.jpg",2048,1365],["c:4/4d/Amamachi%2C_Wajima%2C_Ishikawa_Prefecture_928-0072%2C_Japan_-_panoramio_%2898%29.jpg",2048,1365],["c:1/19/Amamachi%2C_Wajima%2C_Ishikawa_Prefecture_928-0072%2C_Japan_-_panoramio_%2893%29.jpg",2048,1365],["c:b/b7/Amamachi%2C_Wajima%2C_Ishikawa_Prefecture_928-0072%2C_Japan_-_panoramio_%2886%29.jpg",2048,1365],["c:f/f9/Amamachi%2C_Wajima%2C_Ishikawa_Prefecture_928-0072%2C_Japan_-_panoramio_%2876%29.jpg",2048,1365],["c:4/46/Amamachi%2C_Wajima%2C_Ishikawa_Prefecture_928-0072%2C_Japan_-_panoramio_%2854%29.jpg",2048,1365]]},{"id":"17_mitsukejima","n":"見附島（弘法大師伝説）","yomi":"みつけじま","cat":"島","rank":"B","y":2024,"era":["heian","reiwa"],"sh":"県指定天然記念物","ad":"珠洲市宝立町鵜飼","st":"のと里山空港から車で約40分。バスは «見附島口» 下車、歩いて約5分","la":37.3962,"lo":137.2473,"hook":"弘法大師が «最初に見つけた島»。軍艦の形で親しまれた能登のシンボルは、地震で大きく姿を変えた。","lead":"見附島は、珠洲市の海岸から200〜300m沖にうかぶ無人島です。高さ約28m、船のような形から «軍艦島» ともよばれ、能登のシンボルでした。弘法大師（空海）が佐渡から渡ってきたとき最初に見つけた島だ、という伝説が名前の由来です。2024年の地震で大きくくずれました。","story":["珠洲の鵜飼の海岸に立つと、沖に切り立ったがけの島が見えます。長さ約160m、高さ約28m。まっすぐ切り落としたような側面と、とがった先。まるで海を進む軍艦のようで、«軍艦島» の名前で親しまれてきました。島のてっぺんには木がしげり、小さな神社がまつられています。","名前の由来は、弘法大師の伝説です。平安時代、大師が佐渡から能登へ海を渡ってきたとき、最初に «見つけた» 島だから見附島 ―― そう伝えられています。また、この地に降りた神さまが最初に見つけた島だ、という話もあります。«なぜ、有名なお坊さんの話が?» 目立つ島や岩には、昔の人が特別な意味を感じ、物語を重ねてきたのです。","島は、珪藻泥岩という、やわらかい岩でできています。波や風にけずられやすく、少しずつ姿を変えてきました。すぐ近くには «小島» とよばれる岩があり、見附島と二つで信仰されてきましたが、けずられて小さくなり、2019年の台風の高波で消えてしまいました。","2020年ごろから能登では地震が続き、見附島も何度も崩れました。そして2024年1月1日の能登半島地震。島の南東側が大きく崩れ、軍艦のようだった形は失われてしまいました。その後、島の木々も枯れが目立つようになっています。","干潮のときには、海岸から島の近くまで飛び石が現れることがありました。いまは崩れる危険があるため、近づくことはできません。浜から見えるいまの姿は、長い年月と大きな地震の記録そのもの。地震で被害を受けた能登の人びとにとって、変わってしまった島は、それでも «ふるさとの目印» であり続けています。"],"tl":[["平安時代","弘法大師が最初に見つけた島という伝説"],["1993年","能登半島沖地震で東側の一部が崩れる"],["2019年","台風の高波で «小島» が消える"],["2022年","地震で一部が崩れる"],["2023年","最大震度6強の地震で一部が崩れる"],["2024年1月1日","能登半島地震で南東側が大きく崩れ、軍艦の形が失われる"]],"who":[["空海（弘法大師）","平安時代の僧。島を最初に見つけたと伝わる"],["加志波良比古神","この地に降りて島を見つけたと伝わる神"],["中島盛夫","銭湯絵師。見附島の景色を各地の銭湯に描いた"]],"deep":["地震前の島の大きさは、全長約158.5m、最大幅約45.3m、高さ約28.8m。2023年にはドローンによるレーザー計測で、頂部が平らな形であることが確かめられた。","島をつくる珪藻泥岩は、植物プランクトン（珪藻）の殻が積もってできた岩で、やわらかくくずれやすい。能登半島北東部に広く分布する。","«小島» は昔は高さ・幅とも約10mあったとされ、しだいにけずられて2mほどになり、2019年に消えた。","見附島へ続く海岸は «えんむすびーち» ともよばれ、近くの恋路海岸と合わせて縁結びの名所として親しまれてきた。","銭湯のペンキ絵で見附島をよく描いた絵師がいて、能登から遠い町の湯船でもこの島を見ることができた。"],"look":["海岸から見る現在の島の姿（島には近づかない）","崩れた断面にあらわれた珪藻泥岩の地層","海岸の見附公園","近くの恋路海岸"],"q":["見附島が «軍艦島» ともよばれていたのはなぜ？","島の形が、海を進む軍艦のように見えたからです。2024年の地震で大きく崩れ、その形は失われました。"],"koji":[],"myth":"弘法大師が見つけたという話は伝説。","img":["見附島 (石川県)","空海","令和6年能登半島地震"],"wp":"見附島","rel":{"ev":[],"grave":[]},"ph":[["c:9/95/Mitsukejima_%28Ishikawa%29_1.jpg",4608,3456,"見附島 (石川県)"],["c:9/98/Kobo_Daishi_%28Taisanji_Matsuyama%29.jpg",260,270,"空海"],["c:5/5c/Air_Self-Defense_Force_drone_search_operation_at_Wajima_Asaichi.jpg",855,560,"令和6年能登半島地震"]]},{"id":"17_suzu_jinja","n":"須須神社（義経の蝉折の笛）","yomi":"すずじんじゃ","cat":"寺社","rank":"B","y":1187,"era":["nara","heian","kamakura"],"sh":"国の重要文化財（木造男神坐像）","ad":"珠洲市三崎町寺家","st":"珠洲市内から «すずバス» で «須須神社前» 下車。車なら穴水ICから約1時間","la":37.503,"lo":137.318,"hook":"奥州へ逃げる義経が、嵐の海で命をあずけた神社。お礼に納めたという笛が、今も伝わる。","lead":"須須神社は、能登半島の先たん近くにある古い神社で、平安時代の『延喜式』にも名前がのっています。奥州へ落ちのびる源義経が、嵐をさけてこの地にたちより、«蝉折の笛» を納めたと伝わります。重要文化財の神像や、深い森（社叢）でも知られます。","story":["能登半島のいちばん先、禄剛崎に近い寺家の集落。こんもりした森の中に、須須神社の社殿があります。社伝では、はるか昔の崇神天皇のころにまつられたとされ、奈良時代に今の場所へ移ったといわれます。«珠洲» という地名とも、深いつながりがあると考えられています。","1187年ごろ。兄・源頼朝に追われた源義経は、弁慶らとともに北陸道をたどって奥州・平泉へ向かっていました。伝説によると、能登の沖で船が嵐にあい、義経はこの神社の神に無事を祈りました。嵐がおさまると、お礼に愛用の笛 «蝉折» を納めたといいます。弁慶の守り刀も奉納されたと伝わります。","«なぜ義経が能登に?» 義経の奥州への逃避行は、史料では道すじがはっきりしません。そのため北陸の各地に «義経が来た» という伝説が生まれました。須須神社の話もその一つです。けれど、海と山にかこまれた半島の先で、旅人が神に命をあずけた ―― その気持ちは、どの時代にも通じるものでしょう。","神社には、平安時代ごろの «木造男神坐像» 5体が伝わり、国の重要文化財になっています。やさしい顔、きびしい顔、それぞれの神のすがたは、能登の人びとが古くから神を身近に感じていたことを語ります。社殿のまわりの森は «社叢» として天然記念物に指定され、暖かい地方の木と寒い地方の木がまじりあっています。","2023年の奥能登地震では一の鳥居がくずれ、2024年の能登半島地震では二の鳥居がたおれ、手水舎もこわれました。それでも神社は地域の人びとに支えられ、祭りの灯をつなごうとしています。静かな森で手を合わせれば、義経の時代から続く祈りの重なりが感じられます。"],"tl":[["崇神天皇のころ","創建されたと社伝に伝わる"],["749〜756年","今の場所に移ったと伝わる"],["927年","『延喜式』神名帳に記される"],["1187年ごろ","源義経が立ち寄り、蝉折の笛を納めたと伝わる"],["2015年","«キリコ祭り» の日本遺産の構成文化財に"],["2023年","奥能登地震で一の鳥居が崩れる"],["2024年","能登半島地震で二の鳥居が倒れる"]],"who":[["源義経","奥州へ向かう途中に立ち寄り、笛を納めたと伝わる"],["武蔵坊弁慶","義経の家来。守り刀を納めたと伝わる"],["美穂須須美命","須須神社にまつられる神の一柱"]],"deep":["祭神は瓊瓊杵尊・美穂須須美命・木花咲耶姫命など。«須須» の名は、美穂須須美命や «珠洲» の地名と結びついて語られる。","『延喜式』神名帳にのる式内社。高座宮・金分宮のほか、山伏山に奥宮がある。","«蝉折» という名笛は『平家物語』にも登場する（以仁王ゆかりの笛）。須須神社に伝わる笛との関係ははっきりしない。","重要文化財の木造男神坐像5躯は、神仏習合の時代の神像彫刻として貴重。","社叢は、タブノキやスダジイなどの暖地性の木と、北方系の植物が共存する点で注目される。"],"look":["高座宮の社殿と社叢の森","宝物の «蝉折の笛» の伝説（公開の有無は確認）","重要文化財の神像（通常は非公開の場合あり）","近くの禄剛崎灯台と能登半島の先たんの海"],"q":["源義経が須須神社に納めたと伝わる笛の名前は？","«蝉折（せみおれ）» の笛です。嵐をさけられたお礼と伝わります。"],"koji":[],"myth":"義経が立ち寄り笛を納めた話は伝説。創建年代も社伝。","img":["源義経","珠洲市","禄剛埼灯台"],"wp":"須須神社","rel":{"ev":[],"grave":[]},"ph":[["c:d/df/Suzujinjahonden.JPG",2048,1536,"須須神社"],["c:4/4a/%E9%A0%88%E9%A0%88%E7%A5%9E%E7%A4%BE_-_panoramio.jpg",2448,3264],["c:a/a4/Suzujinjaokumiyairiguchi.JPG",2048,1536],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"],["c:d/d4/Mitsukejima_%28Ishikawa%29_4.jpg",2894,1632,"珠洲市"],["c:a/ac/Rokkosaki_Lighthouse_4.jpg",4608,3456,"禄剛埼灯台"]]},{"id":"17_matsunamijo","n":"松波城","yomi":"まつなみじょう","cat":"城","rank":"B","y":1577,"era":["muromachi","azuchi"],"sh":"県指定史跡（庭園は国の名勝）","ad":"鳳珠郡能登町松波","st":"のと里山空港から車で約30分","la":37.3558,"lo":137.2394,"hook":"奥能登を治めた畠山一族の城。山の上に、戦国の «枯山水の庭» が眠っていた。","lead":"松波城は、能登町松波にあった戦国時代の城です。能登の守護・畠山氏の一族が築き、6代にわたって奥能登を治めたと伝わります。1577年、上杉謙信の軍に攻められて落城しました。発掘で見つかった枯山水の庭園のあとは、国の名勝になっています。","story":["室町時代の能登は、守護の畠山氏が七尾城を本拠に治めていました。1470年代、畠山義統の三男とされる義智が、奥能登の松波に城を築いたと伝わります。これが松波城です。以後、松波畠山氏は6代にわたって、半島の先の地域をまとめていきました。","松波の一族は、のちに土地の有力な家・松波氏の名を受けつぎ、«松波氏» と名のるようになります。城は七尾城をささえる «支城» の役目をはたしました。«なぜ山の上の城に庭園が?» 発掘で、城の中に15世紀後半から16世紀の枯山水の庭のあとが見つかったのです。武士たちは戦いにそなえるだけでなく、庭をながめ、茶や歌を楽しむ文化も持っていました。","1577年、上杉謙信が能登へ攻めこみ、七尾城が落ちます。そのあと謙信の家臣・長沢光国の軍が松波城にせまりました。城主の松波義親は城を守りきれず、自害したと伝わります。こうして奥能登の畠山一族の城は終わりをむかえました。","城の裏門（搦手門）は、近くの万福寺の山門として移されたと伝えられ、今も残っています。戦国の城の門が、お寺の門として生き続けているのです。","いま城あとは公園として整えられ、遊歩道で曲輪や空堀をめぐることができます。庭園をふくむ約4000㎡は、2012年に «旧松波城庭園» として国の名勝に指定されました。山の城と «庭» という、ちょっと意外な組み合わせが、この城の見どころです。"],"tl":[["1470年代","畠山義智が松波城を築いたと伝わる"],["16世紀","松波畠山氏が6代にわたり奥能登を治める"],["1577年","七尾城が落ち、上杉方の長沢光国に攻められて落城。松波義親が自害"],["1991年","県の史跡に指定"],["2007年","旧松波駅の駅舎を使った情報館が開く"],["2012年","«旧松波城庭園» が国の名勝に指定"]],"who":[["畠山義智","能登守護・畠山義統の三男とされ、松波城を築いたと伝わる"],["松波義親","最後の城主。1577年に自害したと伝わる"],["長沢光国","上杉謙信の家臣。松波城を攻めた"],["上杉謙信","1577年に能登を攻め、七尾城を落とした"]],"deep":["«旧松波城庭園» は、建物群のあとをふくむ約4000㎡が国の名勝。山城の中の枯山水庭園として、全国的にも珍しい。","築城年は文明6年（1474年）とする伝えが多いが、資料によって年に差がある。","搦手門が万福寺の山門として移されたという話は伝承だが、城の建物が寺に移される例は全国に多い。","松波城の落城は七尾城落城（1577年9月）の直後で、上杉方による能登全体の制圧の一部だった。","長沢光国はのちに穴水城に入ったが、謙信の死後、長連龍に攻められることになる。奥能登の城どうしの歴史はつながっている。"],"look":["国の名勝・旧松波城庭園のあと","曲輪・空堀・堀切などの遺構","万福寺の山門（搦手門と伝わる）","旧松波駅を使った情報館"],"q":["松波城で見つかり、国の名勝になったものは何？","枯山水の庭園のあとです。«旧松波城庭園» として2012年に指定されました。"],"koji":[],"myth":"築城年や、搦手門の移築は伝承をふくむ。","img":["能登畠山氏","七尾城","上杉謙信"],"wp":"松波城","rel":{"ev":[],"grave":[]},"ph":[["c:b/b5/Matsunamijouato.jpg",5232,3488,"松波城"],["c:f/fd/Matsunamijou_honmaruato.jpg",5232,3488],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/9a/Nanaojo-tyoudomaru.JPG",1280,960,"七尾城"],["c:8/88/Uesugi_Kenshin_Portrait_from_Uesugi_Shrine.png",768,1164,"上杉謙信"]]},{"id":"17_anamizujo","n":"穴水城（長連龍の居城）","yomi":"あなみずじょう","cat":"城","rank":"B","y":1578,"era":["kamakura","azuchi"],"sh":"町指定史跡","ad":"鳳珠郡穴水町川島","st":"のと鉄道穴水駅から歩いて約20分","la":37.2298,"lo":136.9141,"hook":"一族をみな殺しにされ、たった一人生き残った武将が、ふるさとの城を取りもどした。","lead":"穴水城は、穴水町にあった城で、能登の守護・畠山氏の重臣だった長氏の城でした。1577年に上杉謙信の手にわたりましたが、一族を失った長連龍が織田信長の助けを受けて取りもどしたと伝わります。今は桜の名所の城址公園です。","story":["穴水の港を見下ろす丘に、穴水城のあとがあります。伝えによると、この城を最初に築いたのは鎌倉時代の武士・長谷部信連。1186年のことだといわれます。信連の子孫は «長（ちょう）» 氏を名のり、長いあいだ能登の有力な武士として、この城を拠点にしました。","戦国時代、長氏は能登の守護・畠山氏の重臣でした。1577年、上杉謙信が七尾城を囲むと、城の中では、上杉につくか、織田につくかで意見が割れます。長氏の当主・長続連は織田信長をたよろうとし、息子の連龍を助けを求める使いとして信長のもとへ送りました。ところがその間に、上杉につこうとする重臣たちが城の中で長一族をおそい、続連をはじめ一族の多くが殺されてしまったのです。","たった一人残された連龍。«なぜ自分だけが生き残ったのか»。その思いを胸に、連龍は信長のもとで力をたくわえます。穴水城は上杉方の長沢光国が入っていましたが、1578年に謙信が急死すると、連龍は兵をあげて穴水城を取りもどしたと伝わります。","その後、連龍は一族のかたきを討ち、前田利家の家臣となりました。長家は江戸時代、加賀藩の重臣 «加賀八家» の一つとして3万石あまりの大きな家になります。一族の悲劇から立ち上がった連龍の物語は、能登の戦国史のなかでも特に劇的なものです。","穴水城は1583年ごろに廃城になりました。いま城あとは公園になり、春には桜がさきます。長氏の子孫の字で刻まれた «穴水城趾» の碑が立ち、三の丸あとからは穴水の港を見わたせます。"],"tl":[["1186年","長谷部信連が築いたと伝わる"],["室町〜戦国時代","長氏が畠山氏の重臣として城を拠点にする"],["1577年","七尾城で長一族の多くが殺される。穴水城は上杉方の長沢光国が入る"],["1578年","謙信の急死後、長連龍が穴水城を取りもどしたと伝わる"],["1581年ごろ","連龍が一族のかたきを討つ"],["1583年","廃城"],["江戸時代","長家が加賀藩の重臣 «加賀八家» の一つとなる"]],"who":[["長連龍","長氏の武将。一族を失いながら穴水城を取りもどした"],["長続連","連龍の父。七尾城で殺された"],["長谷部信連","長氏の祖。城を築いたと伝わる"],["長沢光国","上杉方の武将。一時、穴水城に入った"],["上杉謙信","1577年に能登を攻めた"]],"deep":["長谷部信連は、以仁王の挙兵（1180年）のとき王を逃がしたことで知られる武士。のちに鎌倉幕府から能登の所領をあたえられたとされる。","1577年の七尾城内の事件は、遊佐続光・温井景隆らが上杉方に通じて起こしたとされる。連龍はのちに続光らを討って一族の仇を報いたと伝わる。","連龍の奪還戦は «菱脇の戦い» などの名で伝わるが、戦いの時期や経過には諸説がある。","長家は加賀藩で3万3千石をあたえられ、加賀八家（年寄の家柄）の一つとなった。江戸時代を通じて能登の鹿島郡に所領をもった。","城あとの石碑は、長氏34代の長昭連の字による。"],"look":["«穴水城趾» の石碑","三の丸あとから見る穴水港","曲輪の段々の地形","春の桜"],"q":["穴水城を取りもどした長連龍は、そのあとだれの家臣になった？","前田利家です。長家は江戸時代、加賀藩の重臣 «加賀八家» の一つになりました。"],"koji":[],"myth":"長谷部信連の築城、奪還戦の年と経過は諸説。","img":["長連龍","長続連","長谷部信連"],"wp":"穴水城","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:7/79/Cho_Tsuratatsu.jpg",1350,1850,"長連龍"],["c:d/dc/Yoshitoshi_-_100_Aspects_of_the_Moon_-_36.jpg",513,723,"長谷部信連"]]},{"id":"17_nimagarijo","n":"二曲城","yomi":"ふとげじょう","cat":"城","rank":"B","y":1580,"era":["azuchi"],"sh":"国指定史跡（鳥越城跡附二曲城跡）","ad":"白山市出合町","st":"北陸鉄道鶴来駅から車で約20分。近くに «道の駅一向一揆の里» がある","la":36.4,"lo":136.6207,"hook":"«本領を安堵する» と約束され、会いに行ったらだまし討ち。加賀一向一揆の最後の抵抗の舞台。","lead":"二曲城は、白山市の大日川のほとりにある山城です。白山のふもとの一向一揆の門徒たちの拠点の一つで、川の向こうの鳥越城とともに国の史跡になっています。1580年、城主が柴田勝家にだまし討ちにされ、その後の戦いで一揆の抵抗は終わりました。","story":["加賀の一向一揆は、1488年に守護の富樫政親をたおしてから、約100年ものあいだ «門徒の国» を続けました。けれど1580年、織田信長と本願寺が和睦すると、一揆の本拠だった金沢御坊（尾山御坊）も柴田勝家の軍に落とされます。それでも白山のふもとの山里では、門徒たちがまだ抵抗を続けていました。","その中心の一つが、大日川の河畔にそびえる二曲城です。標高267mの独立した山で、山頂を平らにけずった曲輪と、尾根の堀が残ります。ここは門徒の指導者・鈴木氏の本拠で、城は館の裏山の «詰めの城» でした。川の向こうには、鈴木出羽守の鳥越城があります。","1580年、二曲城の城主・若林長門守は、勝家に «領地をそのまま認めてくれるなら従います» と使いを送りました。勝家はそれを受け入れます。ところが長門守が親子3人で勝家の陣へあいさつに行くと、そこでだまし討ちにあい、殺されてしまいました。同じように鳥越城の鈴木出羽守父子もだまし討ちにされ、その首は安土の信長のもとへ送られたといいます。«約束は、なぜ守られなかったのか» ―― 戦国の非情さを物語る出来事です。","1582年、一揆の人びとは力をふりしぼって城を取りもどしました。しかし数か月後、ふたたび落城。とらえられた門徒300人あまりが処刑されたと伝わります。こうして加賀一向一揆の抵抗は終わりました。","いま、近くには «一向一揆歴史館» があり、この地の門徒たちの歴史を伝えています。山の上の城あとに立つと、信仰を守ろうとした人びとの思いと、多くの命が失われた悲しみが、静かに迫ってきます。"],"tl":[["1488年","加賀一向一揆が守護・富樫政親をたおす"],["1580年","本願寺と信長が和睦。金沢御坊が落ちる"],["1580年","二曲城主・若林長門守父子が柴田勝家にだまし討ちにされる"],["1582年","一揆勢が城を奪い返すが、数か月後に再び落城。300人余りが処刑されたと伝わる"],["1985年","鳥越城跡附二曲城跡として国の史跡に指定"]],"who":[["若林長門守","二曲城の城主。勝家にだまし討ちにされた"],["鈴木出羽守","鳥越城主。白山麓の門徒の指導者。同じくだまし討ちにあった"],["柴田勝家","信長の重臣。加賀一向一揆を平定した"],["織田信長","本願寺と戦い、加賀を支配下においた"]],"deep":["«二曲» と書いて «ふとげ» と読む。«府峠城» とも書かれる。","国史跡の名称は «鳥越城跡 附 二曲城跡»。«附（つけたり）» は、主な史跡に付属して一緒に指定されたものを示す。","二曲城は大日川の河畔、標高267mの独立峰にある。山頂の曲輪と尾根上の曲輪・堀が確認されている。","1582年の一揆勢の再起は、本能寺の変の前後の混乱の時期と重なる。加賀一向一揆の «最後の火花» とよばれることもある。","処刑された門徒の数は «300人余り» と伝わるが、正確な人数は記録によって異なる。"],"look":["山頂の曲輪のあと","尾根の堀","川をはさんだ鳥越城との位置関係","近くの一向一揆歴史館"],"q":["二曲城と一緒に国の史跡に指定されている、川の向こうの城は？","鳥越城です。史跡名は «鳥越城跡附二曲城跡» です。"],"koji":[{"w":"百姓の持ちたる国","m":"一向一揆が治めた加賀を表す言葉。約100年つづいた"}],"myth":"処刑された人数など、細部は伝えによる。","img":["鳥越城","加賀一向一揆","柴田勝家"],"wp":"二曲城","rel":{"ev":[],"grave":[]},"ph":[["c:1/14/Futougejou001.jpg",800,531,"二曲城"],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:9/94/Torigoe01.jpg",800,531,"鳥越城"],["c:0/0c/Shibata_Katsuie_large.jpg",1386,2965,"柴田勝家"]]},{"id":"17_ishibe","n":"石部神社（加賀一之宮の論社）","yomi":"いそべじんじゃ","cat":"寺社","rank":"B","y":823,"era":["nara","heian"],"sh":"","ad":"小松市古府町","st":"小松駅から車で約10分（バスは本数が少ないので注意）","la":36.4105,"lo":136.4775,"hook":"«加賀の一宮はどこ?» ――千年前の国府のそばで、その問いに名乗りをあげてきた小さな古社。","lead":"石部神社は、小松市の «古府（こふ）» という町にある古い神社です。古府という地名は «昔の国府があった場所» を思わせ、ここは加賀国の役所のすぐそばの神社だったと考えられています。そのため «加賀の一宮（いちばん格の高い神社）» だったのではないか、という説があります。","story":["平安時代のはじめ、823年に越前国から北の二つの郡が分かれて «加賀国» が生まれました。日本の «国» のなかで、いちばん最後にできた国です。新しい国には、役所である «国府» が置かれました。その場所が、いまの小松市の古府町あたりだったと考えられています。","国の役人（国司）が着任すると、まず国内の大事な神社をめぐってお参りするのが決まりでした。«全部まわるのは大変だ» ということで、国府の近くに神々をまとめてまつる «総社» がつくられることもありました。石部神社は、その総社の役目もはたしたのでは、といわれています。","では «一宮» はどこだったのでしょう。ふつう加賀の一宮といえば、白山のふもとの白山比咩神社（しらやまひめじんじゃ）が知られています。けれど石部神社にも «一宮» と呼ばれてきた言い伝えがあり、こうした «一宮はうちだ» と名乗る神社を «論社（ろんしゃ）» と呼びます。なぜ二つの候補があるのか?　時代によって国府との近さや神社の勢いが変わったため、と考える人もいます。","石部神社は、平安時代の神社の名簿 «延喜式神名帳» にのる «式内社» のひとつとされます。千年以上前から名前が知られていた、ということです。いまの境内は静かな森で、春には桜がきれいだと地元で親しまれています。","«ここに国の役所があったんだ» と思いながら周りの田んぼや町並みを歩くと、景色が少しちがって見えてきます。国府の建物の跡ははっきり見つかっていませんが、地名と神社が、古い加賀のすがたを今に伝えています。"],"tl":[["823年","越前国から江沼郡・加賀郡が分かれ、加賀国ができる（のちに能美郡・石川郡も）"],["927年","«延喜式» 完成。その神名帳に石部神社の名がのるとされる"],["平安時代","国府の近くの神社として、総社の役目もはたしたと伝わる"],["中世","白山比咩神社が加賀一宮として勢いを強める"],["現在","«加賀国府跡» の推定地のひとつとして、古府の地名とともに注目される"]],"who":[["加賀国の国司","国府に着任した役人。国内の神社を参拝するのが大事なつとめだった"],["白山比咩神社の人々","加賀一宮として知られる神社。石部神社と «一宮» の名を分け合う関係"]],"deep":["«論社» とは、古い名簿にある神社がどこか、あるいは «一宮» がどこかについて、複数の神社が候補になっている状態のこと。全国の一宮には、こうした論社がいくつもあります。","加賀国の成立は823年（弘仁14年）。越前守の紀末成（きのすえなり）の申し出によると伝わり、国が大きすぎて治めにくかったことが理由とされます。","加賀国府の正確な位置はまだ確定していません。小松市の古府町周辺が有力な推定地で、発掘調査が続けられています。«古府» という地名そのものが大きな手がかりです。","延喜式神名帳では、加賀国の式内社は40を超えるとされます。そのなかで石部神社は能美郡の神社として記され、国府に近いことから格が高かったと考えられています。","«石部» という名前は、石を扱う人々や、古い氏族の名と関係があるという説があります。ただし由来ははっきりしていません。"],"look":["古府という地名と、周りに広がる平地（国府があったと考えられる場所）","静かな社叢（神社の森）と社殿","春の桜（地元で親しまれている）","石碑や由緒書き（一宮・総社についての説明）"],"q":["加賀国ができたのは何年?","823年。日本の «国» のなかでいちばん最後にできた国です。"],"koji":[],"myth":"«加賀一宮» だったか、総社を兼ねたかは言い伝え・諸説。国府の位置も推定。","img":["加賀国","白山比咩神社","一宮"],"wp":"石部神社 (小松市)","rel":{"ev":[],"grave":[]},"ph":[["c:2/27/Isobe-jinja_%28Komatsu%29%2C_haiden.jpg",5568,3712,"石部神社 (小松市)"],["c:3/39/Isobe-jinja_%28Komatsu%29%2C_torii.jpg",5568,3712],["c:8/8a/Isobe-jinja_%28Komatsu%29%2C_otorii.jpg",5568,3712],["c:f/fc/Isobe-jinja_%28Komatsu%29%2C_enkei.jpg",5568,3712],["c:a/ab/Isobe-jinja_%28Komatsu%29%2C_Minaminodai_Site.jpg",5568,3712],["j:d/d0/%E7%99%BD%E5%B1%B1%E6%AF%94%E5%92%A9%E7%A5%9E%E7%A4%BE_%E5%A4%96%E6%8B%9D%E6%AE%BF.JPG",3648,2736,"白山比咩神社"],["c:6/6d/Zenkoku-ichinomiya.jpg",600,800,"一宮"]]},{"id":"17_mattojo","n":"松任城","yomi":"まっとうじょう","cat":"城","rank":"B","y":1583,"era":["muromachi","azuchi"],"sh":"","ad":"白山市古城町","st":"松任駅（IRいしかわ鉄道）から歩いて約10分","la":36.5195,"lo":136.565,"hook":"一向一揆の武士の城から、のちの加賀藩2代藩主・前田利長の城へ。いまは «おかりや公園» の小さな丘だけが残る。","lead":"松任城は、いまの白山市の中心、松任駅の近くにあったお城です。戦国時代には一向一揆の側についた武士・鏑木（かぶらき）氏の城で、その後は前田利長が城主になりました。建物は残っていませんが、本丸があった場所が «おかりや公園» になっています。","story":["戦国時代の加賀は、ふしぎな国でした。1488年、浄土真宗（一向宗）の門徒たちが守護の富樫政親をたおし、およそ100年ものあいだ、門徒と地元の武士たちが国を動かしたのです。«百姓の持ちたる国» と呼ばれたこの時代、松任の城を守っていたのが鏑木氏でした。","鏑木氏はもともと地元の武士。一向一揆の «旗本» として、門徒の軍をまとめる役目をになったといわれます。平らな加賀平野のまんなかで、松任は北陸道が通る大事な場所。«ここをおさえれば加賀の真ん中をおさえられる» ――城が置かれたのには、そんな理由がありました。","しかし1580年、織田信長の命を受けた柴田勝家の軍が金沢御堂（尾山御坊）を落とし、加賀の一向一揆は終わりをむかえます。松任城も織田方の手に入りました。","1583年、賤ヶ岳の戦いのあと、豊臣秀吉は前田利家に加賀の二つの郡をあたえます。このとき利家の息子・利長が松任城に入ったと伝わります。のちに加賀藩の2代藩主となる若者が、城主としての一歩をふみだした場所なのです。","江戸時代に入り、«一国一城令» などで松任城は使われなくなりました。城下は北陸道の宿場町として栄え、いまは公園の小高い丘と石碑が、城のあったことを静かに伝えています。"],"tl":[["1488年","長享の一揆。加賀の一向一揆が守護・富樫政親をたおす"],["16世紀","鏑木氏が松任城を拠点とする"],["1580年","柴田勝家らが金沢御堂を攻め落とし、一向一揆がほぼ終わる"],["1583年","前田利長が松任城主になったと伝わる"],["1585年","利長は越中へ移る"],["江戸時代初め","城は廃され、松任は北陸道の宿場町に"]],"who":[["鏑木氏","一向一揆側の地元武士。松任城を拠点とした"],["前田利長","前田利家の長男。松任城主をへて加賀藩2代藩主に"],["柴田勝家","織田信長の重臣。加賀の一向一揆を攻めた"],["前田利家","加賀藩の祖。1583年に加賀へ領地を広げた"]],"deep":["«百姓の持ちたる国»: 加賀の一向一揆の時代を表すことばで、本願寺の関係者が書き残した記録に出てきます。実際には門徒の坊主や地元武士（国人）たちが力を持つ仕組みでした。","松任城の築城時期ははっきりしません。鏑木氏の城として知られていますが、それ以前から館のようなものがあったとも考えられています。","前田利長が松任に入った石高は約4万石といわれます。のちに越中守山城へ移り、父・利家のあとをついで加賀藩を率いました。","おかりや公園の名前は、城跡に «御仮屋（おかりや）» と呼ばれる建物（藩主が立ち寄る休憩所など）が置かれたことに由来するといわれます。","松任は加賀千代女のふるさとでもあり、城跡・宿場町・千代女ゆかりの寺を一度に歩けます。"],"look":["おかりや公園の小高い丘（本丸跡とされる）","松任城跡の石碑","北陸道（旧街道）の名残をたどる町歩き","近くの聖興寺（加賀千代女ゆかり）"],"q":["松任城主をつとめ、のちに加賀藩2代藩主になった人物は?","前田利長。前田利家の長男です。"],"koji":[{"w":"百姓の持ちたる国","m":"一向一揆の時代の加賀のようすを表すことば。武士の守護ではなく、門徒たちが国を動かしているように見えたことから"}],"myth":"築城時期、利長の入城の細かな年月、おかりや公園の名の由来には諸説あり。","img":["加賀一向一揆","前田利長","鏑木氏"],"wp":"松任城","rel":{"ev":[],"grave":[]},"ph":[["c:a/af/%E3%81%8A%E3%81%8B%E3%82%8A%E3%82%84%E5%85%AC%E5%9C%92.jpg",640,480,"松任城"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/68/Maeda_Toshinaga.jpg",354,396,"前田利長"]]},{"id":"17_chiyojo","n":"加賀千代女ゆかりの聖興寺","yomi":"しょうこうじ","cat":"学び","rank":"B","y":1754,"era":["edo"],"sh":"","ad":"白山市中町","st":"松任駅（IRいしかわ鉄道）から歩いて約5分","la":36.5165,"lo":136.564,"hook":"«朝顔に つるべとられて もらい水»――あの句を詠んだ女性俳人が、静かにねむる寺。","lead":"加賀千代女（かがのちよじょ）は、江戸時代の松任に生まれた女性の俳人です。井戸のつるべに朝顔のつるがからまっているのを見て、«かわいそうだから» と近所に水をもらいに行った――そんなやさしい句で知られています。聖興寺には千代女のお墓や、ゆかりの品が伝わっています。","story":["1703年、千代は松任の表具屋（掛け軸やふすまを仕立てる店）の娘として生まれました。子どものころから句をつくるのが好きで、十代で才能を認められたといわれます。«女の子が俳句を?» と思う人もいた時代に、千代の名はやがて北陸をこえて広まっていきました。","有名な «朝顔に つるべとられて もらい水»。朝、井戸に水をくみに行くと、つるべ（おけ）の縄に朝顔がまきついていた。ほどけば花がこわれてしまう。だから自分の家の井戸はあきらめて、となりに水をもらいに行く――小さな命へのまなざしが、たった十七音にこめられています。","千代は、松尾芭蕉の弟子の各務支考（かがみしこう）にも才能をほめられたと伝わります。旅の俳人たちが北陸をおとずれると、千代に会いに来ることもありました。女性が自分の名前で作品を残すのがむずかしかった時代に、千代は «加賀の千代» として知られる存在になったのです。","50歳をすぎたころ、千代は髪をおろして尼となり、«素園（そえん）» と名のりました。1763年には、加賀藩にたのまれて、朝鮮から来た使節（朝鮮通信使）へおくる句を書いたことでも知られます。","1775年、千代は73歳でこの世を去りました。聖興寺には千代女の墓と、千代が使ったと伝わる品々が残されています。近くには «千代女の里俳句館» もあり、松任の町は今も千代女の町として句を大切にしています。"],"tl":[["1703年","松任の表具屋に生まれる"],["1720年代","各務支考に才能を認められたと伝わる"],["1754年ごろ","剃髪して尼となり «素園» と号す"],["1763年","朝鮮通信使への献上の句を書く"],["1775年","73歳で没する。聖興寺に葬られる"],["現在","白山市に «千代女の里俳句館» があり、顕彰が続く"]],"who":[["加賀千代女","松任出身の俳人。のち尼となり素園と号した"],["各務支考","芭蕉の弟子の俳人。若い千代女の才能をほめたと伝わる"],["松尾芭蕉","千代女が生まれる前の人だが、その俳諧の流れの中に千代女がいる"]],"deep":["«朝顔や つるべとられて もらい水» と «や» で覚えている人も多い句。千代女自身の句集では «朝顔に» の形とされ、のちに書き直したという説もあります。","千代女が残した句は1700句以上といわれます。季節の小さな命をやさしく詠んだ作品が多く、明治以降は教科書にものって全国に広まりました。","朝鮮通信使への献上句は21句と伝わり、加賀藩の依頼でつくられました。女性の俳人が外交の場の贈り物をまかされたのは、とても珍しいことです。","千代女は «千代尼（ちよに）» とも呼ばれます。尼になってからの号が «素園» で、晩年の作品や書にこの名が見られます。","聖興寺は浄土真宗の寺。千代女の遺品や句碑があり、見学には事前に寺へ問い合わせるのが安心です。"],"look":["千代女の墓と句碑","千代女ゆかりの遺品（公開日や見学方法は寺に確認）","近くの «千代女の里俳句館»","松任の町に点在する句碑"],"q":["千代女が尼になってから名のった号は?","«素園（そえん）»。50代で髪をおろしてからの名前です。"],"koji":[{"w":"朝顔に つるべとられて もらい水","m":"朝顔の命を大切にして、自分の井戸を使わず水をもらいに行くという句。千代女のやさしさを表す代表作"}],"myth":"«朝顔に» と «朝顔や» の形、支考との出会いの細部には諸説あり。","img":["各務支考","朝鮮通信使"],"wp":"加賀千代女","rel":{"ev":[],"grave":[]},"ph":[["c:6/66/Caga_no_Chiyo_standing_beside_a_well.jpg",1154,3420],["c:4/46/NDL-DC_1311729-Watanabe_Kazan-%E6%94%AF%E8%80%83%E8%82%96%E5%83%8F%E7%9C%9F%E8%B9%9F-crd.jpg",2935,4190,"各務支考"],["c:8/8f/KoreanEmbassy1655KanoTounYasunobu.jpg",2552,1056,"朝鮮通信使"]]},{"id":"17_omicho","n":"近江町市場","yomi":"おうみちょういちば","cat":"町","rank":"B","y":1721,"era":["edo","heisei"],"sh":"","ad":"金沢市上近江町","st":"JR金沢駅から歩いて約15分。バス «武蔵ヶ辻・近江町市場» 下車すぐ","la":36.5715,"lo":136.6565,"hook":"300年つづく «金沢の台所»。ズワイガニも甘エビも、江戸の城下町から続く売り声の中に並ぶ。","lead":"近江町市場は、金沢のまんなかにある大きな市場です。江戸時代の中ごろ、町の中にあった市場がここに集まってできたといわれ、300年ほどの歴史があります。いまも約170のお店がならび、«金沢の台所» と呼ばれています。","story":["加賀藩の城下町・金沢は、江戸時代に人口が10万人をこえる大都市でした。それだけの人の食べ物を、どこで売り買いしていたのでしょう?　はじめは町のあちこちに市が立っていましたが、18世紀のはじめ、魚や野菜の市場がこの近江町に集められたと伝わります。","近江町のある場所は、金沢城から北へのびる北国街道ぞい。港町の宮腰（いまの金石）から魚が運ばれ、まわりの村からは野菜が届く。人と物が行き交う交差点だったのです。«なぜここに市場が?» の答えは、この地の利にありました。","«近江町» という名前にも謎があります。近江国（いまの滋賀県）から来た商人たちが住んでいたから、という説がよく知られていますが、はっきりした記録はありません。前田家に近江の人々が仕えていたこととも関係があるのでは、と考える人もいます。","明治、大正、昭和と、市場は火事や戦争の時代をこえて続きました。金沢は大きな空襲を受けなかったこともあり、古い市場のにぎわいが受けつがれます。2009年には一部が建て替えられて «近江町いちば館» ができ、2015年の北陸新幹線開業からは観光客も大勢おとずれるようになりました。","朝早く行くと、«らっしゃい!» の声と一緒に、氷の上にならんだカニやブリ、加賀野菜がむかえてくれます。300年前の城下町の人たちも、きっと同じような声を聞いていたはずです。"],"tl":[["1583年","前田利家が金沢城に入り、城下町づくりが始まる"],["1721年ごろ","市場がこの地に集められたと伝わる（近江町市場の始まり）"],["明治時代","市場として公設化の動きなど、近代の市場へ"],["1945年","金沢は大きな空襲をまぬがれる"],["2009年","再開発で «近江町いちば館» が完成"],["2015年","北陸新幹線が金沢まで開業し、観光客が大きく増える"]],"who":[["前田利家","加賀藩の祖。金沢の城下町づくりを始めた"],["市場の商人たち","300年にわたって «金沢の台所» を守ってきた人々"]],"deep":["市場の始まりを1721年（享保6年）とする説が広く使われ、2021年には «開設300年» の催しが行われました。ただし当時の史料には不明な点もあります。","«近江町» の名の由来は、近江出身の商人が住んだ説のほか、近江の地名と関係する説もあり、はっきりしません。","金沢は第二次世界大戦で大規模な空襲を受けなかった都市の一つです。そのため城下町の町割りや、市場のような古い商いの場が残りやすかったといわれます。","近江町市場は «上近江町» «下近江町» などにまたがり、通路は «むさし通り» «中通り» などの名前でよばれています。迷路のような路地も見どころです。","冬のズワイガニ（石川では雄を «加能ガニ»、雌を «香箱ガニ» と呼ぶ）は、近江町の冬の顔。季節によって並ぶものがまったく変わります。"],"look":["朝の活気ある売り場（早い時間がおすすめ）","冬の加能ガニ・香箱ガニ","加賀野菜（加賀れんこん、金時草など）","近江町いちば館と、古い路地の対比"],"q":["近江町市場は、ふつう何と呼ばれている?","«金沢の台所»。300年近く町の食を支えてきました。"],"koji":[],"myth":"開設年（1721年）や «近江町» の名の由来には諸説あり。","img":["金沢市","北陸新幹線","加賀野菜"],"wp":"近江町市場","rel":{"ev":[],"grave":[]},"ph":[["c:3/33/Omicho-ichiba_%E8%BF%91%E6%B1%9F%E7%94%BA%E5%B8%82%E5%A0%B4_A091185.JPG",1280,960,"近江町市場"],["c:c/ce/Omicho_covered_market_western_entrance%2C_Kanazawa%2C_2016.jpg",5705,3794],["c:2/24/Omc02.jpg",2808,1872],["c:9/99/OMC03.jpg",2808,1872],["c:1/13/OMC01.jpg",2808,1872],["c:b/b1/Omichyo_Ichibakan.jpg",2048,1536],["c:d/d8/Omicho-ichiba_%E8%BF%91%E6%B1%9F%E7%94%BA%E5%B8%82%E5%A0%B4_A091079.JPG",960,1280],["c:a/a9/Omicho-ichiba_%E8%BF%91%E6%B1%9F%E7%94%BA%E5%B8%82%E5%A0%B4_A091018.JPG",1280,960]]},{"id":"17_jishoin","n":"実性院（大聖寺藩主の墓所）","yomi":"じっしょういん","cat":"墓所","rank":"B","y":1639,"era":["edo"],"sh":"","ad":"加賀市大聖寺下屋敷町","st":"大聖寺駅（IRいしかわ鉄道）から歩いて約15分","la":36.2985,"lo":136.3125,"hook":"加賀百万石の «分家» 大聖寺藩。14代の殿さまたちを見守ってきたのは、秋に萩がゆれる小さな寺。","lead":"実性院（じっしょういん）は、加賀市大聖寺にある曹洞宗のお寺です。江戸時代にこの地を治めた大聖寺藩の前田家の菩提寺（先祖をまつる寺）で、歴代の藩主の墓があります。秋には萩の花が咲き、«萩の寺» とも呼ばれています。","story":["1639年、加賀藩3代藩主・前田利常は、息子たちに領地を分けました。次男の利次には富山藩、三男の利治には大聖寺藩。こうして «加賀藩の支藩» として大聖寺藩が生まれます。石高は7万石。利治はここで初代藩主になりました。","藩ができれば、殿さまをまつる寺が必要です。実性院は、大聖寺藩の前田家の菩提寺として、城下の «山の下寺院群» と呼ばれる寺町の一角に置かれました。«なぜ寺がこんなに集まっているの?» ――寺町には、いざという時の防御の役目もあったといわれます。","初代・利治は、ただの «分家の殿さま» ではありませんでした。領内の九谷村で焼き物づくりを始めさせたと伝わり、これがのちに «古九谷» と呼ばれる色あざやかな焼き物につながったとされます。","大聖寺藩は14代にわたって続き、江戸時代の後半には10万石に格上げされました。ただし、実際にとれる米が増えたわけではなく、格が上がったぶん出費が増え、藩はお金の苦労をしたともいわれます。","実性院の裏山には、歴代藩主の墓がならんでいます。本堂の天井画や、藩主ゆかりの品もあり、秋の萩の季節には多くの人がおとずれます。«百万石の陰» で続いた小さな藩の歴史が、ここに眠っています。"],"tl":[["1639年","加賀藩から大聖寺藩が分かれ、前田利治が初代藩主に（7万石）"],["1650年代","九谷村で焼き物づくりが始まったと伝わる（古九谷）"],["1660年","利治が亡くなる"],["1821年","大聖寺藩が10万石に格上げ"],["1871年","廃藩置県で大聖寺藩が終わる"],["現在","«萩の寺» として秋に親しまれる"]],"who":[["前田利治","大聖寺藩初代藩主。前田利常の三男"],["前田利常","加賀藩3代藩主。大聖寺藩・富山藩を分けた"],["大聖寺藩の歴代藩主","14代にわたって大聖寺を治めた前田家の人々"]],"deep":["大聖寺藩は «加賀藩の支藩» ですが、将軍から直接領地を認められた独立した藩でした。富山藩と並ぶ «前田家の分家» です。","10万石への格上げ（1821年）は «高直し（たかなおし）» と呼ばれます。実際の収穫は変わらず、江戸での格式や負担だけが重くなったという見方があります。","古九谷の生まれた場所については、«九谷村で焼かれた» という説と «有田（佐賀）で焼かれたものもある» という説があり、今も議論が続いています。","山の下寺院群には、実性院をふくむ多くの寺が集まり、城下町の南の守りの役目もあったといわれます。","実性院は曹洞宗の寺で、藩主の墓所は裏手の山の斜面にあります。見学や拝観は寺の案内にしたがいましょう。","大聖寺には藩主の別邸 «長流亭» や、江沼神社のある藩邸跡も残ります。実性院とあわせて歩くと、7万石（のち10万石）の小さな城下町の広さが体でわかります。"],"look":["歴代藩主の墓所（裏山）","秋（9月ごろ）に咲く萩","本堂の天井画など寺の宝物（公開状況は要確認）","山の下寺院群のまちなみ散歩"],"q":["大聖寺藩の初代藩主は誰?","前田利治。加賀藩3代藩主・前田利常の三男です。"],"koji":[],"myth":"古九谷の産地は諸説あり。寺町の防御目的も推測を含む。","img":["大聖寺藩","前田利治","古九谷"],"wp":"実性院","rel":{"ev":[],"grave":[]},"ph":[["c:9/92/260718_Yamanoshita_Jiingun_Kaga_Ishikawa_pref_Japan03s3.jpg",5472,3648,"大聖寺藩"],["c:4/4f/KUTANI_Ewer.JPG",852,627,"古九谷"],["c:9/9f/Ishikawa_Kaga_Kagahashidate00.jpg",2816,2120,"近く: 加賀市"],["c:b/bd/Daishoji_sta_2024.jpg",4032,2268,"近く: 大聖寺駅"],["c:2/21/260718_Ishikawa_Prefectural_Kutani_Ware_Museum_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648,"近く: 石川県九谷焼美術館"],["c:0/0f/Jishu-jiritsu.jpg",583,386,"近く: 石川県立大聖寺高等学校"],["c:8/89/260718_At_Daishoji_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648,"近く: 大聖寺町"],["c:b/bc/Daido_Kogyo_ac_%282%29.jpg",5663,3765,"近く: 大同工業"]]},{"id":"17_kitsuneyama","n":"狐山古墳","yomi":"きつねやまこふん","cat":"遺跡","rank":"B","y":480,"era":["kofun"],"sh":"国指定史跡","ad":"加賀市二子塚町","st":"加賀温泉駅から車で約10分","la":36.333,"lo":136.36,"hook":"きつねが住む山だと思われていた小山が、じつは王の眠る «前方後円墳» だった。","lead":"狐山古墳は、加賀市にある古墳時代の前方後円墳です。長さは約50mあまり。中から石の棺が見つかり、鏡や武具などが出てきました。この地方をおさめた有力者のお墓と考えられています。","story":["むかし、この小さな森のような山は «狐山» と呼ばれていました。«きつねが住んでいそうな山» ――村の人たちは、そんなふうに思っていたのかもしれません。けれど、この山は自然の山ではありませんでした。人の手で土を盛ってつくられた、古墳だったのです。","上から見ると、四角と丸をつなげたカギ穴の形。これが «前方後円墳» です。大和（いまの奈良県）の大王たちと同じ形のお墓をつくることは、«わたしは大王とつながりのある有力者だ» と示すしるしでもありました。","昭和のはじめごろ、古墳の中から石でできた棺が見つかりました。中には銅の鏡や、よろい・かぶと、刀、玉などが納められていたといいます。«いったいどんな人が眠っていたの?» ――副葬品から、戦いにもかかわる力を持った人物だったと考えられています。","5世紀の後半、加賀の南のこのあたりは、海や潟（かた）に近く、日本海を通じて各地とつながる場所でした。狐山古墳の主は、そうした交流をまとめる地域の «王» だったのかもしれません。","いま古墳は、国の史跡として守られています。こんもりした森の形に、1500年前の人々の «王をたたえる気持ち» が今も残っています。見学するときは、古墳の上を荒らさないよう静かに歩きましょう。"],"tl":[["5世紀後半","前方後円墳として築かれたと考えられる"],["昭和初期","石棺と副葬品が見つかる"],["1930年代","国の史跡に指定"],["現在","加賀市の代表的な古墳として保存"]],"who":[["古墳の被葬者","名前はわからないが、この地域をおさめた有力者と考えられる"],["大和の大王","前方後円墳という形を通じて、地方の有力者とつながっていた"]],"deep":["前方後円墳は、全国に約5000基あるといわれます。北陸ではとくに石川県の加賀地方と能登地方に多く見られます。","狐山古墳の出土品は、東京国立博物館に収められているものがあるといわれます。鏡や武具の組み合わせは、5世紀の有力者の墓によく見られるものです。","石棺は «箱式石棺» と呼ばれる、板状の石を組み合わせたタイプとされます。石材をどこから運んだかも研究のテーマです。","5世紀は、よろい・かぶとなど鉄の武具が多く墓に納められた時代。大和政権と地方の有力者が、軍事的な結びつきを強めたことを示すと考えられています。","加賀市周辺には、狐山古墳のほかにも古墳が点在し、加賀南部に有力な集団がいたことを物語っています。","古墳の名前には «狐山» «狸塚» のように動物の名がつくことがよくあります。昔の人は古墳をお墓と知らず、あやしい小山として動物の住みかと考えたのでしょう。","5世紀は «倭の五王» が中国の宋に使いを送った時代。地方の有力者が鉄の武具を持つ背景には、大和政権を通じた朝鮮半島との鉄の交易があったと考えられます。"],"look":["前方後円墳の形（前方部と後円部の高さの違い）","古墳をおおう森と、史跡の説明板","周りの地形（かつての潟や海とのつながりを想像する）","近くの加賀市の古墳・遺跡（あわせてめぐると地域の歴史がわかる）"],"q":["カギ穴のような形のお墓を何と呼ぶ?","«前方後円墳»。大和の大王と同じ形で、有力者の墓でした。"],"koji":[],"myth":"規模・出土品の細部・指定年は資料で要確認。","img":["前方後円墳","古墳時代","加賀市"],"wp":"狐山古墳","rel":{"ev":[],"grave":[]},"ph":[["c:c/c3/NintokuTomb_Aerial_photograph_2007.jpg",1000,982,"前方後円墳"],["c:9/9f/Ishikawa_Kaga_Kagahashidate00.jpg",2816,2120,"加賀市"],["c:2/25/260718_Katayamazu_Onsen_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648,"近く: 片山津町"],["c:4/42/%E5%8B%95%E6%A9%8B%E9%A7%85_%E6%AD%A3%E9%9D%A2%E5%A4%96%E8%A6%B3_-_panoramio_%281%29.jpg",1600,1200,"近く: 動橋駅"],["c:9/94/260606_Kagaonsen_Station_Kaga_Ishikawa_pref_Japan01s3.jpg",5472,3648,"近く: 加賀温泉駅"],["c:7/72/Kaga_City_Fire_Department.jpg",3456,2304,"近く: 加賀市消防本部"]]},{"id":"17_hououzan","n":"法皇山横穴古墳","yomi":"ほうおうざんよこあなこふん","cat":"遺跡","rank":"B","y":600,"era":["kofun","asuka"],"sh":"国指定史跡","ad":"加賀市勅使町","st":"加賀温泉駅から車で約15分","la":36.286,"lo":136.352,"hook":"山の斜面に、ぽっかり開いたたくさんの穴。1400年前、人々は «山の横腹» に家族を葬った。","lead":"法皇山横穴古墳は、山の斜面に横向きの穴をほって作ったお墓（横穴墓）がたくさん集まった遺跡です。古墳時代の終わりごろ、6世紀から7世紀にかけてつくられたと考えられています。国の史跡になっていて、穴のいくつかを外から見ることができます。","story":["山道を歩いていくと、崖のような斜面に、四角い入り口の穴がいくつも並んでいます。«ほら穴?　それとも倉庫?» と思うかもしれません。じつはこれ、すべてお墓です。やわらかい岩をくりぬいて部屋をつくり、そこに亡くなった人を葬ったのです。","古墳時代のはじめ、お墓は土を大きく盛った前方後円墳が中心でした。ところが時代の終わりに近づくと、もっと多くの人が、家族ごとにお墓をつくるようになります。横穴墓は、そうした «家族の墓» と考えられています。","«法皇山» という名前にも、ちょっとした物語があります。平安時代、花山法皇（かざんほうおう）がこのあたりを訪れたという言い伝えがあり、地名の «勅使（ちょくし）» も、天皇の使いが来たことにちなむといわれます。ただし、これはあくまで伝承です。","穴の中からは、土器や鉄の道具、玉などが見つかっています。«死んだあとも暮らしに困らないように» ――そんな願いがこめられた品々です。1400年前の人も、家族を思う気持ちは今と変わらなかったのでしょう。","横穴古墳群は、昭和のはじめに国の史跡に指定されました。穴の数は100をこえるとも伝えられ、北陸でも代表的な横穴墓の遺跡です。見学のときは穴の中に入らず、外から静かにのぞいてみましょう。"],"tl":[["6世紀後半","横穴墓がつくられ始めたと考えられる"],["7世紀","横穴墓の造営が続く"],["平安時代","花山法皇がこの地を訪れたという伝承が生まれる"],["昭和初期","国の史跡に指定"],["現在","史跡公園として一部を見学できる"]],"who":[["横穴に葬られた人々","この地域で暮らした家族たち"],["花山法皇","平安時代の天皇（法皇）。この地を訪れたという伝承がある"]],"deep":["横穴墓（よこあなぼ）は、全国では九州・関東・東海などにも多い形式です。北陸では法皇山が代表例とされます。","横穴の内部は、入り口（羨道）と遺体を置く部屋（玄室）に分かれるのが基本。天井をドーム形やかまぼこ形にくりぬいたものがあります。","花山法皇が北陸を訪れたという話は、加賀の各地に伝わっています。«法皇山» «勅使» の地名はその伝承と結びついていますが、史実かどうかは確かめられていません。","出土品の中には、須恵器（すえき）と呼ばれる、ろくろでつくった固い土器があります。6〜7世紀の年代を考える大事な手がかりです。","穴の数については «100基以上» などと伝えられますが、調査の範囲によって数え方が変わります。","横穴墓は、土を盛る古墳より少ない人手でつくれます。そのため有力者だけでなく、地域のいろいろな家族が墓を持てるようになったと考えられています。","周りの山の岩は、ほりやすいやわらかい凝灰岩などとされます。岩の性質が、横穴墓がたくさんつくられた理由の一つです。"],"look":["斜面に並ぶ横穴の入り口","内部の天井の形（外からのぞける穴で）","史跡の説明板と地形","ほりやすい岩の質感（崖の表面を観察）"],"q":["山の斜面に横向きの穴をほったお墓を何と呼ぶ?","«横穴墓（よこあなぼ）»。家族ごとのお墓と考えられています。"],"koji":[],"myth":"花山法皇来訪と地名の由来は伝承。横穴の数・指定年は資料によって異なる。","img":["横穴墓","花山天皇","須恵器"],"wp":"法皇山横穴古墳","rel":{"ev":[],"grave":[]},"ph":[["c:b/bd/Hououzan_ouketsu_kofun.jpg",5232,3488,"法皇山横穴古墳"],["c:a/ac/Hououzan_ouketsu_kofun_tenjikan.jpg",5232,3488],["j:9/93/%E6%B3%95%E7%9A%87%E5%B1%B14%E5%8F%B7%E6%A8%AA%E7%A9%B4_%E5%8F%8C%E8%80%B3%E5%A3%BA.JPG",4446,3336],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["j:1/18/Yoshimi_Yoshimi-hyakuana_2.JPG",3264,2448,"横穴墓"],["c:c/c2/Emperor_Kazan.jpg",1824,1820,"花山天皇"],["c:4/47/131123_Hyogo_Prefectural_Museum_of_Archaeology_Japan24s5.jpg",4912,3264,"須恵器"]]},{"id":"17_akitsune","n":"秋常山古墳群","yomi":"あきつねやまこふんぐん","cat":"遺跡","rank":"B","y":380,"era":["kofun"],"sh":"国指定史跡","ad":"能美市秋常町","st":"能美根上駅（IRいしかわ鉄道）から車で約10分","la":36.448,"lo":136.512,"hook":"長さ約140m。北陸でいちばん大きいクラスの前方後円墳が、公園の中でよみがえった。","lead":"秋常山古墳群は、能美市の丘の上にある古墳のグループです。中心の «秋常山1号墳» は長さ約140mの前方後円墳で、北陸でも最大級の古墳です。表面にしきつめた石（葺石）が復元され、つくられたころの姿を見ることができます。","story":["能美市の丘に登ると、とつぜん大きな «石の山» が目に飛びこんできます。これが秋常山1号墳です。長さはおよそ140m。サッカー場より長いお墓を、1600年ほど前の人たちが、道具とうでの力だけでつくりあげました。","«なぜこんなに大きなお墓が、この場所に?» ――能美の丘からは、手取川がつくった広い平野と、その先の日本海が見わたせます。この地域をまとめた王は、見晴らしのよい丘の上に、自分の力を示す大きなお墓をつくらせたのでしょう。","古墳の表面は、河原の石でびっしりおおわれていました。これを «葺石（ふきいし）» といいます。完成したばかりの古墳は、緑の森ではなく、日の光を受けて白く輝く «石の山» だったのです。いま見られる姿は、その当時のようすを復元したものです。","秋常山古墳群のまわりには、和田山・末寺山などの古墳群が続き、あわせて «能美古墳群» と呼ばれています。古い時代から新しい時代まで、何代にもわたって有力者たちがこの丘にお墓をつくったことがわかります。","古墳のそばには資料館もあり、出土品や古墳のつくり方を学べます。1号墳の上に立って平野を見わたすと、1600年前の王が見た景色が、少しだけ想像できるかもしれません。"],"tl":[["4世紀後半ごろ","秋常山1号墳がつくられたと考えられる"],["5〜7世紀","周辺の丘に古墳がつくられ続ける"],["1975年","秋常山古墳群が国の史跡に"],["2000年代","発掘調査と葺石の復元整備が進む"],["2012年","周辺の古墳群とあわせ «能美古墳群» として追加指定"]],"who":[["秋常山1号墳の被葬者","名前はわからないが、手取川流域をまとめた有力者と考えられる"],["大和の大王","前方後円墳という形を共有した、中央の支配者"]],"deep":["秋常山1号墳の全長は約140mとされ、北陸地方の前方後円墳では最大級。石川県内では最大とされます。","つくられた年代は4世紀後半〜5世紀初めごろと考えられていますが、細かな時期は研究者によって見方が分かれます。","葺石の復元は、発掘で見つかった石の並び方をもとに行われました。当時は数十万個ともいわれる石が運ばれたと考えられます。","秋常山古墳群をふくむ «能美古墳群» は、約1.5kmほどの範囲に古い時期から新しい時期までの古墳がまとまってあり、地域の首長の移り変わりをたどれる貴重な例です。","手取川は石川県最大の川で、流域の扇状地は古くから米づくりがさかん。古墳の大きさは、この平野の豊かさとも関係すると考えられます。","古墳の上に並べた «埴輪（はにわ）» のかけらも見つかっていて、どんな飾りがあったのかの手がかりになっています。","古墳の周りには «周濠» と呼ばれる溝があったかどうかも調査されてきました。古墳の形を正確に知るには、墳丘だけでなく周りの地形の調査も大切です。"],"look":["葺石で復元された秋常山1号墳","1号墳の上からの平野の眺め","近くの資料館（出土品の展示）","和田山・末寺山古墳群への散策"],"q":["古墳の表面にしきつめた石を何と呼ぶ?","«葺石（ふきいし）»。つくられたころの古墳は白く輝く石の山でした。"],"koji":[],"myth":"築造年代・指定年は諸説・資料で要確認。","img":["能美古墳群","前方後円墳","手取川"],"wp":"秋常山古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:e/e9/Overall_view_of_Akitsune_1.jpg",1821,1024,"秋常山古墳群"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:a/a9/Distribution_of_Nomi_kofungun.jpg",2722,1526],["c:2/27/Akitsune_1_frm_Wadayama_5.jpg",2048,1024],["c:2/23/Akitsuneyama_2.jpg",1820,1024],["c:a/a2/Akitsune_1_koen_enkei.jpg",1820,1024],["c:2/25/Akitsune_1_west_side.jpg",1530,1024],["c:a/a4/Akitsune_1_Fukiishi.jpg",1530,1024]]},{"id":"17_kamiyamada","n":"上山田貝塚","yomi":"かみやまだかいづか","cat":"遺跡","rank":"B","y":-3000,"era":["jomon"],"sh":"国指定史跡","ad":"かほく市上山田","st":"JR宇野気駅から車で約10分","la":36.724,"lo":136.73,"hook":"貝がらのゴミ捨て場から、5000年前の «北陸の縄文ファッション» が見えてくる。","lead":"上山田貝塚は、かほく市にある縄文時代の貝塚です。およそ5000年前、縄文時代中期の人々が暮らしたむらの跡で、貝がらや土器がたくさん見つかりました。ここで出た土器は «上山田式土器» と名づけられ、北陸の縄文土器の «ものさし» になっています。","story":["縄文時代の人たちは、食べた貝のからを決まった場所にすてていました。何百年も積もると、それは白い貝がらの層になります。これが «貝塚» です。ただのゴミ捨て場?　いいえ、考古学者にとっては «むらの暮らしの記録ノート» なのです。","いまの上山田は海から少し離れていますが、縄文時代のこのあたりには、大きな潟（河北潟）の水が近くまで入りこんでいました。人々は潟でシジミなどの貝をとり、魚をつかまえ、森で木の実を集めて暮らしていたと考えられています。","上山田貝塚で見つかった土器には、この地域ならではの模様がありました。そこで研究者は、この土器の形を «上山田式» と名づけました。«この模様があれば、だいたいこのころの土器だ» ――土器の型式は、遺跡の年代をはかる時計のような役目をはたします。","貝塚からは、貝がらのほかに動物の骨や石の道具なども出てきました。貝がらのカルシウムのおかげで、骨がとけずに残りやすいのも貝塚のいいところです。5000年前の食卓のメニューが、少しずつ明らかになっていきました。","いま貝塚は国の史跡として保存され、案内板が立っています。かほく市は哲学者・西田幾多郎のふるさとでもあり、「考えること」の町で、はるか昔の人々の暮らしに思いをめぐらせるのも楽しいかもしれません。"],"tl":[["約5000年前","縄文時代中期、むらが営まれ貝塚ができる"],["昭和時代","発掘調査が行われ、土器が «上山田式» と名づけられる"],["1980年代","国の史跡に指定"],["現在","史跡として保存され、案内板がある"]],"who":[["上山田の縄文人","潟の貝や魚、森の木の実をとって暮らした人々"],["発掘した研究者たち","土器の型式を決め、北陸の縄文時代の年代づけを進めた"]],"deep":["«標識遺跡» とは、ある土器の型式の名前のもとになった遺跡のこと。上山田貝塚は «上山田式土器» の標識遺跡です。","北陸の縄文時代中期の土器は、立体的な飾りが目立つのが特徴。上山田式は、その流れの中に位置づけられます。","河北潟は現在は干拓で小さくなっていますが、縄文時代にはもっと広く、海とつながる入り江のようになっていた時期もあったと考えられます。","日本海側は貝塚が少ない地域とされ、北陸の貝塚は数が限られます。そのため上山田貝塚は、日本海側の縄文人の食べ物を知る貴重な例です。","史跡の指定年や調査の回数は資料によって記載が異なるので、現地の案内板で確認するのがおすすめです。","貝塚の貝の種類を調べると、海水の貝か、淡水・汽水（海水と淡水がまざる水）の貝かで、当時の水辺の環境がわかります。潟のシジミが多ければ、近くに汽水の潟があったと考えられます。","縄文時代中期は、日本列島で人口が多かった時期と考えられ、東日本を中心に大きなむらが各地で営まれました。"],"look":["史跡の案内板と、貝塚のあった丘","周りの地形（かつての河北潟との位置関係）","かほく市の資料展示（出土品が展示されている場合がある）"],"q":["ある型式の土器の名前のもとになった遺跡を何と呼ぶ?","«標識遺跡»。上山田貝塚は «上山田式土器» の標識遺跡です。"],"koji":[],"myth":"指定年・調査の細部は要確認。","img":["貝塚","縄文土器","河北潟"],"wp":"上山田貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:e/e5/Kamiyamada_Shell_Midden.jpg",899,1200,"上山田貝塚"],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["j:6/63/%E7%AC%B9%E5%B1%B1%E9%81%BA%E8%B7%A1%E5%87%BA%E5%9C%9F_%E7%81%AB%E7%84%94%E5%9E%8B%E5%9C%9F%E5%99%A8_%28%E6%B7%B1%E9%89%A2%E5%BD%A2%29_%28%E5%9B%BD%E5%AE%9D%E6%8C%87%E5%AE%9A%E7%95%AA%E5%8F%B71%29.JPG",3413,3386,"縄文土器"],["c:c/c3/KahokuGata.jpg",1280,960,"河北潟"]]},{"id":"17_okyozuka","n":"御経塚遺跡","yomi":"おきょうづかいせき","cat":"遺跡","rank":"B","y":-1000,"era":["jomon"],"sh":"国指定史跡","ad":"野々市市御経塚","st":"野々市駅（IRいしかわ鉄道）から歩いて約20分、または車で約5分","la":36.532,"lo":136.603,"hook":"«お経を埋めた塚» という名の地に眠っていたのは、3000年前の縄文人のむらだった。","lead":"御経塚遺跡は、野々市市にある縄文時代の終わりごろ（後期〜晩期）のむらの跡です。住まいの跡や、土器・石の道具などがたくさん見つかり、国の史跡になりました。いまは公園として整備され、竪穴住居が復元されています。","story":["«御経塚（おきょうづか）»。なんだかお寺のような名前ですね。この地には、むかしお経を埋めた塚があったと言い伝えられていて、それが地名になったといわれます。ところが、その土の下には、お経よりもずっと古い、3000年以上前の人々の暮らしが眠っていました。","1950年代、畑の土の中から土器のかけらが次々と見つかりました。やがて本格的な発掘が行われ、ここが縄文時代の終わりごろに長く続いた大きなむらだったことがわかります。","縄文時代の終わりは、寒さが増し、暮らしが大きく変わった時代です。御経塚の人々は、手取川がつくった平野の近くで、木の実や魚をとりながら暮らしていました。出てきた土器の中には、とても細かい模様や、うすく美しくつくられたものもあります。","ふしぎな道具も見つかりました。«石棒（せきぼう）» や «土偶» など、いのりやまつりに使われたと考えられるものです。«なぜこんなものを作ったの?» ――自然のめぐみへの感謝か、家族の無事を願ったのか。答えはまだなぞに包まれています。","ここで見つかった土器は «御経塚式土器» と名づけられ、北陸の縄文時代晩期を考えるときの大事な物差しになりました。いま遺跡は公園として整備され、復元された竪穴住居の中に入ると、3000年前の暮らしのにおいがふっと感じられるかもしれません。"],"tl":[["約4000〜2500年前","縄文時代後期〜晩期、むらが営まれる"],["1950年代","土器が見つかり、発掘調査が始まる"],["1977年","国の史跡に指定"],["整備後","史跡公園として竪穴住居などを復元"],["現在","野々市市の歴史学習の拠点の一つ"]],"who":[["御経塚の縄文人","縄文時代の終わりごろ、この地に暮らした人々"],["発掘に関わった地元の人々・研究者","土器の発見から調査・保存へとつないだ"]],"deep":["«御経塚式土器» は、北陸の縄文時代晩期の土器型式の一つ。御経塚遺跡がその標識遺跡です。","出土した石棒や土偶は、縄文人のまつりや信仰を考える資料です。後期〜晩期にはこうした «祭りの道具» が増えることが知られています。","縄文時代の後期〜晩期は、気候が寒くなった時期と考えられ、東日本では人口が減った地域もあるといわれます。その中で長く続いた御経塚のむらは注目されます。","遺跡の名前の «御経塚» は、中世以降にお経を埋めた «経塚» があったことに由来するといわれますが、縄文遺跡とは時代がまったく違います。","近くには «野々市市ふるさと歴史館» があり、御経塚遺跡の出土品を見学できます（開館日は要確認）。","竪穴住居は、地面を少しほり下げて柱を立て、屋根をかけた家。夏はすずしく冬はあたたかいといわれ、縄文時代を通じて使われました。","野々市市は、のちに加賀の守護・富樫氏が館をかまえた地でもあり、縄文から中世まで、長い歴史が重なる土地です。"],"look":["復元された竪穴住居","史跡公園の広場と説明板","出土した土器・石棒・土偶（野々市市の歴史館）","御経塚遺跡から富樫館跡など野々市の史跡へ足をのばす"],"q":["御経塚遺跡の名前のもとになった言い伝えは?","むかし、お経を埋めた «経塚» があったといわれることから。縄文のむらとは時代がちがいます。"],"koji":[],"myth":"«御経塚» の地名由来は伝承。発見の経緯・年代は資料で要確認。","img":["縄文時代","土偶","竪穴建物"],"wp":"御経塚遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Okyouzuka_Ruins_-_27.jpg",6016,4016,"御経塚遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["j:3/3d/%E9%9D%92%E6%A3%AE%E7%9C%8C%E3%81%A4%E3%81%8C%E3%82%8B%E5%B8%82%E6%9C%A8%E9%80%A0%E4%BA%80%E3%83%B6%E5%B2%A1%E5%87%BA%E5%9C%9F_%E9%81%AE%E5%85%89%E5%99%A8%E5%9C%9F%E5%81%B6-2.JPG",3711,4947,"土偶"],["c:5/5a/Yoshinogari-iseki_tateanashiki-juukyo.JPG",6016,4000,"竪穴建物"]]},{"id":"17_ogoya","n":"尾小屋鉱山","yomi":"おごやこうざん","cat":"産業","rank":"B","y":1904,"era":["meiji","taisho","showa"],"sh":"","ad":"小松市尾小屋町","st":"小松駅から車で約30分（公共交通は少なく、車が便利）","la":36.343,"lo":136.563,"hook":"山あいの小さな村が、かつては数千人がくらす «銅の町» だった。坑道の闇に、明治の熱気が眠る。","lead":"尾小屋鉱山は、小松市の山奥にあった銅の鉱山です。明治から昭和にかけて大きく発展し、鉱山で働く人とその家族で村はにぎわいました。いまは «尾小屋鉱山資料館» と、実際の坑道を歩ける «マインロード» で当時の様子を知ることができます。","story":["小松の町から山へ山へと車を走らせると、谷の奥に小さな集落があらわれます。ここが尾小屋。いまは静かな山村ですが、100年ほど前、この谷には鉱山で働く人たちの住宅がびっしりとならび、学校や病院、映画館まであったといわれます。","この山から掘り出されたのは «銅»。明治の日本は、電線や機械に使う銅をたくさん必要としていました。尾小屋の銅山は明治のはじめごろから本格的に掘られるようになり、やがて加賀藩の重臣の家がらだった横山家が経営に乗り出して、大きく発展します。","«どうやって銅を町まで運ぶの?» ――その答えが、鉱山と小松の町を結んだ小さな鉄道 «尾小屋鉄道» でした。線路の幅がせまい «軽便鉄道» で、かわいい機関車やディーゼルカーが山あいを走り、鉱石だけでなく人々の暮らしも運びました。","しかし昭和の後半になると、外国から安い銅が入ってくるようになり、日本の多くの鉱山が閉じられていきます。尾小屋鉱山も1970年代はじめに閉山。鉄道も1977年に姿を消しました。にぎやかだった村は、少しずつ静けさを取りもどしていきます。","いま、資料館では当時の道具や写真を見ることができ、マインロードでは実際の坑道を歩いて、鉱夫たちの仕事の様子を体験できます。また、小松市内には尾小屋鉄道の車両が保存されていて、«なかよし鉄道» として走る姿を見られる日もあります。暗い坑道の中で、明治・大正の人々の汗と熱気を感じてみてください。"],"tl":[["明治初期","銅山の開発が本格化"],["1904年ごろ","横山家（横山鉱業部）が経営し、大きく発展"],["1919年","尾小屋鉄道が開業（鉱山と小松を結ぶ）"],["1931年","経営が日本鉱業に移る"],["1971年","閉山"],["1977年","尾小屋鉄道が廃止"],["現在","尾小屋鉱山資料館・マインロードで公開"]],"who":[["横山隆平","旧加賀藩の重臣の家の当主。尾小屋鉱山の経営を担い発展させた"],["鉱山で働いた人々","坑道で鉱石を掘り、村の暮らしを支えた"]],"deep":["横山家は加賀藩の «加賀八家» の一つで、明治以降は実業家として鉱山経営に乗り出しました。尾小屋のほか各地の鉱山にかかわったとされます。","尾小屋鉄道は線路の幅762mmの軽便鉄道で、新小松（小松の町）と尾小屋を結んでいました。廃止後、車両の一部が小松市の «なかよし鉄道» などに保存されています。","鉱山のまわりでは、鉱石を処理するときに出る煙や水が問題になったこともあります。日本の鉱山の歴史は、産業の発展と環境の問題の両方を教えてくれます。","坑道は全長で数十kmにおよんだともいわれます。マインロードではその一部を安全に整備して公開しています。","閉山の年や経営の移り変わりは資料によって書き方が少し異なります。資料館の展示で確かめると安心です。"],"look":["尾小屋鉱山資料館（鉱石や道具、写真）","マインロード（実際の坑道を歩ける。開館期間は要確認）","尾小屋鉄道の名残（駅跡や保存車両）","谷あいの集落に残る鉱山町の雰囲気"],"q":["尾小屋鉱山で主に掘られていた金属は?","«銅»。電線や機械に欠かせない金属でした。"],"koji":[],"myth":"閉山年・経営の移り変わりの細部は資料で要確認。","img":["尾小屋鉄道","横山隆平","日本鉱業"],"wp":"尾小屋鉱山","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/JOMO_%E5%87%BA%E6%B1%90SS.JPG",3264,2448,"日本鉱業"],["c:9/94/Torigoe01.jpg",800,531,"近く: 鳥越村"],["c:5/54/R360-2019-071.jpg",1600,900,"近く: 道の駅一向一揆の里"],["c:3/32/Mitsutani_Tunnel.jpg",3993,5324,"近く: 光谷越"],["c:1/1e/Nakano_pass%2C_Ishikawa_prefecture.jpg",2432,1824,"近く: 中ノ峠"],["c:4/48/Hokutetsu_Kinmei_line_Kamashimizu_station_01.jpg",640,480,"近く: 釜清水駅"],["c:e/e9/Kobo_pond_waters.jpg",4000,3000,"近く: 弘法池"]]},{"id":"17_komatsu_hikojo","n":"小松飛行場（旧海軍小松基地）","yomi":"こまつひこうじょう","cat":"昭和","rank":"B","y":1944,"era":["showa"],"sh":"","ad":"小松市浮柳町","st":"小松駅からバスで約12分","la":36.3947,"lo":136.4068,"hook":"戦争のために海軍がつくった飛行場は、いま旅客機と戦闘機が同じ滑走路を分け合う «空の玄関»。","lead":"小松飛行場は、小松市にある空港です。はじまりは太平洋戦争のころ、日本海軍が建設した飛行場でした。戦後は航空自衛隊の小松基地となり、同時に民間の旅客機も飛ぶ «共用空港» として、北陸の空の玄関になっています。","story":["1940年代のはじめ、日本は戦争の拡大とともに、全国に次々と軍の飛行場をつくっていました。小松の海ぞいの平地にも、海軍の飛行場の建設が始まります。«なぜ小松に?» ――日本海に面した広い平地で、滑走路をのばしやすかったことが理由の一つと考えられます。","建設には、地元の人々や学生など、多くの人がかりだされたといわれます。人の手とシャベルで土を運び、平らにならしていく――つらい工事でした。飛行場は戦争の末期に使われるようになり、若い搭乗員たちが訓練などを行いました。この平らな滑走路の下には、そうした人々の汗と、戦争の時代の記憶が埋まっているのです。","1945年、戦争が終わると、飛行場はアメリカ軍に接収されます。やがて日本に返されると、1961年に航空自衛隊の小松基地が置かれました。一方で、民間の飛行機も飛ぶようになり、東京や札幌、さらには海外とも結ぶ空港に育っていきます。","小松飛行場の特徴は、一本の長い滑走路を、自衛隊の戦闘機と旅客機が一緒に使っていることです。空港のそばでは、ときどき大きなエンジン音がひびきます。«平和な空の旅» と «国の守り» が同じ場所にあるのです。","空港の近くには «石川県立航空プラザ» があり、飛行機の歴史を学ぶことができます。この飛行場の始まりが戦争だったことを思い出しながら、ここで働き、命を落とした人々にも静かに思いをはせたいものです。"],"tl":[["1940年代前半","海軍が飛行場の建設を始める"],["1944年ごろ","海軍の飛行場として使われ始める"],["1945年","終戦。アメリカ軍に接収される"],["1958年ごろ","日本側に返還される"],["1961年","航空自衛隊小松基地が置かれる"],["現在","自衛隊と民間の共用空港として運用"]],"who":[["建設に動員された人々","地元の住民や学生など、多くの人が工事にかかわった"],["海軍の搭乗員たち","戦争末期、この飛行場で訓練などを行った若者たち"]],"deep":["小松飛行場は、防衛省が管理する «共用飛行場»。自衛隊の基地と民間空港が同じ滑走路を使う仕組みで、国内には同様の空港がいくつかあります。","滑走路の長さは約2700m。大型の旅客機も離着陸できます。","毎年秋ごろには «小松基地航空祭» が開かれ、ブルーインパルスの飛行などに多くの人が集まってきました（開催は年によって異なる）。","空港周辺の騒音問題をめぐっては、住民による訴訟が長く続いてきました。基地と暮らしの関係は、今も地域の大きなテーマです。","戦時中に全国につくられた軍の飛行場の多くは、戦後に農地や工場用地に戻りました。小松のように空港として使われ続けた例は、その一部です。"],"look":["石川県立航空プラザ（航空機の展示）","空港の展望デッキから見る旅客機と自衛隊機","周辺に残る戦時中の歴史の説明（資料館などで）"],"q":["小松飛行場の滑走路を使っているのは、旅客機ともう一つは何?","航空自衛隊の飛行機。自衛隊と民間の «共用空港» です。"],"koji":[],"myth":"建設開始年・返還年の細部は資料で要確認。","img":["小松基地","航空自衛隊","石川県立航空プラザ"],"wp":"小松飛行場","rel":{"ev":[],"grave":[]},"ph":[["c:e/ec/Komatsu_airport_terminal_building.jpg",640,480,"小松飛行場"],["c:3/37/Komatsu_airfield_aerial_photograph.jpg",7251,5438],["c:b/b0/Komatsu_Airport_Aerial_photograph_1975.jpg",6053,3885],["c:9/90/Japan_air_self_defense_force_Mitsubishi_F-15_306SQ_RJNK.JPG",5018,3345],["c:f/f3/Japan_air_self_defense_force_Mitsubishi_F-15J_303SQ_RJNK.JPG",4214,2810],["c:b/b9/Japan_air_self_defense_force_Mitsubishi_UH-60J_RJNK.JPG",3888,2592],["c:3/3a/Japan_air_self_defense_force_Raytheon_U-125A_RJNK.JPG",3047,2031],["c:4/47/KomatsuAirportTerminal_02.jpg",2303,895]]},{"id":"17_nishida","n":"西田幾多郎記念哲学館","yomi":"にしだきたろうきねんてつがくかん","cat":"学び","rank":"B","y":1911,"era":["meiji","taisho","showa"],"sh":"","ad":"かほく市内日角","st":"JR宇野気駅から歩いて約20分","la":36.728,"lo":136.716,"hook":"«考えるとは何か?» ――日本を代表する哲学者のふるさとに、考えるための建物が建っている。","lead":"西田幾多郎（にしだきたろう）は、明治から昭和にかけて活躍した日本の哲学者です。いまのかほく市に生まれ、『善の研究』という本で «日本で初めての独自の哲学» と言われる考えを示しました。記念哲学館は、その人生と考えを学べる博物館です。","story":["1870年、西田幾多郎は加賀国河北郡の森村（いまのかほく市）で生まれました。家は村の庄屋。幾多郎は勉強が好きで、金沢の学校に進みます。そこで出会ったのが、のちに禅を世界に広める鈴木大拙でした。二人は同い年、同じ石川の出身。一生の友になります。","若いころの幾多郎の人生は、けっして順調ではありませんでした。大学では «選科生» という立場で、肩身のせまい思いをしたといわれます。家族の病気や死にも何度も向き合いました。«人が生きるとはどういうことか?» ――その問いが、幾多郎を哲学へと向かわせたのかもしれません。","金沢の第四高等学校で教えながら、幾多郎は座禅にも打ちこみました。そして1911年、『善の研究』を出版します。«見る私» と «見られるもの» に分かれる前の、生き生きとした経験――それを «純粋経験» と呼びました。西洋の哲学を学びながら、東洋の考え方も取り入れた、新しい哲学でした。","その後、京都帝国大学の教授となり、多くの弟子を育てます。弟子たちのグループは «京都学派» と呼ばれました。京都で幾多郎が毎日考えごとをしながら歩いた道は、いま «哲学の道» として観光名所になっています。","1945年6月、幾多郎は戦争の終わりを見ることなく、鎌倉で亡くなりました。ふるさとの宇ノ気には、建築家・安藤忠雄が設計した哲学館が2002年に開館します。コンクリートの静かな空間を歩くうちに、自然と «考える» 時間が生まれる――そんな建物です。"],"tl":[["1870年","加賀国河北郡森村（現・かほく市）に生まれる"],["1890年代","第四高等中学校などで学び、鈴木大拙と親しくなる"],["1911年","『善の研究』を出版"],["1910年代","京都帝国大学で教え、のちに教授に"],["1945年","鎌倉で亡くなる"],["2002年","石川県西田幾多郎記念哲学館が開館"]],"who":[["西田幾多郎","哲学者。『善の研究』の著者で、京都学派の中心"],["鈴木大拙","同郷・同い年の親友。禅を世界に広めた"],["安藤忠雄","哲学館の建物を設計した建築家"]],"deep":["『善の研究』のキーワード «純粋経験» は、主観（わたし）と客観（もの）に分かれる前の、ありのままの経験のこと。西田哲学の出発点です。","西田は後に «場所» «絶対矛盾的自己同一» といった独特の言葉で考えを深めました。難しいことで有名ですが、東洋の «無» の考えを哲学で表そうとした試みとされます。","京都の «哲学の道» は、西田や弟子たちが散歩しながら思索したことから名づけられたといわれます。","西田と鈴木大拙は、金沢の学校での同窓で、生涯にわたり手紙をやりとりしました。二人の記念館は、かほく市と金沢市にそれぞれあります。","哲学館には、西田の書や遺品、研究書を集めた図書室などがあり、講座やイベントも開かれています。"],"look":["安藤忠雄設計の建物（光と影の空間）","西田幾多郎の書や遺品の展示","ホワイエや «思索の空間» での静かな時間","近くの西田の生家跡（旧宅跡）"],"q":["西田幾多郎が1911年に出版した代表作は?","『善の研究』。«純粋経験» という考えを示しました。"],"koji":[{"w":"人は人 吾はわれ也 とにかくに 吾行く道を 吾は行くなり","m":"西田幾多郎の歌として知られる。人と比べず、自分の道を進もうという意味"}],"myth":"哲学の道の命名由来は諸説あり。","img":["西田幾多郎","善の研究","京都学派"],"wp":"石川県西田幾多郎記念哲学館","rel":{"ev":[],"grave":[]},"ph":[["c:7/79/Nishida_Museum.jpg",1600,1200,"石川県西田幾多郎記念哲学館"],["c:1/13/Portrait-of-Kitaro-Nishida.png",1078,1456,"西田幾多郎"],["c:1/13/Portrait-of-Kitaro-Nishida-1903.jpg",224,341,"善の研究"],["c:9/92/Japan_Kyoto_philosophers_walk_DSC00297.jpg",2592,1728,"京都学派"]]},{"id":"17_daisetsu","n":"鈴木大拙館","yomi":"すずきだいせつかん","cat":"学び","rank":"B","y":2011,"era":["meiji","showa","heisei"],"sh":"","ad":"金沢市本多町3丁目","st":"JR金沢駅からバスで約15分、«本多町» 下車徒歩約4分","la":36.5594,"lo":136.6597,"hook":"«ZEN» を世界のことばにした男。彼の館では、水面をながめるだけで心がしずまる。","lead":"鈴木大拙（すずきだいせつ）は、金沢に生まれた仏教学者です。英語で本をたくさん書き、日本の禅（ZEN）の考えを世界に広めました。鈴木大拙館は、大拙が生まれた場所の近くに2011年にできた記念館で、「考える」ための静かな空間になっています。","story":["1870年、大拙（本名・貞太郎）は、いまの金沢市本多町で、加賀藩の医者の家に生まれました。小さいころに父を亡くし、家は貧しかったといいます。学校の授業料が払えず、途中でやめなければならないこともありました。","金沢の学校では、のちに哲学者となる西田幾多郎と同級生になります。«人間とは?» «生きるとは?» ――二人はそんな話をしながら友情を深めていきました。大拙はやがて鎌倉の円覚寺で禅の修行をし、師から «大拙» という名前をもらいます。","20代の終わり、大拙はアメリカにわたり、10年以上そこで暮らしました。出版社で働きながら英語をみがき、仏教の本を翻訳します。«禅は言葉では伝えられない» といわれるものを、あえて英語で伝えようとしたのです。","大拙の書いた『禅と日本文化』などの本は、世界中で読まれました。«ZEN» ということばが外国でも通じるようになったのは、大拙の力が大きいといわれます。90歳をこえても研究を続け、1966年に96歳で亡くなりました。","鈴木大拙館は、建築家・谷口吉生の設計です。いちばんの見どころは «水鏡の庭»。浅い水面に、ときどき小さな波紋が広がります。何も書かれていない、何も説明されていない――でも、だからこそ «自分で考える» 時間がそこにあります。"],"tl":[["1870年","金沢の本多町に生まれる"],["1890年代","鎌倉・円覚寺で修行し «大拙» の号を受ける"],["1897年","アメリカへわたる"],["1909年","帰国"],["1938年","英語で書いた禅と日本文化の本が出版される"],["1966年","96歳で亡くなる"],["2011年","鈴木大拙館が開館"]],"who":[["鈴木大拙","仏教学者。禅を英語で世界に紹介した"],["西田幾多郎","金沢の学校での同級生で、一生の友"],["谷口吉生","鈴木大拙館を設計した建築家"]],"deep":["«大拙» は、禅の師・釈宗演から授かった居士号（在家の修行者の名）。«大いにつたない» という意味で、へりくだった名前です。","大拙の英語の本は、アメリカやヨーロッパの思想家や芸術家にも影響を与えたといわれます。«禅ブーム» の土台をつくった一人です。","鈴木大拙館は «玄関棟» «展示棟» «思索空間棟» の三つの建物を回廊でつなぎ、展示を見て、学び、考えるという流れで歩くように設計されています。","大拙は妻ビアトリスとともに、日本の仏教の研究と英語での紹介に力をつくしました。","大拙は晩年まで鎌倉の東慶寺の松ヶ岡文庫で研究を続けました。墓も東慶寺にあります。","大拙の言葉 «無心» は、何も考えないことではなく、とらわれのない自由な心のこと。大拙館の «水鏡の庭» は、その心を感じてもらうための場所だともいわれます。"],"look":["«水鏡の庭» と、ときどき広がる水の波紋","思索空間棟（静かに座って考える部屋）","大拙の書や言葉の展示","周辺の本多の森（美術館・博物館が集まる）"],"q":["鈴木大拙が世界に広めた日本の考えは?","«禅（ZEN）»。英語の本を通して世界に紹介しました。"],"koji":[],"myth":"出版年など細部は版によって異なるので要確認。","img":["鈴木大拙","谷口吉生","円覚寺"],"wp":"鈴木大拙館","rel":{"ev":["basho"],"grave":[]},"ph":[["c:5/5a/%E9%88%B4%E6%9C%A8%E5%A4%A7%E6%8B%99%E9%A4%A8001.jpg",3861,2574,"鈴木大拙館"],["c:5/5e/%E9%88%B4%E6%9C%A8%E5%A4%A7%E6%8B%99%E9%A4%A8003.jpg",3861,2574],["c:e/e9/DTSuzukiMuseum_M003.jpg",2048,3072],["c:e/ea/DTSuzukiMuseum_M001.jpg",3072,2048],["c:d/de/Daisetsu_Teitar%C5%8D_Suzuki_photographed_by_Shigeru_Tamura.jpg",2059,2809,"鈴木大拙"],["c:9/9f/Yoshio_Taniguchi_cropped_2_Yoshio_Taniguchi_20211103.jpg",376,474,"谷口吉生"],["c:e/e9/Engakuji_Sanmon_Kamakura.jpg",800,600,"円覚寺"]]},{"id":"17_funakakushi","n":"能登金剛（巌門・義経の舟隠し）","yomi":"のとこんごう","cat":"伝承","rank":"B","y":1187,"era":["kamakura","showa"],"sh":"","ad":"羽咋郡志賀町牛下ほか","st":"JR羽咋駅から車で約30分（公共交通は少ない）","la":36.98,"lo":136.723,"hook":"«追っ手から逃げる義経の舟48そうが、ここに隠れた»――荒波がけずった岩の入り江に残る伝説。","lead":"能登金剛は、能登半島の西の海岸に続く、約30kmの岩の海岸です。波にけずられた洞くつや断崖が続き、なかでも «巌門（がんもん）» や «義経の舟隠し» が有名です。源義経が奥州へ逃げるとき、ここに舟を隠したという伝説が残っています。","story":["日本海の荒い波が、何万年もかけて岩をけずりました。その結果生まれたのが、能登金剛の断崖やほら穴です。朝鮮半島の名勝 «金剛山» になぞらえて、この名前がついたといわれます。","ここで語りつがれているのが、源義経の伝説です。兄・源頼朝に追われた義経は、少ない家来とともに、北陸道をとおって奥州（東北）の藤原氏のもとへ逃げました。そのとき、«舟で海を行こう» と能登の海岸に立ち寄り、細長い入り江に48そうの舟を隠した――それが «義経の舟隠し» の言い伝えです。","«本当にそんなにたくさんの舟が?» そう思って入り江をのぞくと、両側を高い岩にかこまれ、外の海からは見えにくい場所だとわかります。史実かどうかはわかりませんが、«隠すならここだ» と思わせる地形なのです。","巌門は、岩が波にくりぬかれて、門のような穴があいた場所です。穴をくぐると向こうの海が見え、遊覧船で近くを見ることもできます。近くの «ヤセの断崖» は、松本清張の小説『ゼロの焦点』の舞台として知られるようになりました。","2024年1月の能登半島地震では、この海岸にも大きな被害が出ました。ヤセの断崖の一部が崩れるなど、景色が変わった場所もあります。訪れるときは最新の情報を確かめ、被災した地域の人々への思いやりを忘れずに歩きましょう。"],"tl":[["1187年ごろ","源義経が北陸を通って奥州へ逃れる（舟隠しの伝説の時代）"],["江戸時代","海岸の奇岩が名所として知られる"],["1959年","『ゼロの焦点』が刊行され、ヤセの断崖が有名に"],["1968年","能登半島国定公園に指定"],["2024年","能登半島地震で海岸の一部が崩れるなどの被害"]],"who":[["源義経","平家をほろぼした武将。兄に追われ奥州へ逃れた"],["弁慶","義経の家来。北陸の各地に伝説が残る"],["松本清張","推理小説『ゼロの焦点』の作者。能登の断崖を舞台に選んだ"]],"deep":["義経の奥州落ちのルートは、『義経記』などの物語に書かれていますが、細かな道すじは史実として確かめられていません。北陸各地の伝説は、その物語が広まったことと関係していると考えられます。","«48そう» という舟の数は伝説の中の数字で、史料で確認できるものではありません。","能登金剛は、福浦から富来（とぎ）の方までおよそ30kmにわたる海岸の総称です。巌門・機具岩（はたごいわ）・ヤセの断崖などの見どころが点在します。","『ゼロの焦点』は1961年と2009年に映画化され、断崖の場面が印象的に描かれました。","能登半島地震では海岸が隆起した場所もあり、地形そのものが大きく変わりました。地質学的にも注目されています。"],"look":["巌門（波がくりぬいた岩の門）","義経の舟隠し（細長い入り江）","ヤセの断崖（立ち入りの制限を確認）","遊覧船から見る海岸（運航状況は要確認）"],"q":["義経が隠したと伝わる舟の数は?","48そう。ただし伝説の中の数字です。"],"koji":[],"myth":"舟隠しは伝説で史実ではない。地震後の立ち入り状況は変化中。","img":["源義経","ゼロの焦点","能登半島国定公園"],"wp":"能登金剛","rel":{"ev":[],"grave":[]},"ph":[["c:1/1d/Ganmon2023.jpg",3648,2736,"能登金剛"],["c:e/ea/Notokongo_pleasure_ship.jpg",3191,2257],["c:c/c7/The_Famous_Scenes_of_the_Sixty_States_33_Noto.jpg",1071,1559],["c:9/91/NotoCoast.jpg",1250,854],["c:7/7d/Minamoto_no_Yoshitsune.jpg",1440,1724,"源義経"],["c:1/1d/Sotoura.jpg",640,480,"能登半島国定公園"]]},{"id":"17_rokkosaki","n":"禄剛埼灯台","yomi":"ろっこうさきとうだい","cat":"近代","rank":"B","y":1883,"era":["meiji"],"sh":"","ad":"珠洲市狼煙町","st":"のと里山空港から車で約1時間。バス停 «狼煙» から歩いて約10分","la":37.527,"lo":137.328,"hook":"能登半島のいちばん先。朝日が海から昇り、夕日が海に沈む――明治の白い灯台が140年見てきた景色。","lead":"禄剛埼灯台（ろっこうさきとうだい）は、能登半島の先っぽ、珠洲市の «狼煙（のろし）» という町にある白い石造りの灯台です。明治時代の1883年に初めて光をともしました。日本海を行き来する船の安全を守ってきた、歴史ある灯台です。","story":["能登半島は、日本海につき出た大きな «手» のような形をしています。その先には、昔から船がたくさん行き来していました。北海道と大阪を結んだ «北前船» もこの沖を通りました。でも、岬のまわりは岩が多く、夜や嵐の日にはとても危険な場所でした。","«ここに光があれば、船が迷わずにすむのに» ――その願いがかなったのが、明治の1883年です。明治政府は、外国の技術を取り入れて、全国の岬に灯台をつくっていました。禄剛埼灯台もその一つで、地元の石を積みあげて建てられたといわれます。","この灯台には、ちょっとめずらしい飾りがあります。入り口の上に «菊の紋章» がついているのです。«なぜ灯台に天皇家の紋が?» と思いますよね。明治の初めごろにつくられた灯台の一部には、こうした紋章がつけられていたといわれます。","地名の «狼煙» も、歴史を感じさせます。昔、海を見張って合図の煙（のろし）をあげた場所だったから、と伝えられています。灯台ができる前から、ここは «海を見守る場所» だったのかもしれません。","灯台の立つ岬は、日本海からのぼる朝日と、日本海に沈む夕日を同じ場所で見られることで知られています。2024年の能登半島地震では周辺も大きな被害を受けました。訪れるときは最新の情報を確かめ、復興に向かう地域の人々を思いながら景色をながめたいものです。"],"tl":[["江戸時代","北前船が能登の沖を行き来する"],["1883年","禄剛埼灯台が初点灯"],["昭和時代","灯台の管理が自動化へ向かう"],["1998年ごろ","«日本の灯台50選» に選ばれる"],["2024年","能登半島地震で周辺が大きな被害を受ける"]],"who":[["明治政府の灯台技術者たち","全国の岬に西洋式灯台を建てた"],["灯台守","灯台に住みこみ、光を守った人々"],["北前船の船乗りたち","能登の沖を行き来し、岬の危険とたたかった"]],"deep":["«禄剛埼» の «埼» は、海につき出た土地を表す字。灯台の正式名称では «崎» ではなく «埼» が使われています。","灯台の高さは地上から約12m。岬の崖の上に立つので、海面からの光の高さはずっと高くなります。","明治の灯台づくりは、イギリス人技師R.H.ブラントンらの指導で始まり、その後日本人の技術者も育ちました。禄剛埼灯台の設計者については、はっきりしない点があります。","入口上の菊の紋章は、ほかの灯台ではあまり見られない特徴として知られます。","灯台の中は、特別な公開日をのぞいてふだんは入れません。外からの見学が基本です。","灯台の近くには、ここから各地までの距離を示す «道標» があり、ウラジオストクや東京までのキロ数が書かれています。能登半島の先が、日本海を通じて世界とつながっていることを実感できます。"],"look":["白い石造りの灯台の姿","入口上の菊の紋章","岬からの日本海の眺め（朝日・夕日）","岬の «道標»（各地までの距離を示す）"],"q":["禄剛埼灯台がある町の名前は?","«狼煙（のろし）»。昔、合図の煙をあげた場所と伝わります。"],"koji":[],"myth":"狼煙の地名由来は伝承。設計者は不明点あり。","img":["能登半島","北前船","珠洲市"],"wp":"禄剛埼灯台","rel":{"ev":[],"grave":[]},"ph":[["c:a/ac/Rokkosaki_Lighthouse_4.jpg",4608,3456,"禄剛埼灯台"],["c:0/07/Rokkosaki_Lighthouse_3.jpg",3432,4590],["c:c/c7/Rokkozaki_Senjojiki.jpg",1198,1614],["c:f/f6/Rokkosaki_Lighthouse_1.jpg",1610,1194],["c:e/e9/Rokkosaki_Lighthouse_2.jpg",1588,1164],["c:d/d3/Rokkosaki_Todai.jpg",1024,768],["c:3/3b/Noto_Peninsula_Ishikawa_Japan_SRTM.jpg",614,760,"能登半島"],["c:7/71/Kitamaebune_by_Iida_Yonezo_2.jpg",1024,768,"北前船"]]},{"id":"17_kinken","n":"金劔宮（白山七社）","yomi":"きんけんぐう","cat":"寺社","rank":"B","y":1200,"era":["heian","kamakura"],"sh":"","ad":"白山市鶴来日詰町","st":"北陸鉄道石川線 鶴来駅から歩いて約10分","la":36.448,"lo":136.631,"hook":"«鶴来» の町名はもともと «剣（つるぎ）»。町の名前の由来になった、剣の神社。","lead":"金劔宮（きんけんぐう）は、白山市鶴来にある古い神社です。白山の神をまつる神社のなかでも大事な «白山七社» の一つに数えられてきました。«金運の神社» としても親しまれ、多くの人がお参りに来ます。","story":["白山は、石川・岐阜・福井にまたがる高い山です。昔から «神さまの山» としてあがめられ、そのふもとには白山の神をまつる神社がいくつも建てられました。なかでも大事な七つの神社を «白山七社» と呼び、金劔宮はその一つでした。","この神社のある町の名は «鶴来（つるぎ）»。もともとは «剣（つるぎ）» と書いたといわれます。神社の名前にも «劔» の字が入っていますね。«なぜ剣?» ――神社の名前が町の名になり、のちに縁起のよい «鶴来» の字にかえられた、と伝わっています。","鶴来は、白山へ向かう道の入り口の町でした。手取川が山から平野へ出るところにあり、山の木や物資、参拝の人々が行き交いました。金劔宮は、そんな町の守り神として大切にされてきたのです。","この神社には、源義経と弁慶が奥州へ逃げる途中に立ち寄った、という言い伝えもあります。北陸には義経伝説がたくさん残っていて、金劔宮もその一つです。","いまの金劔宮は、«金運» のご利益で知られ、宝くじを持ってお参りする人もいます。長い石段と森にかこまれた境内に立つと、白山のふもとの古い信仰の空気を感じることができます。"],"tl":[["平安時代","白山信仰が広まり、白山七社が形づくられる"],["中世","白山七社の一つとして信仰を集める"],["江戸時代","鶴来の町の守り神として親しまれる"],["明治時代","近代の社格制度のもとで整えられる"],["現在","«金運の神社» として多くの参拝者が訪れる"]],"who":[["白山の神々","白山信仰でまつられる神々"],["源義経・弁慶","立ち寄ったという伝説がある"],["鶴来の町の人々","神社を守り、町の祭りを支えてきた"]],"deep":["白山七社は、白山本宮（いまの白山比咩神社）・金劔宮・岩本宮・三宮など、白山の神をまつる主な神社のグループとされます。数え方には時代による違いがあります。","白山信仰は、奈良時代に泰澄（たいちょう）が白山を開いたという伝承から始まるとされます。加賀・越前・美濃の三方向から登る道（禅定道）がありました。","«鶴来» の地名が «剣» から来たという説は地元で広く知られていますが、いつ字が変わったかなどは詳しくわかっていません。","金劔宮の祭神は、瓊瓊杵尊（ににぎのみこと）とされています。","義経・弁慶の伝説は、『義経記』や能・歌舞伎の «勧進帳» が広まったことで、北陸の各地に語りつがれるようになったと考えられます。","鶴来は白山の登山口の町として、江戸時代には «白山へ向かう人が泊まる町» でもありました。酒づくりもさかんで、白山の伏流水を使った酒蔵がいまも残っています。","白山七社の神社は、明治の神仏分離で大きく姿を変えました。それまで神と仏をいっしょにまつっていた白山信仰の寺や社が分けられ、今の神社の形になっています。"],"look":["石段と社殿、境内の森","«金運» のお守り（参拝者に人気）","鶴来の古い町並み（酒蔵など）","近くの白山比咩神社とあわせて参拝"],"q":["鶴来の町名は、もともとどんな字で書かれていたといわれる?","«剣（つるぎ）»。金劔宮の «劔» とつながっています。"],"koji":[],"myth":"創建年は不明。義経伝説・地名の由来は伝承。","img":["白山比咩神社","白山信仰","泰澄"],"wp":"金劔宮","rel":{"ev":[],"grave":[]},"ph":[["j:d/d0/%E7%99%BD%E5%B1%B1%E6%AF%94%E5%92%A9%E7%A5%9E%E7%A4%BE_%E5%A4%96%E6%8B%9D%E6%AE%BF.JPG",3648,2736,"白山比咩神社"],["c:4/4f/Hakusan_Shrine_in_Murodo_2008-7-1.jpg",1280,700,"白山信仰"],["c:0/0b/Tsurugi_Station_2021-03_ac_%282%29.jpg",5943,3952,"近く: 鶴来駅"],["c:b/b0/Hokutetsu_Nakatsurugi_station_01.jpg",640,480,"近く: 中鶴来駅"],["c:9/96/Kaga-ichinomiya-station.jpg",2904,2080,"近く: 加賀一の宮駅"],["c:f/f9/Tsurugi_High_School.jpg",3456,2304,"近く: 石川県立鶴来高等学校"],["c:b/be/R157-2020-060.jpg",1920,1078,"近く: 道の駅しらやまさん"]]},{"id":"17_shiramine","n":"白峰（出作りの村・重伝建）","yomi":"しらみね","cat":"町","rank":"B","y":1700,"era":["edo","meiji"],"sh":"国の重要伝統的建造物群保存地区","ad":"白山市白峰","st":"金沢駅から路線バス（乗り換えあり）で2時間前後。車が便利","la":36.176,"lo":136.626,"hook":"雪は3m、家は3階建て。白山のふもとの村人は、夏になると山の奥の «出作り» 小屋へ引っこした。","lead":"白峰は、白山のふもとにある山あいの集落です。雪がとても多い土地で、大きな石置き屋根や、何階建てにもなる家々が並んでいます。かつて村の人々は、夏になると山奥の小屋に移り住んで焼畑をする «出作り（でづくり）» という暮らしをしていました。町並みは国の重要伝統的建造物群保存地区に選ばれています。","story":["冬の白峰は、雪の世界です。多い年には3mをこえる雪がつもり、家の1階がすっぽりうもれてしまうことも。«じゃあどうやって暮らすの?» ――答えは、家を高くすることでした。白峰の家には、3階建て、4階建てのものがあり、上の階に物をしまい、雪にうもれない窓から光をとり入れたのです。","白峰の人々には、もう一つの住まいがありました。春から秋にかけて、家族で山の奥へ入り、«出作り小屋» で暮らすのです。そこでは山の斜面を焼いて畑にする «焼畑» をして、ヒエやアワ、ソバなどを育てました。平らな田んぼがほとんどない山の村の、知恵の暮らしでした。","江戸時代、白山のふもとの村々は、加賀藩ではなく幕府が直接治める «天領» でした。«なぜ?» ――白山の山頂の領有をめぐって、加賀と越前の争いがあり、幕府が預かる形になったといわれます。白峰には村を代表する大庄屋の «山岸家» があり、その大きな屋敷がいまも残っています。","白峰は、白山に登る人々の入り口でもありました。«白山禅定道» と呼ばれる信仰の道をたどって、多くの修行者や参拝者が山頂を目指したのです。また、この地では手でつむいだ糸で織る «牛首紬（うしくびつむぎ）» もつくられてきました。","いま白峰の町を歩くと、石垣、大きな屋根、木の格子、雪をよける工夫があちこちに見つかります。冬には «雪だるままつり» が開かれ、家々の前にたくさんの雪だるまが並びます。雪とともに生きてきた村の、あたたかい景色です。"],"tl":[["中世","白山信仰の登山口の一つとして知られる"],["1660年代","白山ふもとの村々が幕府の直轄（天領）となる"],["江戸〜昭和","出作りと焼畑の暮らしが続く"],["1889年","白峰村となる"],["2005年","合併で白山市の一部となる"],["2012年","国の重要伝統的建造物群保存地区に選定"]],"who":[["山岸家","白峰の大庄屋。大きな屋敷が残る"],["出作りの人々","夏に山奥の小屋で焼畑をした村人たち"],["泰澄","白山を開いたと伝わる奈良時代の僧"]],"deep":["白山ふもとの «白山麓十八ヶ村» は、江戸時代前期（1660年代）に幕府の直轄地（天領）となり、明治まで続いたとされます。山頂の帰属をめぐる加賀・越前の争いが背景にあったといわれます。","旧山岸家住宅は、白峰の大庄屋の家で、国の重要文化財に指定されています（見学はできない場合があるので要確認）。","«出作り» は、本村の家とは別に山の中に «出作り小屋» を持ち、季節や一年中そこで暮らす方式。昭和の中ごろまで続いた家もありました。","白峰の家は、雪の重さにたえるための太い柱や梁、土蔵のような厚い壁が特徴です。窓の少ない壁には、冬の寒さを防ぐ工夫があります。","牛首紬は、玉繭（2匹の蚕が一緒につくった繭）から糸をひく独特の紬で、国の伝統的工芸品です。«釘を抜くほど丈夫»（釘抜紬）と言われました。"],"look":["3階建て・4階建ての民家の並ぶ町並み","旧山岸家住宅の外観","白山禅定道の入口や白山への道","冬の «雪だるままつり»（毎年の開催は要確認）"],"q":["夏のあいだ山奥の小屋で焼畑をする白峰の暮らしを何と呼ぶ?","«出作り（でづくり）»。平地の少ない山村の知恵でした。"],"koji":[],"myth":"天領になった経緯の細部には諸説あり。","img":["白山","牛首紬","白山市"],"wp":"白峰村","rel":{"ev":[],"grave":[]},"ph":[["c:4/4f/Hakusan_Shrine_in_Murodo_2008-7-1.jpg",1280,700,"白峰村"],["c:d/d4/Shiramine_old_town01.jpg",4608,3456],["c:8/83/Murodo_of_Mount_Haku_2016-07-23.jpg",5184,3456],["c:3/38/Ichinose_Visitor_Center.jpg",6000,4000],["c:3/3a/Hyakuman-gan_Rock.JPG",5184,3456],["c:5/5b/771014_Kuwashima_village_and_circular_school_building_aerial.jpg",648,647],["c:e/eb/Mount_Haku_from_Onanjimine_2011-07-17.jpg",2560,1707,"白山"],["c:c/c6/Coin_purse_made_of_Ushikubitsumugi.jpg",960,852,"牛首紬"]]},{"id":"17_choryutei","n":"長流亭（大聖寺藩の休憩所）","yomi":"ちょうりゅうてい","cat":"大名屋敷","rank":"B","y":1709,"era":["edo"],"sh":"国の重要文化財","ad":"加賀市大聖寺八間道","st":"大聖寺駅（IRいしかわ鉄道）から歩いて約15分","la":36.305,"lo":136.314,"hook":"川のほとりの小さな «お殿さまの休けい所»。建ってから300年以上、ほぼそのままの姿で残る。","lead":"長流亭（ちょうりゅうてい）は、大聖寺藩の3代藩主・前田利直が、江戸時代の1709年に建てた休憩所です。大聖寺川のほとりにある小さな建物で、藩主が川遊びや休けいに使いました。国の重要文化財で、公開日には中を見学できます。","story":["大聖寺の町を流れる大聖寺川。その川べりに、小さな瓦屋根の建物がひっそりと建っています。これが長流亭です。«お殿さまの建物なのに、こんなに小さいの?» と思うかもしれません。でも、ここはお城ではなく、ほっとひと息つくための «休けい所» でした。","建てたのは、大聖寺藩の3代藩主・前田利直です。利直は、川を舟で行き来したり、景色を楽しんだりするために、この亭をつくったと伝えられます。川の流れが長く続くようにと願いをこめた «長流» という名前も、すてきですね。","長流亭は、茶室のような落ち着いたつくりで、細かいところまでていねいに仕上げられています。天井や欄間（らんま）、窓の形などに、江戸時代の職人のこだわりが見られます。","この建物は «小堀遠州（こぼりえんしゅう）が設計した» という言い伝えがあります。遠州は江戸時代のはじめの有名な茶人・作庭家です。しかし、遠州は長流亭ができるより60年ほど前に亡くなっています。«遠州風のつくり» が、いつのまにか «遠州が設計» という話になったのかもしれません。","300年以上の時を経て、建物はたびたび修理されてきました。すぐそばには藩邸の跡や江沼神社があり、大聖寺の城下町の中心だった場所です。川の流れを見ながら、殿さまがどんな景色をながめたのか、想像してみてください。"],"tl":[["1639年","大聖寺藩が成立"],["1709年","3代藩主・前田利直が長流亭を建てる"],["1871年","廃藩置県で大聖寺藩が終わる"],["昭和時代","国の重要文化財に指定"],["現在","公開日に内部を見学できる"]],"who":[["前田利直","大聖寺藩3代藩主。長流亭を建てた"],["小堀遠州","設計したという伝承がある江戸初期の茶人（年代は合わない）"]],"deep":["長流亭は «大聖寺藩の藩主の休憩所» として残るめずらしい建物で、江戸時代中期の数寄屋風の建築として価値が高いとされます。","小堀遠州（1579〜1647）の設計という話は、年代からみて事実ではなく、遠州の作風を思わせる建物だという意味で語られてきたと考えられます。","建物のすぐ前は大聖寺川で、藩主が舟で行き来したと伝わります。川からのながめを意識してつくられているといわれます。","近くの江沼神社は、大聖寺藩の藩邸の庭園の一部を受けついでいるとされ、あわせて見ると城下町の中心部の姿がわかります。","長流亭は常時公開ではなく、公開日が決まっています。訪れる前に加賀市の案内で確認しましょう。","大聖寺藩の藩邸（お屋敷）は大聖寺川の近くにあり、長流亭はその一部のような場所でした。藩主にとって、政治の場からほんの少し離れて息をつける «となりの小さな別荘» だったといえます。"],"look":["川ぞいに建つ長流亭の外観","内部の天井・欄間・窓のつくり（公開日に）","すぐ近くの江沼神社と庭園","大聖寺の城下町の町並み"],"q":["長流亭を建てたのは大聖寺藩の何代目の藩主?","3代藩主・前田利直です。"],"koji":[],"myth":"小堀遠州設計説は伝承（年代が合わない）。","img":["大聖寺藩","前田利直","小堀政一"],"wp":"長流亭","rel":{"ev":[],"grave":[]},"ph":[["c:2/2d/Daisyoji_Enuma-jinja_2021-03_ac_%282%29.jpg",5863,3899,"長流亭"],["c:3/3c/Daisyoji_Enuma-jinja_2021-03_ac_%283%29.jpg",5863,3899],["c:6/65/Daisyoji_Enuma-jinja_2021-03_ac_%281%29.jpg",5863,3899],["c:a/ad/260605_Choryu-tei%2C_Enuma-jinja_Kaga_Ishikawa_pref_Japan02s3.jpg",5472,3648],["c:5/5e/Choryu-tei_1935.jpg",1036,736],["c:6/66/Enuma-jinja_1925.jpg",1069,683],["c:c/ca/Choryu-tei_1935_B.jpg",943,751],["c:9/92/260718_Yamanoshita_Jiingun_Kaga_Ishikawa_pref_Japan03s3.jpg",5472,3648,"大聖寺藩"]]},{"id":"17_onoshou","n":"大野庄用水","yomi":"おおのしょうようすい","cat":"産業","rank":"B","y":1590,"era":["azuchi","edo"],"sh":"","ad":"金沢市長町ほか","st":"JR金沢駅からバスで約10分、«香林坊» 下車徒歩約5分","la":36.5625,"lo":136.65,"hook":"武家屋敷の土塀にそって流れる水。この小川は、城下町をつくるための «ものを運ぶ道» だった。","lead":"大野庄用水（おおのしょうようすい）は、金沢の長町武家屋敷跡のそばを流れる用水です。金沢でいちばん古い用水の一つといわれ、城下町づくりの材料を運んだり、生活の水や防火に使われたりしてきました。いまは土塀と石畳の景色によく似合う、金沢の名物の一つです。","story":["金沢の長町を歩くと、黄土色の土塀と石畳の道に、さらさらと水の流れる小川が寄りそっています。«きれいな川だなあ» と思うだけではもったいない。この用水は、金沢の町が生まれるころから、町を支えてきた大事な «道» だったのです。","大野庄用水は、犀川から水を引き、金沢の町を通って海の方へ流れていました。その流れを使って、城や町をつくるための木材などが運ばれたと伝わります。そのため «御荷川（おにがわ）»、つまり «荷物を運ぶ川» とも呼ばれました。","用水が掘られた時期は、はっきりとはわかっていません。前田利家が金沢に入るよりも前、戦国時代にさかのぼるという説もあります。«金沢で最も古い用水» と言われるのは、そのためです。","江戸時代、用水ぞいには加賀藩の中級の武士たちの屋敷が並びました。用水の水は、庭の池に引きこまれたり、火事のときの消火に使われたりしました。武家屋敷の庭の中には、用水の水を取り入れた美しい庭園が今も残っています。","いま、夏の夕方には用水の水音がすずしく、冬には土塀に «こも» をかけて雪から守る景色が見られます。«町をつくるための水路» が、400年の時をへて «町を美しく見せる水路» になった――大野庄用水は、そんな時間の流れも運んでいます。"],"tl":[["戦国時代〜安土桃山","用水が掘られたとされる（時期は諸説）"],["1583年","前田利家が金沢に入る"],["江戸時代","用水ぞいに武家屋敷が並ぶ。資材運搬・防火・庭の水に利用"],["明治以降","生活用水・農業用水として使われ続ける"],["現在","長町武家屋敷跡の景観の中心として保存"]],"who":[["前田利家","金沢城に入り城下町づくりを始めた"],["加賀藩の武士たち","用水ぞいの屋敷に住み、庭に水を引いた"],["用水を守る人々","水路の清掃や管理を続けてきた地元の人たち"]],"deep":["金沢の町には、大野庄用水・鞍月用水・辰巳用水など、数多くの用水が流れています。総延長は150kmにもなるといわれ、«用水の町» と呼ばれます。","«御荷川» の名は、城づくりの資材を運んだことに由来すると伝わりますが、史料による裏づけには限りがあります。","長町の武家屋敷 «野村家» の庭園には、大野庄用水から引いた水が流れこむといわれ、観光客に人気です。","冬に土塀を雪や凍結から守るための «こもかけ» は、毎年12月ごろの金沢の風物詩です。","辰巳用水（1632年）は、金沢城に水を送るためにつくられた用水で、サイフォンの原理を使ったことで知られます。大野庄用水とはつくられた目的が違います。"],"look":["土塀と石畳にそって流れる用水","武家屋敷跡野村家の庭（用水の水を使う）","冬の土塀の «こもかけ»","用水にかかる小さな橋と水門"],"q":["大野庄用水の別名で、«荷物を運ぶ川» という意味の名前は?","«御荷川（おにがわ）»。城下町づくりの資材を運んだと伝わります。"],"koji":[],"myth":"掘られた時期・御荷川の由来は諸説・伝承。","img":["長町武家屋敷跡","辰巳用水","犀川 (石川県)"],"wp":"大野庄用水","rel":{"ev":[],"grave":[]},"ph":[["c:2/24/Nagamachi_Bukeyashiki.jpg",1600,1200,"長町武家屋敷跡"],["c:8/8f/Tatsumi_canal.jpg",480,640,"辰巳用水"],["c:4/4e/Saigawa_River01-r.jpg",1890,1260,"犀川 (石川県)"]]},{"id":"17_komatsu_tenmangu","n":"小松天満宮","yomi":"こまつてんまんぐう","cat":"寺社","rank":"B","y":1657,"era":["edo"],"sh":"国の重要文化財","ad":"小松市天神町","st":"小松駅から歩いて約20分","la":36.413,"lo":136.452,"hook":"隠居した «加賀百万石» の殿さまが、自分の城の «鬼門» を守らせるために建てた天神さま。","lead":"小松天満宮は、学問の神さま・菅原道真をまつる神社です。江戸時代の1657年、加賀藩3代藩主・前田利常が、隠居して住んでいた小松城の守りとして建てました。本殿や神門などが国の重要文化財になっています。","story":["加賀藩3代藩主・前田利常は、藩の仕組みを整えた名君として知られます。1639年に藩主の座を息子にゆずると、金沢ではなく小松の城に移り住みました。«なぜ小松に?» ――隠居後も、藩の南の守りや産業の発展に目を配るためだったといわれます。","前田家は、菅原道真の子孫だと名のっていました。そのため、道真をまつる天満宮をとても大切にしました。利常は、京都の北野天満宮にならい、小松にも天満宮を建てることにします。","場所として選ばれたのは、小松城から見て北東の方角。北東は «鬼門» と呼ばれ、悪いものが入ってくる方角と考えられていました。天満宮は、城を鬼門から守る役目も期待されたのです。","初代の別当（神社をまとめる僧）には、北野天満宮にゆかりのある連歌師・能順（のうじゅん）がまねかれました。能順は連歌の名人で、小松天満宮は連歌の会がさかんな場所にもなりました。","いまも境内には江戸時代のはじめの建物が残り、本殿・幣殿・拝殿、神門などが国の重要文化財に指定されています。梯川（かけはしがわ）の流れのそばで、受験生たちが合格を願って手を合わせる姿が見られます。"],"tl":[["1639年","前田利常が隠居し、小松城に移る"],["1657年","小松天満宮が創建される"],["同じころ","能順が別当として迎えられる"],["1658年","前田利常が亡くなる"],["昭和時代","社殿などが国の重要文化財に"],["現在","学問の神として参拝者が訪れる"]],"who":[["前田利常","加賀藩3代藩主。隠居後に小松天満宮を建てた"],["菅原道真","平安時代の学者・政治家。天満宮の祭神"],["能順","連歌師。小松天満宮の初代別当"]],"deep":["前田家が菅原道真の子孫を名のったことから、加賀藩の家紋は道真ゆかりの梅の花をもとにした «梅鉢紋» です。","能順は北野天満宮の連歌の宗匠をつとめた人物で、加賀藩と京都の文化をつなぐ役目もはたしました。","利常は小松で、茶道や工芸、産業の振興にも力を入れたといわれ、小松が «文化の町» として育つきっかけをつくりました。","前田利常は、小松城を隠居の城として大きく改修し、城下町も整えました。いま小松の町に残る寺や町割りの多くは、利常の時代にさかのぼるといわれます。","利常は «鼻毛の殿さま» という話でも知られます。わざと鼻毛をのばして «ぼんやりした殿さま» のふりをし、幕府に «前田家は危なくない» と思わせた、という逸話です。本当かどうかはわかりませんが、大きな藩を守るための知恵を物語る話として語りつがれています。","天満宮の祭神・菅原道真は、平安時代に右大臣までのぼった学者です。無実の罪で九州の大宰府に流され、そこで亡くなりました。のちに «天神さま» としてまつられ、学問の神として全国で信仰されるようになりました。"],"look":["神門（重要文化財）","本殿・幣殿・拝殿の建物（重要文化財）","梯川にのぞむ境内の景色","梅鉢紋などの装飾","小松の町を歩き、利常ゆかりの寺や小松城跡もあわせてめぐる"],"q":["小松天満宮は、小松城から見てどの方角に建てられた?","北東。«鬼門» の方角を守るためでした。"],"koji":[],"myth":"鬼門守護の目的は伝承を含む。«鼻毛の殿さま» は逸話。","img":["前田利常","菅原道真","小松城"],"wp":"小松天満宮","rel":{"ev":[],"grave":[]},"ph":[["c:5/57/IshikawakenKomatushi-Komatutenmangu-01.jpg",1024,768,"小松天満宮"],["c:b/b9/Maeda_Toshitsune.png",1294,1725,"前田利常"],["c:1/1e/%E6%9D%9F%E5%B8%AF%E5%A4%A9%E7%A5%9E%E5%83%8F.png",2500,3526,"菅原道真"],["c:9/9c/20210721_171937-COLLAGE.jpg",1024,1024,"小松城"]]},{"id":"17_gannenji","n":"芭蕉の金沢逗留（願念寺・一笑塚）","yomi":"がんねんじ","cat":"寺社","rank":"B","y":1689,"era":["edo"],"sh":"","ad":"金沢市野町1丁目","st":"JR金沢駅からバスで約15分、«広小路» 下車徒歩約5分","la":36.554,"lo":136.649,"hook":"«塚も動け 我が泣く声は 秋の風»――会えるはずだった友は、すでにこの世にいなかった。","lead":"1689年、俳人・松尾芭蕉は «おくのほそ道» の旅の途中で金沢に立ち寄りました。芭蕉は金沢で、会うのを楽しみにしていた若い俳人・小杉一笑（こすぎいっしょう）が、前の年に亡くなっていたことを知ります。一笑の墓がある願念寺には、その悲しみを詠んだ句碑が建っています。","story":["1689年の春、芭蕉は弟子の曾良とともに江戸を出発し、東北から北陸へと旅を続けました。夏の終わり、二人は加賀の金沢にたどり着きます。芭蕉には、ここで会いたい人がいました。金沢の若い俳人・小杉一笑です。","一笑は、芭蕉の句にあこがれ、遠く金沢から便りを送っていたともいわれます。«いつか芭蕉先生に会いたい»。芭蕉もまた、一笑の句を知り、会うのを楽しみにしていたのでしょう。ところが金沢に着いた芭蕉を待っていたのは、«一笑は去年の冬に亡くなった» という知らせでした。","一笑の兄が追善の句会を開き、芭蕉はそこで一句を詠みます。«塚も動け 我が泣く声は 秋の風»。わたしの泣く声よ、秋の風となって、友の墓までもゆり動かしてくれ――芭蕉の句の中でも、とくに感情があふれ出たものとして知られています。","芭蕉は金沢に10日ほど滞在し、地元の俳人たちと交流しました。ここで芭蕉に入門した立花北枝（たちばなほくし）は、その後も芭蕉に同行し、北陸の俳諧を広める中心人物になります。«あかあかと 日はつれなくも 秋の風» も、この金沢のころの句として知られています。","一笑の墓があるとされる願念寺は、寺町の近くの野町にある小さな寺です。境内には «塚も動け» の句碑と一笑塚があり、300年以上前の友情と別れを今に伝えています。"],"tl":[["1653年","小杉一笑が金沢に生まれる"],["1688年","一笑が36歳で亡くなる"],["1689年3月","芭蕉が «おくのほそ道» の旅に出発"],["1689年7月","芭蕉が金沢に到着（旧暦）。一笑の死を知る"],["1689年7月","一笑の追善句会で «塚も動け» を詠む"],["1702年","『おくのほそ道』が刊行される"]],"who":[["松尾芭蕉","江戸時代の俳人。«おくのほそ道» の旅で金沢に立ち寄った"],["小杉一笑","金沢の若い俳人。芭蕉の到着前に亡くなった"],["立花北枝","金沢で芭蕉に入門した俳人。北陸の蕉門の中心に"],["河合曾良","芭蕉の旅の同行者"]],"deep":["«おくのほそ道» の本文では、金沢のくだりに一笑の死と «塚も動け» の句が記されています。旅の日記『曾良随行日記』からも、金沢での滞在の様子がわかります。","芭蕉の金沢滞在は旧暦7月15日から約10日間とされます。新暦ではおよそ8月末〜9月はじめにあたります。","一笑の墓の場所については、願念寺が一笑の菩提寺として知られていますが、塚の形は後の時代に整えられたものと考えられます。","芭蕉の北陸の旅では、金沢のあと小松・山中温泉へと進み、山中で曾良と別れます。曾良が体調をくずしたためといわれます。","«あかあかと日はつれなくも秋の風» は、金沢から小松へ向かう道中で詠まれたとする説もあります。"],"look":["«塚も動け» の句碑","一笑塚","近くの寺町寺院群の町並み","犀川べりの景色（芭蕉が歩いたかもしれない道）"],"q":["芭蕉が金沢で会うはずだった若い俳人は誰?","小杉一笑。芭蕉が着く前の冬に亡くなっていました。"],"koji":[{"w":"塚も動け 我が泣く声は 秋の風","m":"亡き友の墓よ、わたしの嘆きの声に動いてくれ、という芭蕉の句。深い悲しみを表す"}],"myth":"一笑の没年月・墓の位置の細部、«あかあかと» の句の場所には諸説あり。","img":["松尾芭蕉","河合曾良"],"wp":"おくのほそ道","rel":{"ev":[],"grave":[]},"ph":[["c:4/4a/OkuroHosomiti_Senju.JPG",1600,1200],["c:3/3c/Kisakata_byobu_%28Kisakata_Historical_Museum%29.jpg",1459,618],["c:e/e5/Buson_OKUnoHOSOMICHI.JPG",1500,455],["c:c/ca/Basho_by_Morikawa_Kyoriku_%281656-1715%29.jpg",512,854,"松尾芭蕉"],["c:3/3c/Kawai_Sora.jpg",1024,768,"河合曾良"]]},{"id":"17_seihakusai","n":"青柏祭（でか山・大地主神社）","yomi":"せいはくさい","cat":"伝承","rank":"B","y":1500,"era":["muromachi","edo"],"sh":"国の重要無形民俗文化財","ad":"七尾市山王町（大地主神社）","st":"JR七尾駅から歩いて約15分","la":37.04,"lo":136.96,"hook":"高さ12m、重さ20t。日本一大きな曳山 «でか山» が、七尾の細い町角をぐいっと曲がる。","lead":"青柏祭（せいはくさい）は、七尾市の大地主神社（おおとこぬしじんじゃ）のお祭りです。毎年5月3日〜5日に、«でか山» と呼ばれる日本最大級の山車（だし）が3台、町の中を引かれます。国の重要無形民俗文化財で、ユネスコ無形文化遺産 «山・鉾・屋台行事» の一つにもなっています。","story":["5月の七尾の町に、見上げるほど大きな山車があらわれます。高さはおよそ12m、重さはおよそ20t。«でか山» という名前のとおり、日本でいちばん大きな曳山（ひきやま）といわれます。上のほうには人形が飾られ、歌舞伎の名場面などが表されています。","でか山を出すのは、府中町・鍛冶町・魚町の三つの町。それぞれの町の人々が、何日もかけて組み立てます。車輪は大きな木でできていて、ハンドルもブレーキもありません。«どうやって曲がるの?» ――ここが、このお祭りのいちばんの見せ場です。","町角に来ると、でか山の前の車輪を «大てこ» と呼ばれる太い棒で持ち上げ、そのまま向きを変えます。これを «辻回し（つじまわし）» といいます。何十人もの力を合わせ、20tの山がぐるりと回ると、大きな歓声と拍手がわきおこります。","お祭りの名前の «青柏» は、神さまへのお供えものを柏の葉にのせてささげたことに由来するといわれます。山王さまとも呼ばれる大地主神社の、古くから続く神事です。そのはじまりはとても古く、平安時代にさかのぼるとも伝えられています。","2024年の能登半島地震で、七尾の町も大きな被害を受けました。それでも、祭りを守り伝えようとする人々の思いは続いています。大きなでか山が町を進む姿は、能登の人々の力強さそのものです。"],"tl":[["平安時代","起源をこの時代にさかのぼるという伝承"],["室町〜戦国","七尾は能登守護・畠山氏の城下として栄える"],["江戸時代","でか山の曳き回しが町の祭りとして盛んに"],["1983年","国の重要無形民俗文化財に指定"],["2016年","«山・鉾・屋台行事» としてユネスコ無形文化遺産に"],["2024年","能登半島地震。祭りの継続に向けた取り組みが続く"]],"who":[["大地主神社（山王神社）","青柏祭を行う神社"],["府中町・鍛冶町・魚町の人々","それぞれのでか山を組み立て、引く"],["能登畠山氏","室町時代の能登守護。七尾を本拠にした"]],"deep":["でか山は «舟形» の山車で、上から見ると前後に長い形をしています。これは七尾が港町であることと関係があると考えられています。","山の上の人形飾りは毎年変わり、歌舞伎や物語の一場面が表されます。人形師が工夫をこらす見どころの一つです。","ユネスコ無形文化遺産 «山・鉾・屋台行事» には、京都祇園祭の山鉾行事や高山祭など全国33件の祭りがふくまれています（2016年登録時）。","祭りの起源について、平安時代の981年とする伝承が紹介されることもありますが、確かな史料で確かめられているわけではありません。","辻回しは、大てこで前輪を浮かせ、後ろの車輪を軸に向きを変える技。町ごとに引き手の息の合わせ方が違うといわれます。"],"look":["でか山の大きさ（下から見上げると迫力がちがう）","町角での «辻回し»","山の上の人形飾り","大地主神社の社殿"],"q":["でか山が町角で向きを変える技を何と呼ぶ?","«辻回し（つじまわし）»。大てこで車輪を持ち上げて回します。"],"koji":[],"myth":"起源の年代は伝承。震災後の開催形態は年により異なるので要確認。","img":["大地主神社","山・鉾・屋台行事","七尾市"],"wp":"青柏祭","rel":{"ev":[],"grave":[]},"ph":[["c:f/f9/Dekayama.JPG",1200,1600,"青柏祭"],["c:0/0d/Nanao_May_5_2006_crowds.jpg",1200,900],["c:8/83/Dekayama_sanno.jpg",640,425],["c:f/f3/%E5%A4%A7%E5%9C%B0%E4%B8%BB%E7%A5%9E%E7%A4%BE.jpg",900,506,"大地主神社"],["c:e/e4/Tatemontage.png",520,785,"山・鉾・屋台行事"],["c:a/a1/Wakura_Onsen_01.jpg",1200,1600,"七尾市"]]},{"id":"17_yamashiro","n":"山代温泉（古総湯と魯山人寓居）","yomi":"やましろおんせん","cat":"町","rank":"B","y":1915,"era":["nara","meiji","taisho"],"sh":"","ad":"加賀市山代温泉","st":"加賀温泉駅からバスで約15分","la":36.292,"lo":136.362,"hook":"カラスが傷をいやしていた湯、明治の湯屋、そして若き日の北大路魯山人。湯けむりの町に歴史が重なる。","lead":"山代温泉は、加賀市にある北陸を代表する温泉地です。奈良時代に僧・行基が見つけたという伝説があり、1300年近い歴史があるといわれます。町の中心には明治時代の共同浴場を復元した «古総湯（こそうゆ）» があり、近くには芸術家・北大路魯山人が滞在した家も残っています。","story":["むかしむかし、行基というお坊さんがこの地を通りかかると、1羽のカラスが、傷ついた羽を水たまりにひたしていました。近づいてみると、それはあたたかい湯。«これは仏さまのめぐみだ» ――こうして山代の湯が開かれた、と伝えられています。725年ごろのことといわれますが、もちろん伝説です。","山代の町は、共同浴場 «総湯» を中心に、旅館や店がぐるりと取りかこむつくりになっていました。これを «湯の曲輪（ゆのがわ）» と呼びます。人々は総湯に通い、その周りで商売をし、町全体がひとつの «お風呂の町» として暮らしていたのです。","2010年、明治時代の総湯をもとにした «古総湯» が復元されました。壁や床には九谷焼のタイル、窓にはステンドグラス。洗い場はなく、ただ湯につかって楽しむ、明治の湯あみのスタイルを体験できます。«昔の人はこんなふうに温泉に入っていたんだ» と実感できる場所です。","1915年、のちに美食家・陶芸家として有名になる北大路魯山人が、山代にやってきました。当時まだ若い書家だった魯山人は、旅館の主人たちに招かれ、看板を彫りながら滞在しました。そして、九谷焼の名工・須田菁華（すだせいか）の窯で、初めて焼き物づくりを体験したのです。","このとき魯山人が暮らした家が、いま «魯山人寓居跡 いろは草庵» として公開されています。«山代での出会いがなければ、陶芸家・魯山人は生まれなかったかもしれない» ――そう言われるほど、ここは魯山人にとって大切な場所でした。"],"tl":[["725年ごろ","行基が温泉を見つけたと伝わる"],["戦国時代","明覚上人ゆかりの寺など、温泉と信仰の結びつきが語られる"],["江戸時代","加賀藩の湯治場として栄える"],["1915年","北大路魯山人が山代に滞在し、須田菁華の窯で陶芸にふれる"],["2010年","明治の総湯を復元した «古総湯» が開業"]],"who":[["行基","奈良時代の僧。温泉を見つけたという伝説がある"],["北大路魯山人","書家・陶芸家・美食家。若いころ山代に滞在"],["須田菁華","九谷焼の陶工。魯山人に焼き物を教えた"]],"deep":["行基が温泉を開いたという伝説は、全国の多くの温泉に伝わっています。山代の開湯伝説もその一つで、史実かどうかはわかりません。","«湯の曲輪» は、総湯を中心に町が円形につくられた温泉町の形。山代ではこの町並みの姿が今も意識されています。","古総湯は、明治19年ごろの総湯の姿をもとに、九谷焼のタイルやステンドグラスで再現されました。すぐ隣にはふだん使いの «総湯» もあります。","魯山人は山代で、旅館の看板（刻字）を彫り、その評判で地元の旦那衆に大切にされたといわれます。いろは草庵の看板も魯山人の作と伝わります。","須田菁華の窯（菁華窯）は、今も山代で続いている九谷焼の窯元です。"],"look":["古総湯（明治の湯あみを体験）","湯の曲輪の町並み","魯山人寓居跡 いろは草庵","九谷焼の窯元・ギャラリー"],"q":["山代温泉で、傷をいやしていたと伝わる鳥は?","カラス。行基がそれを見て温泉を見つけたと伝わります。"],"koji":[],"myth":"行基開湯とカラスの話は伝説。魯山人滞在の細部には諸説あり。","img":["北大路魯山人","行基","九谷焼"],"wp":"山代温泉","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/Ko-Soyu_ac_%281%29.jpg",5605,3726,"山代温泉"],["c:7/74/Soyu_Yamashiro_ac_%282%29.jpg",5990,3983],["c:a/a1/Yamashiro_yakuouinn.jpg",800,600],["c:a/a8/Hadutiwo_gakudou.jpg",800,600],["c:0/08/Rosanjin_Kita%C5%8Dji_1954.jpg",458,657,"北大路魯山人"],["c:8/8d/Gyouki_1.jpg",400,300,"行基"],["c:4/4f/KUTANI_Ewer.JPG",852,627,"九谷焼"]]},{"id":"17_togashi","n":"富樫館跡（加賀守護・富樫氏）","yomi":"とがしやかたあと","cat":"城","rank":"B","y":1488,"era":["kamakura","muromachi"],"sh":"","ad":"野々市市本町","st":"野々市駅（IRいしかわ鉄道）から歩いて約15分","la":36.525,"lo":136.614,"hook":"加賀の国を400年近くおさめた守護・富樫氏。そのやかたの跡に、いまは石碑が一つ立つだけ。","lead":"富樫氏（とがしし）は、平安時代の終わりから戦国時代まで、加賀国で力を持った武士の一族です。室町時代には加賀の守護となり、野々市（ののいち）に館をかまえました。しかし1488年、一向一揆に敗れ、富樫政親は自害。館の跡には、石碑が立っています。","story":["野々市は、いまでは金沢のとなりの住宅の多い町ですが、中世の加賀の中心でした。ここに館をかまえたのが富樫氏です。富樫氏は平安時代から加賀に根をはった武士の一族で、室町時代には幕府から加賀の守護に任じられました。","ところが富樫家の中では、兄弟や親子のあいだで、守護の座をめぐる争いがくり返されました。そのたびに、国の武士や寺の力を借りることになります。そのなかで、どんどん力をつけていったのが、浄土真宗（一向宗）の門徒たちでした。","富樫政親は、弟との争いに勝つため、一向宗の門徒の力を借りて守護の座についたといわれます。しかしその後、門徒たちとの関係が悪くなり、対立するようになりました。«助けてくれた者たちを、今度は押さえつけようとした» ――それが悲劇の始まりでした。","1488年、門徒たちと国の武士たちは大軍で政親の高尾城を囲みました。これが «長享の一揆» です。政親は追いつめられ、自害したと伝えられます。こうして加賀は、門徒たちが力を持つ «百姓の持ちたる国» となり、約100年続きました。","有名な歌舞伎 «勧進帳» に出てくる関守・富樫左衛門は、この富樫氏の一族として描かれています。ただし、安宅関の物語は能や歌舞伎でつくられた話です。いま野々市の館跡には石碑が立ち、目に見える遺構は残っていませんが、加賀の中世を思い起こさせる場所となっています。"],"tl":[["平安時代末","富樫氏が加賀の武士として名をあらわす"],["1335年ごろ","富樫高家が足利尊氏に従い、加賀守護となる"],["15世紀","富樫家の中で守護の座をめぐる争いが続く"],["1474年","富樫政親が一向宗門徒の力を借りて弟に勝つ"],["1488年","長享の一揆。高尾城が落ち、政親が自害"],["その後","加賀は約100年、一向一揆の国となる"]],"who":[["富樫政親","加賀守護。長享の一揆で自害"],["富樫高家","室町幕府の初めに加賀守護となった"],["蓮如","浄土真宗本願寺の僧。北陸で門徒を増やした"],["富樫左衛門","«勧進帳» に登場する安宅関の関守（物語の人物）"]],"deep":["«百姓の持ちたる国» という言葉は、本願寺の関係者の記録に出てくる表現で、加賀の一向一揆の時代を表す言葉として有名です。","政親の死後も、富樫泰高が名目上の守護として立てられ、富樫氏はしばらく存続しました。完全に力を失ったのは戦国時代のなかごろです。","高尾城は金沢市の南の丘にあった城で、長享の一揆の最後の戦いの場となりました。現在も城跡が残るとされます。","富樫館の正確な位置や規模は、まだはっきりしていません。野々市の町の中に石碑が立ち、発掘調査で中世の遺構が見つかっています。","能 «安宅» や歌舞伎 «勧進帳» の富樫は、義経一行を見逃す情けある関守として描かれますが、史実の人物かどうかは確かめられていません。"],"look":["富樫館跡の石碑","野々市の町並み（中世の加賀の中心）","金沢市の高尾城跡（あわせて訪れる）","近くの布市神社などゆかりの地"],"q":["1488年、富樫政親をたおした一揆を何と呼ぶ?","«長享の一揆»。加賀は約100年、一向一揆の国になりました。"],"koji":[{"w":"百姓の持ちたる国","m":"一向一揆の時代の加賀を表す言葉。守護ではなく門徒たちが国を動かしたことから"}],"myth":"館の位置・規模は未確定。勧進帳の富樫は物語の人物。","img":["富樫政親","加賀一向一揆","勧進帳"],"wp":"富樫氏","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:a/a5/K%C5%8Dshir%C5%8D_Matsumoto_VII_as_Benkei.jpg",273,413,"勧進帳"],["c:0/0d/Okyouzuka_Ruins_-_27.jpg",6016,4016,"近く: 野々市市"],["c:2/2c/Kanazawa_Institute_of_Technology.jpg",1600,1200,"近く: 金沢工業大学"],["c:2/2d/Nonoichi-station2.JPG",1280,960,"近く: 野々市駅 (北陸鉄道)"],["c:5/50/Magae-station1.JPG",1600,1200,"近く: 馬替駅"],["c:7/75/Nonoichi_Kodai_Mae_Station.jpg",3456,2304,"近く: 野々市工大前駅"],["c:d/dd/Nukajyutakumaeeki.jpg",3264,2448,"近く: 額住宅前駅"]]}];
